// Nuvemath — 10-sinf, I qism (Algebra va analiz asoslari 10) nazariyasi, t1–t10. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '10-1';

  // ---------- t1. Takrorlash: kvadrat funksiya, progressiyalar, trigonometrik ayniyatlar ----------
  T.add(P, 't1', { sections: [
    { kind: 'intro', h: L('Yangi bosqich — analiz asoslari', 'Новый этап — начала анализа', 'A new stage — foundations of analysis'), p: [
      L('10-sinfda algebra kursi yangi nom oladi: <b>algebra va analiz asoslari</b>. Endi biz alohida misollarni emas, balki butun jarayonlarni — o‘zgarishni, o‘sishni, tebranishni — funksiyalar orqali o‘rganamiz. Ammo har qanday baland bino mustahkam poydevorga tayanadi. Bizning poydevorimiz — 8–9-sinflarda o‘rganilgan uchta katta mavzu: <b>kvadrat funksiya</b>, <b>progressiyalar</b> va <b>trigonometrik ayniyatlar</b>.', 'В 10 классе курс алгебры получает новое имя: <b>алгебра и начала анализа</b>. Теперь мы изучаем не отдельные примеры, а целые процессы — изменение, рост, колебания — с помощью функций. Но любое высокое здание стоит на прочном фундаменте. Наш фундамент — три большие темы 8–9 классов: <b>квадратичная функция</b>, <b>прогрессии</b> и <b>тригонометрические тождества</b>.', 'In grade 10 the algebra course gets a new name: <b>algebra and the foundations of analysis</b>. We now study not single examples but whole processes — change, growth, oscillation — through functions. Yet every tall building rests on a solid foundation. Ours is three big topics from grades 8–9: the <b>quadratic function</b>, <b>progressions</b> and <b>trigonometric identities</b>.'),
      L('Nega aynan shular? Kvadrat funksiya — optimallashtirish masalalarining eng sodda modeli: eng katta yuz, eng katta foyda, eng baland nuqta. Progressiyalar — ketma-ketliklar va limit tushunchasiga ko‘prik; geometrik progressiya esa keyinroq ko‘rsatkichli funksiyaga aylanadi. Trigonometrik ayniyatlar davriy funksiyalar va tebranishlarni o‘rganishda har qadamda kerak bo‘ladi.', 'Почему именно они? Квадратичная функция — простейшая модель задач оптимизации: наибольшая площадь, наибольшая прибыль, самая высокая точка. Прогрессии — мост к последовательностям и пределам; геометрическая прогрессия позже превратится в показательную функцию. Тригонометрические тождества нужны на каждом шагу при изучении периодических функций и колебаний.', 'Why these? The quadratic is the simplest model for optimisation: the largest area, the biggest profit, the highest point. Progressions are a bridge to sequences and limits, and the geometric progression will later turn into the exponential function. Trigonometric identities are needed at every step when we study periodic functions and oscillations.'),
      L('Bu mavzuda biz formulalarni shunchaki eslab qolmaymiz — ularning qayerdan kelib chiqishini qayta tiklaymiz. Formulani keltirib chiqara oladigan o‘quvchi uni hech qachon unutmaydi.', 'В этой теме мы не просто вспоминаем формулы — мы восстанавливаем, откуда они берутся. Ученик, умеющий вывести формулу, никогда её не забудет.', 'In this topic we do not just recall formulas — we rebuild where they come from. A student who can derive a formula never forgets it.')
    ] },
    { kind: 'def', h: L('Kvadrat funksiya va parabola', 'Квадратичная функция и парабола', 'The quadratic function and the parabola'), p: [
      L('y = ax² + bx + c (a ≠ 0) ko‘rinishidagi funksiya <b>kvadrat funksiya</b> deyiladi, uning grafigi — <b>parabola</b>. a &gt; 0 bo‘lsa, shoxlari yuqoriga, a &lt; 0 bo‘lsa, pastga qaragan. Parabola uchining abssissasi x₀ = −b/(2a), ordinatasi y₀ = f(x₀). Simmetriya o‘qi — x = x₀ vertikal to‘g‘ri chiziq.', 'Функция вида y = ax² + bx + c (a ≠ 0) называется <b>квадратичной</b>, её график — <b>парабола</b>. При a &gt; 0 ветви направлены вверх, при a &lt; 0 — вниз. Абсцисса вершины x₀ = −b/(2a), ордината y₀ = f(x₀). Ось симметрии — вертикальная прямая x = x₀.', 'A function y = ax² + bx + c (a ≠ 0) is called <b>quadratic</b>; its graph is a <b>parabola</b>. If a &gt; 0 the arms point up, if a &lt; 0 they point down. The vertex has x₀ = −b/(2a) and y₀ = f(x₀). The axis of symmetry is the vertical line x = x₀.'),
      L('Uch formulasi to‘la kvadrat ajratishdan kelib chiqadi: ax² + bx + c = a(x + b/(2a))² − D/(4a), bu yerda D = b² − 4ac — <b>diskriminant</b>. Qavs ichidagi kvadrat x = −b/(2a) da nolga teng, shuning uchun funksiya shu nuqtada eng kichik (a &gt; 0) yoki eng katta (a &lt; 0) qiymatga erishadi: y₀ = −D/(4a).', 'Формула вершины следует из выделения полного квадрата: ax² + bx + c = a(x + b/(2a))² − D/(4a), где D = b² − 4ac — <b>дискриминант</b>. Квадрат в скобках равен нулю при x = −b/(2a), поэтому в этой точке функция принимает наименьшее (a &gt; 0) или наибольшее (a &lt; 0) значение: y₀ = −D/(4a).', 'The vertex formula comes from completing the square: ax² + bx + c = a(x + b/(2a))² − D/(4a), where D = b² − 4ac is the <b>discriminant</b>. The bracket squared is zero at x = −b/(2a), so there the function reaches its minimum (a &gt; 0) or maximum (a &lt; 0): y₀ = −D/(4a).')
    ], list: [
      L('D &gt; 0 — parabola Ox o‘qini ikki nuqtada kesadi: x₁,₂ = (−b ± √D)/(2a).', 'D &gt; 0 — парабола пересекает ось Ox в двух точках: x₁,₂ = (−b ± √D)/(2a).', 'D &gt; 0 — the parabola crosses Ox twice: x₁,₂ = (−b ± √D)/(2a).'),
      L('D = 0 — parabola Ox ga uchida urinadi.', 'D = 0 — парабола касается Ox вершиной.', 'D = 0 — the parabola touches Ox at its vertex.'),
      L('D &lt; 0 — parabola Ox ni kesmaydi, butunlay uning ustida yoki ostida yotadi.', 'D &lt; 0 — парабола не пересекает Ox, целиком лежит выше или ниже неё.', 'D &lt; 0 — the parabola misses Ox, lying entirely above or below it.')
    ] },
    { kind: 'steps', h: L('Kvadrat tengsizlikni parabola yordamida yechish', 'Квадратное неравенство с помощью параболы', 'Solving a quadratic inequality with the parabola'), p: [
      L('ax² + bx + c &gt; 0 (yoki &lt;, ≥, ≤) tengsizlikni yechishning eng ishonchli usuli — grafikni ko‘z oldiga keltirish. Bizga butun parabola kerak emas: faqat shoxlar yo‘nalishi va Ox bilan kesishish nuqtalari yetarli.', 'Самый надёжный способ решить неравенство ax² + bx + c &gt; 0 (или &lt;, ≥, ≤) — представить график. Нам не нужна вся парабола: достаточно направления ветвей и точек пересечения с Ox.', 'The most reliable way to solve ax² + bx + c &gt; 0 (or &lt;, ≥, ≤) is to picture the graph. We do not need the whole parabola: the direction of the arms and the points where it meets Ox are enough.')
    ], list: [
      L('1) ax² + bx + c = 0 tenglamani yeching (ildizlarni toping yoki D &lt; 0 ekanini aniqlang).', '1) Решите уравнение ax² + bx + c = 0 (найдите корни или установите, что D &lt; 0).', '1) Solve ax² + bx + c = 0 (find the roots or see that D &lt; 0).'),
      L('2) a ning ishorasiga qarab shoxlar yo‘nalishini aniqlang.', '2) По знаку a определите направление ветвей.', '2) Use the sign of a to decide which way the arms point.'),
      L('3) Son o‘qida ildizlarni belgilab, parabolaning eskizini chizing.', '3) Отметьте корни на числовой прямой и нарисуйте эскиз параболы.', '3) Mark the roots on a number line and sketch the parabola.'),
      L('4) &gt; 0 uchun Ox dan yuqoridagi, &lt; 0 uchun pastdagi qismni oling; qat’iy bo‘lmagan tengsizlikda ildizlarni ham qo‘shing.', '4) Для &gt; 0 берите часть выше Ox, для &lt; 0 — ниже; при нестрогом неравенстве включите и корни.', '4) For &gt; 0 take the part above Ox, for &lt; 0 the part below; for a non-strict inequality include the roots.')
    ], after: [
      L('Masalan, x² − 5x + 6 &lt; 0: ildizlar 2 va 3, shoxlar yuqoriga, demak parabola ildizlar orasida Ox dan pastda. Javob: (2; 3).', 'Например, x² − 5x + 6 &lt; 0: корни 2 и 3, ветви вверх, значит, парабола ниже Ox между корнями. Ответ: (2; 3).', 'For example, x² − 5x + 6 &lt; 0: roots 2 and 3, arms up, so the parabola is below Ox between the roots. Answer: (2; 3).')
    ] },
    { kind: 'def', h: L('Arifmetik va geometrik progressiyalar', 'Арифметическая и геометрическая прогрессии', 'Arithmetic and geometric progressions'), p: [
      L('<b>Arifmetik progressiya</b> — har bir hadi oldingisiga bir xil d son (ayirma) qo‘shish bilan hosil bo‘ladigan ketma-ketlik: aₙ = a₁ + (n − 1)d. Uning dastlabki n ta hadi yig‘indisi Sₙ = (a₁ + aₙ)n/2. Bu formulani Gauss usuli bilan isbotlash oson: yig‘indini oldinga va orqaga yozib qo‘shsak, har bir juft a₁ + aₙ ga teng bo‘ladi, juftlar soni esa n ta.', '<b>Арифметическая прогрессия</b> — последовательность, каждый член которой получается прибавлением к предыдущему одного и того же числа d (разности): aₙ = a₁ + (n − 1)d. Сумма первых n членов Sₙ = (a₁ + aₙ)n/2. Её легко доказать способом Гаусса: запишем сумму в прямом и обратном порядке и сложим — каждая пара равна a₁ + aₙ, а пар n.', 'An <b>arithmetic progression</b> is a sequence where each term is the previous one plus the same number d (the common difference): aₙ = a₁ + (n − 1)d. The sum of the first n terms is Sₙ = (a₁ + aₙ)n/2. Gauss’s trick proves it: write the sum forwards and backwards and add — each pair equals a₁ + aₙ, and there are n pairs.'),
      L('<b>Geometrik progressiya</b> — har bir hadi oldingisini bir xil q ≠ 0 songa (maxrajga) ko‘paytirish bilan hosil bo‘ladi: bₙ = b₁qⁿ⁻¹. Yig‘indisi Sₙ = b₁(qⁿ − 1)/(q − 1), q ≠ 1. |q| &lt; 1 bo‘lsa, cheksiz kamayuvchi geometrik progressiya yig‘indisi S = b₁/(1 − q). Xarakteristik xossa: arifmetik progressiyada har bir o‘rta had qo‘shnilarining o‘rta arifmetigi, geometrik progressiyada esa (musbat hadlar uchun) o‘rta geometrigi.', '<b>Геометрическая прогрессия</b> — каждый член получается умножением предыдущего на одно и то же число q ≠ 0 (знаменатель): bₙ = b₁qⁿ⁻¹. Сумма Sₙ = b₁(qⁿ − 1)/(q − 1), q ≠ 1. При |q| &lt; 1 сумма бесконечно убывающей прогрессии S = b₁/(1 − q). Характеристическое свойство: в арифметической прогрессии каждый средний член — среднее арифметическое соседей, в геометрической (для положительных членов) — среднее геометрическое.', 'A <b>geometric progression</b> multiplies each term by the same number q ≠ 0 (the common ratio): bₙ = b₁qⁿ⁻¹. Its sum is Sₙ = b₁(qⁿ − 1)/(q − 1), q ≠ 1. When |q| &lt; 1 the infinite sum is S = b₁/(1 − q). Characteristic property: in an arithmetic progression each middle term is the arithmetic mean of its neighbours; in a geometric one (with positive terms) it is their geometric mean.')
    ] },
    { kind: 'rule', h: L('Asosiy trigonometrik ayniyatlar', 'Основные тригонометрические тождества', 'Basic trigonometric identities'), p: [
      L('Birlik aylanada α burchakka mos nuqtaning koordinatalari (cos α; sin α). Bu nuqta markazdan 1 masofada, shuning uchun Pifagor teoremasiga ko‘ra <b>sin²α + cos²α = 1</b>. Bu ayniyatdan boshqalari kelib chiqadi: ikkala tomonni cos²α ga bo‘lsak, 1 + tg²α = 1/cos²α; sin²α ga bo‘lsak, 1 + ctg²α = 1/sin²α. Shuningdek tg α = sin α / cos α va tg α · ctg α = 1.', 'На единичной окружности точка, соответствующая углу α, имеет координаты (cos α; sin α). Она находится на расстоянии 1 от центра, поэтому по теореме Пифагора <b>sin²α + cos²α = 1</b>. Из этого тождества следуют остальные: делим на cos²α — 1 + tg²α = 1/cos²α; делим на sin²α — 1 + ctg²α = 1/sin²α. Кроме того, tg α = sin α / cos α и tg α · ctg α = 1.', 'On the unit circle the point for angle α has coordinates (cos α; sin α). It is at distance 1 from the centre, so by Pythagoras <b>sin²α + cos²α = 1</b>. The others follow: dividing by cos²α gives 1 + tan²α = 1/cos²α; dividing by sin²α gives 1 + cot²α = 1/sin²α. Also tan α = sin α / cos α and tan α · cot α = 1.'),
      L('<b>Qo‘shish formulalari:</b> sin(α ± β) = sin α cos β ± cos α sin β; cos(α ± β) = cos α cos β ∓ sin α sin β. Ulardan β = α deb olib, ikkilangan burchak formulalarini olamiz: sin 2α = 2 sin α cos α, cos 2α = cos²α − sin²α = 1 − 2sin²α = 2cos²α − 1. Oxirgi ikki ko‘rinish darajani pasaytirishda juda qulay.', '<b>Формулы сложения:</b> sin(α ± β) = sin α cos β ± cos α sin β; cos(α ± β) = cos α cos β ∓ sin α sin β. Положив β = α, получаем формулы двойного угла: sin 2α = 2 sin α cos α, cos 2α = cos²α − sin²α = 1 − 2sin²α = 2cos²α − 1. Последние два вида очень удобны для понижения степени.', '<b>Addition formulas:</b> sin(α ± β) = sin α cos β ± cos α sin β; cos(α ± β) = cos α cos β ∓ sin α sin β. Setting β = α gives the double-angle formulas: sin 2α = 2 sin α cos α, cos 2α = cos²α − sin²α = 1 − 2sin²α = 2cos²α − 1. The last two forms are very handy for lowering powers.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Kvadrat tenglamalarni Bobil olimlari miloddan avvalgi 2000-yillardayoq so‘z bilan yozilgan qoidalar orqali yechishgan. Muhammad ibn Muso al-Xorazmiy IX asrda «Al-jabr va-l-muqobala» kitobida kvadrat tenglamalarning olti turini tizimli tasnifladi va to‘la kvadrat ajratishni geometrik — kvadratni to‘ldirish orqali isbotladi. «Algebra» so‘zining o‘zi shu kitob nomidan kelib chiqqan.', 'Квадратные уравнения вавилонские учёные решали ещё около 2000 г. до н. э. по правилам, записанным словами. Мухаммад ибн Муса аль-Хорезми в IX веке в книге «Аль-джабр валь-мукабала» систематически классифицировал шесть видов квадратных уравнений и доказал выделение полного квадрата геометрически — достраиванием квадрата. Само слово «алгебра» произошло от названия этой книги.', 'Babylonian scholars solved quadratic equations as early as about 2000 BC using rules written in words. In the 9th century Muhammad ibn Musa al-Khwarizmi, in his book “Al-jabr wa’l-muqabala”, systematically classified six types of quadratic equations and proved completing the square geometrically — by literally completing a square. The very word “algebra” comes from the book’s title.'),
      L('Progressiyalar ham qadimiy: Misrning Rind papirusida (taxminan mil. av. 1650-yil) non bo‘lish masalasi arifmetik progressiyaga keltiriladi. Hindistonda shaxmat taxtasi va bug‘doy donlari haqidagi afsona geometrik progressiyaning qanchalik tez o‘sishini ko‘rsatadi: 1 + 2 + 4 + … + 2⁶³ = 2⁶⁴ − 1 ≈ 1,8 · 10¹⁹ ta don. Trigonometriyani mustaqil fan sifatida shakllantirishda Abu Rayhon Beruniy va Nosiriddin Tusiy katta hissa qo‘shgan; Tusiy XIII asrda trigonometriyani astronomiyadan ajratib, alohida risola yozgan.', 'Прогрессии тоже древние: в египетском папирусе Ринда (около 1650 г. до н. э.) задача о делении хлебов сводится к арифметической прогрессии. Индийская легенда о шахматной доске и пшеничных зёрнах показывает, как быстро растёт геометрическая прогрессия: 1 + 2 + 4 + … + 2⁶³ = 2⁶⁴ − 1 ≈ 1,8 · 10¹⁹ зёрен. Большой вклад в становление тригонометрии как самостоятельной науки внесли Абу Райхан Беруни и Насир ад-Дин Туси; Туси в XIII веке отделил тригонометрию от астрономии, написав отдельный трактат.', 'Progressions are ancient too: in the Egyptian Rhind papyrus (about 1650 BC) a bread-sharing problem leads to an arithmetic progression. The Indian legend of the chessboard and grains of wheat shows how fast a geometric progression grows: 1 + 2 + 4 + … + 2⁶³ = 2⁶⁴ − 1 ≈ 1.8 · 10¹⁹ grains. Abu Rayhan al-Biruni and Nasir al-Din al-Tusi did much to make trigonometry an independent science; in the 13th century al-Tusi separated it from astronomy in a treatise of its own.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: kvadrat funksiya', 'Решённые примеры: квадратичная функция', 'Worked examples: the quadratic'), ex: [
      { q: L('y = 2x² − 8x + 3 parabolaning uchini va funksiyaning qiymatlar to‘plamini toping.', 'Найдите вершину параболы y = 2x² − 8x + 3 и множество значений функции.', 'Find the vertex of y = 2x² − 8x + 3 and the range of the function.'),
        s: L('x₀ = −b/(2a) = 8/4 = 2; y₀ = 2 · 4 − 16 + 3 = −5. a = 2 &gt; 0, shoxlar yuqoriga, demak −5 — eng kichik qiymat. Uch (2; −5), E(y) = [−5; +∞).', 'x₀ = −b/(2a) = 8/4 = 2; y₀ = 2 · 4 − 16 + 3 = −5. a = 2 &gt; 0, ветви вверх, значит, −5 — наименьшее значение. Вершина (2; −5), E(y) = [−5; +∞).', 'x₀ = −b/(2a) = 8/4 = 2; y₀ = 2 · 4 − 16 + 3 = −5. a = 2 &gt; 0, arms up, so −5 is the minimum. Vertex (2; −5), range [−5; +∞).') },
      { q: L('Tengsizlikni yeching: −x² + 2x + 8 ≥ 0.', 'Решите неравенство: −x² + 2x + 8 ≥ 0.', 'Solve: −x² + 2x + 8 ≥ 0.'),
        s: L('−1 ga ko‘paytirib ishorani almashtiramiz: x² − 2x − 8 ≤ 0. Ildizlar: D = 4 + 32 = 36, x = (2 ± 6)/2, ya’ni −2 va 4. Shoxlar yuqoriga, ildizlar orasida parabola Ox dan pastda. Javob: [−2; 4].', 'Умножим на −1 и сменим знак: x² − 2x − 8 ≤ 0. Корни: D = 4 + 32 = 36, x = (2 ± 6)/2, то есть −2 и 4. Ветви вверх, между корнями парабола ниже Ox. Ответ: [−2; 4].', 'Multiply by −1 and flip the sign: x² − 2x − 8 ≤ 0. Roots: D = 4 + 32 = 36, x = (2 ± 6)/2, i.e. −2 and 4. Arms up, so the parabola is below Ox between the roots. Answer: [−2; 4].') },
      { q: L('m ning qanday qiymatlarida x² + mx + 9 &gt; 0 tengsizlik barcha x da bajariladi?', 'При каких m неравенство x² + mx + 9 &gt; 0 выполняется при всех x?', 'For which m does x² + mx + 9 &gt; 0 hold for every x?'),
        s: L('Shoxlar yuqoriga (a = 1). Parabola butunlay Ox dan yuqorida bo‘lishi uchun D &lt; 0 kerak: m² − 36 &lt; 0, ya’ni −6 &lt; m &lt; 6. Javob: m ∈ (−6; 6).', 'Ветви вверх (a = 1). Чтобы парабола целиком лежала выше Ox, нужно D &lt; 0: m² − 36 &lt; 0, то есть −6 &lt; m &lt; 6. Ответ: m ∈ (−6; 6).', 'The arms point up (a = 1). For the parabola to lie entirely above Ox we need D &lt; 0: m² − 36 &lt; 0, i.e. −6 &lt; m &lt; 6. Answer: m ∈ (−6; 6).') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: progressiya va trigonometriya', 'Решённые примеры: прогрессии и тригонометрия', 'Worked examples: progressions and trigonometry'), ex: [
      { q: L('Arifmetik progressiyada a₃ = 7, a₇ = 19. a₁, d va S₁₀ ni toping.', 'В арифметической прогрессии a₃ = 7, a₇ = 19. Найдите a₁, d и S₁₀.', 'In an arithmetic progression a₃ = 7 and a₇ = 19. Find a₁, d and S₁₀.'),
        s: L('a₇ − a₃ = 4d = 12, d = 3; a₁ = a₃ − 2d = 1. a₁₀ = 1 + 9 · 3 = 28, S₁₀ = (1 + 28) · 10/2 = 145.', 'a₇ − a₃ = 4d = 12, d = 3; a₁ = a₃ − 2d = 1. a₁₀ = 1 + 9 · 3 = 28, S₁₀ = (1 + 28) · 10/2 = 145.', 'a₇ − a₃ = 4d = 12, so d = 3; a₁ = a₃ − 2d = 1. a₁₀ = 1 + 9 · 3 = 28, S₁₀ = (1 + 28) · 10/2 = 145.') },
      { q: L('0,(3) = 0,333… davriy kasrni oddiy kasrga aylantiring.', 'Обратите периодическую дробь 0,(3) = 0,333… в обыкновенную.', 'Write the repeating decimal 0.(3) = 0.333… as a fraction.'),
        s: L('0,3 + 0,03 + 0,003 + … — cheksiz kamayuvchi geometrik progressiya, b₁ = 0,3, q = 0,1. S = 0,3/(1 − 0,1) = 0,3/0,9 = 1/3.', '0,3 + 0,03 + 0,003 + … — бесконечно убывающая геометрическая прогрессия, b₁ = 0,3, q = 0,1. S = 0,3/(1 − 0,1) = 0,3/0,9 = 1/3.', '0.3 + 0.03 + 0.003 + … is an infinite geometric series with b₁ = 0.3, q = 0.1. S = 0.3/(1 − 0.1) = 0.3/0.9 = 1/3.') },
      { q: L('sin α = 3/5, α — II chorak burchagi. cos α, tg α va sin 2α ni toping.', 'sin α = 3/5, α — угол II четверти. Найдите cos α, tg α и sin 2α.', 'sin α = 3/5 and α is in quadrant II. Find cos α, tan α and sin 2α.'),
        s: L('cos²α = 1 − 9/25 = 16/25. II chorakda kosinus manfiy: cos α = −4/5. tg α = (3/5)/(−4/5) = −3/4. sin 2α = 2 · (3/5) · (−4/5) = −24/25.', 'cos²α = 1 − 9/25 = 16/25. Во II четверти косинус отрицателен: cos α = −4/5. tg α = (3/5)/(−4/5) = −3/4. sin 2α = 2 · (3/5) · (−4/5) = −24/25.', 'cos²α = 1 − 9/25 = 16/25. In quadrant II cosine is negative: cos α = −4/5. tan α = (3/5)/(−4/5) = −3/4. sin 2α = 2 · (3/5) · (−4/5) = −24/25.') },
      { q: L('cos 75° ning aniq qiymatini toping.', 'Найдите точное значение cos 75°.', 'Find the exact value of cos 75°.'),
        s: L('cos 75° = cos(45° + 30°) = cos 45° cos 30° − sin 45° sin 30° = (√2/2)(√3/2) − (√2/2)(1/2) = (√6 − √2)/4 ≈ 0,259.', 'cos 75° = cos(45° + 30°) = cos 45° cos 30° − sin 45° sin 30° = (√2/2)(√3/2) − (√2/2)(1/2) = (√6 − √2)/4 ≈ 0,259.', 'cos 75° = cos(45° + 30°) = cos 45° cos 30° − sin 45° sin 30° = (√2/2)(√3/2) − (√2/2)(1/2) = (√6 − √2)/4 ≈ 0.259.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Uch formulasida ishora:</b> x₀ = −b/(2a), «b/(2a)» emas. y = x² + 6x da uch x₀ = −3, +3 emas.', '<b>Знак в формуле вершины:</b> x₀ = −b/(2a), а не «b/(2a)». У y = x² + 6x вершина x₀ = −3, а не +3.', '<b>Sign in the vertex formula:</b> x₀ = −b/(2a), not “b/(2a)”. For y = x² + 6x the vertex is at x₀ = −3, not +3.'),
      L('<b>Manfiy songa ko‘paytirish:</b> tengsizlikni −1 ga ko‘paytirganda ishora teskarisiga o‘zgaradi — buni unutish eng ko‘p uchraydigan xato.', '<b>Умножение на отрицательное число:</b> при умножении неравенства на −1 знак меняется на противоположный — забыть об этом самая частая ошибка.', '<b>Multiplying by a negative:</b> multiplying an inequality by −1 reverses its sign — forgetting this is the most common error.'),
      L('<b>D &lt; 0 bo‘lsa «yechim yo‘q» deb yozish:</b> x² + 1 &gt; 0 ning yechimi — barcha haqiqiy sonlar, chunki parabola butunlay Ox dan yuqorida.', '<b>Писать «нет решений» при D &lt; 0:</b> решение x² + 1 &gt; 0 — все действительные числа, ведь парабола целиком выше Ox.', '<b>Writing “no solution” when D &lt; 0:</b> x² + 1 &gt; 0 holds for all real numbers, because the parabola lies entirely above Ox.'),
      L('<b>Progressiyada n − 1 o‘rniga n:</b> aₙ = a₁ + (n − 1)d. Birinchi hadga hali birorta ham d qo‘shilmagan.', '<b>n вместо n − 1 в прогрессии:</b> aₙ = a₁ + (n − 1)d. К первому члену ещё не прибавлено ни одного d.', '<b>Using n instead of n − 1:</b> aₙ = a₁ + (n − 1)d. No d has yet been added to the first term.'),
      L('<b>Ildizdan chiqarishda ishorani yo‘qotish:</b> cos α = ±√(1 − sin²α). Ishorani chorak hal qiladi.', '<b>Потеря знака при извлечении корня:</b> cos α = ±√(1 − sin²α). Знак определяет четверть.', '<b>Losing the sign when taking a root:</b> cos α = ±√(1 − sin²α). The quadrant decides the sign.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Sport va fizika.</b> Basketbol to‘pi yoki favvora suvi parabola bo‘ylab uchadi: h(t) = h₀ + v₀t − 5t². Eng baland nuqta vaqti t₀ = v₀/10 — bu aynan parabola uchi. Masalan, v₀ = 15 m/s bilan otilgan to‘p 1,5 sekunddan keyin eng yuqoriga ko‘tariladi.', '<b>Спорт и физика.</b> Баскетбольный мяч или струя фонтана летят по параболе: h(t) = h₀ + v₀t − 5t². Время подъёма в высшую точку t₀ = v₀/10 — это и есть вершина параболы. Например, мяч, брошенный со скоростью 15 м/с, поднимется выше всего через 1,5 секунды.', '<b>Sport and physics.</b> A basketball or a fountain jet flies along a parabola: h(t) = h₀ + v₀t − 5t². The time of the highest point, t₀ = v₀/10, is exactly the vertex. A ball thrown at 15 m/s reaches its peak after 1.5 seconds.'),
      L('<b>Moliya.</b> Har oy bir xil summa qo‘shib boriladigan jamg‘arma — arifmetik progressiya; bank har yili foiz qo‘shadigan omonat — geometrik progressiya: 10 % yillik stavkada pul taxminan 7 yilda ikki baravar ko‘payadi (1,1⁷ ≈ 1,95).', '<b>Финансы.</b> Накопления, к которым каждый месяц добавляется одна сумма, — арифметическая прогрессия; вклад, на который банк ежегодно начисляет проценты, — геометрическая: при 10 % годовых деньги удваиваются примерно за 7 лет (1,1⁷ ≈ 1,95).', '<b>Finance.</b> Savings topped up by the same amount each month form an arithmetic progression; a deposit earning yearly interest is geometric: at 10 % a year money roughly doubles in 7 years (1.1⁷ ≈ 1.95).'),
      L('<b>Muhandislik.</b> Sun’iy yo‘ldosh antennalari va avtomobil faralari parabolik shaklda: fokusdagi manbadan chiqqan nurlar parallel dasta bo‘lib qaytadi. Trigonometrik formulalar esa GPS koordinatalarini, ko‘prik tayanchlaridagi kuchlarni va o‘zgaruvchan tok kuchlanishini hisoblashda ishlatiladi.', '<b>Инженерия.</b> Спутниковые антенны и автомобильные фары имеют параболическую форму: лучи от источника в фокусе отражаются параллельным пучком. Тригонометрические формулы применяют при расчёте GPS-координат, сил в опорах мостов и переменного напряжения.', '<b>Engineering.</b> Satellite dishes and car headlights are parabolic: rays from a source at the focus reflect as a parallel beam. Trigonometric formulas are used to compute GPS coordinates, forces in bridge supports and alternating voltage.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('y = −x² + 4x − 1 funksiyaning eng katta qiymatini toping.', 'Найдите наибольшее значение функции y = −x² + 4x − 1.', 'Find the largest value of y = −x² + 4x − 1.'),
        s: L('x₀ = −4/(−2) = 2, y₀ = −4 + 8 − 1 = 3. Javob: 3.', 'x₀ = −4/(−2) = 2, y₀ = −4 + 8 − 1 = 3. Ответ: 3.', 'x₀ = −4/(−2) = 2, y₀ = −4 + 8 − 1 = 3. Answer: 3.') },
      { q: L('Geometrik progressiyada b₁ = 3, q = 2. S₆ ni toping.', 'В геометрической прогрессии b₁ = 3, q = 2. Найдите S₆.', 'A geometric progression has b₁ = 3, q = 2. Find S₆.'),
        s: L('S₆ = 3(2⁶ − 1)/(2 − 1) = 3 · 63 = 189.', 'S₆ = 3(2⁶ − 1)/(2 − 1) = 3 · 63 = 189.', 'S₆ = 3(2⁶ − 1)/(2 − 1) = 3 · 63 = 189.') },
      { q: L('Soddalashtiring: (1 − cos²α)/sin α.', 'Упростите: (1 − cos²α)/sin α.', 'Simplify: (1 − cos²α)/sin α.'),
        s: L('1 − cos²α = sin²α, shuning uchun ifoda sin²α / sin α = sin α (sin α ≠ 0).', '1 − cos²α = sin²α, поэтому выражение равно sin²α / sin α = sin α (sin α ≠ 0).', '1 − cos²α = sin²α, so the expression equals sin²α / sin α = sin α (sin α ≠ 0).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Parabola uchi: x₀ = −b/(2a), y₀ = −D/(4a); a ning ishorasi shoxlar yo‘nalishini beradi.', 'Вершина параболы: x₀ = −b/(2a), y₀ = −D/(4a); знак a задаёт направление ветвей.', 'Vertex: x₀ = −b/(2a), y₀ = −D/(4a); the sign of a gives the direction of the arms.'),
      L('Kvadrat tengsizlik: ildizlar + shoxlar yo‘nalishi + eskiz.', 'Квадратное неравенство: корни + направление ветвей + эскиз.', 'Quadratic inequality: roots + direction of arms + sketch.'),
      L('Arifmetik progressiya: aₙ = a₁ + (n − 1)d, Sₙ = (a₁ + aₙ)n/2.', 'Арифметическая прогрессия: aₙ = a₁ + (n − 1)d, Sₙ = (a₁ + aₙ)n/2.', 'Arithmetic progression: aₙ = a₁ + (n − 1)d, Sₙ = (a₁ + aₙ)n/2.'),
      L('Geometrik progressiya: bₙ = b₁qⁿ⁻¹, Sₙ = b₁(qⁿ − 1)/(q − 1), |q| &lt; 1 da S = b₁/(1 − q).', 'Геометрическая прогрессия: bₙ = b₁qⁿ⁻¹, Sₙ = b₁(qⁿ − 1)/(q − 1), при |q| &lt; 1 S = b₁/(1 − q).', 'Geometric progression: bₙ = b₁qⁿ⁻¹, Sₙ = b₁(qⁿ − 1)/(q − 1), and S = b₁/(1 − q) when |q| &lt; 1.'),
      L('sin²α + cos²α = 1 — barcha trigonometrik ayniyatlarning onasi.', 'sin²α + cos²α = 1 — мать всех тригонометрических тождеств.', 'sin²α + cos²α = 1 is the mother of all trigonometric identities.'),
      L('Qo‘shish formulalaridan ikkilangan burchak formulalari kelib chiqadi.', 'Из формул сложения выводятся формулы двойного угла.', 'The double-angle formulas follow from the addition formulas.')
    ] }
  ] });

  // ---------- t2. Funksiya, berilish usullari, aniqlanish sohasi va qiymatlar to‘plami ----------
  T.add(P, 't2', { sections: [
    { kind: 'intro', h: L('Hamma narsa nimagadir bog‘liq', 'Всё от чего-то зависит', 'Everything depends on something'), p: [
      L('Telefoningiz batareyasi zaryadlanish vaqtiga, taksi narxi masofaga, havo harorati sutkaning soatiga bog‘liq. Matematikada bunday bog‘lanishlarni tasvirlash uchun bitta kuchli tushuncha bor — <b>funksiya</b>. Funksiya — bu «mashina»: unga kirish qiymati x beriladi, u esa qat’iy qoida bo‘yicha yagona chiqish qiymati y ni qaytaradi.', 'Заряд батареи телефона зависит от времени зарядки, цена такси — от расстояния, температура воздуха — от часа суток. Для описания таких зависимостей в математике есть одно мощное понятие — <b>функция</b>. Функция — это «машина»: на вход ей подают x, а она по строгому правилу выдаёт единственное значение y.', 'Your phone’s battery level depends on charging time, a taxi fare on distance, the air temperature on the hour of the day. Mathematics has one powerful idea for such dependences — the <b>function</b>. A function is a “machine”: you feed in an input x, and by a fixed rule it returns exactly one output y.'),
      L('Siz funksiyalar bilan 7-sinfdan beri ishlaysiz: y = kx + b, y = x², y = k/x, y = √x. Endi esa funksiya tushunchasini umumiy holda, aniq ta’riflar bilan o‘rganamiz. Har qanday funksiya haqida birinchi beriladigan ikki savol: <b>qanday x larni kiritish mumkin?</b> va <b>qanday y lar chiqishi mumkin?</b> Bular — aniqlanish sohasi va qiymatlar to‘plami.', 'Вы работаете с функциями с 7 класса: y = kx + b, y = x², y = k/x, y = √x. Теперь мы изучим понятие функции в общем виде, с точными определениями. Первые два вопроса о любой функции: <b>какие x можно подавать?</b> и <b>какие y могут получиться?</b> Это область определения и множество значений.', 'You have worked with functions since grade 7: y = kx + b, y = x², y = k/x, y = √x. Now we study the notion in general, with precise definitions. The first two questions about any function are: <b>which x may we feed in?</b> and <b>which y can come out?</b> These are the domain and the range.')
    ] },
    { kind: 'def', h: L('Funksiya ta’rifi', 'Определение функции', 'Definition of a function'), p: [
      L('X va Y — sonli to‘plamlar bo‘lsin. Agar X to‘plamdagi <b>har bir</b> x songa biror qoida bo‘yicha Y to‘plamdagi <b>yagona</b> y son mos qo‘yilgan bo‘lsa, X da <b>funksiya</b> berilgan deyiladi va y = f(x) deb yoziladi. x — <b>argument</b> (erkli o‘zgaruvchi), y — funksiyaning x nuqtadagi <b>qiymati</b> (bog‘liq o‘zgaruvchi).', 'Пусть X и Y — числовые множества. Если <b>каждому</b> числу x из X по некоторому правилу сопоставлено <b>единственное</b> число y из Y, то говорят, что на X задана <b>функция</b>, и пишут y = f(x). x — <b>аргумент</b> (независимая переменная), y — <b>значение</b> функции в точке x (зависимая переменная).', 'Let X and Y be sets of numbers. If to <b>every</b> x in X some rule assigns <b>exactly one</b> y in Y, we say a <b>function</b> is defined on X and write y = f(x). x is the <b>argument</b> (independent variable) and y is the <b>value</b> of the function at x (dependent variable).'),
      L('Ta’rifdagi ikki kalit so‘zga e’tibor bering. «Har bir» — sohadagi hech bir x javobsiz qolmaydi. «Yagona» — bitta x ga ikki xil y mos kelmaydi. Masalan, x² + y² = 25 tenglama y ni x ning funksiyasi sifatida bermaydi: x = 3 da y = 4 ham, y = −4 ham to‘g‘ri keladi. Grafik tilida bu <b>vertikal chiziq testi</b>: har qanday vertikal to‘g‘ri chiziq funksiya grafigini ko‘pi bilan bitta nuqtada kesadi.', 'Обратите внимание на два ключевых слова. «Каждому» — ни одно x из области не остаётся без ответа. «Единственное» — одному x не соответствуют два разных y. Например, уравнение x² + y² = 25 не задаёт y как функцию x: при x = 3 подходят и y = 4, и y = −4. На языке графиков это <b>тест вертикальной прямой</b>: любая вертикальная прямая пересекает график функции не более чем в одной точке.', 'Note the two key words. “Every” — no x in the domain is left without an answer. “Exactly one” — one x never gets two different y. For example, x² + y² = 25 does not give y as a function of x: at x = 3 both y = 4 and y = −4 work. In graph language this is the <b>vertical line test</b>: every vertical line meets the graph of a function in at most one point.')
    ] },
    { kind: 'def', h: L('Aniqlanish sohasi va qiymatlar to‘plami', 'Область определения и множество значений', 'Domain and range'), p: [
      L('Argument qabul qila oladigan barcha qiymatlar to‘plami — funksiyaning <b>aniqlanish sohasi</b>, D(f) bilan belgilanadi. Funksiya qabul qiladigan barcha qiymatlar to‘plami — <b>qiymatlar to‘plami</b> (qiymatlar sohasi), E(f). Agar funksiya faqat formula bilan berilgan bo‘lsa va soha ko‘rsatilmagan bo‘lsa, D(f) deb formula ma’noga ega bo‘ladigan barcha x lar olinadi — bu <b>tabiiy aniqlanish sohasi</b>.', 'Множество всех значений, которые может принимать аргумент, — <b>область определения</b> функции, обозначается D(f). Множество всех значений, которые принимает функция, — <b>множество значений</b> (область значений), E(f). Если функция задана только формулой и область не указана, за D(f) берут все x, при которых формула имеет смысл, — <b>естественная область определения</b>.', 'The set of all values the argument may take is the <b>domain</b> of the function, written D(f). The set of all values the function takes is the <b>range</b>, E(f). If a function is given only by a formula and no domain is stated, D(f) is all x for which the formula makes sense — the <b>natural domain</b>.')
    ], list: [
      L('Kasr: maxraj nolga teng bo‘lmasligi kerak. y = 1/(x − 3) uchun x ≠ 3.', 'Дробь: знаменатель не равен нулю. Для y = 1/(x − 3): x ≠ 3.', 'Fraction: the denominator must not be zero. For y = 1/(x − 3): x ≠ 3.'),
      L('Juft darajali ildiz: ildiz osti manfiy emas. y = √(x + 2) uchun x ≥ −2.', 'Корень чётной степени: подкоренное выражение неотрицательно. Для y = √(x + 2): x ≥ −2.', 'Even root: the radicand is non-negative. For y = √(x + 2): x ≥ −2.'),
      L('Ildiz maxrajda bo‘lsa — qat’iy musbat: y = 1/√x uchun x &gt; 0.', 'Корень в знаменателе — строго положителен: для y = 1/√x x &gt; 0.', 'A root in the denominator must be strictly positive: for y = 1/√x, x &gt; 0.'),
      L('Bir nechta shart bo‘lsa — ularning hammasi birga (sistema) bajarilishi kerak.', 'Если условий несколько — они должны выполняться все вместе (система).', 'If there are several conditions, all must hold together (a system).')
    ] },
    { kind: 'table', h: L('Funksiyaning berilish usullari', 'Способы задания функции', 'Ways of giving a function'), p: [
      L('Bir xil bog‘lanishni turli usullarda ifodalash mumkin. Har bir usulning o‘z afzalligi va kamchiligi bor, shuning uchun amalda ular ko‘pincha birga ishlatiladi.', 'Одну и ту же зависимость можно выразить разными способами. У каждого способа свои плюсы и минусы, поэтому на практике их часто используют вместе.', 'The same dependence can be expressed in different ways. Each has its strengths and weaknesses, so in practice they are often used together.')
    ], table: { head: [L('Usul', 'Способ', 'Method'), L('Misol', 'Пример', 'Example'), L('Afzalligi', 'Плюс', 'Strength'), L('Kamchiligi', 'Минус', 'Weakness')], rows: [
      [L('Analitik (formula)', 'Аналитический (формула)', 'Analytic (formula)'), L('y = x² − 4', 'y = x² − 4', 'y = x² − 4'), L('istalgan qiymatni aniq hisoblash', 'точный расчёт любого значения', 'exact value anywhere'), L('ko‘rgazmali emas', 'не наглядно', 'not visual')],
      [L('Jadval', 'Табличный', 'Table'), L('soat — harorat', 'час — температура', 'hour — temperature'), L('tayyor qiymatlar', 'готовые значения', 'ready-made values'), L('faqat ayrim nuqtalar', 'только отдельные точки', 'only some points')],
      [L('Grafik', 'Графический', 'Graph'), L('kardiogramma', 'кардиограмма', 'cardiogram'), L('xossalar bir qarashda ko‘rinadi', 'свойства видны сразу', 'properties seen at a glance'), L('qiymatlar taxminiy', 'значения приближённые', 'values approximate')],
      [L('So‘z bilan', 'Словесный', 'In words'), L('«sonning butun qismi»', '«целая часть числа»', '“the integer part of a number”'), L('formula yo‘q bo‘lsa ham ishlaydi', 'работает и без формулы', 'works even without a formula'), L('hisoblash noqulay', 'неудобно вычислять', 'awkward to compute')]
    ] }, after: [
      L('Funksiya bir nechta formula bilan «bo‘lakli» ham berilishi mumkin. Masalan, |x| funksiyasi: x ≥ 0 da y = x, x &lt; 0 da y = −x. Bunday funksiyalar soliq shkalalari va telefon tariflarida tez-tez uchraydi.', 'Функция может задаваться и «кусочно» несколькими формулами. Например, |x|: при x ≥ 0 y = x, при x &lt; 0 y = −x. Такие функции часто встречаются в налоговых шкалах и тарифах связи.', 'A function can also be given “piecewise” by several formulas. For example |x|: y = x for x ≥ 0 and y = −x for x &lt; 0. Such functions are common in tax scales and phone tariffs.')
    ] },
    { kind: 'history', h: L('Funksiya tushunchasining tarixi', 'История понятия функции', 'History of the function concept'), p: [
      L('«Funksiya» (lotincha functio — bajarish) so‘zini birinchi bo‘lib 1673–1692-yillarda nemis olimi Gotfrid Leybnits ishlatgan, lekin u buni egri chiziq bilan bog‘liq kesmalar ma’nosida qo‘llagan. 1718-yilda Iogann Bernulli funksiyani «o‘zgaruvchi va o‘zgarmaslardan tuzilgan ifoda» deb ta’rifladi. Leonard Eyler 1734-yilda f(x) belgisini kiritdi — biz bugun ham undan foydalanamiz.', 'Слово «функция» (лат. functio — исполнение) первым употребил немецкий учёный Готфрид Лейбниц в 1673–1692 годах, но в смысле отрезков, связанных с кривой. В 1718 году Иоганн Бернулли определил функцию как «выражение, составленное из переменной и постоянных». Леонард Эйлер в 1734 году ввёл обозначение f(x), которым мы пользуемся и сегодня.', 'The word “function” (Latin functio — performance) was first used by the German scholar Gottfried Leibniz in 1673–1692, but for line segments related to a curve. In 1718 Johann Bernoulli defined a function as “an expression made of a variable and constants”. In 1734 Leonhard Euler introduced the notation f(x), which we still use today.'),
      L('Formula bo‘lishi shart emasligini XIX asrda Lobachevskiy (1834) va Dirixle (1837) ta’kidladilar: funksiya — bu har bir x ga y ni mos qo‘yadigan istalgan qoida. Dirixle hatto formula bilan yozish qiyin bo‘lgan funksiya misolini keltirgan: x ratsional bo‘lsa 1, irratsional bo‘lsa 0. Bu zamonaviy ta’rif bugun butun matematika va informatikaning asosida turadi — dasturlashdagi «funksiya» ham aynan shu g‘oya.', 'Что формула не обязательна, подчеркнули в XIX веке Лобачевский (1834) и Дирихле (1837): функция — это любое правило, сопоставляющее каждому x значение y. Дирихле даже привёл пример функции, которую трудно записать формулой: 1, если x рационально, и 0, если иррационально. Это современное определение лежит в основе всей математики и информатики — «функция» в программировании это та же идея.', 'In the 19th century Lobachevsky (1834) and Dirichlet (1837) stressed that a formula is not required: a function is any rule assigning y to each x. Dirichlet even gave a function hard to write as a formula: 1 if x is rational and 0 if it is irrational. This modern definition underlies all of mathematics and computer science — a “function” in programming is the same idea.')
    ] },
    { kind: 'steps', h: L('Aniqlanish sohasini topish algoritmi', 'Алгоритм нахождения области определения', 'Algorithm for finding the domain'), list: [
      L('1) Formulada «xavfli» joylarni toping: maxrajlar, juft darajali ildizlar, keyinroq — logarifmlar va tangens.', '1) Найдите в формуле «опасные» места: знаменатели, корни чётной степени, позже — логарифмы и тангенс.', '1) Find the “dangerous” spots in the formula: denominators, even roots and later logarithms and tangent.'),
      L('2) Har biri uchun shart yozing: maxraj ≠ 0, ildiz osti ≥ 0 (maxrajda bo‘lsa &gt; 0).', '2) Для каждого запишите условие: знаменатель ≠ 0, подкоренное ≥ 0 (в знаменателе — &gt; 0).', '2) Write a condition for each: denominator ≠ 0, radicand ≥ 0 (or &gt; 0 if it is in a denominator).'),
      L('3) Barcha shartlarni sistemaga birlashtiring va yeching.', '3) Объедините все условия в систему и решите её.', '3) Combine all conditions into a system and solve it.'),
      L('4) Javobni oraliqlar orqali yozing va son o‘qida tekshiring.', '4) Запишите ответ промежутками и проверьте на числовой прямой.', '4) Write the answer as intervals and check it on a number line.')
    ], after: [
      L('Qiymatlar to‘plamini topish odatda qiyinroq. Asosiy usullar: grafikdan foydalanish, to‘la kvadrat ajratish, a ≥ 0 (masalan, √u ≥ 0, x² ≥ 0) kabi baholar, yoki y = f(x) tenglamani x ga nisbatan yechib, qaysi y larda yechim mavjudligini tekshirish.', 'Найти множество значений обычно труднее. Основные приёмы: использовать график, выделить полный квадрат, применить оценки вроде √u ≥ 0, x² ≥ 0, или решить уравнение y = f(x) относительно x и выяснить, при каких y решение существует.', 'Finding the range is usually harder. Main methods: use the graph, complete the square, use bounds such as √u ≥ 0 and x² ≥ 0, or solve y = f(x) for x and see for which y a solution exists.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: aniqlanish sohasi', 'Решённые примеры: область определения', 'Worked examples: domain'), ex: [
      { q: L('y = √(6 − 2x) + 1/(x + 1) funksiyaning aniqlanish sohasini toping.', 'Найдите область определения y = √(6 − 2x) + 1/(x + 1).', 'Find the domain of y = √(6 − 2x) + 1/(x + 1).'),
        s: L('Shartlar: 6 − 2x ≥ 0 ⇒ x ≤ 3; x + 1 ≠ 0 ⇒ x ≠ −1. Birgalikda: D = (−∞; −1) ∪ (−1; 3].', 'Условия: 6 − 2x ≥ 0 ⇒ x ≤ 3; x + 1 ≠ 0 ⇒ x ≠ −1. Вместе: D = (−∞; −1) ∪ (−1; 3].', 'Conditions: 6 − 2x ≥ 0 ⇒ x ≤ 3; x + 1 ≠ 0 ⇒ x ≠ −1. Together: D = (−∞; −1) ∪ (−1; 3].') },
      { q: L('y = √(x² − 9) ning aniqlanish sohasini toping.', 'Найдите область определения y = √(x² − 9).', 'Find the domain of y = √(x² − 9).'),
        s: L('x² − 9 ≥ 0 ⇒ (x − 3)(x + 3) ≥ 0. Parabola shoxlari yuqoriga, ildizlar ±3, ildizlardan tashqarida musbat. D = (−∞; −3] ∪ [3; +∞).', 'x² − 9 ≥ 0 ⇒ (x − 3)(x + 3) ≥ 0. Ветви параболы вверх, корни ±3, вне корней положительна. D = (−∞; −3] ∪ [3; +∞).', 'x² − 9 ≥ 0 ⇒ (x − 3)(x + 3) ≥ 0. The parabola opens up with roots ±3 and is positive outside them. D = (−∞; −3] ∪ [3; +∞).') },
      { q: L('y = (x + 2)/√(4 − x) funksiyaning aniqlanish sohasini toping.', 'Найдите область определения y = (x + 2)/√(4 − x).', 'Find the domain of y = (x + 2)/√(4 − x).'),
        s: L('Ildiz maxrajda, shuning uchun 4 − x &gt; 0 ⇒ x &lt; 4. Surat cheklov bermaydi. D = (−∞; 4).', 'Корень в знаменателе, поэтому 4 − x &gt; 0 ⇒ x &lt; 4. Числитель ограничений не даёт. D = (−∞; 4).', 'The root is in the denominator, so 4 − x &gt; 0 ⇒ x &lt; 4. The numerator adds nothing. D = (−∞; 4).') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: qiymatlar to‘plami', 'Решённые примеры: множество значений', 'Worked examples: range'), ex: [
      { q: L('y = √(4 − x²) ning D va E to‘plamlarini toping.', 'Найдите D и E для y = √(4 − x²).', 'Find D and E for y = √(4 − x²).'),
        s: L('4 − x² ≥ 0 ⇒ D = [−2; 2]. Ildiz osti 0 dan (x = ±2 da) 4 gacha (x = 0 da) o‘zgaradi, demak y 0 dan 2 gacha. E = [0; 2]. Grafik — radiusi 2 bo‘lgan yarim aylana.', '4 − x² ≥ 0 ⇒ D = [−2; 2]. Подкоренное меняется от 0 (при x = ±2) до 4 (при x = 0), значит, y — от 0 до 2. E = [0; 2]. График — полуокружность радиуса 2.', '4 − x² ≥ 0 ⇒ D = [−2; 2]. The radicand ranges from 0 (at x = ±2) to 4 (at x = 0), so y ranges from 0 to 2. E = [0; 2]. The graph is a semicircle of radius 2.') },
      { q: L('y = x² − 6x + 10 ning qiymatlar to‘plamini toping.', 'Найдите множество значений y = x² − 6x + 10.', 'Find the range of y = x² − 6x + 10.'),
        s: L('To‘la kvadrat: y = (x − 3)² + 1. (x − 3)² ≥ 0 va istalgan manfiy bo‘lmagan qiymatni qabul qiladi, demak y ≥ 1. E = [1; +∞).', 'Полный квадрат: y = (x − 3)² + 1. (x − 3)² ≥ 0 и принимает любые неотрицательные значения, значит, y ≥ 1. E = [1; +∞).', 'Complete the square: y = (x − 3)² + 1. (x − 3)² ≥ 0 and takes every non-negative value, so y ≥ 1. E = [1; +∞).') },
      { q: L('y = 3 − 2√x ning qiymatlar to‘plamini toping.', 'Найдите множество значений y = 3 − 2√x.', 'Find the range of y = 3 − 2√x.'),
        s: L('√x istalgan qiymatni [0; +∞) dan oladi, −2√x esa (−∞; 0] dan. 3 qo‘shsak: E = (−∞; 3].', '√x принимает любые значения из [0; +∞), −2√x — из (−∞; 0]. Прибавив 3: E = (−∞; 3].', '√x takes every value in [0; +∞), so −2√x takes every value in (−∞; 0]. Adding 3: E = (−∞; 3].') },
      { q: L('y = 1/(x² + 1) ning qiymatlar to‘plamini toping.', 'Найдите множество значений y = 1/(x² + 1).', 'Find the range of y = 1/(x² + 1).'),
        s: L('x² + 1 ≥ 1, ya’ni maxraj [1; +∞) dan qiymat oladi. Unda 1/(x² + 1) ∈ (0; 1]: x = 0 da 1 ga teng, x o‘sgan sari 0 ga yaqinlashadi, lekin hech qachon 0 bo‘lmaydi. E = (0; 1].', 'x² + 1 ≥ 1, то есть знаменатель принимает значения из [1; +∞). Тогда 1/(x² + 1) ∈ (0; 1]: при x = 0 равна 1, с ростом x приближается к 0, но никогда не равна 0. E = (0; 1].', 'x² + 1 ≥ 1, so the denominator takes values in [1; +∞). Then 1/(x² + 1) ∈ (0; 1]: it equals 1 at x = 0 and approaches 0 as x grows, but is never 0. E = (0; 1].') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Formulani soddalashtirgandan keyin soha topish.</b> y = (x² − 1)/(x − 1) = x + 1, lekin x = 1 sohaga kirmaydi: grafik — «teshik»li to‘g‘ri chiziq.', '<b>Искать область после упрощения.</b> y = (x² − 1)/(x − 1) = x + 1, но x = 1 в область не входит: график — прямая с «выколотой» точкой.', '<b>Finding the domain after simplifying.</b> y = (x² − 1)/(x − 1) = x + 1, but x = 1 is excluded: the graph is a line with a hole.'),
      L('<b>Ildiz maxrajdaligini unutish:</b> 1/√x da x = 0 ham mumkin emas.', '<b>Забыть, что корень в знаменателе:</b> в 1/√x нельзя и x = 0.', '<b>Forgetting the root is in the denominator:</b> in 1/√x, x = 0 is also forbidden.'),
      L('<b>D va E ni almashtirib yuborish:</b> D — x lar (gorizontal o‘q), E — y lar (vertikal o‘q).', '<b>Путать D и E:</b> D — это x (горизонтальная ось), E — это y (вертикальная ось).', '<b>Mixing up D and E:</b> D is about x (horizontal axis), E is about y (vertical axis).'),
      L('<b>Har qanday egri chiziqni funksiya deb hisoblash.</b> Aylana funksiya grafigi emas — vertikal chiziq testidan o‘tmaydi.', '<b>Считать любую кривую графиком функции.</b> Окружность — не график функции: она не проходит тест вертикальной прямой.', '<b>Treating any curve as a function graph.</b> A circle is not one — it fails the vertical line test.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('Aniqlanish sohasi hayotda «ma’noli kirish qiymatlari» degani. Avtobusdagi yo‘lovchilar soni funksiyasi uchun x faqat 0 dan avtobus sig‘imigacha bo‘lgan butun sonlar; tezlik manfiy bo‘lolmaydi; inson bo‘yi 3 metr bo‘lmaydi. Muhandis model tuzayotganda birinchi navbatda shu chegaralarni belgilaydi.', 'Область определения в жизни означает «осмысленные входные значения». Для функции «число пассажиров в автобусе» x — только целые числа от 0 до вместимости автобуса; скорость не бывает отрицательной; рост человека не бывает 3 метра. Строя модель, инженер прежде всего задаёт эти границы.', 'In real life the domain means “meaningful inputs”. For the function “passengers on a bus”, x is only a whole number from 0 to the bus’s capacity; speed cannot be negative; nobody is 3 metres tall. When building a model an engineer sets these limits first.'),
      L('Dasturlashda funksiya sohasidan tashqari qiymat berish xatoga olib keladi: nolga bo‘lish dasturni to‘xtatadi, manfiy sonning kvadrat ildizi «NaN» (son emas) beradi. Shuning uchun yaxshi dasturchi ham, yaxshi matematik ham avval sohani tekshiradi. Kalkulyator 1/0 uchun «Error» ko‘rsatsa — u sizga aniqlanish sohasi haqida eslatyapti.', 'В программировании значение вне области определения приводит к ошибке: деление на ноль останавливает программу, корень из отрицательного числа даёт «NaN» (не число). Поэтому хороший программист, как и хороший математик, сначала проверяет область. Если калькулятор пишет «Error» на 1/0 — он напоминает вам об области определения.', 'In programming, an input outside the domain causes an error: division by zero crashes a program, and the square root of a negative number gives “NaN” (not a number). So a good programmer, like a good mathematician, checks the domain first. When a calculator shows “Error” for 1/0, it is reminding you about domains.'),
      L('Qiymatlar to‘plami esa natijaning chegaralarini beradi: masalan, ehtimollik doim [0; 1] oralig‘ida, foiz — [0; 100] da. Agar hisob-kitob natijasi bu chegaradan chiqsa, demak xato bor.', 'Множество значений задаёт границы результата: например, вероятность всегда в [0; 1], процент — в [0; 100]. Если результат расчёта выходит за эти границы, значит, где-то ошибка.', 'The range gives the limits of the output: a probability always lies in [0; 1] and a percentage in [0; 100]. If a computed result falls outside these limits, there is a mistake somewhere.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('f(x) = x² − 3x bo‘lsa, f(−2) va f(a + 1) ni toping.', 'Если f(x) = x² − 3x, найдите f(−2) и f(a + 1).', 'If f(x) = x² − 3x, find f(−2) and f(a + 1).'),
        s: L('f(−2) = 4 + 6 = 10. f(a + 1) = (a + 1)² − 3(a + 1) = a² + 2a + 1 − 3a − 3 = a² − a − 2.', 'f(−2) = 4 + 6 = 10. f(a + 1) = (a + 1)² − 3(a + 1) = a² + 2a + 1 − 3a − 3 = a² − a − 2.', 'f(−2) = 4 + 6 = 10. f(a + 1) = (a + 1)² − 3(a + 1) = a² + 2a + 1 − 3a − 3 = a² − a − 2.') },
      { q: L('y = 5/(x² − 4x) ning aniqlanish sohasini toping.', 'Найдите область определения y = 5/(x² − 4x).', 'Find the domain of y = 5/(x² − 4x).'),
        s: L('x² − 4x = x(x − 4) ≠ 0 ⇒ x ≠ 0, x ≠ 4. D = (−∞; 0) ∪ (0; 4) ∪ (4; +∞).', 'x² − 4x = x(x − 4) ≠ 0 ⇒ x ≠ 0, x ≠ 4. D = (−∞; 0) ∪ (0; 4) ∪ (4; +∞).', 'x² − 4x = x(x − 4) ≠ 0 ⇒ x ≠ 0, x ≠ 4. D = (−∞; 0) ∪ (0; 4) ∪ (4; +∞).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Funksiya — har bir x ∈ D ga yagona y ni mos qo‘yuvchi qoida.', 'Функция — правило, сопоставляющее каждому x ∈ D единственное y.', 'A function is a rule giving exactly one y for each x ∈ D.'),
      L('Berilish usullari: formula, jadval, grafik, so‘z bilan; bo‘lakli ham bo‘lishi mumkin.', 'Способы задания: формула, таблица, график, словами; бывает и кусочное задание.', 'Ways to give it: formula, table, graph, words; it can also be piecewise.'),
      L('D(f) — mumkin bo‘lgan x lar: maxraj ≠ 0, juft ildiz osti ≥ 0.', 'D(f) — допустимые x: знаменатель ≠ 0, под корнем чётной степени ≥ 0.', 'D(f) — allowed x: denominator ≠ 0, even radicand ≥ 0.'),
      L('E(f) — chiqadigan y lar: grafik, to‘la kvadrat va baholar yordamida topiladi.', 'E(f) — получающиеся y: находят по графику, выделением квадрата и оценками.', 'E(f) — the y that occur: found from the graph, by completing the square and by bounds.'),
      L('Vertikal chiziq testi: funksiya grafigini har bir vertikal chiziq ko‘pi bilan bir marta kesadi.', 'Тест вертикальной прямой: каждая вертикаль пересекает график функции не более одного раза.', 'Vertical line test: each vertical line meets a function’s graph at most once.'),
      L('f(x) belgisi Eylerga (1734), zamonaviy ta’rif Lobachevskiy va Dirixlega tegishli.', 'Обозначение f(x) — Эйлер (1734), современное определение — Лобачевский и Дирихле.', 'The notation f(x) is Euler’s (1734); the modern definition is due to Lobachevsky and Dirichlet.')
    ] }
  ] });

  // ---------- t3. Funksiyalar ustida amallar. Murakkab va teskari funksiya ----------
  T.add(P, 't3', { sections: [
    { kind: 'intro', h: L('Funksiyalarni ham qo‘shish mumkin', 'Функции тоже можно складывать', 'Functions can be combined too'), p: [
      L('Sonlarni qo‘shamiz, ayiramiz, ko‘paytiramiz. Funksiyalar ustida ham xuddi shunday amallar bajarish mumkin — va bundan tashqari, yana ikkita o‘ziga xos amal bor: funksiyalarni <b>ketma-ket qo‘llash</b> (kompozitsiya) va funksiyani <b>teskarisiga aylantirish</b>. Bu ikki g‘oya analizning eng muhim vositalaridan biri.', 'Числа мы складываем, вычитаем, умножаем. Над функциями можно выполнять такие же действия — и, кроме того, есть ещё два особых действия: <b>последовательное применение</b> функций (композиция) и <b>обращение</b> функции. Эти две идеи — одни из важнейших инструментов анализа.', 'We add, subtract and multiply numbers. We can do the same with functions — and there are two extra, special operations: applying functions <b>one after another</b> (composition) and <b>inverting</b> a function. These two ideas are among the most important tools of analysis.'),
      L('Kundalik misol: do‘kon tovar narxiga avval 20 % chegirma beradi, keyin kassada 15 % QQS qo‘shiladi. Bu ikki amalni ketma-ket bajarish — murakkab funksiya. Teskari funksiya esa «orqaga hisoblash»: chekdagi yakuniy summadan boshlang‘ich narxni topish. Dollarni so‘mga aylantirish funksiyasining teskarisi — so‘mni dollarga aylantirish.', 'Бытовой пример: магазин сначала даёт скидку 20 %, затем на кассе добавляется 15 % НДС. Выполнение двух действий подряд — сложная функция. Обратная функция — «обратный расчёт»: по итоговой сумме в чеке найти исходную цену. Обратная к функции перевода долларов в сумы — перевод сумов в доллары.', 'An everyday example: a shop first gives a 20 % discount, then 15 % VAT is added at the till. Doing the two steps in a row is a composite function. The inverse is “working backwards”: finding the original price from the total on the receipt. The inverse of converting dollars to soums is converting soums to dollars.')
    ] },
    { kind: 'def', h: L('Arifmetik amallar', 'Арифметические действия', 'Arithmetic operations'), p: [
      L('f va g funksiyalar umumiy to‘plamda aniqlangan bo‘lsin. Ularning yig‘indisi, ayirmasi, ko‘paytmasi va bo‘linmasi nuqtama-nuqta aniqlanadi: (f + g)(x) = f(x) + g(x), (f − g)(x) = f(x) − g(x), (f · g)(x) = f(x) · g(x), (f / g)(x) = f(x) / g(x). Natijaviy funksiyaning aniqlanish sohasi — D(f) va D(g) ning kesishmasi, bo‘linmada esa qo‘shimcha ravishda g(x) ≠ 0.', 'Пусть f и g определены на общем множестве. Их сумма, разность, произведение и частное определяются поточечно: (f + g)(x) = f(x) + g(x), (f − g)(x) = f(x) − g(x), (f · g)(x) = f(x) · g(x), (f / g)(x) = f(x) / g(x). Область определения результата — пересечение D(f) и D(g), а для частного дополнительно g(x) ≠ 0.', 'Let f and g be defined on a common set. Their sum, difference, product and quotient are defined pointwise: (f + g)(x) = f(x) + g(x), (f − g)(x) = f(x) − g(x), (f · g)(x) = f(x) · g(x), (f / g)(x) = f(x) / g(x). The domain of the result is the intersection of D(f) and D(g), and for the quotient also g(x) ≠ 0.'),
      L('Masalan, f(x) = √x va g(x) = x − 2 bo‘lsa, (f/g)(x) = √x/(x − 2) funksiyasi x ≥ 0 va x ≠ 2 da aniqlangan: D = [0; 2) ∪ (2; +∞). Murakkab ko‘rinishdagi formulalar odatda oddiy funksiyalardan shunday amallar bilan «yig‘ilgan» bo‘ladi.', 'Например, при f(x) = √x и g(x) = x − 2 функция (f/g)(x) = √x/(x − 2) определена при x ≥ 0 и x ≠ 2: D = [0; 2) ∪ (2; +∞). Сложные на вид формулы обычно «собраны» из простых функций именно такими действиями.', 'For example, with f(x) = √x and g(x) = x − 2, (f/g)(x) = √x/(x − 2) is defined for x ≥ 0 and x ≠ 2: D = [0; 2) ∪ (2; +∞). Complicated-looking formulas are usually “assembled” from simple functions by such operations.')
    ] },
    { kind: 'def', h: L('Murakkab funksiya (kompozitsiya)', 'Сложная функция (композиция)', 'Composite function'), p: [
      L('Agar avval x ga g funksiya qo‘llanib u = g(x) hosil qilinsa, so‘ng u ga f qo‘llansa, y = f(g(x)) funksiya hosil bo‘ladi. U f va g ning <b>kompozitsiyasi</b> yoki <b>murakkab funksiya</b> deyiladi va (f ∘ g)(x) deb ham yoziladi. g — <b>ichki</b>, f — <b>tashqi</b> funksiya. Hisoblash ichkaridan tashqariga qarab boradi.', 'Если сначала к x применить g и получить u = g(x), а затем к u применить f, получится функция y = f(g(x)). Она называется <b>композицией</b> f и g, или <b>сложной функцией</b>, и записывается также (f ∘ g)(x). g — <b>внутренняя</b>, f — <b>внешняя</b> функция. Вычисление идёт изнутри наружу.', 'If we first apply g to x to get u = g(x) and then apply f to u, we get y = f(g(x)). This is the <b>composition</b> of f and g, or a <b>composite function</b>, also written (f ∘ g)(x). g is the <b>inner</b> function and f the <b>outer</b> one. Evaluation goes from the inside out.'),
      L('Muhim: kompozitsiya odatda <b>o‘rin almashtirish xossasiga ega emas</b>, ya’ni f(g(x)) ≠ g(f(x)). f(x) = 2x + 1, g(x) = x² uchun f(g(x)) = 2x² + 1, g(f(x)) = (2x + 1)² = 4x² + 4x + 1. Paypoq va oyoq kiyimni kiyish tartibi ham ahamiyatli — avval paypoq, keyin tufli!', 'Важно: композиция, как правило, <b>не коммутативна</b>, то есть f(g(x)) ≠ g(f(x)). Для f(x) = 2x + 1, g(x) = x²: f(g(x)) = 2x² + 1, g(f(x)) = (2x + 1)² = 4x² + 4x + 1. Порядок надевания носков и обуви тоже важен — сначала носки, потом туфли!', 'Important: composition is usually <b>not commutative</b>: f(g(x)) ≠ g(f(x)). For f(x) = 2x + 1, g(x) = x²: f(g(x)) = 2x² + 1 but g(f(x)) = (2x + 1)² = 4x² + 4x + 1. The order of socks and shoes matters too — socks first, then shoes!'),
      L('Murakkab funksiyaning aniqlanish sohasi: x ∈ D(g) va bir vaqtda g(x) ∈ D(f). Masalan, y = √(1 − x²) da ichki funksiya 1 − x², tashqisi √u; shart 1 − x² ≥ 0.', 'Область определения сложной функции: x ∈ D(g) и одновременно g(x) ∈ D(f). Например, в y = √(1 − x²) внутренняя функция 1 − x², внешняя √u; условие 1 − x² ≥ 0.', 'Domain of a composite: x ∈ D(g) and at the same time g(x) ∈ D(f). For instance, in y = √(1 − x²) the inner function is 1 − x², the outer is √u, and the condition is 1 − x² ≥ 0.')
    ] },
    { kind: 'def', h: L('Teskari funksiya', 'Обратная функция', 'Inverse function'), p: [
      L('f funksiya turli x larga turli y larni mos qo‘ysa (ya’ni <b>o‘zaro bir qiymatli</b>, inyektiv bo‘lsa), u <b>qaytariluvchi</b> deyiladi. Bunda har bir y ∈ E(f) uchun f(x) = y bo‘ladigan yagona x mavjud. y ga shu x ni mos qo‘yuvchi funksiya f ning <b>teskari funksiyasi</b> f⁻¹ deyiladi. Ta’rifdan: f⁻¹(f(x)) = x va f(f⁻¹(y)) = y; D(f⁻¹) = E(f), E(f⁻¹) = D(f).', 'Если f разным x сопоставляет разные y (то есть <b>взаимно однозначна</b>, инъективна), она называется <b>обратимой</b>. Тогда для каждого y ∈ E(f) существует единственный x с f(x) = y. Функция, сопоставляющая y этот x, называется <b>обратной</b> к f и обозначается f⁻¹. Из определения: f⁻¹(f(x)) = x и f(f⁻¹(y)) = y; D(f⁻¹) = E(f), E(f⁻¹) = D(f).', 'If f sends different x to different y (it is <b>one-to-one</b>, injective), it is called <b>invertible</b>. Then each y ∈ E(f) comes from exactly one x with f(x) = y. The function sending y to that x is the <b>inverse</b> of f, written f⁻¹. By definition f⁻¹(f(x)) = x and f(f⁻¹(y)) = y; D(f⁻¹) = E(f), E(f⁻¹) = D(f).'),
      L('<b>Teorema.</b> Oraliqda qat’iy monoton (faqat o‘suvchi yoki faqat kamayuvchi) funksiya qaytariluvchi, teskari funksiya ham xuddi shunday monoton bo‘ladi. Isbot g‘oyasi: agar x₁ &lt; x₂ bo‘lsa, o‘suvchi funksiyada f(x₁) &lt; f(x₂), demak qiymatlar hech qachon takrorlanmaydi. y = x² butun ℝ da qaytarilmaydi (2 va −2 bir xil 4 ni beradi), lekin [0; +∞) da qaytariladi va teskarisi y = √x.', '<b>Теорема.</b> Строго монотонная на промежутке функция обратима, и обратная к ней монотонна в том же смысле. Идея доказательства: если x₁ &lt; x₂, то у возрастающей функции f(x₁) &lt; f(x₂), значит, значения никогда не повторяются. y = x² на всей ℝ необратима (2 и −2 дают одно и то же 4), но на [0; +∞) обратима, и обратная — y = √x.', '<b>Theorem.</b> A strictly monotonic function on an interval is invertible, and its inverse is monotonic in the same sense. Proof idea: if x₁ &lt; x₂, an increasing function gives f(x₁) &lt; f(x₂), so values never repeat. y = x² is not invertible on all of ℝ (2 and −2 both give 4), but on [0; +∞) it is, with inverse y = √x.')
    ] },
    { kind: 'steps', h: L('Teskari funksiyani topish algoritmi', 'Алгоритм нахождения обратной функции', 'How to find an inverse'), list: [
      L('1) Funksiya qaralayotgan oraliqda monotonligini (qaytariluvchiligini) tekshiring.', '1) Проверьте, что функция монотонна (обратима) на рассматриваемом промежутке.', '1) Check that the function is monotonic (invertible) on the interval in question.'),
      L('2) y = f(x) tenglikdan x ni y orqali ifodalang.', '2) Из равенства y = f(x) выразите x через y.', '2) From y = f(x) express x in terms of y.'),
      L('3) An’anaga ko‘ra harflarni almashtiring: x ↔ y. Hosil bo‘lgan y = f⁻¹(x) — teskari funksiya.', '3) По традиции поменяйте буквы: x ↔ y. Полученная y = f⁻¹(x) — обратная функция.', '3) By convention swap the letters x ↔ y. The resulting y = f⁻¹(x) is the inverse.'),
      L('4) Sohalarni yozing: D(f⁻¹) = E(f), E(f⁻¹) = D(f). Tekshiring: f(f⁻¹(x)) = x.', '4) Запишите области: D(f⁻¹) = E(f), E(f⁻¹) = D(f). Проверьте: f(f⁻¹(x)) = x.', '4) State the domains: D(f⁻¹) = E(f), E(f⁻¹) = D(f). Check: f(f⁻¹(x)) = x.')
    ], after: [
      L('<b>Grafik xossa.</b> Agar (a; b) nuqta f grafigida yotsa, (b; a) nuqta f⁻¹ grafigida yotadi. (a; b) va (b; a) nuqtalar y = x to‘g‘ri chiziqqa nisbatan simmetrik, shuning uchun f va f⁻¹ grafiklari y = x ga nisbatan o‘zaro simmetrik. Grafikni «oyna»da aks ettirgandek tasavvur qiling.', '<b>Графическое свойство.</b> Если точка (a; b) лежит на графике f, то точка (b; a) лежит на графике f⁻¹. Точки (a; b) и (b; a) симметричны относительно прямой y = x, поэтому графики f и f⁻¹ симметричны относительно y = x. Представьте отражение графика в «зеркале».', '<b>Graph property.</b> If (a; b) is on the graph of f, then (b; a) is on the graph of f⁻¹. The points (a; b) and (b; a) are mirror images in the line y = x, so the graphs of f and f⁻¹ are symmetric about y = x. Picture the graph reflected in a “mirror”.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Teskari amallar g‘oyasi juda qadimiy: qo‘shish — ayirish, ko‘paytirish — bo‘lish, kvadratga ko‘tarish — kvadrat ildiz chiqarish. Al-Xorazmiyning «al-jabr» (to‘ldirish) va «al-muqobala» (qarama-qarshi qo‘yish) amallari ham aslida tenglamaning ikki tomoniga teskari amallarni qo‘llashdir. XVII asrda Jon Neper logarifmlarni kashf etganida, ular ko‘rsatkichli funksiyaga teskari funksiya ekanligi keyinroq, Eyler davrida aniq tushunildi.', 'Идея обратных действий очень древняя: сложение — вычитание, умножение — деление, возведение в квадрат — извлечение корня. Действия аль-Хорезми «аль-джабр» (восполнение) и «аль-мукабала» (противопоставление) — это, по сути, применение обратных действий к обеим частям уравнения. Когда в XVII веке Джон Непер открыл логарифмы, то, что они обратны показательной функции, ясно поняли позже, во времена Эйлера.', 'The idea of inverse operations is very old: addition and subtraction, multiplication and division, squaring and square roots. Al-Khwarizmi’s operations “al-jabr” (restoring) and “al-muqabala” (balancing) are really applying inverse operations to both sides of an equation. When John Napier discovered logarithms in the 17th century, the fact that they are inverse to the exponential function was clearly understood only later, in Euler’s time.'),
      L('f⁻¹ belgisini 1813-yilda ingliz matematigi Jon Gershel taklif qilgan. Kompozitsiya uchun ∘ belgisi esa XX asrda keng tarqaldi. Bugun kompozitsiya dasturlashda «quvur» (pipeline) g‘oyasi sifatida yashaydi: bir funksiyaning chiqishi keyingisining kirishiga uzatiladi.', 'Обозначение f⁻¹ предложил английский математик Джон Гершель в 1813 году. Знак ∘ для композиции широко распространился в XX веке. Сегодня композиция живёт в программировании как идея «конвейера» (pipeline): выход одной функции передаётся на вход следующей.', 'The notation f⁻¹ was proposed by the English mathematician John Herschel in 1813. The ∘ sign for composition spread in the 20th century. Today composition lives on in programming as the “pipeline” idea: one function’s output is fed into the next one’s input.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: kompozitsiya', 'Решённые примеры: композиция', 'Worked examples: composition'), ex: [
      { q: L('f(x) = 2x + 1, g(x) = x². f(g(3)), g(f(3)) va f(f(x)) ni toping.', 'f(x) = 2x + 1, g(x) = x². Найдите f(g(3)), g(f(3)) и f(f(x)).', 'f(x) = 2x + 1, g(x) = x². Find f(g(3)), g(f(3)) and f(f(x)).'),
        s: L('g(3) = 9, f(9) = 19. f(3) = 7, g(7) = 49. f(f(x)) = 2(2x + 1) + 1 = 4x + 3. Natijalar turlicha — tartib muhim.', 'g(3) = 9, f(9) = 19. f(3) = 7, g(7) = 49. f(f(x)) = 2(2x + 1) + 1 = 4x + 3. Результаты разные — порядок важен.', 'g(3) = 9, f(9) = 19. f(3) = 7, g(7) = 49. f(f(x)) = 2(2x + 1) + 1 = 4x + 3. The results differ — order matters.') },
      { q: L('y = (3x − 1)⁵ funksiyani ikki sodda funksiyaning kompozitsiyasi ko‘rinishida yozing.', 'Запишите y = (3x − 1)⁵ как композицию двух простых функций.', 'Write y = (3x − 1)⁵ as a composition of two simple functions.'),
        s: L('Ichki funksiya u = g(x) = 3x − 1, tashqi f(u) = u⁵. Demak y = f(g(x)).', 'Внутренняя функция u = g(x) = 3x − 1, внешняя f(u) = u⁵. Значит, y = f(g(x)).', 'Inner function u = g(x) = 3x − 1, outer f(u) = u⁵. So y = f(g(x)).') },
      { q: L('f(x) = √x, g(x) = 5 − x. f(g(x)) ning aniqlanish sohasini toping.', 'f(x) = √x, g(x) = 5 − x. Найдите область определения f(g(x)).', 'f(x) = √x, g(x) = 5 − x. Find the domain of f(g(x)).'),
        s: L('f(g(x)) = √(5 − x). g(x) ∈ D(f) bo‘lishi kerak: 5 − x ≥ 0 ⇒ x ≤ 5. D = (−∞; 5].', 'f(g(x)) = √(5 − x). Нужно g(x) ∈ D(f): 5 − x ≥ 0 ⇒ x ≤ 5. D = (−∞; 5].', 'f(g(x)) = √(5 − x). We need g(x) ∈ D(f): 5 − x ≥ 0 ⇒ x ≤ 5. D = (−∞; 5].') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: teskari funksiya', 'Решённые примеры: обратная функция', 'Worked examples: inverse'), ex: [
      { q: L('y = 2x + 1 ga teskari funksiyani toping.', 'Найдите функцию, обратную к y = 2x + 1.', 'Find the inverse of y = 2x + 1.'),
        s: L('Funksiya o‘suvchi, demak qaytariluvchi. x = (y − 1)/2. Harflarni almashtiramiz: f⁻¹(x) = (x − 1)/2. Tekshirish: f(f⁻¹(x)) = 2 · (x − 1)/2 + 1 = x.', 'Функция возрастает, значит, обратима. x = (y − 1)/2. Меняем буквы: f⁻¹(x) = (x − 1)/2. Проверка: f(f⁻¹(x)) = 2 · (x − 1)/2 + 1 = x.', 'The function increases, so it is invertible. x = (y − 1)/2. Swap letters: f⁻¹(x) = (x − 1)/2. Check: f(f⁻¹(x)) = 2 · (x − 1)/2 + 1 = x.') },
      { q: L('y = x² + 2, x ≥ 0 ga teskari funksiyani toping.', 'Найдите обратную к y = x² + 2, x ≥ 0.', 'Find the inverse of y = x² + 2, x ≥ 0.'),
        s: L('x ≥ 0 da funksiya o‘suvchi, E = [2; +∞). x² = y − 2, x ≥ 0 bo‘lgani uchun x = √(y − 2). Javob: f⁻¹(x) = √(x − 2), D(f⁻¹) = [2; +∞), E(f⁻¹) = [0; +∞).', 'При x ≥ 0 функция возрастает, E = [2; +∞). x² = y − 2, и так как x ≥ 0, x = √(y − 2). Ответ: f⁻¹(x) = √(x − 2), D(f⁻¹) = [2; +∞), E(f⁻¹) = [0; +∞).', 'For x ≥ 0 the function increases, E = [2; +∞). x² = y − 2 and since x ≥ 0, x = √(y − 2). Answer: f⁻¹(x) = √(x − 2), D(f⁻¹) = [2; +∞), E(f⁻¹) = [0; +∞).') },
      { q: L('y = 3/(x − 1) ga teskari funksiyani toping.', 'Найдите обратную к y = 3/(x − 1).', 'Find the inverse of y = 3/(x − 1).'),
        s: L('y(x − 1) = 3 ⇒ x = 1 + 3/y. Harflarni almashtiramiz: f⁻¹(x) = 1 + 3/x, x ≠ 0. Bu funksiya f ning qiymatlar to‘plami y ≠ 0 da aniqlangan — hammasi mos.', 'y(x − 1) = 3 ⇒ x = 1 + 3/y. Меняем буквы: f⁻¹(x) = 1 + 3/x, x ≠ 0. Она определена на множестве значений f: y ≠ 0 — всё сходится.', 'y(x − 1) = 3 ⇒ x = 1 + 3/y. Swap letters: f⁻¹(x) = 1 + 3/x, x ≠ 0. It is defined on the range of f, y ≠ 0 — everything matches.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>f⁻¹(x) ni 1/f(x) deb o‘ylash.</b> f⁻¹ — teskari funksiya, daraja emas: y = 2x uchun f⁻¹(x) = x/2, 1/(2x) emas.', '<b>Считать f⁻¹(x) равным 1/f(x).</b> f⁻¹ — обратная функция, а не степень: для y = 2x f⁻¹(x) = x/2, а не 1/(2x).', '<b>Thinking f⁻¹(x) means 1/f(x).</b> f⁻¹ is the inverse function, not a power: for y = 2x, f⁻¹(x) = x/2, not 1/(2x).'),
      L('<b>Kompozitsiya tartibini almashtirish.</b> f(g(x)) da avval g hisoblanadi.', '<b>Путать порядок композиции.</b> В f(g(x)) сначала вычисляется g.', '<b>Swapping the order of composition.</b> In f(g(x)), g is computed first.'),
      L('<b>Qaytarilmaydigan funksiyaga teskari topish.</b> y = x² uchun «f⁻¹ = √x» faqat x ≥ 0 cheklovi bilan to‘g‘ri.', '<b>Искать обратную к необратимой функции.</b> Для y = x² «f⁻¹ = √x» верно только с ограничением x ≥ 0.', '<b>Inverting a non-invertible function.</b> For y = x², “f⁻¹ = √x” is right only with the restriction x ≥ 0.'),
      L('<b>Sohalarni unutish:</b> D(f⁻¹) = E(f). y = √x ning teskarisi y = x², lekin faqat x ≥ 0 da.', '<b>Забывать про области:</b> D(f⁻¹) = E(f). Обратная к y = √x — y = x², но только при x ≥ 0.', '<b>Forgetting the domains:</b> D(f⁻¹) = E(f). The inverse of y = √x is y = x², but only for x ≥ 0.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Valyuta va o‘lchov birliklari.</b> Selsiydan Farengeytga o‘tish F = 1,8C + 32; teskarisi C = (F − 32)/1,8. Ob-havo ilovasi aynan shu ikki funksiyadan foydalanadi.', '<b>Валюты и единицы измерения.</b> Перевод из Цельсия в Фаренгейт F = 1,8C + 32; обратный C = (F − 32)/1,8. Приложение погоды пользуется именно этими двумя функциями.', '<b>Currency and units.</b> Celsius to Fahrenheit is F = 1.8C + 32; the inverse is C = (F − 32)/1.8. A weather app uses exactly these two functions.'),
      L('<b>Shifrlash.</b> Shifrlash funksiyasi matnni kodga aylantiradi, deshifrlash — uning teskarisi. Agar funksiya qaytarilmasa, xabarni tiklab bo‘lmaydi. Zamonaviy kriptografiya «bir tomonlama» funksiyalarga tayanadi: to‘g‘ri yo‘nalishda hisoblash oson, teskarisini maxfiy kalitsiz topish deyarli imkonsiz.', '<b>Шифрование.</b> Функция шифрования превращает текст в код, расшифровка — обратная к ней. Если функция необратима, сообщение не восстановить. Современная криптография опирается на «односторонние» функции: в прямом направлении считать легко, а обратную без секретного ключа найти практически невозможно.', '<b>Encryption.</b> An encryption function turns text into code; decryption is its inverse. If the function were not invertible, the message could not be recovered. Modern cryptography relies on “one-way” functions: easy to compute forwards, practically impossible to invert without the secret key.'),
      L('<b>Ishlab chiqarish.</b> Zavodda xomashyo bir necha bosqichdan o‘tadi: har bir bosqich — funksiya, butun jarayon — ularning kompozitsiyasi. Fotosuratga ketma-ket filtrlar qo‘yish ham kompozitsiya, «bekor qilish» (Ctrl+Z) tugmasi esa teskari funksiyani bajaradi.', '<b>Производство.</b> На заводе сырьё проходит несколько стадий: каждая стадия — функция, весь процесс — их композиция. Наложение фильтров на фото подряд — тоже композиция, а кнопка «отменить» (Ctrl+Z) выполняет обратную функцию.', '<b>Manufacturing.</b> In a factory raw material passes through several stages: each stage is a function, the whole process their composition. Applying photo filters one after another is also composition, and the “undo” button (Ctrl+Z) performs an inverse.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('f(x) = x − 4, g(x) = √x. g(f(13)) va f(g(13)) qaysi biri butun son?', 'f(x) = x − 4, g(x) = √x. Какое из g(f(13)) и f(g(13)) — целое число?', 'f(x) = x − 4, g(x) = √x. Which of g(f(13)) and f(g(13)) is an integer?'),
        s: L('g(f(13)) = √9 = 3 — butun. f(g(13)) = √13 − 4 — irratsional.', 'g(f(13)) = √9 = 3 — целое. f(g(13)) = √13 − 4 — иррационально.', 'g(f(13)) = √9 = 3 — an integer. f(g(13)) = √13 − 4 is irrational.') },
      { q: L('y = x³ ga teskari funksiya nima?', 'Какая функция обратна к y = x³?', 'What is the inverse of y = x³?'),
        s: L('y = x³ butun ℝ da o‘suvchi, demak qaytariluvchi: f⁻¹(x) = ∛x, D = E = ℝ.', 'y = x³ возрастает на всей ℝ, значит, обратима: f⁻¹(x) = ∛x, D = E = ℝ.', 'y = x³ increases on all of ℝ, so it is invertible: f⁻¹(x) = ∛x, D = E = ℝ.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('(f ± g), f · g, f / g nuqtama-nuqta aniqlanadi; soha — umumiy qism (bo‘linmada g ≠ 0).', '(f ± g), f · g, f / g определяются поточечно; область — общая часть (в частном g ≠ 0).', 'f ± g, f · g, f / g are defined pointwise; the domain is the common part (g ≠ 0 for a quotient).'),
      L('Murakkab funksiya f(g(x)): avval ichki g, so‘ng tashqi f; tartib muhim.', 'Сложная функция f(g(x)): сначала внутренняя g, затем внешняя f; порядок важен.', 'Composite f(g(x)): first the inner g, then the outer f; order matters.'),
      L('Qat’iy monoton funksiya qaytariluvchi.', 'Строго монотонная функция обратима.', 'A strictly monotonic function is invertible.'),
      L('Teskarisini topish: x ni y orqali ifodalash, so‘ng x ↔ y.', 'Нахождение обратной: выразить x через y, затем x ↔ y.', 'To invert: express x via y, then swap x ↔ y.'),
      L('f(f⁻¹(x)) = x, D(f⁻¹) = E(f), E(f⁻¹) = D(f).', 'f(f⁻¹(x)) = x, D(f⁻¹) = E(f), E(f⁻¹) = D(f).', 'f(f⁻¹(x)) = x, D(f⁻¹) = E(f), E(f⁻¹) = D(f).'),
      L('f va f⁻¹ grafiklari y = x to‘g‘ri chiziqqa nisbatan simmetrik.', 'Графики f и f⁻¹ симметричны относительно прямой y = x.', 'The graphs of f and f⁻¹ are symmetric about the line y = x.')
    ] }
  ] });

  // ---------- t4. Davriy funksiyalar. Funksiya xossalari ----------
  T.add(P, 't4', { sections: [
    { kind: 'intro', h: L('Takrorlanadigan dunyo', 'Повторяющийся мир', 'A world of repetition'), p: [
      L('Kun va tun almashinadi, fasllar har yili qaytadi, yurak har soniyada deyarli bir xil zarb qiladi, soat millari har 12 soatda avvalgi holatiga keladi. Bunday takrorlanuvchi jarayonlarni matematikada <b>davriy funksiyalar</b> tasvirlaydi. Ularning eng muhimlari — sin x va cos x.', 'День сменяется ночью, времена года возвращаются каждый год, сердце бьётся почти одинаково каждую секунду, стрелки часов каждые 12 часов возвращаются в прежнее положение. Такие повторяющиеся процессы в математике описывают <b>периодические функции</b>. Важнейшие из них — sin x и cos x.', 'Day follows night, the seasons return every year, the heart beats almost identically every second, and clock hands return to the same position every 12 hours. Such repeating processes are described by <b>periodic functions</b>. The most important are sin x and cos x.'),
      L('Bu mavzuda biz davriylikdan tashqari funksiyaning boshqa asosiy xossalarini ham tizimlashtiramiz: juft-toqlik, nollar, ishora saqlanish oraliqlari, monotonlik, eng katta va eng kichik qiymatlar, chegaralanganlik. Bu xossalar ro‘yxati — funksiyani «tekshirish rejasi», u keyinchalik hosila yordamida chuqurroq o‘rganiladi.', 'В этой теме, кроме периодичности, мы систематизируем и другие основные свойства функции: чётность, нули, промежутки знакопостоянства, монотонность, наибольшее и наименьшее значения, ограниченность. Этот список — «план исследования» функции, который позже углубится с помощью производной.', 'Besides periodicity, this topic organises the other main properties of a function: parity, zeros, intervals of constant sign, monotonicity, largest and smallest values and boundedness. This list is a “plan for investigating” a function, which will later be deepened with derivatives.')
    ] },
    { kind: 'def', h: L('Davriy funksiya ta’rifi', 'Определение периодической функции', 'Definition of a periodic function'), p: [
      L('Agar shunday T ≠ 0 son mavjud bo‘lsaki, aniqlanish sohasidagi har bir x uchun x + T va x − T ham sohaga tegishli bo‘lsa va <b>f(x + T) = f(x)</b> bajarilsa, f <b>davriy funksiya</b>, T esa uning <b>davri</b> deyiladi. Agar T davr bo‘lsa, 2T, 3T, −T ham davr bo‘ladi. Shuning uchun odatda <b>eng kichik musbat davr</b> haqida gapiriladi.', 'Если существует число T ≠ 0 такое, что для каждого x из области определения x + T и x − T тоже принадлежат области и <b>f(x + T) = f(x)</b>, то f называется <b>периодической</b>, а T — её <b>периодом</b>. Если T — период, то 2T, 3T, −T — тоже периоды. Поэтому обычно говорят о <b>наименьшем положительном периоде</b>.', 'If there is a number T ≠ 0 such that for every x in the domain x + T and x − T are also in the domain and <b>f(x + T) = f(x)</b>, then f is <b>periodic</b> and T is a <b>period</b>. If T is a period, so are 2T, 3T and −T, so we usually speak of the <b>smallest positive period</b>.'),
      L('Davriy funksiyaning grafigi uzunligi T bo‘lgan bitta bo‘lakni chizib, keyin uni Ox o‘qi bo‘ylab o‘ngga va chapga cheksiz «ko‘chirish» orqali hosil qilinadi — xuddi gilam naqshi kabi. sin x va cos x ning eng kichik musbat davri 2π, tg x va ctg x niki π. Doimiy funksiya y = c ham davriy, lekin uning eng kichik musbat davri yo‘q — har qanday son davr bo‘ladi.', 'График периодической функции получается так: рисуют один кусок длины T, а затем бесконечно «переносят» его вдоль Ox вправо и влево — как узор ковра. Наименьший положительный период sin x и cos x равен 2π, tg x и ctg x — π. Постоянная y = c тоже периодична, но наименьшего положительного периода у неё нет — периодом служит любое число.', 'The graph of a periodic function is made by drawing one piece of length T and then “copying” it endlessly left and right along Ox — like a carpet pattern. sin x and cos x have smallest positive period 2π; tan x and cot x have π. The constant y = c is periodic too, but has no smallest positive period — every number is a period.')
    ] },
    { kind: 'rule', h: L('sin kx ning davri', 'Период sin kx', 'The period of sin kx'), p: [
      L('<b>Teorema.</b> Agar f ning eng kichik musbat davri T bo‘lsa, y = f(kx + b) (k ≠ 0) funksiyaning eng kichik musbat davri T/|k|. Isbot g‘oyasi: f(k(x + T/k) + b) = f(kx + b + T) = f(kx + b). Demak sin kx va cos kx ning davri 2π/|k|, tg kx niki π/|k|.', '<b>Теорема.</b> Если наименьший положительный период f равен T, то у y = f(kx + b) (k ≠ 0) наименьший положительный период T/|k|. Идея доказательства: f(k(x + T/k) + b) = f(kx + b + T) = f(kx + b). Значит, период sin kx и cos kx равен 2π/|k|, tg kx — π/|k|.', '<b>Theorem.</b> If f has smallest positive period T, then y = f(kx + b) (k ≠ 0) has smallest positive period T/|k|. Proof idea: f(k(x + T/k) + b) = f(kx + b + T) = f(kx + b). So sin kx and cos kx have period 2π/|k| and tan kx has π/|k|.'),
      L('Ikki davriy funksiya yig‘indisi davriy bo‘lishi uchun davrlar nisbati ratsional bo‘lishi kerak; bunda yig‘indining davri — davrlarning eng kichik umumiy karralisi. Masalan, sin 2x (davri π) + cos 3x (davri 2π/3) uchun EKUK(π; 2π/3) = 2π.', 'Чтобы сумма двух периодических функций была периодической, отношение периодов должно быть рациональным; тогда период суммы — наименьшее общее кратное периодов. Например, для sin 2x (период π) + cos 3x (период 2π/3) НОК(π; 2π/3) = 2π.', 'For a sum of two periodic functions to be periodic, the ratio of the periods must be rational; then the period of the sum is the least common multiple of the periods. For sin 2x (period π) + cos 3x (period 2π/3), LCM(π; 2π/3) = 2π.')
    ] },
    { kind: 'def', h: L('Juft va toq funksiyalar', 'Чётные и нечётные функции', 'Even and odd functions'), p: [
      L('Aniqlanish sohasi 0 ga nisbatan simmetrik bo‘lgan (x ∈ D bo‘lsa, −x ∈ D) f funksiya barcha x uchun <b>f(−x) = f(x)</b> bo‘lsa — <b>juft</b>, <b>f(−x) = −f(x)</b> bo‘lsa — <b>toq</b> deyiladi. Juft funksiya grafigi Oy o‘qiga nisbatan, toq funksiya grafigi koordinata boshiga nisbatan simmetrik. Misollar: x², |x|, cos x — juft; x³, 1/x, sin x, tg x — toq; x² + x — na juft, na toq.', 'Функция f с симметричной относительно 0 областью определения (если x ∈ D, то −x ∈ D) называется <b>чётной</b>, если для всех x <b>f(−x) = f(x)</b>, и <b>нечётной</b>, если <b>f(−x) = −f(x)</b>. График чётной функции симметричен относительно оси Oy, нечётной — относительно начала координат. Примеры: x², |x|, cos x — чётные; x³, 1/x, sin x, tg x — нечётные; x² + x — ни та, ни другая.', 'A function f whose domain is symmetric about 0 (x ∈ D implies −x ∈ D) is <b>even</b> if <b>f(−x) = f(x)</b> for all x and <b>odd</b> if <b>f(−x) = −f(x)</b>. An even graph is symmetric about the Oy axis, an odd graph about the origin. Examples: x², |x|, cos x are even; x³, 1/x, sin x, tan x are odd; x² + x is neither.'),
      L('Bu xossa ishni ikki baravar qisqartiradi: grafikning faqat x ≥ 0 qismini chizib, qolganini simmetriya bilan to‘ldirish yetarli. Agar soha simmetrik bo‘lmasa (masalan, √x), funksiya juft ham, toq ham bo‘lolmaydi.', 'Это свойство сокращает работу вдвое: достаточно нарисовать часть графика при x ≥ 0, а остальное достроить по симметрии. Если область несимметрична (например, √x), функция не может быть ни чётной, ни нечётной.', 'This halves the work: draw only the part for x ≥ 0 and complete the rest by symmetry. If the domain is not symmetric (e.g. √x), the function can be neither even nor odd.')
    ] },
    { kind: 'table', h: L('Funksiyani tekshirish rejasi', 'План исследования функции', 'Plan for investigating a function'), table: { head: [L('Xossa', 'Свойство', 'Property'), L('Savol', 'Вопрос', 'Question'), L('y = x² − 4 uchun', 'для y = x² − 4', 'for y = x² − 4')], rows: [
      [L('Aniqlanish sohasi', 'Область определения', 'Domain'), L('Qaysi x lar mumkin?', 'Какие x допустимы?', 'Which x are allowed?'), L('ℝ', 'ℝ', 'ℝ')],
      [L('Qiymatlar to‘plami', 'Множество значений', 'Range'), L('Qaysi y lar chiqadi?', 'Какие y получаются?', 'Which y occur?'), L('[−4; +∞)', '[−4; +∞)', '[−4; +∞)')],
      [L('Nollari', 'Нули', 'Zeros'), L('f(x) = 0 qachon?', 'Когда f(x) = 0?', 'When is f(x) = 0?'), L('x = ±2', 'x = ±2', 'x = ±2')],
      [L('Ishorasi', 'Знакопостоянство', 'Sign'), L('Qayerda &gt; 0, &lt; 0?', 'Где &gt; 0, &lt; 0?', 'Where &gt; 0, &lt; 0?'), L('|x| &gt; 2 da musbat, |x| &lt; 2 da manfiy', 'положительна при |x| &gt; 2, отрицательна при |x| &lt; 2', 'positive for |x| &gt; 2, negative for |x| &lt; 2')],
      [L('Juft-toqlik', 'Чётность', 'Parity'), L('f(−x) = ±f(x)?', 'f(−x) = ±f(x)?', 'f(−x) = ±f(x)?'), L('juft', 'чётная', 'even')],
      [L('Monotonlik', 'Монотонность', 'Monotonicity'), L('Qayerda o‘sadi/kamayadi?', 'Где растёт/убывает?', 'Where up/down?'), L('(−∞; 0] da kamayadi, [0; +∞) da o‘sadi', 'убывает на (−∞; 0], растёт на [0; +∞)', 'decreases on (−∞; 0], increases on [0; +∞)')],
      [L('Ekstremum', 'Экстремум', 'Extremum'), L('Eng katta/kichik qiymat?', 'Наиб./наим. значение?', 'Max/min value?'), L('min = −4 (x = 0 da)', 'min = −4 (при x = 0)', 'min = −4 (at x = 0)')],
      [L('Davriylik', 'Периодичность', 'Periodicity'), L('f(x + T) = f(x)?', 'f(x + T) = f(x)?', 'f(x + T) = f(x)?'), L('davriy emas', 'непериодическая', 'not periodic')]
    ] } },
    { kind: 'def', h: L('Monotonlik va ekstremumlar', 'Монотонность и экстремумы', 'Monotonicity and extrema'), p: [
      L('f funksiya I oraliqda <b>o‘suvchi</b> deyiladi, agar shu oraliqdagi istalgan x₁ &lt; x₂ uchun f(x₁) &lt; f(x₂) bo‘lsa; <b>kamayuvchi</b> — agar f(x₁) &gt; f(x₂) bo‘lsa. Grafik tilida: chapdan o‘ngga yurganda o‘suvchi funksiya grafigi «tepaga chiqadi», kamayuvchisi «pastga tushadi».', 'Функция f называется <b>возрастающей</b> на промежутке I, если для любых x₁ &lt; x₂ из I выполняется f(x₁) &lt; f(x₂), и <b>убывающей</b>, если f(x₁) &gt; f(x₂). На языке графиков: при движении слева направо график возрастающей функции «идёт в гору», убывающей — «под гору».', 'f is <b>increasing</b> on an interval I if for any x₁ &lt; x₂ in I we have f(x₁) &lt; f(x₂), and <b>decreasing</b> if f(x₁) &gt; f(x₂). In graph terms: moving left to right, an increasing graph “goes uphill” and a decreasing one “downhill”.'),
      L('x₀ nuqtaning biror atrofida barcha x lar uchun f(x) ≤ f(x₀) bo‘lsa, x₀ — <b>maksimum nuqtasi</b>; f(x) ≥ f(x₀) bo‘lsa — <b>minimum nuqtasi</b>. Ular umumiy nom bilan <b>ekstremumlar</b> deyiladi. Mahalliy maksimum butun funksiyaning eng katta qiymati bo‘lishi shart emas — tog‘ tizmasidagi har bir cho‘qqi eng baland cho‘qqi emas. Funksiya <b>chegaralangan</b> deyiladi, agar |f(x)| ≤ M bo‘lsa; masalan, |sin x| ≤ 1.', 'Если в некоторой окрестности точки x₀ для всех x выполняется f(x) ≤ f(x₀), то x₀ — <b>точка максимума</b>; если f(x) ≥ f(x₀) — <b>точка минимума</b>. Вместе они называются <b>экстремумами</b>. Локальный максимум не обязан быть наибольшим значением всей функции — не каждая вершина горного хребта самая высокая. Функция <b>ограничена</b>, если |f(x)| ≤ M; например, |sin x| ≤ 1.', 'If near x₀ we have f(x) ≤ f(x₀) for all x, x₀ is a <b>maximum point</b>; if f(x) ≥ f(x₀), a <b>minimum point</b>. Together they are called <b>extrema</b>. A local maximum need not be the largest value of the whole function — not every peak of a mountain range is the highest. A function is <b>bounded</b> if |f(x)| ≤ M; for instance |sin x| ≤ 1.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Davriy hodisalarni o‘rganish astronomiyadan boshlangan. Bobil va qadimgi Hind astronomlari Oy fazalari va sayyoralar harakatining davrlarini juda aniq hisoblashgan. Mirzo Ulug‘bek rasadxonasida (Samarqand, XV asr) yil uzunligi 365 kun 6 soat 10 daqiqa deb topilgan — bu hozirgi qiymatdan bor-yo‘g‘i taxminan bir daqiqaga farq qiladi. Ulug‘bek jadvallarida sinuslar ham juda yuqori aniqlikda hisoblangan.', 'Изучение периодических явлений началось с астрономии. Вавилонские и древнеиндийские астрономы очень точно вычисляли периоды фаз Луны и движения планет. В обсерватории Мирзо Улугбека (Самарканд, XV век) длина года была определена как 365 дней 6 часов 10 минут — это отличается от современного значения всего примерно на минуту. В таблицах Улугбека и синусы вычислены с очень высокой точностью.', 'The study of periodic phenomena began with astronomy. Babylonian and ancient Indian astronomers computed the periods of the Moon’s phases and planetary motion very precisely. At Mirzo Ulugbek’s observatory (Samarkand, 15th century) the length of the year was found as 365 days 6 hours 10 minutes — only about a minute off the modern value. Ulugbek’s tables also give sines to very high accuracy.'),
      L('1807-yilda fransuz olimi Jozef Furye ajoyib g‘oyani ilgari surdi: deyarli har qanday davriy jarayonni sinus va kosinuslar yig‘indisi ko‘rinishida yozish mumkin. Bu «Furye qatorlari» bugun musiqani MP3 formatida siqish, rasmni JPEG da saqlash va radio signallarini qayta ishlashda qo‘llaniladi.', 'В 1807 году французский учёный Жозеф Фурье выдвинул замечательную идею: почти любой периодический процесс можно записать как сумму синусов и косинусов. Эти «ряды Фурье» сегодня используются при сжатии музыки в MP3, сохранении изображений в JPEG и обработке радиосигналов.', 'In 1807 the French scientist Joseph Fourier put forward a remarkable idea: almost any periodic process can be written as a sum of sines and cosines. These “Fourier series” are used today to compress music into MP3, store pictures as JPEG and process radio signals.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('y = sin(3x − 1) va y = tg(x/2) ning eng kichik musbat davrini toping.', 'Найдите наименьший положительный период y = sin(3x − 1) и y = tg(x/2).', 'Find the smallest positive period of y = sin(3x − 1) and y = tan(x/2).'),
        s: L('sin(3x − 1): T = 2π/3. tg(x/2): k = 1/2, T = π/(1/2) = 2π.', 'sin(3x − 1): T = 2π/3. tg(x/2): k = 1/2, T = π/(1/2) = 2π.', 'sin(3x − 1): T = 2π/3. tan(x/2): k = 1/2, T = π/(1/2) = 2π.') },
      { q: L('f(x) = x³ − 5x funksiyani juft-toqlikka tekshiring.', 'Исследуйте на чётность f(x) = x³ − 5x.', 'Determine the parity of f(x) = x³ − 5x.'),
        s: L('D = ℝ — simmetrik. f(−x) = (−x)³ − 5(−x) = −x³ + 5x = −(x³ − 5x) = −f(x). Funksiya toq, grafigi koordinata boshiga nisbatan simmetrik.', 'D = ℝ — симметрична. f(−x) = (−x)³ − 5(−x) = −x³ + 5x = −(x³ − 5x) = −f(x). Функция нечётная, график симметричен относительно начала координат.', 'D = ℝ is symmetric. f(−x) = (−x)³ − 5(−x) = −x³ + 5x = −(x³ − 5x) = −f(x). The function is odd; its graph is symmetric about the origin.') },
      { q: L('f(x) = x² · cos x juftmi yoki toqmi?', 'Чётна или нечётна f(x) = x² · cos x?', 'Is f(x) = x² · cos x even or odd?'),
        s: L('f(−x) = (−x)² cos(−x) = x² cos x = f(x), chunki cos juft. Funksiya juft.', 'f(−x) = (−x)² cos(−x) = x² cos x = f(x), так как cos чётный. Функция чётная.', 'f(−x) = (−x)² cos(−x) = x² cos x = f(x), since cos is even. The function is even.') },
      { q: L('y = 3 − 2 sin x ning eng katta va eng kichik qiymatlarini toping.', 'Найдите наибольшее и наименьшее значения y = 3 − 2 sin x.', 'Find the largest and smallest values of y = 3 − 2 sin x.'),
        s: L('−1 ≤ sin x ≤ 1 ⇒ −2 ≤ −2 sin x ≤ 2 ⇒ 1 ≤ y ≤ 5. Eng katta qiymat 5 (sin x = −1 da), eng kichik 1 (sin x = 1 da). E = [1; 5].', '−1 ≤ sin x ≤ 1 ⇒ −2 ≤ −2 sin x ≤ 2 ⇒ 1 ≤ y ≤ 5. Наибольшее 5 (при sin x = −1), наименьшее 1 (при sin x = 1). E = [1; 5].', '−1 ≤ sin x ≤ 1 ⇒ −2 ≤ −2 sin x ≤ 2 ⇒ 1 ≤ y ≤ 5. Largest 5 (when sin x = −1), smallest 1 (when sin x = 1). E = [1; 5].') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>sin kx davrini 2πk deb yozish.</b> To‘g‘risi 2π/k: k katta bo‘lsa, tebranish tezlashadi, davr qisqaradi.', '<b>Писать период sin kx как 2πk.</b> Правильно 2π/k: чем больше k, тем быстрее колебания и короче период.', '<b>Writing the period of sin kx as 2πk.</b> It is 2π/k: larger k means faster oscillation and a shorter period.'),
      L('<b>Sohani tekshirmasdan juft-toqlik haqida xulosa.</b> y = x², x ∈ [−1; 2] juft emas — soha simmetrik emas.', '<b>Делать вывод о чётности, не проверив область.</b> y = x², x ∈ [−1; 2] не чётная — область несимметрична.', '<b>Judging parity without checking the domain.</b> y = x² on [−1; 2] is not even — the domain is not symmetric.'),
      L('<b>«Juft bo‘lmasa — toq» deb o‘ylash.</b> Ko‘p funksiyalar na juft, na toq.', '<b>Думать «не чётная — значит, нечётная».</b> Многие функции ни чётные, ни нечётные.', '<b>Thinking “not even means odd”.</b> Many functions are neither.'),
      L('<b>O‘sishni bir nechta oraliqlar birlashmasida e’lon qilish.</b> 1/x (−∞; 0) da ham, (0; +∞) da ham kamayadi, lekin ularning birlashmasida kamayuvchi emas: −1 &lt; 1, ammo f(−1) = −1 &lt; f(1) = 1.', '<b>Объявлять монотонность на объединении промежутков.</b> 1/x убывает и на (−∞; 0), и на (0; +∞), но на их объединении не убывает: −1 &lt; 1, однако f(−1) = −1 &lt; f(1) = 1.', '<b>Claiming monotonicity on a union of intervals.</b> 1/x decreases on (−∞; 0) and on (0; +∞), but not on their union: −1 &lt; 1 yet f(−1) = −1 &lt; f(1) = 1.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Tovush va musiqa.</b> «Lya» notasi sekundiga 440 marta tebranadi — bu sin(2π · 440 · t) funksiyasi, davri 1/440 soniya. Bir oktava yuqoridagi nota ikki baravar qisqa davrga ega. Elektr tarmog‘ida kuchlanish ham sinusoida bo‘yicha o‘zgaradi: O‘zbekistonda chastota 50 Hz, ya’ni davr 0,02 soniya.', '<b>Звук и музыка.</b> Нота «ля» колеблется 440 раз в секунду — это функция sin(2π · 440 · t) с периодом 1/440 секунды. Нота на октаву выше имеет вдвое меньший период. Напряжение в электросети тоже меняется по синусоиде: в Узбекистане частота 50 Гц, то есть период 0,02 секунды.', '<b>Sound and music.</b> The note A vibrates 440 times a second — the function sin(2π · 440 · t), with period 1/440 second. A note one octave higher has half the period. Mains voltage also varies sinusoidally: in Uzbekistan the frequency is 50 Hz, so the period is 0.02 second.'),
      L('<b>Tabiat va tibbiyot.</b> Dengiz suvining ko‘tarilishi va qaytishi taxminan 12 soat 25 daqiqa davr bilan takrorlanadi. Kardiogramma — yurakning davriy signali; shifokor davrning buzilishidan aritmiyani aniqlaydi. Monotonlik va ekstremumlar esa iqtisodda kerak: narx qachon eng past bo‘lishini bilish — xarid uchun eng yaxshi vaqtni bilish demak.', '<b>Природа и медицина.</b> Приливы и отливы повторяются с периодом около 12 часов 25 минут. Кардиограмма — периодический сигнал сердца; по нарушению периода врач распознаёт аритмию. А монотонность и экстремумы нужны в экономике: знать, когда цена минимальна, — значит знать лучшее время для покупки.', '<b>Nature and medicine.</b> Tides repeat with a period of about 12 hours 25 minutes. A cardiogram is the heart’s periodic signal; a doctor detects arrhythmia from a broken period. Monotonicity and extrema matter in economics: knowing when a price is lowest means knowing the best time to buy.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('y = cos²x funksiyaning eng kichik musbat davrini toping.', 'Найдите наименьший положительный период y = cos²x.', 'Find the smallest positive period of y = cos²x.'),
        s: L('Darajani pasaytiramiz: cos²x = (1 + cos 2x)/2. cos 2x ning davri 2π/2 = π, demak T = π (2π emas!).', 'Понижаем степень: cos²x = (1 + cos 2x)/2. Период cos 2x равен 2π/2 = π, значит, T = π (а не 2π!).', 'Lower the power: cos²x = (1 + cos 2x)/2. cos 2x has period 2π/2 = π, so T = π (not 2π!).') },
      { q: L('f davriy, T = 4 va f(1) = 7. f(13) va f(−7) ni toping.', 'f периодична, T = 4 и f(1) = 7. Найдите f(13) и f(−7).', 'f is periodic with T = 4 and f(1) = 7. Find f(13) and f(−7).'),
        s: L('13 = 1 + 3 · 4, demak f(13) = f(1) = 7. −7 = 1 − 2 · 4, demak f(−7) = 7.', '13 = 1 + 3 · 4, значит, f(13) = f(1) = 7. −7 = 1 − 2 · 4, значит, f(−7) = 7.', '13 = 1 + 3 · 4, so f(13) = f(1) = 7. −7 = 1 − 2 · 4, so f(−7) = 7.') },
      { q: L('y = |x| − 3 qaysi oraliqlarda o‘sadi va kamayadi? Eng kichik qiymati nechaga teng?', 'На каких промежутках y = |x| − 3 возрастает и убывает? Чему равно наименьшее значение?', 'Where does y = |x| − 3 increase and decrease? What is its smallest value?'),
        s: L('(−∞; 0] da kamayadi, [0; +∞) da o‘sadi; x = 0 — minimum nuqtasi, eng kichik qiymat −3. Funksiya juft.', 'Убывает на (−∞; 0], возрастает на [0; +∞); x = 0 — точка минимума, наименьшее значение −3. Функция чётная.', 'It decreases on (−∞; 0] and increases on [0; +∞); x = 0 is the minimum point, smallest value −3. The function is even.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('f(x + T) = f(x) — davriylik; sin, cos davri 2π, tg, ctg davri π.', 'f(x + T) = f(x) — периодичность; период sin, cos — 2π, tg, ctg — π.', 'f(x + T) = f(x) is periodicity; sin and cos have period 2π, tan and cot π.'),
      L('f(kx + b) ning davri T/|k|; sin kx uchun 2π/|k|.', 'Период f(kx + b) равен T/|k|; для sin kx — 2π/|k|.', 'f(kx + b) has period T/|k|; sin kx has 2π/|k|.'),
      L('Juft: f(−x) = f(x), Oy ga simmetrik; toq: f(−x) = −f(x), boshga simmetrik.', 'Чётная: f(−x) = f(x), симметрия относительно Oy; нечётная: f(−x) = −f(x), относительно начала.', 'Even: f(−x) = f(x), symmetric about Oy; odd: f(−x) = −f(x), symmetric about the origin.'),
      L('O‘suvchi: x₁ &lt; x₂ ⇒ f(x₁) &lt; f(x₂); kamayuvchi — aksincha.', 'Возрастающая: x₁ &lt; x₂ ⇒ f(x₁) &lt; f(x₂); убывающая — наоборот.', 'Increasing: x₁ &lt; x₂ ⇒ f(x₁) &lt; f(x₂); decreasing is the reverse.'),
      L('Tekshirish rejasi: D, E, nollar, ishora, juft-toqlik, monotonlik, ekstremum, davriylik.', 'План исследования: D, E, нули, знаки, чётность, монотонность, экстремумы, периодичность.', 'Investigation plan: D, E, zeros, sign, parity, monotonicity, extrema, periodicity.')
    ] }
  ] });

  // ---------- t5. Funksiya grafigi ustida sodda almashtirishlar ----------
  T.add(P, 't5', { sections: [
    { kind: 'intro', h: L('Bitta grafik — yuzlab grafik', 'Один график — сотни графиков', 'One graph — hundreds of graphs'), p: [
      L('y = (x − 3)² + 2, y = −2√(x + 1), y = |sin x| — bu grafiklarni nuqtalar jadvali bilan chizish uzoq vaqt oladi. Lekin ularning har biri bizga tanish «asosiy» grafikdan (y = x², y = √x, y = sin x) bir nechta sodda harakat — <b>siljitish</b>, <b>cho‘zish</b> va <b>aks ettirish</b> orqali hosil bo‘ladi. Bu harakatlarni bilgan o‘quvchi yuzlab grafiklarni bir necha soniyada chiza oladi.', 'Строить графики y = (x − 3)² + 2, y = −2√(x + 1), y = |sin x| по таблице точек долго. Но каждый из них получается из знакомого «основного» графика (y = x², y = √x, y = sin x) несколькими простыми движениями — <b>сдвигом</b>, <b>растяжением</b> и <b>отражением</b>. Ученик, знающий эти движения, строит сотни графиков за секунды.', 'Plotting y = (x − 3)² + 2, y = −2√(x + 1) or y = |sin x| point by point takes ages. But each comes from a familiar “basic” graph (y = x², y = √x, y = sin x) by a few simple moves — <b>shifting</b>, <b>stretching</b> and <b>reflecting</b>. A student who knows these moves can sketch hundreds of graphs in seconds.'),
      L('Kompyuter grafikasida ham xuddi shunday: o‘yindagi qahramon ekranda siljiganda, kattalashganda yoki oynada aks etganda, kompyuter koordinatalar ustida aynan shu almashtirishlarni bajaradi. Bu mavzuda har bir almashtirishning qoidasini va <b>nega</b> u shunday ishlashini tushunamiz.', 'В компьютерной графике то же самое: когда герой игры сдвигается, увеличивается или отражается в зеркале, компьютер выполняет над координатами именно эти преобразования. В этой теме мы поймём правило каждого преобразования и <b>почему</b> оно так работает.', 'Computer graphics works the same way: when a game character moves, grows or is mirrored, the computer applies exactly these transformations to coordinates. In this topic we learn the rule for each transformation and <b>why</b> it works.')
    ] },
    { kind: 'rule', h: L('Parallel ko‘chirishlar', 'Параллельные переносы', 'Translations'), p: [
      L('<b>y = f(x) + b</b>: har bir nuqtaning ordinatasiga b qo‘shiladi, grafik Oy bo‘ylab b birlik siljiydi — b &gt; 0 da yuqoriga, b &lt; 0 da pastga. Bu tabiiy: chiqish qiymatiga son qo‘shyapmiz.', '<b>y = f(x) + b</b>: к ординате каждой точки прибавляется b, график сдвигается вдоль Oy на b единиц — вверх при b &gt; 0, вниз при b &lt; 0. Это естественно: мы прибавляем число к выходу.', '<b>y = f(x) + b</b>: b is added to every y-coordinate, so the graph moves b units along Oy — up for b &gt; 0, down for b &lt; 0. This is natural: we add a number to the output.'),
      L('<b>y = f(x − a)</b>: grafik Ox bo‘ylab a birlik siljiydi — a &gt; 0 da <b>o‘ngga</b>, a &lt; 0 da chapga. Nega minus bo‘lsa o‘ngga? Yangi funksiya x nuqtada eski funksiyaning x − a nuqtadagi qiymatini oladi. Masalan, y = (x − 3)² ning eng kichik qiymati x − 3 = 0, ya’ni x = 3 da — uch 3 birlik o‘ngga ketgan. Eski grafikdagi «voqea» yangi grafikda a birlik <b>kechroq</b> sodir bo‘ladi.', '<b>y = f(x − a)</b>: график сдвигается вдоль Ox на a единиц — <b>вправо</b> при a &gt; 0, влево при a &lt; 0. Почему минус — вправо? Новая функция в точке x принимает значение старой в точке x − a. Например, наименьшее значение y = (x − 3)² — при x − 3 = 0, то есть x = 3: вершина ушла на 3 вправо. «Событие» старого графика на новом происходит на a единиц <b>позже</b>.', '<b>y = f(x − a)</b>: the graph moves a units along Ox — <b>right</b> for a &gt; 0, left for a &lt; 0. Why does minus mean right? The new function at x takes the old value at x − a. For example, y = (x − 3)² is smallest when x − 3 = 0, i.e. x = 3: the vertex moved 3 to the right. Every “event” of the old graph happens a units <b>later</b> on the new one.'),
      L('Ikkalasi birga: y = f(x − a) + b — grafik (a; b) vektor bo‘yicha ko‘chiriladi. Masalan, y = (x − 3)² + 2 — uchi (3; 2) da bo‘lgan parabola.', 'Вместе: y = f(x − a) + b — график переносится на вектор (a; b). Например, y = (x − 3)² + 2 — парабола с вершиной в (3; 2).', 'Together: y = f(x − a) + b moves the graph by the vector (a; b). For example, y = (x − 3)² + 2 is a parabola with vertex (3; 2).')
    ] },
    { kind: 'rule', h: L('Cho‘zish va siqish', 'Растяжение и сжатие', 'Stretching and compressing'), p: [
      L('<b>y = k · f(x)</b>, k &gt; 0: barcha ordinatalar k marta ko‘paytiriladi — grafik Oy o‘qi bo‘ylab k &gt; 1 da k marta <b>cho‘ziladi</b>, 0 &lt; k &lt; 1 da siqiladi. Ox o‘qidagi nuqtalar (nollar) joyida qoladi. Masalan, y = 3 sin x ning amplitudasi 3.', '<b>y = k · f(x)</b>, k &gt; 0: все ординаты умножаются на k — график <b>растягивается</b> вдоль оси Oy в k раз при k &gt; 1 и сжимается при 0 &lt; k &lt; 1. Точки на оси Ox (нули) остаются на месте. Например, амплитуда y = 3 sin x равна 3.', '<b>y = k · f(x)</b>, k &gt; 0: every y-coordinate is multiplied by k — the graph is <b>stretched</b> along Oy by k when k &gt; 1 and compressed when 0 &lt; k &lt; 1. Points on Ox (the zeros) stay put. For example, y = 3 sin x has amplitude 3.'),
      L('<b>y = f(kx)</b>, k &gt; 0: grafik Ox o‘qi bo‘ylab k &gt; 1 da k marta <b>siqiladi</b>, 0 &lt; k &lt; 1 da cho‘ziladi. Bu ham «teskari» ko‘rinadi: y = sin 2x da x ikki baravar tezroq «yuguradi», shuning uchun to‘lqin ikki baravar zichroq va davr π ga teng. Oy o‘qidagi nuqta (x = 0) joyida qoladi.', '<b>y = f(kx)</b>, k &gt; 0: график <b>сжимается</b> вдоль оси Ox в k раз при k &gt; 1 и растягивается при 0 &lt; k &lt; 1. Это тоже кажется «наоборот»: в y = sin 2x x «бежит» вдвое быстрее, поэтому волна вдвое плотнее, а период равен π. Точка на оси Oy (x = 0) остаётся на месте.', '<b>y = f(kx)</b>, k &gt; 0: the graph is <b>compressed</b> along Ox by k when k &gt; 1 and stretched when 0 &lt; k &lt; 1. This also looks “backwards”: in y = sin 2x, x “runs” twice as fast, so the wave is twice as dense and the period is π. The point on Oy (x = 0) stays put.')
    ] },
    { kind: 'rule', h: L('Aks ettirishlar va modul', 'Отражения и модуль', 'Reflections and absolute value'), list: [
      L('<b>y = −f(x)</b> — grafik Ox o‘qiga nisbatan simmetrik aks ettiriladi (yuqori pastga, past yuqoriga).', '<b>y = −f(x)</b> — график симметрично отражается относительно оси Ox (верх вниз, низ вверх).', '<b>y = −f(x)</b> — the graph is reflected in the Ox axis (top goes down, bottom goes up).'),
      L('<b>y = f(−x)</b> — grafik Oy o‘qiga nisbatan aks ettiriladi (o‘ng chapga). Juft funksiya uchun grafik o‘zgarmaydi.', '<b>y = f(−x)</b> — график отражается относительно оси Oy (право налево). Для чётной функции график не меняется.', '<b>y = f(−x)</b> — the graph is reflected in the Oy axis (right goes left). For an even function nothing changes.'),
      L('<b>y = |f(x)|</b> — Ox dan yuqoridagi qism saqlanadi, pastdagi qism Ox ga nisbatan yuqoriga aks ettiriladi. Grafik hech qachon Ox dan pastga tushmaydi.', '<b>y = |f(x)|</b> — часть выше Ox сохраняется, часть ниже Ox отражается вверх. График никогда не опускается ниже Ox.', '<b>y = |f(x)|</b> — the part above Ox is kept and the part below is flipped upward. The graph never goes below Ox.'),
      L('<b>y = f(|x|)</b> — x ≥ 0 dagi qism saqlanadi va Oy ga nisbatan chapga aks ettiriladi (chap qism o‘chiriladi). Natija — juft funksiya.', '<b>y = f(|x|)</b> — часть при x ≥ 0 сохраняется и отражается относительно Oy влево (левая часть стирается). Получается чётная функция.', '<b>y = f(|x|)</b> — the part for x ≥ 0 is kept and mirrored to the left in Oy (the old left part is erased). The result is even.')
    ] },
    { kind: 'table', h: L('Almashtirishlar jadvali', 'Таблица преобразований', 'Table of transformations'), table: { head: [L('Formula', 'Формула', 'Formula'), L('Grafik bilan nima bo‘ladi', 'Что происходит с графиком', 'What happens to the graph'), L('Nuqta (x; y) qayerga o‘tadi', 'Куда переходит точка (x; y)', 'Where (x; y) goes')], rows: [
      [L('f(x) + b', 'f(x) + b', 'f(x) + b'), L('b ga yuqoriga', 'вверх на b', 'up by b'), L('(x; y + b)', '(x; y + b)', '(x; y + b)')],
      [L('f(x − a)', 'f(x − a)', 'f(x − a)'), L('a ga o‘ngga', 'вправо на a', 'right by a'), L('(x + a; y)', '(x + a; y)', '(x + a; y)')],
      [L('k · f(x)', 'k · f(x)', 'k · f(x)'), L('Oy bo‘ylab k marta cho‘zish', 'растяжение вдоль Oy в k раз', 'vertical stretch by k'), L('(x; ky)', '(x; ky)', '(x; ky)')],
      [L('f(kx)', 'f(kx)', 'f(kx)'), L('Ox bo‘ylab k marta siqish', 'сжатие вдоль Ox в k раз', 'horizontal squeeze by k'), L('(x/k; y)', '(x/k; y)', '(x/k; y)')],
      [L('−f(x)', '−f(x)', '−f(x)'), L('Ox ga nisbatan aks', 'отражение относительно Ox', 'reflect in Ox'), L('(x; −y)', '(x; −y)', '(x; −y)')],
      [L('f(−x)', 'f(−x)', 'f(−x)'), L('Oy ga nisbatan aks', 'отражение относительно Oy', 'reflect in Oy'), L('(−x; y)', '(−x; y)', '(−x; y)')]
    ] }, after: [
      L('Qoidani eslab qolish usuli: f dan <b>tashqaridagi</b> o‘zgarishlar (y ga ta’sir qiladi) «kutilganidek» ishlaydi, f ning <b>ichidagi</b> o‘zgarishlar (x ga ta’sir qiladi) esa «teskari» ishlaydi.', 'Как запомнить: изменения <b>снаружи</b> f (действуют на y) работают «как ожидаешь», а изменения <b>внутри</b> f (действуют на x) — «наоборот».', 'Memory aid: changes <b>outside</b> f (acting on y) work “as expected”, while changes <b>inside</b> f (acting on x) work “backwards”.')
    ] },
    { kind: 'steps', h: L('Bir nechta almashtirishni bajarish tartibi', 'Порядок нескольких преобразований', 'Order of several transformations'), p: [
      L('y = A · f(k(x − a)) + b ko‘rinishidagi funksiya grafigini asosiy y = f(x) grafikdan quyidagi tartibda hosil qilish xavfsiz. Avval formulani shu ko‘rinishga keltiring: masalan, sin(2x − π/3) = sin 2(x − π/6), demak siljish π/6, π/3 emas!', 'График функции вида y = A · f(k(x − a)) + b безопасно строить из основного y = f(x) в таком порядке. Сначала приведите формулу к этому виду: например, sin(2x − π/3) = sin 2(x − π/6), значит, сдвиг π/6, а не π/3!', 'It is safe to build y = A · f(k(x − a)) + b from the basic y = f(x) in the following order. First bring the formula into this form: for instance sin(2x − π/3) = sin 2(x − π/6), so the shift is π/6, not π/3!')
    ], list: [
      L('1) Ox bo‘ylab siqish/cho‘zish (k) va kerak bo‘lsa Oy ga nisbatan aks (k &lt; 0).', '1) Сжатие/растяжение вдоль Ox (k) и при необходимости отражение относительно Oy (k &lt; 0).', '1) Horizontal squeeze/stretch (k) and, if needed, reflection in Oy (k &lt; 0).'),
      L('2) Ox bo‘ylab a birlik siljitish.', '2) Сдвиг вдоль Ox на a единиц.', '2) Shift a units along Ox.'),
      L('3) Oy bo‘ylab A marta cho‘zish va kerak bo‘lsa Ox ga nisbatan aks (A &lt; 0).', '3) Растяжение вдоль Oy в A раз и при необходимости отражение относительно Ox (A &lt; 0).', '3) Vertical stretch by A and, if needed, reflection in Ox (A &lt; 0).'),
      L('4) Oy bo‘ylab b birlik siljitish.', '4) Сдвиг вдоль Oy на b единиц.', '4) Shift b units along Oy.'),
      L('5) Tekshirish: bir-ikki xarakterli nuqtani (uch, nol) formulaga qo‘yib ko‘ring.', '5) Проверка: подставьте одну-две характерные точки (вершину, нуль) в формулу.', '5) Check: substitute one or two key points (vertex, zero) into the formula.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Grafiklarni koordinatalar tekisligida chizish g‘oyasi 1637-yilda Rene Dekartning «Geometriya» asarida va mustaqil ravishda Per Fermaning ishlarida paydo bo‘ldi. Bu analitik geometriyaning tug‘ilishi edi: endi egri chiziq tenglama bilan, tenglama esa egri chiziq bilan ifodalanishi mumkin bo‘ldi.', 'Идея изображать графики на координатной плоскости появилась в 1637 году в «Геометрии» Рене Декарта и независимо в работах Пьера Ферма. Это было рождение аналитической геометрии: теперь кривую можно было выразить уравнением, а уравнение — кривой.', 'The idea of drawing graphs in a coordinate plane appeared in 1637 in René Descartes’ “La Géométrie” and independently in the work of Pierre de Fermat. It was the birth of analytic geometry: a curve could now be expressed by an equation, and an equation by a curve.'),
      L('Almashtirishlar g‘oyasini geometriyada XIX asrda nemis matematigi Feliks Kleyn tizimlashtirdi: 1872-yildagi «Erlangen dasturi»da u har bir geometriyani shakllarni o‘zgartirmaydigan almashtirishlar guruhi orqali ta’rifladi. Siljitish, aks ettirish va burish — harakatlar; cho‘zish — o‘xshashlik. Bugun bu g‘oya kompyuter grafikasi, animatsiya va robototexnikaning asosida turadi.', 'Идею преобразований в геометрии систематизировал в XIX веке немецкий математик Феликс Клейн: в «Эрлангенской программе» 1872 года он определил каждую геометрию через группу преобразований, не меняющих фигуры. Сдвиг, отражение и поворот — движения; растяжение — подобие. Сегодня эта идея лежит в основе компьютерной графики, анимации и робототехники.', 'The German mathematician Felix Klein systematised transformations in the 19th century: in his 1872 “Erlangen Programme” he defined each geometry by a group of transformations that preserve figures. Translations, reflections and rotations are isometries; stretching is a similarity. Today this idea underpins computer graphics, animation and robotics.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('y = x² − 4x + 1 grafigini y = x² dan qanday hosil qilish mumkin?', 'Как получить график y = x² − 4x + 1 из y = x²?', 'How do we get the graph of y = x² − 4x + 1 from y = x²?'),
        s: L('To‘la kvadrat: x² − 4x + 1 = (x − 2)² − 3. Demak y = x² parabolasini 2 birlik o‘ngga va 3 birlik pastga siljitamiz. Uch (2; −3).', 'Полный квадрат: x² − 4x + 1 = (x − 2)² − 3. Значит, параболу y = x² сдвигаем на 2 вправо и на 3 вниз. Вершина (2; −3).', 'Complete the square: x² − 4x + 1 = (x − 2)² − 3. So shift y = x² 2 units right and 3 down. Vertex (2; −3).') },
      { q: L('y = −2√(x + 1) + 3 grafigini qanday chizish mumkin? Sohasi va qiymatlar to‘plami qanday?', 'Как построить y = −2√(x + 1) + 3? Каковы область определения и множество значений?', 'How do we sketch y = −2√(x + 1) + 3? What are its domain and range?'),
        s: L('y = √x ni 1 birlik chapga suramiz (√(x + 1)), Oy bo‘ylab 2 marta cho‘zamiz, Ox ga nisbatan aks ettiramiz (−2√(x + 1)), so‘ng 3 birlik yuqoriga ko‘taramiz. Boshlang‘ich nuqta (0; 0) → (−1; 3). D = [−1; +∞), E = (−∞; 3].', 'Сдвигаем y = √x на 1 влево (√(x + 1)), растягиваем вдоль Oy в 2 раза, отражаем относительно Ox (−2√(x + 1)), затем поднимаем на 3 вверх. Начальная точка (0; 0) → (−1; 3). D = [−1; +∞), E = (−∞; 3].', 'Shift y = √x 1 unit left (√(x + 1)), stretch vertically by 2, reflect in Ox (−2√(x + 1)), then raise by 3. The starting point (0; 0) goes to (−1; 3). D = [−1; +∞), E = (−∞; 3].') },
      { q: L('y = |x² − 4| grafigini tasvirlang.', 'Опишите график y = |x² − 4|.', 'Describe the graph of y = |x² − 4|.'),
        s: L('y = x² − 4 parabolasining (−2; 2) oraliqdagi qismi Ox dan pastda; uni yuqoriga aks ettiramiz. Uch (0; −4) → (0; 4). Grafik «W» harfiga o‘xshaydi, nollari ±2.', 'Часть параболы y = x² − 4 на (−2; 2) лежит ниже Ox; отражаем её вверх. Вершина (0; −4) → (0; 4). График похож на букву «W», нули ±2.', 'The part of y = x² − 4 on (−2; 2) is below Ox; flip it upward. The vertex (0; −4) becomes (0; 4). The graph looks like a “W” with zeros at ±2.') },
      { q: L('y = sin x grafigidan y = 2 sin(x − π/4) grafigini hosil qiling. Uning davri, amplitudasi va eng katta qiymati qanday?', 'Получите график y = 2 sin(x − π/4) из y = sin x. Каковы период, амплитуда и наибольшее значение?', 'Obtain y = 2 sin(x − π/4) from y = sin x. What are its period, amplitude and largest value?'),
        s: L('Sinusoidani π/4 o‘ngga siljitamiz va Oy bo‘ylab 2 marta cho‘zamiz. Davr 2π (o‘zgarmaydi), amplituda 2, eng katta qiymat 2, u x − π/4 = π/2, ya’ni x = 3π/4 da erishiladi.', 'Сдвигаем синусоиду на π/4 вправо и растягиваем вдоль Oy в 2 раза. Период 2π (не меняется), амплитуда 2, наибольшее значение 2 достигается при x − π/4 = π/2, то есть x = 3π/4.', 'Shift the sine curve π/4 right and stretch it vertically by 2. Period 2π (unchanged), amplitude 2, largest value 2, reached when x − π/4 = π/2, i.e. x = 3π/4.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>f(x − 3) ni chapga siljitish.</b> Minus — o‘ngga, plyus — chapga (x ichida).', '<b>Сдвигать f(x − 3) влево.</b> Минус — вправо, плюс — влево (внутри x).', '<b>Shifting f(x − 3) to the left.</b> Inside the bracket minus means right, plus means left.'),
      L('<b>f(2x + 6) ni 6 birlik chapga siljitish.</b> Avval qavsdan chiqaring: f(2(x + 3)) — siljish 3 birlik.', '<b>Сдвигать f(2x + 6) на 6 влево.</b> Сначала вынесите множитель: f(2(x + 3)) — сдвиг на 3.', '<b>Shifting f(2x + 6) six units left.</b> Factor first: f(2(x + 3)) — the shift is 3 units.'),
      L('<b>f(2x) ni Ox bo‘ylab cho‘zish.</b> Aslida 2 marta siqiladi.', '<b>Растягивать f(2x) вдоль Ox.</b> На самом деле он сжимается в 2 раза.', '<b>Stretching f(2x) horizontally.</b> It is actually squeezed by 2.'),
      L('<b>|f(x)| va f(|x|) ni chalkashtirish.</b> Birinchisida pastki qism yuqoriga aks etadi, ikkinchisida o‘ng qism chapga.', '<b>Путать |f(x)| и f(|x|).</b> В первом нижняя часть отражается вверх, во втором правая — влево.', '<b>Confusing |f(x)| with f(|x|).</b> In the first the lower part flips up; in the second the right part is mirrored left.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Kompyuter grafikasi.</b> Ekrandagi har bir rasm, harf va o‘yin qahramoni koordinatalar to‘plami. Siljitish, masshtablash va aks ettirish — grafik dasturlarning asosiy amallari. Shrift o‘lchamini kattalashtirsangiz, kompyuter harf konturiga k · f ko‘rinishidagi almashtirishni qo‘llaydi.', '<b>Компьютерная графика.</b> Каждая картинка, буква и герой игры на экране — набор координат. Сдвиг, масштабирование и отражение — основные операции графических программ. Когда вы увеличиваете шрифт, компьютер применяет к контуру буквы преобразование вида k · f.', '<b>Computer graphics.</b> Every picture, letter and game character on screen is a set of coordinates. Translation, scaling and reflection are the basic operations of graphics software. When you enlarge a font, the computer applies a k · f-type transformation to each letter’s outline.'),
      L('<b>Fizika va iqtisod.</b> Ikki odam bir xil yo‘ldan 10 daqiqa farq bilan chiqsa, ikkinchisining grafigi birinchisinikidan 10 birlik o‘ngga siljigan — f(t − 10). Narxlar 12 % oshsa, narx grafigi 1,12 marta cho‘ziladi. Ovoz balandligini oshirish — tovush to‘lqinini Oy bo‘ylab cho‘zish; videoni tezlashtirib ko‘rish — signalni Ox bo‘ylab siqish.', '<b>Физика и экономика.</b> Если два человека выходят по одной дороге с разницей 10 минут, график второго сдвинут на 10 единиц вправо — f(t − 10). Если цены выросли на 12 %, график цены растягивается в 1,12 раза. Увеличение громкости — растяжение звуковой волны вдоль Oy; ускоренный просмотр видео — сжатие сигнала вдоль Ox.', '<b>Physics and economics.</b> If two people set off on the same road 10 minutes apart, the second one’s graph is shifted 10 units right — f(t − 10). If prices rise by 12 %, the price graph is stretched by 1.12. Turning up the volume stretches a sound wave vertically; watching a video at double speed squeezes the signal horizontally.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('y = 1/x grafigi 2 birlik o‘ngga va 1 birlik yuqoriga siljitildi. Yangi funksiya formulasi va asimptotalari qanday?', 'График y = 1/x сдвинули на 2 вправо и на 1 вверх. Какова формула новой функции и её асимптоты?', 'The graph of y = 1/x is shifted 2 right and 1 up. What is the new formula and what are its asymptotes?'),
        s: L('y = 1/(x − 2) + 1. Vertikal asimptota x = 2, gorizontal asimptota y = 1.', 'y = 1/(x − 2) + 1. Вертикальная асимптота x = 2, горизонтальная y = 1.', 'y = 1/(x − 2) + 1. Vertical asymptote x = 2, horizontal asymptote y = 1.') },
      { q: L('y = (x + 1)² − 9 parabolaning uchi va Ox bilan kesishish nuqtalarini toping.', 'Найдите вершину параболы y = (x + 1)² − 9 и точки пересечения с Ox.', 'Find the vertex of y = (x + 1)² − 9 and where it meets Ox.'),
        s: L('Uch (−1; −9). (x + 1)² = 9 ⇒ x + 1 = ±3 ⇒ x = 2 yoki x = −4.', 'Вершина (−1; −9). (x + 1)² = 9 ⇒ x + 1 = ±3 ⇒ x = 2 или x = −4.', 'Vertex (−1; −9). (x + 1)² = 9 ⇒ x + 1 = ±3 ⇒ x = 2 or x = −4.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('f(x) + b — b ga yuqoriga; f(x − a) — a ga o‘ngga.', 'f(x) + b — вверх на b; f(x − a) — вправо на a.', 'f(x) + b — up by b; f(x − a) — right by a.'),
      L('k · f(x) — Oy bo‘ylab k marta cho‘zish; f(kx) — Ox bo‘ylab k marta siqish.', 'k · f(x) — растяжение вдоль Oy в k раз; f(kx) — сжатие вдоль Ox в k раз.', 'k · f(x) — vertical stretch by k; f(kx) — horizontal squeeze by k.'),
      L('−f(x) — Ox ga nisbatan aks; f(−x) — Oy ga nisbatan aks.', '−f(x) — отражение относительно Ox; f(−x) — относительно Oy.', '−f(x) — reflect in Ox; f(−x) — reflect in Oy.'),
      L('|f(x)| — pastki qism yuqoriga; f(|x|) — o‘ng qism chapga aks etadi.', '|f(x)| — нижняя часть вверх; f(|x|) — правая часть отражается влево.', '|f(x)| — lower part flips up; f(|x|) — right part is mirrored left.'),
      L('Ichki o‘zgarishlar (x bilan) «teskari», tashqi (y bilan) «to‘g‘ri» ishlaydi.', 'Внутренние изменения (с x) работают «наоборот», внешние (с y) — «прямо».', 'Inner changes (on x) work “backwards”, outer ones (on y) “forwards”.'),
      L('Murakkab holda avval formulani y = A · f(k(x − a)) + b ko‘rinishiga keltiring.', 'В сложном случае сначала приведите формулу к виду y = A · f(k(x − a)) + b.', 'In complex cases first rewrite the formula as y = A · f(k(x − a)) + b.')
    ] }
  ] });

  // ---------- t6. Chiziqli va kvadratik modellashtirish ----------
  T.add(P, 't6', { sections: [
    { kind: 'intro', h: L('Matematika — hayot tili', 'Математика — язык жизни', 'Mathematics — the language of life'), p: [
      L('Taksi qancha turadi? To‘p qayerga tushadi? Do‘kon narxni qanchaga qo‘ysa eng ko‘p foyda oladi? Bu savollarga javob berish uchun hayotiy vaziyatni matematik tilga — <b>funksiyaga</b> — o‘girish kerak. Bu jarayon <b>matematik modellashtirish</b> deyiladi, hosil bo‘lgan funksiya esa <b>model</b>.', 'Сколько стоит такси? Куда упадёт мяч? По какой цене магазину продавать, чтобы получить наибольшую прибыль? Чтобы ответить на эти вопросы, жизненную ситуацию нужно перевести на математический язык — в <b>функцию</b>. Этот процесс называется <b>математическим моделированием</b>, а полученная функция — <b>моделью</b>.', 'How much will the taxi cost? Where will the ball land? What price gives a shop the biggest profit? To answer such questions we translate a real situation into mathematical language — a <b>function</b>. This process is called <b>mathematical modelling</b>, and the resulting function is a <b>model</b>.'),
      L('Eng sodda va eng ko‘p ishlatiladigan modellar — <b>chiziqli</b> (y = kx + b) va <b>kvadratik</b> (y = ax² + bx + c). Birinchisi bir tekis o‘zgarishni, ikkinchisi tezlanuvchi o‘zgarishni va «eng yaxshi» qiymat — maksimum yoki minimumli vaziyatlarni tasvirlaydi. Bu mavzuda biz model tuzish, uni yechish va natijani hayot nuqtai nazaridan tekshirishni o‘rganamiz.', 'Самые простые и самые распространённые модели — <b>линейная</b> (y = kx + b) и <b>квадратичная</b> (y = ax² + bx + c). Первая описывает равномерное изменение, вторая — ускоряющееся изменение и ситуации с «наилучшим» значением — максимумом или минимумом. В этой теме мы научимся строить модель, решать её и проверять результат с точки зрения жизни.', 'The simplest and most common models are <b>linear</b> (y = kx + b) and <b>quadratic</b> (y = ax² + bx + c). The first describes steady change, the second accelerating change and situations with a “best” value — a maximum or minimum. In this topic we learn to build a model, solve it and check the result against reality.')
    ] },
    { kind: 'def', h: L('Chiziqli model', 'Линейная модель', 'The linear model'), p: [
      L('Agar bir kattalik ikkinchisining har bir birlik o‘zgarishida <b>bir xil miqdorga</b> o‘zgarsa, bog‘lanish chiziqli: y = kx + b. Bu yerda <b>k</b> — o‘zgarish tezligi (burchak koeffitsienti): x bir birlikka oshganda y qanchaga o‘zgarishi; <b>b</b> — boshlang‘ich qiymat (x = 0 dagi y). Masalan, taksi narxi = 5 000 + 2 000 · km: b = 5 000 so‘m — o‘tirish narxi, k = 2 000 so‘m/km.', 'Если одна величина при каждом единичном изменении другой меняется <b>на одну и ту же величину</b>, зависимость линейная: y = kx + b. Здесь <b>k</b> — скорость изменения (угловой коэффициент): насколько меняется y при увеличении x на единицу; <b>b</b> — начальное значение (y при x = 0). Например, цена такси = 5 000 + 2 000 · км: b = 5 000 сумов — посадка, k = 2 000 сумов/км.', 'If one quantity changes by <b>the same amount</b> for each unit change of another, the relationship is linear: y = kx + b. Here <b>k</b> is the rate of change (slope): how much y changes when x increases by one; <b>b</b> is the starting value (y at x = 0). E.g. taxi fare = 5 000 + 2 000 · km: b = 5 000 soums is the pick-up fee and k = 2 000 soums/km.'),
      L('Ikki nuqta (x₁; y₁) va (x₂; y₂) ma’lum bo‘lsa, k = (y₂ − y₁)/(x₂ − x₁), so‘ng b = y₁ − kx₁. Chiziqli modelning belgisi: jadvalda x teng qadam bilan oshganda y ning <b>ayirmalari</b> bir xil bo‘ladi. Bu arifmetik progressiyaning o‘zi!', 'Если известны две точки (x₁; y₁) и (x₂; y₂), то k = (y₂ − y₁)/(x₂ − x₁), затем b = y₁ − kx₁. Признак линейной модели: когда x в таблице растёт с равным шагом, <b>разности</b> y одинаковы. Это и есть арифметическая прогрессия!', 'Given two points (x₁; y₁) and (x₂; y₂), k = (y₂ − y₁)/(x₂ − x₁) and then b = y₁ − kx₁. Sign of a linear model: when x grows in equal steps in a table, the <b>differences</b> of y are equal. That is just an arithmetic progression!')
    ] },
    { kind: 'def', h: L('Kvadratik model', 'Квадратичная модель', 'The quadratic model'), p: [
      L('Kvadratik model y = ax² + bx + c uch holatda paydo bo‘ladi. <b>1) Tezlanuvchi harakat:</b> yuqoriga otilgan jism balandligi h = h₀ + v₀t − gt²/2 (g ≈ 9,8 m/s²). <b>2) Yuz:</b> to‘g‘ri to‘rtburchak yuzi S = x(p − x) ikki chiziqli kattalik ko‘paytmasi. <b>3) Daromad:</b> narx p ga oshgan sari sotuv chiziqli kamaysa, daromad = narx × sotuv soni — yana ikki chiziqli funksiya ko‘paytmasi.', 'Квадратичная модель y = ax² + bx + c появляется в трёх случаях. <b>1) Равноускоренное движение:</b> высота брошенного вверх тела h = h₀ + v₀t − gt²/2 (g ≈ 9,8 м/с²). <b>2) Площадь:</b> площадь прямоугольника S = x(p − x) — произведение двух линейных величин. <b>3) Выручка:</b> если с ростом цены продажи линейно падают, выручка = цена × количество — снова произведение двух линейных функций.', 'A quadratic model y = ax² + bx + c arises in three situations. <b>1) Uniformly accelerated motion:</b> the height of a body thrown upward is h = h₀ + v₀t − gt²/2 (g ≈ 9.8 m/s²). <b>2) Area:</b> a rectangle’s area S = x(p − x) is a product of two linear quantities. <b>3) Revenue:</b> if sales fall linearly as the price rises, revenue = price × quantity — again a product of two linear functions.'),
      L('Kvadratik modelning eng qimmatli xususiyati — <b>optimallashtirish</b>: eng katta yoki eng kichik qiymat parabola uchida, x₀ = −b/(2a) da. Jadval belgisi: x teng qadam bilan oshganda y ning ikkinchi ayirmalari (ayirmalarning ayirmalari) bir xil.', 'Самое ценное свойство квадратичной модели — <b>оптимизация</b>: наибольшее или наименьшее значение в вершине параболы, при x₀ = −b/(2a). Табличный признак: при равном шаге x вторые разности y (разности разностей) одинаковы.', 'The most valuable feature of a quadratic model is <b>optimisation</b>: the largest or smallest value is at the vertex, x₀ = −b/(2a). Table sign: with equal steps in x, the second differences of y (differences of differences) are constant.')
    ] },
    { kind: 'steps', h: L('Modellashtirish bosqichlari', 'Этапы моделирования', 'Stages of modelling'), list: [
      L('1) <b>O‘zgaruvchilarni tanlash:</b> nima noma’lum (x), nima hisoblanadi (y)? Birliklarni yozing.', '1) <b>Выбор переменных:</b> что неизвестно (x), что вычисляется (y)? Запишите единицы.', '1) <b>Choose variables:</b> what is unknown (x) and what is computed (y)? Write the units.'),
      L('2) <b>Formula tuzish:</b> shartdagi bog‘lanishlarni tenglamaga aylantiring.', '2) <b>Составление формулы:</b> переведите связи из условия в уравнение.', '2) <b>Build the formula:</b> turn the relationships in the problem into an equation.'),
      L('3) <b>Sohani aniqlash:</b> x ning ma’noli qiymatlari (uzunlik &gt; 0, vaqt ≥ 0, odamlar soni — butun).', '3) <b>Область:</b> осмысленные значения x (длина &gt; 0, время ≥ 0, число людей — целое).', '3) <b>Domain:</b> meaningful values of x (length &gt; 0, time ≥ 0, number of people a whole number).'),
      L('4) <b>Matematik yechish:</b> tenglama, tengsizlik yoki parabola uchi.', '4) <b>Математическое решение:</b> уравнение, неравенство или вершина параболы.', '4) <b>Solve mathematically:</b> an equation, an inequality or the vertex of a parabola.'),
      L('5) <b>Talqin va tekshirish:</b> javob hayotda ma’noga egami? Manfiy vaqt yoki 2,7 ta avtobus chiqsa, model yoki hisob qayta ko‘rib chiqiladi.', '5) <b>Интерпретация и проверка:</b> имеет ли ответ смысл? Если получилось отрицательное время или 2,7 автобуса, пересмотрите модель или расчёт.', '5) <b>Interpret and check:</b> does the answer make sense? Negative time or 2.7 buses means the model or the calculation needs another look.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Galileo Galiley XVII asr boshida qiya tekislikda sharlarni dumalatib, erkin tushayotgan jism bosib o‘tgan yo‘l vaqtning <b>kvadratiga</b> proporsional ekanini aniqladi: teng vaqt oraliqlarida bosib o‘tilgan yo‘llar 1 : 3 : 5 : 7 … nisbatda. Bu fizikadagi birinchi aniq kvadratik model edi. U shuningdek otilgan jism parabola bo‘ylab uchishini isbotladi — artilleriya uchun muhim kashfiyot.', 'В начале XVII века Галилео Галилей, скатывая шары по наклонной плоскости, установил, что путь свободно падающего тела пропорционален <b>квадрату</b> времени: пути за равные промежутки времени относятся как 1 : 3 : 5 : 7 … Это была первая точная квадратичная модель в физике. Он также доказал, что брошенное тело летит по параболе, — важное открытие для артиллерии.', 'In the early 17th century Galileo Galilei rolled balls down an inclined plane and found that the distance travelled by a falling body is proportional to the <b>square</b> of time: distances in equal time intervals are in the ratio 1 : 3 : 5 : 7 … This was the first precise quadratic model in physics. He also proved that a projectile flies along a parabola — an important discovery for artillery.'),
      L('Chiziqli modellar statistikada ham asosiy o‘rin tutadi. 1805-yilda Adrien-Mari Lejandr va mustaqil ravishda Karl Fridrix Gauss <b>eng kichik kvadratlar usulini</b> yaratdilar: tajriba nuqtalariga eng yaqin to‘g‘ri chiziqni topish. Gauss shu usul bilan yo‘qolgan Serera asteroidining orbitasini hisoblab, uning qayerda paydo bo‘lishini oldindan aytgan. Bugun bu usul sun’iy intellektdagi «chiziqli regressiya»ning asosi.', 'Линейные модели играют главную роль и в статистике. В 1805 году Адриен-Мари Лежандр и независимо Карл Фридрих Гаусс создали <b>метод наименьших квадратов</b>: поиск прямой, наиболее близкой к точкам опыта. Гаусс этим методом рассчитал орбиту потерянного астероида Церера и предсказал, где он появится. Сегодня этот метод — основа «линейной регрессии» в искусственном интеллекте.', 'Linear models are central in statistics too. In 1805 Adrien-Marie Legendre and, independently, Carl Friedrich Gauss created the <b>method of least squares</b>: finding the line closest to experimental points. Gauss used it to compute the orbit of the lost asteroid Ceres and predict where it would reappear. Today it is the basis of “linear regression” in artificial intelligence.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: chiziqli model', 'Решённые примеры: линейная модель', 'Worked examples: linear model'), ex: [
      { q: L('Mobil tarif: oyiga 30 000 so‘m abonent to‘lovi va har bir GB uchun 4 000 so‘m. Boshqa tarif: abonent to‘lovi yo‘q, har GB 7 000 so‘m. Qancha GB dan boshlab birinchi tarif arzon?', 'Мобильный тариф: 30 000 сумов абонплата в месяц и 4 000 сумов за каждый ГБ. Другой тариф: без абонплаты, 7 000 сумов за ГБ. Со скольких ГБ первый тариф дешевле?', 'Phone plan A: 30 000 soums a month plus 4 000 soums per GB. Plan B: no fee, 7 000 soums per GB. From how many GB is plan A cheaper?'),
        s: L('A(x) = 30 000 + 4 000x, B(x) = 7 000x. A &lt; B ⇒ 30 000 &lt; 3 000x ⇒ x &gt; 10. 10 GB dan ko‘p ishlatilsa, birinchi tarif foydali; aynan 10 GB da ikkalasi 70 000 so‘m.', 'A(x) = 30 000 + 4 000x, B(x) = 7 000x. A &lt; B ⇒ 30 000 &lt; 3 000x ⇒ x &gt; 10. При расходе больше 10 ГБ выгоднее первый тариф; ровно при 10 ГБ оба стоят 70 000 сумов.', 'A(x) = 30 000 + 4 000x, B(x) = 7 000x. A &lt; B ⇒ 30 000 &lt; 3 000x ⇒ x &gt; 10. Above 10 GB plan A is cheaper; at exactly 10 GB both cost 70 000 soums.') },
      { q: L('Suv isitgichda suv 20 °C dan boshlab har daqiqada 3 °C ga isiydi. Harorat formulasini yozing va 80 °C ga necha daqiqada yetishini toping.', 'В водонагревателе вода нагревается от 20 °C на 3 °C в минуту. Запишите формулу температуры и найдите, через сколько минут она достигнет 80 °C.', 'Water in a heater starts at 20 °C and warms by 3 °C per minute. Write the temperature formula and find when it reaches 80 °C.'),
        s: L('T(t) = 20 + 3t, t ≥ 0 (daqiqa). 20 + 3t = 80 ⇒ t = 20 daqiqa. Model faqat 100 °C gacha ma’noli — undan keyin suv qaynaydi.', 'T(t) = 20 + 3t, t ≥ 0 (минуты). 20 + 3t = 80 ⇒ t = 20 минут. Модель имеет смысл только до 100 °C — потом вода кипит.', 'T(t) = 20 + 3t, t ≥ 0 (minutes). 20 + 3t = 80 ⇒ t = 20 minutes. The model only makes sense up to 100 °C — after that the water boils.') },
      { q: L('Jadval: x = 1, 2, 3, 4 da y = 7, 10, 13, 16. Modelni toping.', 'Таблица: при x = 1, 2, 3, 4 y = 7, 10, 13, 16. Найдите модель.', 'Table: at x = 1, 2, 3, 4, y = 7, 10, 13, 16. Find the model.'),
        s: L('Ayirmalar 3, 3, 3 — bir xil, demak chiziqli: k = 3, b = 7 − 3 = 4. y = 3x + 4.', 'Разности 3, 3, 3 — одинаковы, значит, линейная: k = 3, b = 7 − 3 = 4. y = 3x + 4.', 'The differences are 3, 3, 3 — constant, so it is linear: k = 3, b = 7 − 3 = 4. y = 3x + 4.') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: kvadratik model va optimallashtirish', 'Решённые примеры: квадратичная модель и оптимизация', 'Worked examples: quadratic model and optimisation'), ex: [
      { q: L('Perimetri 40 m bo‘lgan to‘g‘ri to‘rtburchak shaklidagi bog‘ning eng katta yuzi qancha?', 'Какова наибольшая площадь прямоугольного сада с периметром 40 м?', 'What is the largest area of a rectangular garden with perimeter 40 m?'),
        s: L('Bir tomon x, ikkinchisi 20 − x, 0 &lt; x &lt; 20. S(x) = x(20 − x) = −x² + 20x. Uch: x₀ = −20/(−2) = 10. S = 10 · 10 = 100 m². Eng yaxshi shakl — kvadrat.', 'Одна сторона x, другая 20 − x, 0 &lt; x &lt; 20. S(x) = x(20 − x) = −x² + 20x. Вершина: x₀ = −20/(−2) = 10. S = 10 · 10 = 100 м². Лучшая форма — квадрат.', 'One side x, the other 20 − x, 0 &lt; x &lt; 20. S(x) = x(20 − x) = −x² + 20x. Vertex: x₀ = −20/(−2) = 10. S = 10 · 10 = 100 m². The best shape is a square.') },
      { q: L('To‘p 2 m balandlikdan 15 m/s tezlik bilan yuqoriga otildi: h(t) = 2 + 15t − 5t². Eng katta balandlik va to‘p yerga tushish vaqtini toping.', 'Мяч бросили вверх с высоты 2 м со скоростью 15 м/с: h(t) = 2 + 15t − 5t². Найдите наибольшую высоту и время падения на землю.', 'A ball is thrown up from 2 m at 15 m/s: h(t) = 2 + 15t − 5t². Find the greatest height and when it hits the ground.'),
        s: L('t₀ = −15/(−10) = 1,5 s; h(1,5) = 2 + 22,5 − 11,25 = 13,25 m. Yerga tushish: 5t² − 15t − 2 = 0, t = (15 + √(225 + 40))/10 = (15 + √265)/10 ≈ 3,13 s (manfiy ildiz ma’nosiz).', 't₀ = −15/(−10) = 1,5 с; h(1,5) = 2 + 22,5 − 11,25 = 13,25 м. Падение: 5t² − 15t − 2 = 0, t = (15 + √(225 + 40))/10 = (15 + √265)/10 ≈ 3,13 с (отрицательный корень не имеет смысла).', 't₀ = −15/(−10) = 1.5 s; h(1.5) = 2 + 22.5 − 11.25 = 13.25 m. Landing: 5t² − 15t − 2 = 0, t = (15 + √(225 + 40))/10 = (15 + √265)/10 ≈ 3.13 s (the negative root is meaningless).') },
      { q: L('Kafe kofeni 20 000 so‘mdan sotganda kuniga 300 ta sotadi. Narx har 1 000 so‘mga oshganda 10 ta kam sotiladi. Qaysi narxda daromad eng katta?', 'Кафе продаёт кофе по 20 000 сумов — 300 чашек в день. При повышении цены на каждые 1 000 сумов продаётся на 10 чашек меньше. При какой цене выручка наибольшая?', 'A café sells 300 coffees a day at 20 000 soums. Each 1 000-soum price rise loses 10 sales. Which price maximises revenue?'),
        s: L('x — narx oshirishlar soni. Daromad R(x) = (20 000 + 1 000x)(300 − 10x) = 10 000(20 + x)(30 − x). (20 + x)(30 − x) = −x² + 10x + 600, uch x₀ = 5. Narx 25 000 so‘m, sotuv 250 ta, daromad 6 250 000 so‘m (avval 6 000 000).', 'x — число повышений. Выручка R(x) = (20 000 + 1 000x)(300 − 10x) = 10 000(20 + x)(30 − x). (20 + x)(30 − x) = −x² + 10x + 600, вершина x₀ = 5. Цена 25 000 сумов, продажи 250, выручка 6 250 000 сумов (было 6 000 000).', 'Let x be the number of price rises. Revenue R(x) = (20 000 + 1 000x)(300 − 10x) = 10 000(20 + x)(30 − x). (20 + x)(30 − x) = −x² + 10x + 600 with vertex x₀ = 5. Price 25 000 soums, 250 sales, revenue 6 250 000 soums (it was 6 000 000).') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Sohani hisobga olmaslik.</b> Uzunlik manfiy, vaqt manfiy bo‘lolmaydi; tenglamaning «ortiqcha» ildizlarini tashlang.', '<b>Не учитывать область.</b> Длина и время не бывают отрицательными; отбрасывайте «лишние» корни уравнения.', '<b>Ignoring the domain.</b> Length and time cannot be negative; discard the “extra” roots of the equation.'),
      L('<b>Uchni topib, qiymatni hisoblamaslik.</b> Savol «eng katta yuz» bo‘lsa, javob x₀ emas, S(x₀).', '<b>Найти вершину, но не вычислить значение.</b> Если спрашивают «наибольшую площадь», ответ — не x₀, а S(x₀).', '<b>Finding the vertex but not the value.</b> If asked for “the largest area”, the answer is S(x₀), not x₀.'),
      L('<b>Modelni chegaradan tashqarida ishlatish.</b> Bola bo‘yi 5 yoshgacha yiliga ~7 sm o‘ssa, chiziqli model 40 yoshda 3 metr beradi — absurd.', '<b>Применять модель за пределами её области.</b> Если ребёнок растёт до 5 лет на ~7 см в год, линейная модель даст к 40 годам 3 метра — абсурд.', '<b>Using a model beyond its range.</b> If a child grows ~7 cm a year up to age 5, a linear model predicts 3 metres at 40 — absurd.'),
      L('<b>Birliklarni aralashtirish.</b> Tezlik km/soatda, vaqt daqiqada bo‘lsa — avval bir xil birlikka keltiring.', '<b>Смешивать единицы.</b> Если скорость в км/ч, а время в минутах — сначала приведите к одним единицам.', '<b>Mixing units.</b> If speed is in km/h and time in minutes, convert to the same units first.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Biznes.</b> Har qanday korxona xarajatlarini C(x) = doimiy xarajat + o‘zgaruvchan xarajat · x chiziqli modeli bilan hisoblaydi. Daromad bilan xarajat teng bo‘ladigan nuqta — <b>zararsizlik nuqtasi</b>: undan ko‘p sotilsa, foyda boshlanadi. Narxni optimallashtirish esa yuqoridagi kafe misolidagi kabi kvadratik masala.', '<b>Бизнес.</b> Любое предприятие рассчитывает затраты по линейной модели C(x) = постоянные затраты + переменные затраты · x. Точка, где выручка равна затратам, — <b>точка безубыточности</b>: при больших продажах начинается прибыль. А оптимизация цены — квадратичная задача, как в примере с кафе.', '<b>Business.</b> Every company models costs linearly: C(x) = fixed cost + variable cost · x. The point where revenue equals cost is the <b>break-even point</b>: sell more and profit begins. Optimising the price is a quadratic problem, as in the café example.'),
      L('<b>Sport va xavfsizlik.</b> Avtomobilning tormoz yo‘li tezlikning kvadratiga proporsional: tezlik 2 baravar oshsa, tormoz yo‘li 4 baravar uzayadi. Shuning uchun shahar ichida 60 km/soat o‘rniga 90 km/soat yurish tormoz yo‘lini taxminan 2,25 baravar uzaytiradi. Yadro uloqtiruvchilar va basketbolchilar ham otish burchagi va tezligini parabola qonuniga ko‘ra tanlaydi.', '<b>Спорт и безопасность.</b> Тормозной путь автомобиля пропорционален квадрату скорости: при скорости вдвое больше тормозной путь в 4 раза длиннее. Поэтому езда в городе со скоростью 90 км/ч вместо 60 км/ч удлиняет тормозной путь примерно в 2,25 раза. Толкатели ядра и баскетболисты тоже выбирают угол и скорость броска по закону параболы.', '<b>Sport and safety.</b> A car’s braking distance is proportional to the square of its speed: double the speed and the braking distance is four times longer. So driving at 90 km/h instead of 60 km/h in town makes it about 2.25 times longer. Shot-putters and basketball players also choose their angle and speed by the law of the parabola.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Barcha to‘g‘ri to‘rtburchaklar ichida berilgan perimetrda eng katta yuzga kvadrat ega. Aylana esa barcha shakllar ichida eng katta yuzga ega — afsonaviy malika Didona Karfagen shahri uchun yerni aynan yarim aylana shaklida o‘ragan.', 'Среди прямоугольников с данным периметром наибольшую площадь имеет квадрат. А среди всех фигур — круг: легендарная царица Дидона огородила землю для Карфагена именно полукругом.', 'Among rectangles with a given perimeter the square has the largest area, and among all shapes the circle does: the legendary Queen Dido enclosed the land for Carthage in a semicircle.'),
      L('Havo qarshiligi bo‘lmaganda, berilgan tezlik bilan otilgan jism eng uzoqqa 45° burchak ostida uchadi: masofa v²sin 2α/g, sin 2α esa α = 45° da eng katta.', 'Без сопротивления воздуха тело, брошенное с данной скоростью, улетает дальше всего под углом 45°: дальность v²sin 2α/g, а sin 2α наибольший при α = 45°.', 'Without air resistance a body thrown at a given speed flies farthest at 45°: the range is v²sin 2α/g, and sin 2α is largest at α = 45°.'),
      L('Toshkent teleminorasi balandligi 375 m. Uning tepasidan tashlangan tosh (havo qarshiligisiz) h = 375 − 4,9t² modeli bo‘yicha taxminan 8,7 sekundda yerga tushadi.', 'Высота Ташкентской телебашни 375 м. Камень, брошенный с её вершины (без сопротивления воздуха), по модели h = 375 − 4,9t² упадёт примерно за 8,7 секунды.', 'The Tashkent TV Tower is 375 m tall. A stone dropped from the top (ignoring air resistance) follows h = 375 − 4.9t² and lands after about 8.7 seconds.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('Devor yonida to‘g‘ri to‘rtburchak maydonni uch tomondan 60 m to‘r bilan o‘rash kerak (to‘rtinchi tomon — devor). Eng katta yuz qancha?', 'У стены нужно огородить прямоугольный участок сеткой длиной 60 м с трёх сторон (четвёртая — стена). Какова наибольшая площадь?', 'A rectangular plot by a wall is fenced on three sides with 60 m of netting (the wall is the fourth side). What is the largest area?'),
        s: L('Devorga perpendikulyar tomonlar x, parallel tomon 60 − 2x. S = x(60 − 2x) = −2x² + 60x, x₀ = 15, S = 15 · 30 = 450 m².', 'Стороны, перпендикулярные стене, x, параллельная 60 − 2x. S = x(60 − 2x) = −2x² + 60x, x₀ = 15, S = 15 · 30 = 450 м².', 'Sides perpendicular to the wall are x, the parallel side 60 − 2x. S = x(60 − 2x) = −2x² + 60x, x₀ = 15, S = 15 · 30 = 450 m².') },
      { q: L('(0; 5) va (4; 17) nuqtalardan o‘tuvchi chiziqli modelni toping.', 'Найдите линейную модель через точки (0; 5) и (4; 17).', 'Find the linear model through (0; 5) and (4; 17).'),
        s: L('k = (17 − 5)/(4 − 0) = 3, b = 5. y = 3x + 5.', 'k = (17 − 5)/(4 − 0) = 3, b = 5. y = 3x + 5.', 'k = (17 − 5)/(4 − 0) = 3, b = 5. y = 3x + 5.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Model — hayotiy vaziyatni tasvirlovchi funksiya.', 'Модель — функция, описывающая жизненную ситуацию.', 'A model is a function describing a real situation.'),
      L('Chiziqli model y = kx + b: k — o‘zgarish tezligi, b — boshlang‘ich qiymat; ayirmalar o‘zgarmas.', 'Линейная модель y = kx + b: k — скорость изменения, b — начальное значение; разности постоянны.', 'Linear model y = kx + b: k is the rate of change, b the starting value; differences are constant.'),
      L('Kvadratik model: harakat, yuz, daromad; ikkinchi ayirmalar o‘zgarmas.', 'Квадратичная модель: движение, площадь, выручка; вторые разности постоянны.', 'Quadratic model: motion, area, revenue; second differences are constant.'),
      L('Eng katta/eng kichik qiymat parabola uchida: x₀ = −b/(2a).', 'Наибольшее/наименьшее значение — в вершине: x₀ = −b/(2a).', 'The max/min is at the vertex: x₀ = −b/(2a).'),
      L('Bosqichlar: o‘zgaruvchilar → formula → soha → yechish → talqin.', 'Этапы: переменные → формула → область → решение → интерпретация.', 'Stages: variables → formula → domain → solve → interpret.'),
      L('Modelning qo‘llanish chegarasini doim yodda tuting.', 'Всегда помните о границах применимости модели.', 'Always remember the limits of a model.')
    ] }
  ] });

  // ---------- t7. Ratsional tenglamalar va ularning sistemalari ----------
  T.add(P, 't7', { sections: [
    { kind: 'intro', h: L('Kasrli tenglamalar — hiyla bilan', 'Дробные уравнения — с подвохом', 'Fractional equations — with a catch'), p: [
      L('Ikki quvur hovuzni birgalikda 6 soatda to‘ldiradi, birinchisi yolg‘iz o‘zi ikkinchisidan 5 soat tezroq. Har bir quvur alohida necha soatda to‘ldiradi? Bunday masalani yechmoqchi bo‘lsangiz, noma’lum maxrajda turgan tenglama hosil bo‘ladi: 1/x + 1/(x + 5) = 1/6. Bu — <b>kasr-ratsional tenglama</b>.', 'Две трубы вместе наполняют бассейн за 6 часов, первая одна — на 5 часов быстрее второй. За сколько часов наполнит бассейн каждая труба? Решая такую задачу, получаем уравнение с неизвестным в знаменателе: 1/x + 1/(x + 5) = 1/6. Это — <b>дробно-рациональное уравнение</b>.', 'Two pipes fill a pool together in 6 hours, and the first alone is 5 hours faster than the second. How long does each take alone? Solving this gives an equation with the unknown in a denominator: 1/x + 1/(x + 5) = 1/6. This is a <b>rational (fractional) equation</b>.'),
      L('Bunday tenglamalarning o‘ziga xos «tuzog‘i» bor: maxrajdan qutulish uchun ikkala tomonni noma’lum qatnashgan ifodaga ko‘paytiramiz va shu paytda <b>chet ildizlar</b> paydo bo‘lishi mumkin. Bu mavzuda biz ratsional tenglamalarni xavfsiz yechish algoritmini, almashtirish usulini va ratsional tenglamalar sistemalarini o‘rganamiz.', 'У таких уравнений есть особая «ловушка»: чтобы избавиться от знаменателя, мы умножаем обе части на выражение с неизвестным, и при этом могут появиться <b>посторонние корни</b>. В этой теме мы изучим безопасный алгоритм решения рациональных уравнений, метод замены и системы рациональных уравнений.', 'Such equations hide a “trap”: to clear denominators we multiply both sides by an expression containing the unknown, and <b>extraneous roots</b> may appear. In this topic we learn a safe algorithm for rational equations, the substitution method and systems of rational equations.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('<b>Ratsional ifoda</b> — sonlar va o‘zgaruvchilardan qo‘shish, ayirish, ko‘paytirish, bo‘lish va natural darajaga ko‘tarish yordamida tuzilgan ifoda. Agar unda o‘zgaruvchiga bo‘lish bo‘lmasa — <b>butun</b> ifoda (ko‘phad), bo‘lsa — <b>kasr</b> ifoda. Tenglamaning ikki tomoni ratsional ifodalardan iborat bo‘lsa, u <b>ratsional tenglama</b> deyiladi. Har qanday ratsional tenglamani P(x)/Q(x) = 0 ko‘rinishiga keltirish mumkin, bu yerda P va Q — ko‘phadlar.', '<b>Рациональное выражение</b> — выражение, составленное из чисел и переменных с помощью сложения, вычитания, умножения, деления и возведения в натуральную степень. Если в нём нет деления на переменную — это <b>целое</b> выражение (многочлен), если есть — <b>дробное</b>. Уравнение, обе части которого рациональные выражения, называется <b>рациональным</b>. Любое рациональное уравнение приводится к виду P(x)/Q(x) = 0, где P и Q — многочлены.', 'A <b>rational expression</b> is built from numbers and variables using addition, subtraction, multiplication, division and natural powers. Without division by a variable it is <b>integral</b> (a polynomial); with it, <b>fractional</b>. An equation whose sides are rational expressions is a <b>rational equation</b>. Any rational equation can be written as P(x)/Q(x) = 0, where P and Q are polynomials.'),
      L('<b>Asosiy qoida:</b> kasr nolga teng ⇔ surat nolga teng va maxraj noldan farqli. P(x)/Q(x) = 0 ⇔ { P(x) = 0, Q(x) ≠ 0 }. <b>Chet ildiz</b> — o‘zgartirilgan tenglamaning ildizi bo‘lgan, lekin dastlabki tenglamani qanoatlantirmaydigan son. Ratsional tenglamalarda chet ildizlar maxrajni nolga aylantiradigan sonlardir.', '<b>Основное правило:</b> дробь равна нулю ⇔ числитель равен нулю, а знаменатель отличен от нуля. P(x)/Q(x) = 0 ⇔ { P(x) = 0, Q(x) ≠ 0 }. <b>Посторонний корень</b> — число, являющееся корнем преобразованного уравнения, но не удовлетворяющее исходному. В рациональных уравнениях посторонние корни — это числа, обращающие знаменатель в нуль.', '<b>Main rule:</b> a fraction is zero ⇔ its numerator is zero and its denominator is not. P(x)/Q(x) = 0 ⇔ { P(x) = 0, Q(x) ≠ 0 }. An <b>extraneous root</b> is a root of the transformed equation that does not satisfy the original one. In rational equations these are the numbers that make a denominator zero.')
    ] },
    { kind: 'steps', h: L('Yechish algoritmi', 'Алгоритм решения', 'Solution algorithm'), list: [
      L('1) <b>ODZ (mumkin bo‘lgan qiymatlar sohasi):</b> barcha maxrajlarni ko‘paytuvchilarga ajrating va ularni nolga aylantiruvchi x larni yozing.', '1) <b>ОДЗ:</b> разложите все знаменатели на множители и выпишите x, обращающие их в нуль.', '1) <b>Domain:</b> factor every denominator and list the x that make them zero.'),
      L('2) <b>Umumiy maxraj:</b> maxrajlarning eng kichik umumiy karralisini toping.', '2) <b>Общий знаменатель:</b> найдите наименьшее общее кратное знаменателей.', '2) <b>Common denominator:</b> find the least common multiple of the denominators.'),
      L('3) <b>Ko‘paytirish:</b> tenglamaning ikkala tomonini umumiy maxrajga ko‘paytirib, butun tenglama hosil qiling.', '3) <b>Умножение:</b> умножьте обе части на общий знаменатель и получите целое уравнение.', '3) <b>Multiply:</b> multiply both sides by the common denominator to get a polynomial equation.'),
      L('4) <b>Butun tenglamani yeching</b> (chiziqli, kvadrat yoki ko‘paytuvchilarga ajratish).', '4) <b>Решите целое уравнение</b> (линейное, квадратное или разложением на множители).', '4) <b>Solve the polynomial equation</b> (linear, quadratic or by factoring).'),
      L('5) <b>Tekshiring:</b> 1-qadamda taqiqlangan qiymatlarni javobdan chiqarib tashlang.', '5) <b>Проверьте:</b> исключите из ответа значения, запрещённые на шаге 1.', '5) <b>Check:</b> remove from the answer any values forbidden in step 1.')
    ], after: [
      L('Nega chet ildiz paydo bo‘ladi? Ikkala tomonni Q(x) ga ko‘paytirganda, Q(x) = 0 bo‘lgan nuqtada «0 = 0» hosil bo‘ladi va bu nuqta yangi tenglamani qanoatlantirib qolishi mumkin. Bu yerda nolga ko‘paytirish teng kuchli almashtirish emas.', 'Почему появляются посторонние корни? Умножив обе части на Q(x), в точке, где Q(x) = 0, получаем «0 = 0», и эта точка может удовлетворить новому уравнению. Умножение на нуль — не равносильное преобразование.', 'Why do extraneous roots appear? Multiplying both sides by Q(x) gives “0 = 0” where Q(x) = 0, so that point may satisfy the new equation. Multiplying by zero is not an equivalent transformation.')
    ] },
    { kind: 'rule', h: L('Yangi o‘zgaruvchi kiritish', 'Введение новой переменной', 'Introducing a new variable'), p: [
      L('Agar tenglamada bitta ifoda bir necha marta takrorlansa, uni yangi harf bilan belgilash tenglamani soddalashtiradi. Masalan, (x² + x)² − 8(x² + x) + 12 = 0 da t = x² + x deb olsak, t² − 8t + 12 = 0, t = 2 yoki t = 6. So‘ng x² + x = 2 ⇒ x = 1, −2; x² + x = 6 ⇒ x = 2, −3. To‘rtinchi darajali tenglama ikkita kvadrat tenglamaga aylandi.', 'Если в уравнении одно выражение повторяется несколько раз, обозначение его новой буквой упрощает уравнение. Например, в (x² + x)² − 8(x² + x) + 12 = 0 положим t = x² + x: t² − 8t + 12 = 0, t = 2 или t = 6. Затем x² + x = 2 ⇒ x = 1, −2; x² + x = 6 ⇒ x = 2, −3. Уравнение четвёртой степени превратилось в два квадратных.', 'If one expression repeats in an equation, naming it with a new letter simplifies things. In (x² + x)² − 8(x² + x) + 12 = 0, let t = x² + x: t² − 8t + 12 = 0, t = 2 or t = 6. Then x² + x = 2 ⇒ x = 1, −2; x² + x = 6 ⇒ x = 2, −3. A quartic became two quadratics.'),
      L('Kasrli tenglamalarda ko‘p uchraydigan holat: x/(x + 1) + (x + 1)/x = 5/2. Bunda t = x/(x + 1) desak, ikkinchi kasr 1/t bo‘ladi: t + 1/t = 5/2 ⇒ 2t² − 5t + 2 = 0 ⇒ t = 2 yoki 1/2. Bikvadrat tenglama ax⁴ + bx² + c = 0 ham t = x² almashtirish bilan yechiladi; bunda t ≥ 0 shartini unutmang.', 'Частый случай в дробных уравнениях: x/(x + 1) + (x + 1)/x = 5/2. Положим t = x/(x + 1), тогда вторая дробь равна 1/t: t + 1/t = 5/2 ⇒ 2t² − 5t + 2 = 0 ⇒ t = 2 или 1/2. Биквадратное уравнение ax⁴ + bx² + c = 0 тоже решается заменой t = x²; не забудьте условие t ≥ 0.', 'A common fractional case: x/(x + 1) + (x + 1)/x = 5/2. Let t = x/(x + 1); then the second fraction is 1/t: t + 1/t = 5/2 ⇒ 2t² − 5t + 2 = 0 ⇒ t = 2 or 1/2. A biquadratic ax⁴ + bx² + c = 0 is also solved with t = x²; do not forget t ≥ 0.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Quvurlar va ishchilar haqidagi «birgalikdagi ish» masalalari juda qadimiy. Ular Xitoyning «To‘qqiz bobdan iborat matematika» kitobida (mil. av. II–I asrlar) va hind matematigi Bxaskara II ning «Lilavati» asarida (1150-yil) uchraydi. Mashhur misol: «Hovuzga to‘rtta quvur suv quyadi: biri bir kunda, ikkinchisi yarim kunda, uchinchisi chorak kunda, to‘rtinchisi beshdan bir kunda to‘ldiradi. Birgalikda qancha vaqtda to‘ldiradi?» — javob 1/12 kun.', 'Задачи на «совместную работу» о трубах и работниках очень древние. Они встречаются в китайской книге «Математика в девяти книгах» (II–I вв. до н. э.) и в «Лилавати» индийского математика Бхаскары II (1150 год). Знаменитый пример: «В бассейн льют воду четыре трубы: одна наполняет его за день, вторая за полдня, третья за четверть дня, четвёртая за пятую часть дня. За какое время наполнят вместе?» — ответ 1/12 дня.', '“Joint work” problems about pipes and workers are very old. They appear in the Chinese “Nine Chapters on the Mathematical Art” (2nd–1st centuries BC) and in the Indian mathematician Bhaskara II’s “Lilavati” (1150). A famous example: “Four pipes fill a pool: one in a day, the second in half a day, the third in a quarter of a day, the fourth in a fifth of a day. How long together?” — the answer is 1/12 of a day.'),
      L('Ratsional tenglamalar sistemalarini simmetrik almashtirishlar orqali yechish usullari Uyg‘onish davri Yevropasida, ayniqsa Fransua Viyet ishlarida (XVI asr) rivojlandi. Viyet harfiy belgilashlarni tizimli kiritgan va ildizlar bilan koeffitsientlar orasidagi bog‘lanishni — bugun Viyet teoremasi deb ataladigan qoidani — umumiy ko‘rinishda yozgan.', 'Методы решения систем рациональных уравнений с помощью симметричных замен развивались в Европе эпохи Возрождения, особенно в трудах Франсуа Виета (XVI век). Виет систематически ввёл буквенные обозначения и записал в общем виде связь между корнями и коэффициентами — правило, которое сегодня называют теоремой Виета.', 'Methods for solving systems of rational equations with symmetric substitutions developed in Renaissance Europe, especially in the work of François Viète (16th century). Viète systematically introduced letter notation and wrote in general form the link between roots and coefficients — the rule now called Vieta’s theorem.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: tenglamalar', 'Решённые примеры: уравнения', 'Worked examples: equations'), ex: [
      { q: L('Yeching: (x² − 4)/(x − 2) = 5.', 'Решите: (x² − 4)/(x − 2) = 5.', 'Solve: (x² − 4)/(x − 2) = 5.'),
        s: L('ODZ: x ≠ 2. Surat (x − 2)(x + 2), qisqartiramiz: x + 2 = 5 ⇒ x = 3. 3 ≠ 2 — mos. Javob: 3.', 'ОДЗ: x ≠ 2. Числитель (x − 2)(x + 2), сокращаем: x + 2 = 5 ⇒ x = 3. 3 ≠ 2 — подходит. Ответ: 3.', 'Domain: x ≠ 2. The numerator is (x − 2)(x + 2); cancel: x + 2 = 5 ⇒ x = 3. 3 ≠ 2, so it is valid. Answer: 3.') },
      { q: L('Yeching: 3/(x − 1) − 2/(x + 1) = 4/(x² − 1).', 'Решите: 3/(x − 1) − 2/(x + 1) = 4/(x² − 1).', 'Solve: 3/(x − 1) − 2/(x + 1) = 4/(x² − 1).'),
        s: L('x² − 1 = (x − 1)(x + 1), ODZ: x ≠ ±1. Umumiy maxrajga ko‘paytiramiz: 3(x + 1) − 2(x − 1) = 4 ⇒ x + 5 = 4 ⇒ x = −1. Lekin x = −1 taqiqlangan — chet ildiz. Javob: yechim yo‘q.', 'x² − 1 = (x − 1)(x + 1), ОДЗ: x ≠ ±1. Умножаем на общий знаменатель: 3(x + 1) − 2(x − 1) = 4 ⇒ x + 5 = 4 ⇒ x = −1. Но x = −1 запрещён — посторонний корень. Ответ: решений нет.', 'x² − 1 = (x − 1)(x + 1); domain x ≠ ±1. Multiply by the common denominator: 3(x + 1) − 2(x − 1) = 4 ⇒ x + 5 = 4 ⇒ x = −1. But x = −1 is forbidden — extraneous. Answer: no solution.') },
      { q: L('Quvurlar masalasini yeching: 1/x + 1/(x + 5) = 1/6.', 'Решите задачу о трубах: 1/x + 1/(x + 5) = 1/6.', 'Solve the pipe problem: 1/x + 1/(x + 5) = 1/6.'),
        s: L('x &gt; 0. Umumiy maxraj 6x(x + 5): 6(x + 5) + 6x = x(x + 5) ⇒ x² − 7x − 30 = 0 ⇒ x = 10 yoki x = −3. Vaqt manfiy bo‘lmaydi: birinchi quvur 10 soatda, ikkinchisi 15 soatda to‘ldiradi. Tekshirish: 1/10 + 1/15 = 5/30 = 1/6 ✓.', 'x &gt; 0. Общий знаменатель 6x(x + 5): 6(x + 5) + 6x = x(x + 5) ⇒ x² − 7x − 30 = 0 ⇒ x = 10 или x = −3. Время не отрицательно: первая труба наполняет за 10 часов, вторая — за 15. Проверка: 1/10 + 1/15 = 5/30 = 1/6 ✓.', 'x &gt; 0. Common denominator 6x(x + 5): 6(x + 5) + 6x = x(x + 5) ⇒ x² − 7x − 30 = 0 ⇒ x = 10 or x = −3. Time is not negative: the first pipe takes 10 hours, the second 15. Check: 1/10 + 1/15 = 5/30 = 1/6 ✓.') },
      { q: L('Yeching: x/(x + 1) + (x + 1)/x = 5/2.', 'Решите: x/(x + 1) + (x + 1)/x = 5/2.', 'Solve: x/(x + 1) + (x + 1)/x = 5/2.'),
        s: L('ODZ: x ≠ 0, −1. t = x/(x + 1): t + 1/t = 5/2 ⇒ t = 2 yoki t = 1/2. x/(x + 1) = 2 ⇒ x = 2x + 2 ⇒ x = −2. x/(x + 1) = 1/2 ⇒ 2x = x + 1 ⇒ x = 1. Javob: −2; 1.', 'ОДЗ: x ≠ 0, −1. t = x/(x + 1): t + 1/t = 5/2 ⇒ t = 2 или t = 1/2. x/(x + 1) = 2 ⇒ x = 2x + 2 ⇒ x = −2. x/(x + 1) = 1/2 ⇒ 2x = x + 1 ⇒ x = 1. Ответ: −2; 1.', 'Domain: x ≠ 0, −1. Let t = x/(x + 1): t + 1/t = 5/2 ⇒ t = 2 or t = 1/2. x/(x + 1) = 2 ⇒ x = 2x + 2 ⇒ x = −2. x/(x + 1) = 1/2 ⇒ 2x = x + 1 ⇒ x = 1. Answer: −2; 1.') }
    ] },
    { kind: 'rule', h: L('Ratsional tenglamalar sistemalari', 'Системы рациональных уравнений', 'Systems of rational equations'), p: [
      L('Sistemalarni yechishning asosiy usullari 8–9-sinflardan ma’lum: <b>o‘rniga qo‘yish</b>, <b>qo‘shish</b> va <b>yangi o‘zgaruvchilar kiritish</b>. Ratsional sistemalarda bunga ODZ ni tekshirish qo‘shiladi: har bir topilgan juftlik barcha maxrajlarni noldan farqli qilishi kerak.', 'Основные методы решения систем известны из 8–9 классов: <b>подстановка</b>, <b>сложение</b> и <b>введение новых переменных</b>. В рациональных системах к этому добавляется проверка ОДЗ: каждая найденная пара должна оставлять все знаменатели ненулевыми.', 'The main methods for systems are known from grades 8–9: <b>substitution</b>, <b>elimination</b> and <b>new variables</b>. For rational systems we add a domain check: each pair found must keep every denominator non-zero.'),
      L('<b>Simmetrik sistemalar</b> (x va y o‘rnini almashtirganda o‘zgarmaydigan) uchun u = x + y, v = xy almashtirish juda samarali. U holda x² + y² = u² − 2v, 1/x + 1/y = u/v. u va v topilgach, x va y — t² − ut + v = 0 tenglamaning ildizlari (Viyet teoremasi). Kasrli sistemalarda ba’zan a = 1/x, b = 1/y almashtirish sistemani chiziqliga aylantiradi.', 'Для <b>симметричных систем</b> (не меняющихся при перестановке x и y) очень эффективна замена u = x + y, v = xy. Тогда x² + y² = u² − 2v, 1/x + 1/y = u/v. Найдя u и v, получаем x и y как корни уравнения t² − ut + v = 0 (теорема Виета). В дробных системах иногда замена a = 1/x, b = 1/y делает систему линейной.', 'For <b>symmetric systems</b> (unchanged when x and y are swapped) the substitution u = x + y, v = xy is very effective. Then x² + y² = u² − 2v and 1/x + 1/y = u/v. Once u and v are known, x and y are the roots of t² − ut + v = 0 (Vieta’s theorem). In fractional systems the substitution a = 1/x, b = 1/y sometimes makes the system linear.')
    ], ex: [
      { q: L('Sistemani yeching: x + y = 5, 1/x + 1/y = 5/6.', 'Решите систему: x + y = 5, 1/x + 1/y = 5/6.', 'Solve: x + y = 5, 1/x + 1/y = 5/6.'),
        s: L('1/x + 1/y = (x + y)/(xy) = 5/(xy) = 5/6 ⇒ xy = 6. x va y — t² − 5t + 6 = 0 ning ildizlari: 2 va 3. Javob: (2; 3), (3; 2). Maxrajlar nol emas ✓.', '1/x + 1/y = (x + y)/(xy) = 5/(xy) = 5/6 ⇒ xy = 6. x и y — корни t² − 5t + 6 = 0: 2 и 3. Ответ: (2; 3), (3; 2). Знаменатели не нулевые ✓.', '1/x + 1/y = (x + y)/(xy) = 5/(xy) = 5/6 ⇒ xy = 6. x and y are the roots of t² − 5t + 6 = 0: 2 and 3. Answer: (2; 3), (3; 2). Denominators non-zero ✓.') },
      { q: L('Sistemani yeching: 2/x + 3/y = 2, 4/x − 3/y = 1.', 'Решите систему: 2/x + 3/y = 2, 4/x − 3/y = 1.', 'Solve: 2/x + 3/y = 2, 4/x − 3/y = 1.'),
        s: L('a = 1/x, b = 1/y: 2a + 3b = 2, 4a − 3b = 1. Qo‘shamiz: 6a = 3, a = 1/2; 3b = 2 − 1 = 1, b = 1/3. Demak x = 2, y = 3.', 'a = 1/x, b = 1/y: 2a + 3b = 2, 4a − 3b = 1. Складываем: 6a = 3, a = 1/2; 3b = 2 − 1 = 1, b = 1/3. Значит, x = 2, y = 3.', 'Let a = 1/x, b = 1/y: 2a + 3b = 2, 4a − 3b = 1. Add: 6a = 3, a = 1/2; 3b = 2 − 1 = 1, b = 1/3. So x = 2, y = 3.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>ODZ ni yozmaslik</b> va natijada chet ildizni javobga qo‘shish — eng ko‘p uchraydigan xato.', '<b>Не выписать ОДЗ</b> и в результате включить посторонний корень в ответ — самая частая ошибка.', '<b>Not writing the domain</b> and so keeping an extraneous root — the most common error.'),
      L('<b>Qisqartirishdan keyin shartni yo‘qotish.</b> (x² − 4)/(x − 2) = 4 ⇒ x + 2 = 4 ⇒ x = 2 — lekin bu taqiqlangan, yechim yo‘q.', '<b>Потерять условие после сокращения.</b> (x² − 4)/(x − 2) = 4 ⇒ x + 2 = 4 ⇒ x = 2 — но это запрещено, решений нет.', '<b>Losing the condition after cancelling.</b> (x² − 4)/(x − 2) = 4 ⇒ x + 2 = 4 ⇒ x = 2 — but that is forbidden: no solution.'),
      L('<b>Faqat bir hadni ko‘paytirish.</b> Umumiy maxrajga tenglamaning <b>barcha</b> hadlarini, shu jumladan butun sonlarni ham ko‘paytiring.', '<b>Умножить только один член.</b> На общий знаменатель умножаются <b>все</b> члены уравнения, включая целые числа.', '<b>Multiplying only some terms.</b> Multiply <b>every</b> term by the common denominator, including whole numbers.'),
      L('<b>Almashtirishdan keyin to‘xtab qolish.</b> t topilgach, x ga qaytishni unutmang.', '<b>Остановиться после замены.</b> Найдя t, не забудьте вернуться к x.', '<b>Stopping after the substitution.</b> Once t is found, remember to go back to x.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Birgalikdagi ish.</b> Agar bir ishchi ishni a soatda, ikkinchisi b soatda bajarsa, birgalikda t = ab/(a + b) soatda bajaradi: 1/a + 1/b = 1/t. Bu formula quvurlar, printerlar, kombaynlar va hatto kompyuter protsessorlari uchun ham ishlaydi.', '<b>Совместная работа.</b> Если один работник выполняет работу за a часов, а другой за b, то вместе они справятся за t = ab/(a + b) часов: 1/a + 1/b = 1/t. Эта формула работает для труб, принтеров, комбайнов и даже процессоров.', '<b>Joint work.</b> If one worker finishes a job in a hours and another in b, together they take t = ab/(a + b) hours: 1/a + 1/b = 1/t. The formula works for pipes, printers, combine harvesters and even computer processors.'),
      L('<b>Fizika.</b> Parallel ulangan rezistorlarning umumiy qarshiligi 1/R = 1/R₁ + 1/R₂ — xuddi shu tuzilishdagi ratsional tenglama. Linza formulasi 1/F = 1/d + 1/f fotoapparat va ko‘zoynak hisobida ishlatiladi. <b>Harakat:</b> daryoda oqim bo‘ylab va oqimga qarshi suzish vaqtlari t = s/(v + u) va t = s/(v − u) — kasrli tenglamalar.', '<b>Физика.</b> Общее сопротивление параллельно соединённых резисторов 1/R = 1/R₁ + 1/R₂ — рациональное уравнение того же строения. Формула линзы 1/F = 1/d + 1/f используется при расчёте фотоаппаратов и очков. <b>Движение:</b> время плавания по течению и против течения t = s/(v + u) и t = s/(v − u) — дробные уравнения.', '<b>Physics.</b> The total resistance of resistors in parallel, 1/R = 1/R₁ + 1/R₂, is a rational equation of the same shape. The lens formula 1/F = 1/d + 1/f is used for cameras and glasses. <b>Motion:</b> the times downstream and upstream, t = s/(v + u) and t = s/(v − u), give fractional equations.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('Yeching: (x + 3)/(x − 2) = (2x − 1)/(x − 2).', 'Решите: (x + 3)/(x − 2) = (2x − 1)/(x − 2).', 'Solve: (x + 3)/(x − 2) = (2x − 1)/(x − 2).'),
        s: L('x ≠ 2. x + 3 = 2x − 1 ⇒ x = 4. Javob: 4.', 'x ≠ 2. x + 3 = 2x − 1 ⇒ x = 4. Ответ: 4.', 'x ≠ 2. x + 3 = 2x − 1 ⇒ x = 4. Answer: 4.') },
      { q: L('Qayiq oqim bo‘ylab 24 km va orqaga jami 5 soatda suzdi. Oqim tezligi 2 km/soat. Qayiqning turg‘un suvdagi tezligini toping.', 'Лодка проплыла 24 км по течению и обратно за 5 часов. Скорость течения 2 км/ч. Найдите скорость лодки в стоячей воде.', 'A boat goes 24 km downstream and back in 5 hours. The current is 2 km/h. Find the boat’s speed in still water.'),
        s: L('24/(v + 2) + 24/(v − 2) = 5, v &gt; 2. 24(v − 2) + 24(v + 2) = 5(v² − 4) ⇒ 5v² − 48v − 20 = 0 ⇒ v = (48 ± 52)/10 ⇒ v = 10 (manfiy ildiz tashlanadi). Javob: 10 km/soat.', '24/(v + 2) + 24/(v − 2) = 5, v &gt; 2. 24(v − 2) + 24(v + 2) = 5(v² − 4) ⇒ 5v² − 48v − 20 = 0 ⇒ v = (48 ± 52)/10 ⇒ v = 10 (отрицательный корень отбрасываем). Ответ: 10 км/ч.', '24/(v + 2) + 24/(v − 2) = 5, v &gt; 2. 24(v − 2) + 24(v + 2) = 5(v² − 4) ⇒ 5v² − 48v − 20 = 0 ⇒ v = (48 ± 52)/10 ⇒ v = 10 (discard the negative root). Answer: 10 km/h.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('P(x)/Q(x) = 0 ⇔ P(x) = 0 va Q(x) ≠ 0.', 'P(x)/Q(x) = 0 ⇔ P(x) = 0 и Q(x) ≠ 0.', 'P(x)/Q(x) = 0 ⇔ P(x) = 0 and Q(x) ≠ 0.'),
      L('Algoritm: ODZ → umumiy maxraj → butun tenglama → yechish → tekshirish.', 'Алгоритм: ОДЗ → общий знаменатель → целое уравнение → решение → проверка.', 'Algorithm: domain → common denominator → polynomial equation → solve → check.'),
      L('Chet ildizlar maxrajni nolga aylantiruvchi sonlar; ular tashlanadi.', 'Посторонние корни — числа, обращающие знаменатель в нуль; их отбрасывают.', 'Extraneous roots make a denominator zero and are discarded.'),
      L('Takrorlanuvchi ifoda — yangi o‘zgaruvchi kiritish uchun signal.', 'Повторяющееся выражение — сигнал ввести новую переменную.', 'A repeated expression signals a new variable.'),
      L('Simmetrik sistemalar: u = x + y, v = xy; kasrli: a = 1/x, b = 1/y.', 'Симметричные системы: u = x + y, v = xy; дробные: a = 1/x, b = 1/y.', 'Symmetric systems: u = x + y, v = xy; fractional ones: a = 1/x, b = 1/y.'),
      L('Matnli masalada javobning hayotiy ma’nosini tekshiring.', 'В текстовой задаче проверьте жизненный смысл ответа.', 'In word problems check that the answer makes real-world sense.')
    ] }
  ] });

  // ---------- t8. Ratsional tengsizliklar va ularning sistemalari ----------
  T.add(P, 't8', { sections: [
    { kind: 'intro', h: L('Qachon musbat, qachon manfiy?', 'Когда плюс, когда минус?', 'When positive, when negative?'), p: [
      L('Tenglama bitta nuqtani topadi, tengsizlik esa butun bir <b>oraliqni</b>. Firma qachon foyda ko‘radi? Dori konsentratsiyasi qachon xavfsiz chegarada? Ko‘prik qaysi yuklarda chidaydi? Bunday savollar ko‘pincha kasrli ifodaning ishorasini aniqlashga — <b>ratsional tengsizlikka</b> keltiriladi.', 'Уравнение находит одну точку, а неравенство — целый <b>промежуток</b>. Когда фирма получает прибыль? Когда концентрация лекарства в безопасных пределах? Какие нагрузки выдержит мост? Такие вопросы часто сводятся к определению знака дробного выражения — к <b>рациональному неравенству</b>.', 'An equation finds a single point; an inequality finds a whole <b>interval</b>. When does a company make a profit? When is a drug concentration within safe limits? Which loads can a bridge take? Such questions often reduce to finding the sign of a fractional expression — a <b>rational inequality</b>.'),
      L('9-sinfda kvadrat tengsizliklarni parabola yordamida yechgansiz. Endi esa har qanday ko‘phadlar va kasrlar uchun ishlaydigan universal usulni — <b>intervallar usulini</b> o‘rganamiz. Uning g‘oyasi juda sodda: ko‘paytuvchilarning har biri faqat o‘z nolida ishorasini almashtiradi.', 'В 9 классе вы решали квадратные неравенства с помощью параболы. Теперь мы изучим универсальный способ, работающий для любых многочленов и дробей, — <b>метод интервалов</b>. Его идея очень проста: каждый множитель меняет знак только в своём нуле.', 'In grade 9 you solved quadratic inequalities with the parabola. Now we learn a universal method that works for any polynomials and fractions — the <b>interval method</b>. Its idea is simple: each factor changes sign only at its own zero.')
    ] },
    { kind: 'def', h: L('Ratsional tengsizlik', 'Рациональное неравенство', 'Rational inequality'), p: [
      L('P(x)/Q(x) &gt; 0 (yoki &lt;, ≥, ≤) ko‘rinishidagi tengsizlik, bu yerda P va Q — ko‘phadlar, <b>ratsional tengsizlik</b> deyiladi. Kasr va ko‘paytma bir xil ishoraga ega bo‘lgani uchun <b>P/Q &gt; 0 ⇔ P · Q &gt; 0</b> (Q ≠ 0 avtomatik bajariladi). Qat’iy bo‘lmagan holda: P/Q ≥ 0 ⇔ { P · Q ≥ 0, Q ≠ 0 } — maxraj nollari javobga hech qachon kirmaydi.', 'Неравенство вида P(x)/Q(x) &gt; 0 (или &lt;, ≥, ≤), где P и Q — многочлены, называется <b>рациональным</b>. Так как дробь и произведение имеют одинаковый знак, <b>P/Q &gt; 0 ⇔ P · Q &gt; 0</b> (Q ≠ 0 выполняется автоматически). В нестрогом случае: P/Q ≥ 0 ⇔ { P · Q ≥ 0, Q ≠ 0 } — нули знаменателя никогда не входят в ответ.', 'An inequality P(x)/Q(x) &gt; 0 (or &lt;, ≥, ≤) with polynomials P and Q is a <b>rational inequality</b>. Since a fraction and a product have the same sign, <b>P/Q &gt; 0 ⇔ P · Q &gt; 0</b> (Q ≠ 0 holds automatically). In the non-strict case P/Q ≥ 0 ⇔ { P · Q ≥ 0, Q ≠ 0 } — zeros of the denominator never enter the answer.'),
      L('<b>Asosiy fakt:</b> x − a ko‘paytuvchi x &gt; a da musbat, x &lt; a da manfiy. Shuning uchun (x − a₁)(x − a₂)…(x − aₙ) ko‘paytma nollar orasidagi har bir oraliqda o‘zgarmas ishorani saqlaydi va har bir oddiy nolni kesib o‘tganda ishorasini almashtiradi. Eng o‘ng oraliqda barcha ko‘paytuvchilar musbat — ko‘paytma ham musbat.', '<b>Основной факт:</b> множитель x − a положителен при x &gt; a и отрицателен при x &lt; a. Поэтому произведение (x − a₁)(x − a₂)…(x − aₙ) сохраняет знак на каждом промежутке между нулями и меняет знак при переходе через каждый простой нуль. На самом правом промежутке все множители положительны — и произведение тоже.', '<b>Key fact:</b> the factor x − a is positive for x &gt; a and negative for x &lt; a. So the product (x − a₁)(x − a₂)…(x − aₙ) keeps a constant sign on each interval between zeros and changes sign at each simple zero. On the rightmost interval all factors are positive, so the product is too.')
    ] },
    { kind: 'steps', h: L('Intervallar usuli', 'Метод интервалов', 'The interval method'), list: [
      L('1) Barcha hadlarni chap tomonga o‘tkazing: o‘ngda 0 qolsin. Umumiy maxrajga keltiring.', '1) Перенесите всё в левую часть: справа должен остаться 0. Приведите к общему знаменателю.', '1) Move everything to the left so that 0 is on the right. Bring to a common denominator.'),
      L('2) Surat va maxrajni chiziqli ko‘paytuvchilarga ajrating; x oldidagi koeffitsientlar musbat bo‘lsin (kerak bo‘lsa −1 ni chiqarib, ishorani almashtiring).', '2) Разложите числитель и знаменатель на линейные множители; коэффициенты при x пусть будут положительными (при необходимости вынесите −1 и смените знак).', '2) Factor the numerator and denominator into linear factors with positive x-coefficients (take out −1 and flip the sign if needed).'),
      L('3) Surat nollarini (≥, ≤ da — bo‘yalgan nuqtalar) va maxraj nollarini (doim bo‘sh, «teshik» nuqtalar) son o‘qiga belgilang.', '3) Отметьте на прямой нули числителя (при ≥, ≤ — закрашенные точки) и нули знаменателя (всегда пустые, «выколотые» точки).', '3) Mark the zeros of the numerator (filled dots for ≥, ≤) and of the denominator (always open dots) on the number line.'),
      L('4) Eng o‘ng oraliqqa «+» qo‘ying, so‘ng chapga qarab ishoralarni almashtiring. Juft karrali nolda (masalan, (x − 1)²) ishora almashmaydi!', '4) На самом правом промежутке поставьте «+», затем, двигаясь влево, чередуйте знаки. В нуле чётной кратности (например, (x − 1)²) знак не меняется!', '4) Put “+” on the rightmost interval, then alternate signs moving left. At a zero of even multiplicity (e.g. (x − 1)²) the sign does not change!'),
      L('5) Kerakli ishorali oraliqlarni tanlang va javobni yozing.', '5) Выберите промежутки с нужным знаком и запишите ответ.', '5) Pick the intervals with the required sign and write the answer.')
    ] },
    { kind: 'table', h: L('Ishoralar jadvali usuli', 'Метод таблицы знаков', 'The sign-table method'), p: [
      L('Intervallar usulini jadval ko‘rinishida ham bajarish mumkin. Bu usul ayniqsa boshida foydali: har bir ko‘paytuvchining ishorasi alohida yoziladi, so‘ng ishoralar ko‘paytiriladi. Masalan, (x + 2)(x − 3)/(x − 1) ifoda uchun nollar −2, 1, 3 son o‘qini to‘rt oraliqqa bo‘ladi.', 'Метод интервалов можно выполнять и в виде таблицы. Это особенно полезно вначале: знак каждого множителя записывается отдельно, затем знаки перемножаются. Например, для (x + 2)(x − 3)/(x − 1) нули −2, 1, 3 делят прямую на четыре промежутка.', 'The interval method can also be done as a table. This is especially helpful at first: write the sign of each factor separately, then multiply the signs. For (x + 2)(x − 3)/(x − 1), the zeros −2, 1, 3 split the line into four intervals.')
    ], table: { head: [L('Ko‘paytuvchi', 'Множитель', 'Factor'), L('(−∞; −2)', '(−∞; −2)', '(−∞; −2)'), L('(−2; 1)', '(−2; 1)', '(−2; 1)'), L('(1; 3)', '(1; 3)', '(1; 3)'), L('(3; +∞)', '(3; +∞)', '(3; +∞)')], rows: [
      [L('x + 2', 'x + 2', 'x + 2'), L('−', '−', '−'), L('+', '+', '+'), L('+', '+', '+'), L('+', '+', '+')],
      [L('x − 1', 'x − 1', 'x − 1'), L('−', '−', '−'), L('−', '−', '−'), L('+', '+', '+'), L('+', '+', '+')],
      [L('x − 3', 'x − 3', 'x − 3'), L('−', '−', '−'), L('−', '−', '−'), L('−', '−', '−'), L('+', '+', '+')],
      [L('Butun ifoda', 'Всё выражение', 'Whole expression'), L('−', '−', '−'), L('+', '+', '+'), L('−', '−', '−'), L('+', '+', '+')]
    ] }, after: [
      L('Demak (x + 2)(x − 3)/(x − 1) &gt; 0 ning yechimi (−2; 1) ∪ (3; +∞), ≤ 0 ning yechimi esa (−∞; −2] ∪ (1; 3]. E’tibor bering: x = 1 maxraj noli, u hech qachon javobga kirmaydi. Jadval usuli tajriba ortgach, «o‘ngdan + qo‘yib almashtirish» qoidasiga aylanadi — ikkalasi bir xil natija beradi.', 'Значит, решение (x + 2)(x − 3)/(x − 1) &gt; 0 — (−2; 1) ∪ (3; +∞), а решение ≤ 0 — (−∞; −2] ∪ (1; 3]. Обратите внимание: x = 1 — нуль знаменателя, он никогда не входит в ответ. С опытом таблица превращается в правило «справа плюс, затем чередуем» — оба дают один результат.', 'So (x + 2)(x − 3)/(x − 1) &gt; 0 has solution (−2; 1) ∪ (3; +∞), and ≤ 0 has (−∞; −2] ∪ (1; 3]. Note that x = 1 is a denominator zero and never enters the answer. With practice the table becomes the rule “plus on the right, then alternate” — both give the same result.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Tengsizlik belgilari &lt; va &gt; ni ingliz matematigi Tomas Garriot kiritgan; ular u vafotidan keyin, 1631-yilda nashr etilgan kitobida paydo bo‘lgan. ≤ va ≥ belgilarini 1734-yilda fransuz olimi Per Buger taklif qilgan. Bungacha tengsizliklar so‘z bilan yozilardi.', 'Знаки неравенства &lt; и &gt; ввёл английский математик Томас Хэрриот; они появились в его книге, изданной после его смерти, в 1631 году. Знаки ≤ и ≥ в 1734 году предложил французский учёный Пьер Бугер. До этого неравенства записывали словами.', 'The inequality signs &lt; and &gt; were introduced by the English mathematician Thomas Harriot; they appeared in his book published after his death, in 1631. The signs ≤ and ≥ were proposed in 1734 by the French scientist Pierre Bouguer. Before that, inequalities were written in words.'),
      L('Tengsizliklar nazariyasi XIX–XX asrlarda Koshi, Chebishev va boshqa olimlar ishlarida chuqur rivojlandi. 1934-yilda Xardi, Littlvud va Poya «Tengsizliklar» nomli mashhur kitobni nashr etishdi. Intervallar usuli esa o‘zining soddaligi tufayli butun dunyo maktablarida tengsizliklarni yechishning asosiy vositasiga aylandi.', 'Теория неравенств глубоко развилась в XIX–XX веках в трудах Коши, Чебышёва и других учёных. В 1934 году Харди, Литлвуд и Полиа выпустили знаменитую книгу «Неравенства». А метод интервалов благодаря своей простоте стал главным инструментом решения неравенств в школах всего мира.', 'The theory of inequalities developed deeply in the 19th–20th centuries in the work of Cauchy, Chebyshev and others. In 1934 Hardy, Littlewood and Pólya published the famous book “Inequalities”. Thanks to its simplicity, the interval method became the main tool for solving inequalities in schools worldwide.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Yeching: (x − 1)/(x + 3) ≤ 0.', 'Решите: (x − 1)/(x + 3) ≤ 0.', 'Solve: (x − 1)/(x + 3) ≤ 0.'),
        s: L('Nollar: x = 1 (surat, bo‘yalgan), x = −3 (maxraj, bo‘sh). Ishoralar o‘ngdan: (1; +∞) «+», (−3; 1) «−», (−∞; −3) «+». Bizga «−» va nol kerak: (−3; 1].', 'Нули: x = 1 (числитель, закрашенная), x = −3 (знаменатель, пустая). Знаки справа: (1; +∞) «+», (−3; 1) «−», (−∞; −3) «+». Нужны «−» и нуль: (−3; 1].', 'Zeros: x = 1 (numerator, filled) and x = −3 (denominator, open). Signs from the right: (1; +∞) “+”, (−3; 1) “−”, (−∞; −3) “+”. We need “−” and zero: (−3; 1].') },
      { q: L('Yeching: (x + 2)(x − 1)(x − 4) &gt; 0.', 'Решите: (x + 2)(x − 1)(x − 4) &gt; 0.', 'Solve: (x + 2)(x − 1)(x − 4) &gt; 0.'),
        s: L('Nollar −2, 1, 4. Ishoralar o‘ngdan chapga: +, −, +, −. Musbat oraliqlar: (−2; 1) ∪ (4; +∞).', 'Нули −2, 1, 4. Знаки справа налево: +, −, +, −. Положительные промежутки: (−2; 1) ∪ (4; +∞).', 'Zeros −2, 1, 4. Signs from right to left: +, −, +, −. Positive intervals: (−2; 1) ∪ (4; +∞).') },
      { q: L('Yeching: (x − 2)²(x + 1)/(x − 5) ≥ 0.', 'Решите: (x − 2)²(x + 1)/(x − 5) ≥ 0.', 'Solve: (x − 2)²(x + 1)/(x − 5) ≥ 0.'),
        s: L('Nollar: −1 va 2 (bo‘yalgan), 5 (bo‘sh). O‘ngdan: (5; +∞) «+»; 5 dan o‘tib «−» (2; 5); 2 — juft karrali, ishora saqlanadi: (−1; 2) «−»; −1 dan o‘tib (−∞; −1) «+». Javob: (−∞; −1] ∪ {2} ∪ (5; +∞). x = 2 alohida nuqta — uni yo‘qotmang!', 'Нули: −1 и 2 (закрашенные), 5 (пустая). Справа: (5; +∞) «+»; после 5 — «−» на (2; 5); 2 — чётной кратности, знак сохраняется: (−1; 2) «−»; после −1 — (−∞; −1) «+». Ответ: (−∞; −1] ∪ {2} ∪ (5; +∞). x = 2 — отдельная точка, не потеряйте её!', 'Zeros: −1 and 2 (filled), 5 (open). From the right: (5; +∞) “+”; past 5, “−” on (2; 5); 2 has even multiplicity, so the sign stays: (−1; 2) “−”; past −1, (−∞; −1) “+”. Answer: (−∞; −1] ∪ {2} ∪ (5; +∞). x = 2 is an isolated point — don’t lose it!') },
      { q: L('Yeching: 2/(x − 1) &lt; 1.', 'Решите: 2/(x − 1) &lt; 1.', 'Solve: 2/(x − 1) &lt; 1.'),
        s: L('Ko‘paytirib yubormang (x − 1 ning ishorasi noma’lum)! 2/(x − 1) − 1 &lt; 0 ⇒ (3 − x)/(x − 1) &lt; 0 ⇒ (x − 3)/(x − 1) &gt; 0. Nollar 1, 3. Javob: (−∞; 1) ∪ (3; +∞).', 'Не умножайте (знак x − 1 неизвестен)! 2/(x − 1) − 1 &lt; 0 ⇒ (3 − x)/(x − 1) &lt; 0 ⇒ (x − 3)/(x − 1) &gt; 0. Нули 1, 3. Ответ: (−∞; 1) ∪ (3; +∞).', 'Do not multiply out (the sign of x − 1 is unknown)! 2/(x − 1) − 1 &lt; 0 ⇒ (3 − x)/(x − 1) &lt; 0 ⇒ (x − 3)/(x − 1) &gt; 0. Zeros 1, 3. Answer: (−∞; 1) ∪ (3; +∞).') }
    ] },
    { kind: 'rule', h: L('Tengsizliklar sistemalari', 'Системы неравенств', 'Systems of inequalities'), p: [
      L('<b>Sistema</b> (figurali qavs) — barcha tengsizliklar bir vaqtda bajarilishi kerak; javob — yechimlarning <b>kesishmasi</b>. <b>Majmua</b> (kvadrat qavs) — kamida bittasi bajarilishi kerak; javob — <b>birlashma</b>. Har bir tengsizlikni alohida yechib, natijalarni bitta son o‘qida tasvirlash eng ishonchli yo‘l.', '<b>Система</b> (фигурная скобка) — все неравенства должны выполняться одновременно; ответ — <b>пересечение</b> решений. <b>Совокупность</b> (квадратная скобка) — должно выполняться хотя бы одно; ответ — <b>объединение</b>. Самый надёжный путь — решить каждое неравенство отдельно и изобразить результаты на одной числовой прямой.', 'A <b>system</b> (curly brace) requires all inequalities to hold at once; the answer is the <b>intersection</b>. A <b>collection</b> (square bracket) needs at least one to hold; the answer is the <b>union</b>. The safest way is to solve each inequality separately and draw the results on one number line.'),
      L('Ikki tomonlama tengsizlik a &lt; f(x) &lt; b — bu sistema: { f(x) &gt; a, f(x) &lt; b }. Masalan, 0 &lt; 1/x &lt; 1 ⇔ x &gt; 1.', 'Двойное неравенство a &lt; f(x) &lt; b — это система { f(x) &gt; a, f(x) &lt; b }. Например, 0 &lt; 1/x &lt; 1 ⇔ x &gt; 1.', 'A double inequality a &lt; f(x) &lt; b is the system { f(x) &gt; a, f(x) &lt; b }. For example, 0 &lt; 1/x &lt; 1 ⇔ x &gt; 1.')
    ], ex: [
      { q: L('Sistemani yeching: x² − 9 &lt; 0 va (x − 1)/(x + 2) ≥ 0.', 'Решите систему: x² − 9 &lt; 0 и (x − 1)/(x + 2) ≥ 0.', 'Solve the system: x² − 9 &lt; 0 and (x − 1)/(x + 2) ≥ 0.'),
        s: L('Birinchisi: (−3; 3). Ikkinchisi: (−∞; −2) ∪ [1; +∞). Kesishma: (−3; −2) ∪ [1; 3).', 'Первое: (−3; 3). Второе: (−∞; −2) ∪ [1; +∞). Пересечение: (−3; −2) ∪ [1; 3).', 'First: (−3; 3). Second: (−∞; −2) ∪ [1; +∞). Intersection: (−3; −2) ∪ [1; 3).') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Maxrajga ko‘paytirish.</b> 1/x &gt; 2 ni «1 &gt; 2x» deb yozish noto‘g‘ri — x manfiy bo‘lsa, ishora almashadi. Har doim 0 ga keltiring.', '<b>Умножение на знаменатель.</b> Писать 1/x &gt; 2 как «1 &gt; 2x» неверно — при отрицательном x знак меняется. Всегда приводите к сравнению с 0.', '<b>Multiplying by the denominator.</b> Writing 1/x &gt; 2 as “1 &gt; 2x” is wrong — for negative x the sign flips. Always compare with 0.'),
      L('<b>Maxraj nolini javobga qo‘shish.</b> ≥ bo‘lsa ham maxraj nollari doim bo‘sh nuqta.', '<b>Включать нуль знаменателя в ответ.</b> Даже при ≥ нули знаменателя — всегда пустые точки.', '<b>Including a denominator zero.</b> Even with ≥, zeros of the denominator are always open.'),
      L('<b>Juft karrali nolda ishorani almashtirish.</b> (x − a)² dan o‘tganda ishora saqlanadi.', '<b>Менять знак в нуле чётной кратности.</b> При переходе через (x − a)² знак сохраняется.', '<b>Switching sign at an even zero.</b> Crossing (x − a)² keeps the sign.'),
      L('<b>Manfiy koeffitsientli ko‘paytuvchi.</b> (2 − x) ni (x − 2) ga almashtirganda tengsizlik ishorasini almashtirishni unutmang.', '<b>Множитель с отрицательным коэффициентом.</b> Заменяя (2 − x) на (x − 2), не забудьте сменить знак неравенства.', '<b>A factor with negative coefficient.</b> When replacing (2 − x) by (x − 2), remember to flip the inequality.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Iqtisod.</b> Mahsulot birligining o‘rtacha tannarxi c(x) = (F + vx)/x, bu yerda F — doimiy xarajat, v — bir dona uchun xarajat. «Tannarx 12 000 so‘mdan oshmasin» sharti ratsional tengsizlik: (F + vx)/x ≤ 12 000. Undan zavod kamida nechta mahsulot ishlab chiqarishi kerakligi topiladi.', '<b>Экономика.</b> Средняя себестоимость единицы продукции c(x) = (F + vx)/x, где F — постоянные затраты, v — затраты на одну штуку. Условие «себестоимость не выше 12 000 сумов» — рациональное неравенство: (F + vx)/x ≤ 12 000. Из него находят, сколько изделий минимум должен выпустить завод.', '<b>Economics.</b> The average cost per unit is c(x) = (F + vx)/x, where F is the fixed cost and v the cost per item. The requirement “cost at most 12 000 soums” is a rational inequality: (F + vx)/x ≤ 12 000, which tells the factory the minimum number of items to make.'),
      L('<b>Tibbiyot va muhandislik.</b> Dori qondagi konsentratsiyasi ko‘pincha C(t) = at/(t² + b) ko‘rinishida modellanadi; shifokor C(t) ≥ C_min bo‘ladigan vaqt oralig‘ini — dori ta’sir qiladigan vaqtni topadi. Muhandislar esa materialdagi kuchlanish ruxsat etilgan chegaradan oshmasligi uchun shunga o‘xshash tengsizliklarni yechadi.', '<b>Медицина и инженерия.</b> Концентрацию лекарства в крови часто моделируют функцией C(t) = at/(t² + b); врач находит промежуток времени, когда C(t) ≥ C_min, — время действия лекарства. Инженеры решают подобные неравенства, чтобы напряжение в материале не превышало допустимого.', '<b>Medicine and engineering.</b> Drug concentration in the blood is often modelled by C(t) = at/(t² + b); a doctor finds the time interval where C(t) ≥ C_min — how long the drug works. Engineers solve similar inequalities to keep stress in a material within the allowed limit.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('Yeching: (x² − 4)/(x² + 1) &lt; 0.', 'Решите: (x² − 4)/(x² + 1) &lt; 0.', 'Solve: (x² − 4)/(x² + 1) &lt; 0.'),
        s: L('x² + 1 &gt; 0 doim, shuning uchun x² − 4 &lt; 0 ⇒ (−2; 2).', 'x² + 1 &gt; 0 всегда, поэтому x² − 4 &lt; 0 ⇒ (−2; 2).', 'x² + 1 &gt; 0 always, so x² − 4 &lt; 0 ⇒ (−2; 2).') },
      { q: L('Yeching: x/(x − 3) ≥ 2.', 'Решите: x/(x − 3) ≥ 2.', 'Solve: x/(x − 3) ≥ 2.'),
        s: L('x/(x − 3) − 2 ≥ 0 ⇒ (6 − x)/(x − 3) ≥ 0 ⇒ (x − 6)/(x − 3) ≤ 0. Javob: (3; 6].', 'x/(x − 3) − 2 ≥ 0 ⇒ (6 − x)/(x − 3) ≥ 0 ⇒ (x − 6)/(x − 3) ≤ 0. Ответ: (3; 6].', 'x/(x − 3) − 2 ≥ 0 ⇒ (6 − x)/(x − 3) ≥ 0 ⇒ (x − 6)/(x − 3) ≤ 0. Answer: (3; 6].') }
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Mashhur tengsizlik: musbat a va b uchun (a + b)/2 ≥ √(ab) — o‘rta arifmetik o‘rta geometrikdan kichik emas. Undan, masalan, x &gt; 0 da x + 1/x ≥ 2 kelib chiqadi; tenglik faqat x = 1 da.', 'Знаменитое неравенство: для положительных a и b (a + b)/2 ≥ √(ab) — среднее арифметическое не меньше среднего геометрического. Из него, например, следует x + 1/x ≥ 2 при x &gt; 0; равенство только при x = 1.', 'A famous inequality: for positive a and b, (a + b)/2 ≥ √(ab) — the arithmetic mean is at least the geometric mean. It gives, for example, x + 1/x ≥ 2 for x &gt; 0, with equality only at x = 1.'),
      L('Kompyuter algebra tizimlari (masalan, Wolfram Alpha) ratsional tengsizliklarni xuddi intervallar usuli g‘oyasi bilan yechadi: avval ko‘phadning ildizlarini topadi, so‘ng har bir oraliqdan bitta sinov nuqtasini oladi.', 'Системы компьютерной алгебры (например, Wolfram Alpha) решают рациональные неравенства по той же идее, что и метод интервалов: сначала находят корни многочленов, затем берут по одной пробной точке из каждого промежутка.', 'Computer algebra systems (Wolfram Alpha, for instance) solve rational inequalities with the same idea as the interval method: they find the roots of the polynomials, then test one point from each interval.'),
      L('Har qanday oraliqdan bitta «sinov nuqtasi»ni olish — ishorani tekshirishning eng oddiy usuli: masalan, (x − 1)/(x + 3) uchun x = 0 da −1/3 &lt; 0, demak butun (−3; 1) oraliqda ifoda manfiy.', 'Взять одну «пробную точку» из промежутка — простейший способ проверить знак: например, для (x − 1)/(x + 3) при x = 0 получаем −1/3 &lt; 0, значит, на всём (−3; 1) выражение отрицательно.', 'Taking one “test point” from an interval is the simplest sign check: for (x − 1)/(x + 3) at x = 0 we get −1/3 &lt; 0, so the expression is negative on the whole of (−3; 1).')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('P/Q &gt; 0 ⇔ P · Q &gt; 0; P/Q ≥ 0 ⇔ P · Q ≥ 0, Q ≠ 0.', 'P/Q &gt; 0 ⇔ P · Q &gt; 0; P/Q ≥ 0 ⇔ P · Q ≥ 0, Q ≠ 0.', 'P/Q &gt; 0 ⇔ P · Q &gt; 0; P/Q ≥ 0 ⇔ P · Q ≥ 0, Q ≠ 0.'),
      L('Avval hammasini chapga o‘tkazib, 0 bilan solishtiring; maxrajga ko‘paytirmang.', 'Сначала перенесите всё влево и сравнивайте с 0; не умножайте на знаменатель.', 'First move everything left and compare with 0; never multiply by the denominator.'),
      L('Intervallar usuli: nollar → o‘ngda «+» → navbatma-navbat ishoralar.', 'Метод интервалов: нули → справа «+» → чередование знаков.', 'Interval method: zeros → “+” on the right → alternate signs.'),
      L('Juft karrali nolda ishora almashmaydi.', 'В нуле чётной кратности знак не меняется.', 'At an even-multiplicity zero the sign does not change.'),
      L('Maxraj nollari — doim bo‘sh nuqtalar.', 'Нули знаменателя — всегда выколотые точки.', 'Denominator zeros are always open points.'),
      L('Sistema — kesishma, majmua — birlashma.', 'Система — пересечение, совокупность — объединение.', 'System — intersection; collection — union.')
    ] }
  ] });

  // ---------- t9. Irratsional tenglamalar va ularning sistemalari ----------
  T.add(P, 't9', { sections: [
    { kind: 'intro', h: L('Ildiz ostidagi noma’lum', 'Неизвестное под корнем', 'The unknown under a root'), p: [
      L('Mayatnik tebranish davri T = 2π√(l/g), erkin tushish vaqti t = √(2h/g), ufqgacha masofa d ≈ √(2Rh). Fizikada noma’lum kattalik ko‘pincha ildiz ostida bo‘ladi. Masalan, «mayatnik davri 2 soniya bo‘lishi uchun ip uzunligi qancha bo‘lishi kerak?» degan savol <b>irratsional tenglamaga</b> olib keladi.', 'Период маятника T = 2π√(l/g), время свободного падения t = √(2h/g), расстояние до горизонта d ≈ √(2Rh). В физике неизвестная величина часто стоит под корнем. Например, вопрос «какой длины должна быть нить, чтобы период маятника был 2 секунды?» приводит к <b>иррациональному уравнению</b>.', 'A pendulum’s period T = 2π√(l/g), free-fall time t = √(2h/g), distance to the horizon d ≈ √(2Rh). In physics the unknown is often under a root. For example, “how long must the string be for a 2-second period?” leads to an <b>irrational equation</b>.'),
      L('Bunday tenglamalarni yechishning asosiy g‘oyasi oddiy — ildizdan qutulish uchun ikkala tomonni darajaga ko‘tarish. Lekin bu qadam teng kuchli emas: kvadratga ko‘targanda yangi, «yolg‘on» ildizlar paydo bo‘lishi mumkin. Bu mavzuda biz ularni qanday ushlash va yo‘qotmaslikni o‘rganamiz.', 'Основная идея решения таких уравнений проста — чтобы избавиться от корня, возводим обе части в степень. Но этот шаг неравносилен: при возведении в квадрат могут появиться новые, «ложные» корни. В этой теме мы научимся их отлавливать.', 'The main idea for solving such equations is simple — raise both sides to a power to get rid of the root. But this step is not equivalent: squaring can create new, “false” roots. In this topic we learn how to catch them.')
    ] },
    { kind: 'def', h: L('Ta’rif va asosiy xossalar', 'Определение и основные свойства', 'Definition and basic properties'), p: [
      L('O‘zgaruvchi ildiz belgisi ostida (yoki kasr ko‘rsatkichli daraja asosida) qatnashgan tenglama <b>irratsional tenglama</b> deyiladi: √(x + 3) = x − 3, √x + √(x − 5) = 5, ∛(x − 1) = 2. Esda tutish kerak bo‘lgan ikki fakt: 1) arifmetik kvadrat ildiz <b>manfiy emas</b>: √a ≥ 0; 2) juft darajali ildiz faqat a ≥ 0 da aniqlangan.', 'Уравнение, в котором переменная стоит под знаком корня (или в основании степени с дробным показателем), называется <b>иррациональным</b>: √(x + 3) = x − 3, √x + √(x − 5) = 5, ∛(x − 1) = 2. Нужно помнить два факта: 1) арифметический квадратный корень <b>неотрицателен</b>: √a ≥ 0; 2) корень чётной степени определён только при a ≥ 0.', 'An equation with the variable under a root sign (or in the base of a power with a fractional exponent) is an <b>irrational equation</b>: √(x + 3) = x − 3, √x + √(x − 5) = 5, ∛(x − 1) = 2. Remember two facts: 1) the arithmetic square root is <b>non-negative</b>: √a ≥ 0; 2) an even root is defined only for a ≥ 0.'),
      L('Bu ikki faktdan ko‘p tenglamalarni hisoblashsiz yechish mumkin: √(x − 2) = −3 ning yechimi yo‘q (chap tomon manfiy emas). √(x − 4) + √(1 − x) = 1 ham yechimga ega emas: x ≥ 4 va x ≤ 1 bir vaqtda bajarilmaydi. Toq darajali ildizlar (∛) bilan muammo yo‘q: ular barcha haqiqiy sonlarda aniqlangan va kubga ko‘tarish teng kuchli almashtirish.', 'Из этих двух фактов многие уравнения решаются без вычислений: √(x − 2) = −3 не имеет решений (левая часть неотрицательна). √(x − 4) + √(1 − x) = 1 тоже не имеет решений: x ≥ 4 и x ≤ 1 не выполняются одновременно. С корнями нечётной степени (∛) проблем нет: они определены при всех действительных числах, а возведение в куб — равносильное преобразование.', 'These two facts solve many equations without any calculation: √(x − 2) = −3 has no solution (the left side is non-negative). √(x − 4) + √(1 − x) = 1 has none either: x ≥ 4 and x ≤ 1 cannot both hold. Odd roots (∛) cause no trouble: they are defined for all real numbers and cubing is an equivalent transformation.')
    ] },
    { kind: 'rule', h: L('Nega chet ildizlar paydo bo‘ladi?', 'Откуда берутся посторонние корни?', 'Where do extraneous roots come from?'), p: [
      L('a = b bo‘lsa, a² = b². Lekin teskarisi to‘g‘ri emas: a² = b² dan a = b yoki a = −b kelib chiqadi. Masalan, x = 3 tenglamaning bitta ildizi bor, x² = 9 ning esa ikkita: 3 va −3. Demak kvadratga ko‘tarish natijasida biz f = g tenglamaga f = −g tenglamaning ildizlarini ham «qo‘shib» olamiz.', 'Если a = b, то a² = b². Но обратное неверно: из a² = b² следует a = b или a = −b. Например, уравнение x = 3 имеет один корень, а x² = 9 — два: 3 и −3. Значит, возводя в квадрат, мы «добавляем» к уравнению f = g корни уравнения f = −g.', 'If a = b then a² = b². But the converse fails: a² = b² gives a = b or a = −b. For example, x = 3 has one root but x² = 9 has two: 3 and −3. So squaring “adds” the roots of f = −g to the equation f = g.'),
      L('Shuning uchun asosiy teng kuchli o‘tish quyidagicha: <b>√f(x) = g(x) ⇔ { f(x) = g²(x), g(x) ≥ 0 }</b>. f(x) ≥ 0 shartini alohida yozish shart emas — u f = g² dan avtomatik kelib chiqadi. Ikkinchi yo‘l — oxirida barcha topilgan sonlarni dastlabki tenglamaga qo‘yib <b>tekshirish</b>. Irratsional tenglamalarda tekshirish yechimning ajralmas qismi.', 'Поэтому основной равносильный переход таков: <b>√f(x) = g(x) ⇔ { f(x) = g²(x), g(x) ≥ 0 }</b>. Условие f(x) ≥ 0 писать отдельно не нужно — оно автоматически следует из f = g². Второй путь — в конце <b>проверить</b>, подставив все найденные числа в исходное уравнение. В иррациональных уравнениях проверка — неотъемлемая часть решения.', 'So the key equivalent step is: <b>√f(x) = g(x) ⇔ { f(x) = g²(x), g(x) ≥ 0 }</b>. The condition f(x) ≥ 0 need not be written separately — it follows from f = g². The other way is to <b>check</b> all numbers found by substituting them into the original equation. In irrational equations checking is an essential part of the solution.')
    ] },
    { kind: 'steps', h: L('Yechish usullari', 'Методы решения', 'Solution methods'), list: [
      L('<b>Ildizni yolg‘izlab, kvadratga ko‘tarish.</b> Bitta ildizni bir tomonda qoldiring, qolganini ikkinchi tomonga o‘tkazing, so‘ng kvadratga ko‘taring.', '<b>Уединение корня и возведение в квадрат.</b> Оставьте один корень в одной части, остальное перенесите, затем возведите в квадрат.', '<b>Isolate the root and square.</b> Keep one root on one side, move the rest to the other, then square.'),
      L('<b>Ikki ildiz bo‘lsa — ikki marta kvadratga ko‘tarish.</b> Birinchi kvadratlashdan keyin yana bitta ildiz qoladi; uni yolg‘izlab, qayta ko‘taring.', '<b>Два корня — два возведения в квадрат.</b> После первого возведения остаётся один корень; уедините его и возведите снова.', '<b>Two roots — square twice.</b> After the first squaring one root remains; isolate it and square again.'),
      L('<b>Yangi o‘zgaruvchi.</b> x + √x − 6 = 0 da t = √x ≥ 0: t² + t − 6 = 0, t = 2 (t = −3 mos emas), x = 4.', '<b>Новая переменная.</b> В x + √x − 6 = 0 положим t = √x ≥ 0: t² + t − 6 = 0, t = 2 (t = −3 не подходит), x = 4.', '<b>New variable.</b> In x + √x − 6 = 0 let t = √x ≥ 0: t² + t − 6 = 0, t = 2 (t = −3 fails), x = 4.'),
      L('<b>Funksiyalar xossalaridan foydalanish.</b> √(x + 1) + √(x + 6) = 5 da chap tomon o‘suvchi, demak ildiz ko‘pi bilan bitta; x = 3 ni tanlab topamiz: 2 + 3 = 5.', '<b>Использование свойств функций.</b> В √(x + 1) + √(x + 6) = 5 левая часть возрастает, значит, корень не более одного; подбором x = 3: 2 + 3 = 5.', '<b>Use properties of functions.</b> In √(x + 1) + √(x + 6) = 5 the left side is increasing, so there is at most one root; trying x = 3 gives 2 + 3 = 5.'),
      L('<b>Har doim oxirida tekshiring</b> yoki teng kuchli sistemadan foydalaning.', '<b>Всегда делайте проверку в конце</b> или используйте равносильную систему.', '<b>Always check at the end</b> or use the equivalent system.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('«Irratsional» so‘zi lotincha irrationalis — «aqlga sig‘maydigan», «nisbatsiz» degan ma’noni bildiradi. Afsonaga ko‘ra, miloddan avvalgi V asrda Pifagor maktabi a’zosi Gippas tomoni 1 bo‘lgan kvadrat diagonali √2 ni ikki butun son nisbati sifatida yozib bo‘lmasligini isbotlagan. Bu kashfiyot «hamma narsa son» degan pifagorchilar falsafasini larzaga keltirgan.', 'Слово «иррациональный» происходит от латинского irrationalis — «неразумный», «несоизмеримый». По преданию, в V веке до н. э. пифагореец Гиппас доказал, что диагональ квадрата со стороной 1, √2, нельзя записать как отношение двух целых чисел. Это открытие потрясло философию пифагорейцев «всё есть число».', 'The word “irrational” comes from the Latin irrationalis — “without reason”, “without ratio”. According to legend, in the 5th century BC the Pythagorean Hippasus proved that the diagonal of a unit square, √2, cannot be written as a ratio of two whole numbers. The discovery shook the Pythagorean philosophy that “all is number”.'),
      L('Ildiz belgisi √ ni 1525-yilda nemis matematigi Kristof Rudolf kiritgan; u lotincha radix (ildiz) so‘zining bosh harfi r dan kelib chiqqan deb hisoblanadi. Ildiz ustidagi gorizontal chiziqni esa 1637-yilda Dekart qo‘shgan. O‘rta Osiyo olimlari ham ildizlar bilan ko‘p ishlagan: Umar Xayyom kub tenglamalarni geometrik usulda yechgan, Jamshid al-Koshiy esa 1427-yilda «Arifmetika kaliti» asarida istalgan darajali ildizni chiqarish usulini bayon qilgan.', 'Знак корня √ ввёл немецкий математик Кристоф Рудольф в 1525 году; считается, что он произошёл от буквы r — первой буквы латинского radix (корень). Горизонтальную черту над корнем добавил Декарт в 1637 году. Учёные Средней Азии тоже много работали с корнями: Омар Хайям решал кубические уравнения геометрически, а Джамшид ал-Каши в 1427 году в «Ключе арифметики» описал способ извлечения корня любой степени.', 'The root sign √ was introduced by the German mathematician Christoph Rudolff in 1525; it is thought to come from the letter r of the Latin radix (root). Descartes added the horizontal bar over the root in 1637. Central Asian scholars worked a lot with roots too: Omar Khayyam solved cubic equations geometrically, and Jamshid al-Kashi described how to extract roots of any degree in his “Key to Arithmetic” in 1427.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Yeching: √(x + 3) = x − 3.', 'Решите: √(x + 3) = x − 3.', 'Solve: √(x + 3) = x − 3.'),
        s: L('Shart: x − 3 ≥ 0 ⇒ x ≥ 3. Kvadratga ko‘taramiz: x + 3 = x² − 6x + 9 ⇒ x² − 7x + 6 = 0 ⇒ x = 6 yoki x = 1. x = 1 shartni buzadi (o‘ng tomon −2) — chet ildiz. Tekshirish: √9 = 3 = 6 − 3 ✓. Javob: 6.', 'Условие: x − 3 ≥ 0 ⇒ x ≥ 3. Возводим в квадрат: x + 3 = x² − 6x + 9 ⇒ x² − 7x + 6 = 0 ⇒ x = 6 или x = 1. x = 1 нарушает условие (правая часть −2) — посторонний корень. Проверка: √9 = 3 = 6 − 3 ✓. Ответ: 6.', 'Condition: x − 3 ≥ 0 ⇒ x ≥ 3. Square: x + 3 = x² − 6x + 9 ⇒ x² − 7x + 6 = 0 ⇒ x = 6 or x = 1. x = 1 breaks the condition (right side −2) — extraneous. Check: √9 = 3 = 6 − 3 ✓. Answer: 6.') },
      { q: L('Yeching: √(2x − 1) = √(x + 4).', 'Решите: √(2x − 1) = √(x + 4).', 'Solve: √(2x − 1) = √(x + 4).'),
        s: L('Ikkala tomon manfiy emas, kvadratga ko‘taramiz: 2x − 1 = x + 4 ⇒ x = 5. Ildiz ostilar: 9 ≥ 0 va 9 ≥ 0 ✓. Javob: 5.', 'Обе части неотрицательны, возводим в квадрат: 2x − 1 = x + 4 ⇒ x = 5. Подкоренные: 9 ≥ 0 и 9 ≥ 0 ✓. Ответ: 5.', 'Both sides are non-negative; square: 2x − 1 = x + 4 ⇒ x = 5. Radicands: 9 ≥ 0 and 9 ≥ 0 ✓. Answer: 5.') },
      { q: L('Yeching: √(x + 5) − √x = 1.', 'Решите: √(x + 5) − √x = 1.', 'Solve: √(x + 5) − √x = 1.'),
        s: L('√(x + 5) = 1 + √x. Kvadrat: x + 5 = 1 + 2√x + x ⇒ 2√x = 4 ⇒ √x = 2 ⇒ x = 4. Tekshirish: √9 − √4 = 3 − 2 = 1 ✓. Javob: 4.', '√(x + 5) = 1 + √x. Квадрат: x + 5 = 1 + 2√x + x ⇒ 2√x = 4 ⇒ √x = 2 ⇒ x = 4. Проверка: √9 − √4 = 3 − 2 = 1 ✓. Ответ: 4.', '√(x + 5) = 1 + √x. Square: x + 5 = 1 + 2√x + x ⇒ 2√x = 4 ⇒ √x = 2 ⇒ x = 4. Check: √9 − √4 = 3 − 2 = 1 ✓. Answer: 4.') },
      { q: L('Yeching: ∛(x² − 8) = −2.', 'Решите: ∛(x² − 8) = −2.', 'Solve: ∛(x² − 8) = −2.'),
        s: L('Kub ildiz — kubga ko‘tarish teng kuchli: x² − 8 = −8 ⇒ x² = 0 ⇒ x = 0. Javob: 0. (Kub ildizda manfiy natija mumkin!)', 'Кубический корень — возведение в куб равносильно: x² − 8 = −8 ⇒ x² = 0 ⇒ x = 0. Ответ: 0. (У кубического корня отрицательный результат возможен!)', 'Cube root — cubing is equivalent: x² − 8 = −8 ⇒ x² = 0 ⇒ x = 0. Answer: 0. (A cube root can be negative!)') }
    ] },
    { kind: 'rule', h: L('Irratsional tenglamalar sistemalari', 'Системы иррациональных уравнений', 'Systems of irrational equations'), p: [
      L('Sistemalarda ko‘pincha yangi o‘zgaruvchilar kiritish eng qisqa yo‘l: u = √x, v = √y (u, v ≥ 0). Shundan so‘ng sistema ratsional — odatda chiziqli yoki simmetrik — sistemaga aylanadi. Topilgan u, v manfiy bo‘lmasligi kerak, aks holda ular tashlanadi.', 'В системах часто кратчайший путь — ввести новые переменные: u = √x, v = √y (u, v ≥ 0). После этого система становится рациональной — обычно линейной или симметричной. Найденные u, v должны быть неотрицательными, иначе их отбрасывают.', 'For systems the shortest route is often new variables: u = √x, v = √y (u, v ≥ 0). The system then becomes rational — usually linear or symmetric. The values of u and v found must be non-negative, otherwise they are discarded.')
    ], ex: [
      { q: L('Sistemani yeching: √x + √y = 5, x − y = 5.', 'Решите систему: √x + √y = 5, x − y = 5.', 'Solve: √x + √y = 5, x − y = 5.'),
        s: L('u = √x, v = √y ≥ 0. u + v = 5, u² − v² = 5 ⇒ (u − v)(u + v) = 5 ⇒ u − v = 1. Demak u = 3, v = 2; x = 9, y = 4. Tekshirish: 3 + 2 = 5, 9 − 4 = 5 ✓.', 'u = √x, v = √y ≥ 0. u + v = 5, u² − v² = 5 ⇒ (u − v)(u + v) = 5 ⇒ u − v = 1. Значит, u = 3, v = 2; x = 9, y = 4. Проверка: 3 + 2 = 5, 9 − 4 = 5 ✓.', 'u = √x, v = √y ≥ 0. u + v = 5, u² − v² = 5 ⇒ (u − v)(u + v) = 5 ⇒ u − v = 1. So u = 3, v = 2; x = 9, y = 4. Check: 3 + 2 = 5, 9 − 4 = 5 ✓.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>Tekshirmaslik.</b> √(x + 3) = x − 3 da x = 1 ni javobga yozish — klassik xato.', '<b>Не делать проверку.</b> Записать x = 1 в ответ для √(x + 3) = x − 3 — классическая ошибка.', '<b>Not checking.</b> Writing x = 1 as an answer to √(x + 3) = x − 3 is a classic mistake.'),
      L('<b>Yig‘indini noto‘g‘ri kvadratga ko‘tarish.</b> (1 + √x)² = 1 + 2√x + x, «1 + x» emas.', '<b>Неверно возводить сумму в квадрат.</b> (1 + √x)² = 1 + 2√x + x, а не «1 + x».', '<b>Squaring a sum wrongly.</b> (1 + √x)² = 1 + 2√x + x, not “1 + x”.'),
      L('<b>√(a²) = a deb yozish.</b> To‘g‘risi √(a²) = |a|.', '<b>Писать √(a²) = a.</b> Правильно √(a²) = |a|.', '<b>Writing √(a²) = a.</b> Correctly √(a²) = |a|.'),
      L('<b>Ildizni yolg‘izlamay kvadratga ko‘tarish.</b> √x + √(x − 5) = 5 ni darhol kvadratga ko‘tarish ishni chalkashtiradi — avval bitta ildizni o‘tkazing.', '<b>Возводить в квадрат, не уединив корень.</b> Сразу возводить √x + √(x − 5) = 5 в квадрат — запутаться; сначала перенесите один корень.', '<b>Squaring without isolating a root.</b> Squaring √x + √(x − 5) = 5 directly gets messy — move one root across first.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Mayatnik va soatlar.</b> T = 2π√(l/g) formulasidan l = gT²/(4π²). Davri 2 soniya bo‘lgan («sekund») mayatnik uzunligi taxminan 0,994 m. Eski devor soatlarida aynan shunday mayatniklar ishlatilgan.', '<b>Маятник и часы.</b> Из T = 2π√(l/g) получаем l = gT²/(4π²). Длина «секундного» маятника с периодом 2 секунды — примерно 0,994 м. Именно такие маятники ставили в старинные напольные часы.', '<b>Pendulums and clocks.</b> From T = 2π√(l/g) we get l = gT²/(4π²). A “seconds” pendulum with a 2-second period is about 0.994 m long. Old grandfather clocks used exactly such pendulums.'),
      L('<b>Navigatsiya va xavfsizlik.</b> Ufqgacha masofa d ≈ √(2Rh): 1,7 m bo‘yli odam dengiz bo‘yida taxminan 4,7 km uzoqlikni ko‘radi, 100 m balandlikdagi mayoq esa 36 km gacha ko‘rinadi. Yo‘l harakati xavfsizligida tormoz izi uzunligidan tezlikni aniqlashda v = √(2μgs) formulasi qo‘llaniladi — bu yerda ham noma’lum ildiz ostida.', '<b>Навигация и безопасность.</b> Расстояние до горизонта d ≈ √(2Rh): человек ростом 1,7 м на берегу моря видит примерно на 4,7 км, а маяк высотой 100 м виден до 36 км. При расследовании ДТП скорость по длине тормозного следа находят по формуле v = √(2μgs) — и здесь неизвестное под корнем.', '<b>Navigation and safety.</b> The horizon distance d ≈ √(2Rh): a person 1.7 m tall on a beach sees about 4.7 km, and a 100 m lighthouse is visible up to 36 km. In accident investigation, speed is found from the length of skid marks by v = √(2μgs) — again the unknown is under a root.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('Yeching: √(5 − x) = x + 1.', 'Решите: √(5 − x) = x + 1.', 'Solve: √(5 − x) = x + 1.'),
        s: L('x ≥ −1. 5 − x = x² + 2x + 1 ⇒ x² + 3x − 4 = 0 ⇒ x = 1 yoki x = −4. x = −4 &lt; −1 — chet. Javob: 1.', 'x ≥ −1. 5 − x = x² + 2x + 1 ⇒ x² + 3x − 4 = 0 ⇒ x = 1 или x = −4. x = −4 &lt; −1 — посторонний. Ответ: 1.', 'x ≥ −1. 5 − x = x² + 2x + 1 ⇒ x² + 3x − 4 = 0 ⇒ x = 1 or x = −4. x = −4 &lt; −1 is extraneous. Answer: 1.') },
      { q: L('Yeching: x − 5√x + 6 = 0.', 'Решите: x − 5√x + 6 = 0.', 'Solve: x − 5√x + 6 = 0.'),
        s: L('t = √x ≥ 0: t² − 5t + 6 = 0, t = 2 yoki 3. x = 4 yoki 9.', 't = √x ≥ 0: t² − 5t + 6 = 0, t = 2 или 3. x = 4 или 9.', 't = √x ≥ 0: t² − 5t + 6 = 0, t = 2 or 3. x = 4 or 9.') }
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('√2 = 1,41421356… — o‘nli kasr ko‘rinishida cheksiz va davriy emas. Bobil gil taxtachasi YBC 7289 (taxminan mil. av. 1800-yil) da √2 oltmishli sanoqda 1,414213 aniqlikda yozilgan.', '√2 = 1,41421356… — бесконечная непериодическая десятичная дробь. На вавилонской глиняной табличке YBC 7289 (около 1800 г. до н. э.) √2 записан в шестидесятеричной системе с точностью 1,414213.', '√2 = 1.41421356… is an infinite non-repeating decimal. The Babylonian clay tablet YBC 7289 (about 1800 BC) records √2 in base 60 to an accuracy of 1.414213.'),
      L('Qadimgi «Geron usuli» bilan ildizni qo‘lda tez hisoblash mumkin: xₙ₊₁ = (xₙ + a/xₙ)/2. √10 uchun x₀ = 3 dan boshlasak: 3,1667; 3,1623 — ikki qadamda to‘rt xona aniqlik. Kalkulyatorlar ham shunga o‘xshash algoritmdan foydalanadi.', 'Древним «методом Герона» корень можно быстро вычислить вручную: xₙ₊₁ = (xₙ + a/xₙ)/2. Для √10, начиная с x₀ = 3: 3,1667; 3,1623 — четыре знака за два шага. Калькуляторы используют похожий алгоритм.', 'The ancient “Heron’s method” computes a root quickly by hand: xₙ₊₁ = (xₙ + a/xₙ)/2. For √10 starting at x₀ = 3: 3.1667, 3.1623 — four digits in two steps. Calculators use a similar algorithm.'),
      L('√(x − 1) + √(1 − x) = 0 tenglamaning aniqlanish sohasi bitta nuqtadan iborat: x = 1. Uni tekshirsak, 0 + 0 = 0 — demak bu yagona yechim. Ba’zan ODZ ning o‘zi javobni beradi!', 'Область определения уравнения √(x − 1) + √(1 − x) = 0 состоит из одной точки: x = 1. Проверка: 0 + 0 = 0 — это единственное решение. Иногда ОДЗ сама даёт ответ!', 'The domain of √(x − 1) + √(1 − x) = 0 is the single point x = 1. Checking: 0 + 0 = 0, so it is the only solution. Sometimes the domain alone gives the answer!')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Irratsional tenglama — noma’lum ildiz ostida.', 'Иррациональное уравнение — неизвестное под корнем.', 'An irrational equation has the unknown under a root.'),
      L('√a ≥ 0 va juft ildiz faqat a ≥ 0 da aniqlangan.', '√a ≥ 0, и корень чётной степени определён только при a ≥ 0.', '√a ≥ 0, and an even root is defined only for a ≥ 0.'),
      L('√f = g ⇔ f = g², g ≥ 0.', '√f = g ⇔ f = g², g ≥ 0.', '√f = g ⇔ f = g², g ≥ 0.'),
      L('Kvadratga ko‘tarish chet ildiz berishi mumkin — tekshirish majburiy.', 'Возведение в квадрат может дать посторонние корни — проверка обязательна.', 'Squaring may create extraneous roots — checking is essential.'),
      L('Usullar: yolg‘izlash va kvadratlash, yangi o‘zgaruvchi, monotonlik.', 'Методы: уединение и возведение в квадрат, новая переменная, монотонность.', 'Methods: isolate and square, new variable, monotonicity.'),
      L('Kub ildizda kubga ko‘tarish teng kuchli.', 'Для кубического корня возведение в куб равносильно.', 'For cube roots, cubing is equivalent.')
    ] }
  ] });

  // ---------- t10. Ko‘rsatkichli funksiya ----------
  T.add(P, 't10', { sections: [
    { kind: 'intro', h: L('Eng tez o‘sadigan funksiya', 'Самая быстрорастущая функция', 'The fastest-growing function'), p: [
      L('Bitta bakteriya har 20 daqiqada ikkiga bo‘linadi. 1 soatdan keyin 8 ta, 5 soatdan keyin 32 768 ta, bir sutkadan keyin esa 2⁷² ≈ 4,7 · 10²¹ ta bo‘ladi. Bu o‘sishni na chiziqli, na kvadratik funksiya tasvirlay olmaydi. Uni <b>ko‘rsatkichli funksiya</b> y = aˣ tasvirlaydi — bunda o‘zgaruvchi asosda emas, <b>daraja ko‘rsatkichida</b> turadi.', 'Одна бактерия делится надвое каждые 20 минут. Через час их 8, через 5 часов — 32 768, а через сутки — 2⁷² ≈ 4,7 · 10²¹. Такой рост не описать ни линейной, ни квадратичной функцией. Его описывает <b>показательная функция</b> y = aˣ — здесь переменная стоит не в основании, а <b>в показателе степени</b>.', 'One bacterium splits in two every 20 minutes. After an hour there are 8, after 5 hours 32 768, and after a day 2⁷² ≈ 4.7 · 10²¹. No linear or quadratic function can describe this growth. The <b>exponential function</b> y = aˣ can — here the variable is not in the base but <b>in the exponent</b>.'),
      L('Ko‘rsatkichli qonun tabiat va jamiyatda hamma joyda: bank omonati, aholi soni, viruslar tarqalishi, radioaktiv parchalanish, choyning sovishi, kompyuter quvvatining o‘sishi. Bu mavzu — 10-sinfdagi yangi funksiyalar olamiga ochilgan eshik; keyingi mavzularda ko‘rsatkichli tenglamalar, tengsizliklar va logarifmlar shu funksiyaga tayanadi.', 'Показательный закон повсюду в природе и обществе: банковский вклад, численность населения, распространение вирусов, радиоактивный распад, остывание чая, рост мощности компьютеров. Эта тема — дверь в мир новых функций 10 класса; на ней держатся следующие темы: показательные уравнения, неравенства и логарифмы.', 'Exponential laws are everywhere in nature and society: bank deposits, population, the spread of viruses, radioactive decay, tea cooling, the growth of computing power. This topic is the door to the new functions of grade 10; exponential equations, inequalities and logarithms all rest on it.')
    ] },
    { kind: 'def', h: L('Haqiqiy ko‘rsatkichli daraja', 'Степень с действительным показателем', 'Powers with real exponents'), p: [
      L('aˣ ni barcha haqiqiy x uchun aniqlash bosqichma-bosqich amalga oshiriladi. Natural n uchun aⁿ = a · a · … · a. So‘ng a⁰ = 1, a⁻ⁿ = 1/aⁿ. Ratsional ko‘rsatkich uchun a^(m/n) = ⁿ√(aᵐ) (a &gt; 0). Masalan, 8^(2/3) = ∛64 = 4, 16^(−1/2) = 1/4.', 'Определение aˣ для всех действительных x строится поэтапно. Для натурального n: aⁿ = a · a · … · a. Затем a⁰ = 1, a⁻ⁿ = 1/aⁿ. Для рационального показателя a^(m/n) = ⁿ√(aᵐ) (a &gt; 0). Например, 8^(2/3) = ∛64 = 4, 16^(−1/2) = 1/4.', 'aˣ is defined for all real x step by step. For natural n, aⁿ = a · a · … · a. Then a⁰ = 1 and a⁻ⁿ = 1/aⁿ. For a rational exponent, a^(m/n) = ⁿ√(aᵐ) (a &gt; 0). E.g. 8^(2/3) = ∛64 = 4 and 16^(−1/2) = 1/4.'),
      L('Irratsional ko‘rsatkich, masalan 2^√2, yaqinlashishlar orqali aniqlanadi: √2 ≈ 1,4; 1,41; 1,414; … bo‘lgani uchun 2^1,4 ≈ 2,639; 2^1,41 ≈ 2,657; 2^1,414 ≈ 2,665; … — bu sonlar 2^√2 ≈ 2,6651 ga yaqinlashadi. Natijada aˣ barcha haqiqiy x da aniqlanadi va barcha daraja xossalari saqlanadi: aˣ · aʸ = aˣ⁺ʸ, aˣ : aʸ = aˣ⁻ʸ, (aˣ)ʸ = aˣʸ, (ab)ˣ = aˣbˣ.', 'Иррациональный показатель, например 2^√2, определяется через приближения: так как √2 ≈ 1,4; 1,41; 1,414; …, то 2^1,4 ≈ 2,639; 2^1,41 ≈ 2,657; 2^1,414 ≈ 2,665; … — эти числа приближаются к 2^√2 ≈ 2,6651. В итоге aˣ определена при всех действительных x, и все свойства степеней сохраняются: aˣ · aʸ = aˣ⁺ʸ, aˣ : aʸ = aˣ⁻ʸ, (aˣ)ʸ = aˣʸ, (ab)ˣ = aˣbˣ.', 'An irrational exponent such as 2^√2 is defined by approximation: since √2 ≈ 1.4, 1.41, 1.414, …, we get 2^1.4 ≈ 2.639, 2^1.41 ≈ 2.657, 2^1.414 ≈ 2.665, … — these approach 2^√2 ≈ 2.6651. So aˣ is defined for every real x, and all the power rules still hold: aˣ · aʸ = aˣ⁺ʸ, aˣ : aʸ = aˣ⁻ʸ, (aˣ)ʸ = aˣʸ, (ab)ˣ = aˣbˣ.')
    ] },
    { kind: 'def', h: L('Ko‘rsatkichli funksiya ta’rifi', 'Определение показательной функции', 'Definition of the exponential function'), p: [
      L('<b>y = aˣ</b> (a &gt; 0, a ≠ 1) ko‘rinishidagi funksiya <b>ko‘rsatkichli funksiya</b> deyiladi. Nega a &gt; 0? Manfiy asosda, masalan (−8)^(1/2) haqiqiy son emas, ya’ni funksiya «teshiklarga to‘la» bo‘lardi. Nega a ≠ 1? 1ˣ = 1 — bu oddiy o‘zgarmas, uni alohida o‘rganishga hojat yo‘q.', 'Функция вида <b>y = aˣ</b> (a &gt; 0, a ≠ 1) называется <b>показательной</b>. Почему a &gt; 0? При отрицательном основании, например (−8)^(1/2), значение не является действительным числом, то есть функция была бы «вся в дырах». Почему a ≠ 1? 1ˣ = 1 — просто константа, изучать её отдельно незачем.', 'A function <b>y = aˣ</b> (a &gt; 0, a ≠ 1) is called <b>exponential</b>. Why a &gt; 0? With a negative base, (−8)^(1/2) for instance is not a real number, so the function would be “full of holes”. Why a ≠ 1? 1ˣ = 1 is just a constant, not worth separate study.'),
      L('Matematikada eng muhim asos — <b>e ≈ 2,71828</b> soni (Eyler soni). y = eˣ funksiyasi o‘zining o‘sish tezligiga teng bo‘lgan yagona funksiya (bu hosila mavzusida tushuntiriladi). U uzluksiz murakkab foiz hisobida tabiiy ravishda paydo bo‘ladi: (1 + 1/n)ⁿ ifoda n o‘sgan sari e ga yaqinlashadi.', 'Самое важное основание в математике — число <b>e ≈ 2,71828</b> (число Эйлера). Функция y = eˣ — единственная функция, равная своей скорости роста (это объясняется в теме о производной). Оно естественно появляется при непрерывном начислении сложных процентов: выражение (1 + 1/n)ⁿ с ростом n приближается к e.', 'The most important base in mathematics is <b>e ≈ 2.71828</b> (Euler’s number). y = eˣ is the only function equal to its own rate of growth (explained in the topic on derivatives). It appears naturally in continuously compounded interest: (1 + 1/n)ⁿ approaches e as n grows.')
    ] },
    { kind: 'table', h: L('Ko‘rsatkichli funksiya xossalari', 'Свойства показательной функции', 'Properties of the exponential function'), table: { head: [L('Xossa', 'Свойство', 'Property'), L('a &gt; 1', 'a &gt; 1', 'a &gt; 1'), L('0 &lt; a &lt; 1', '0 &lt; a &lt; 1', '0 &lt; a &lt; 1')], rows: [
      [L('Aniqlanish sohasi', 'Область определения', 'Domain'), L('ℝ', 'ℝ', 'ℝ'), L('ℝ', 'ℝ', 'ℝ')],
      [L('Qiymatlar to‘plami', 'Множество значений', 'Range'), L('(0; +∞)', '(0; +∞)', '(0; +∞)'), L('(0; +∞)', '(0; +∞)', '(0; +∞)')],
      [L('Monotonlik', 'Монотонность', 'Monotonicity'), L('o‘suvchi', 'возрастает', 'increasing'), L('kamayuvchi', 'убывает', 'decreasing')],
      [L('Oy bilan kesishish', 'Пересечение с Oy', 'y-intercept'), L('(0; 1)', '(0; 1)', '(0; 1)'), L('(0; 1)', '(0; 1)', '(0; 1)')],
      [L('x → +∞ da', 'при x → +∞', 'as x → +∞'), L('aˣ → +∞', 'aˣ → +∞', 'aˣ → +∞'), L('aˣ → 0', 'aˣ → 0', 'aˣ → 0')],
      [L('x → −∞ da', 'при x → −∞', 'as x → −∞'), L('aˣ → 0', 'aˣ → 0', 'aˣ → 0'), L('aˣ → +∞', 'aˣ → +∞', 'aˣ → +∞')],
      [L('Asimptota', 'Асимптота', 'Asymptote'), L('y = 0 (chapda)', 'y = 0 (слева)', 'y = 0 (on the left)'), L('y = 0 (o‘ngda)', 'y = 0 (справа)', 'y = 0 (on the right)')]
    ] }, after: [
      L('Funksiya na juft, na toq, davriy emas, chegaralanmagan va ekstremumlarga ega emas. Eng muhimi: aˣ &gt; 0 <b>har doim</b> — grafik Ox o‘qidan yuqorida, unga cheksiz yaqinlashsa ham hech qachon tegmaydi. y = aˣ va y = (1/a)ˣ = a⁻ˣ grafiklari Oy o‘qiga nisbatan simmetrik.', 'Функция ни чётная, ни нечётная, непериодическая, неограниченная и не имеет экстремумов. Главное: aˣ &gt; 0 <b>всегда</b> — график выше оси Ox и, бесконечно приближаясь к ней, никогда её не касается. Графики y = aˣ и y = (1/a)ˣ = a⁻ˣ симметричны относительно оси Oy.', 'The function is neither even nor odd, not periodic, unbounded and has no extrema. Most importantly, aˣ &gt; 0 <b>always</b> — the graph lies above Ox and, though it approaches the axis endlessly, never touches it. The graphs of y = aˣ and y = (1/a)ˣ = a⁻ˣ are symmetric about Oy.')
    ] },
    { kind: 'rule', h: L('Monotonlikdan kelib chiqadigan qoida', 'Правило, следующее из монотонности', 'A rule from monotonicity'), p: [
      L('Ko‘rsatkichli funksiya qat’iy monoton, shuning uchun: <b>aˣ¹ = aˣ² ⇔ x₁ = x₂</b>. Bu ko‘rsatkichli tenglamalarni yechishning asosi: 2ˣ = 32 = 2⁵ ⇒ x = 5. Tengsizliklarda esa asosga qarash kerak: a &gt; 1 da aˣ¹ &lt; aˣ² ⇔ x₁ &lt; x₂ (ishora saqlanadi), 0 &lt; a &lt; 1 da aˣ¹ &lt; aˣ² ⇔ x₁ &gt; x₂ (ishora almashadi).', 'Показательная функция строго монотонна, поэтому: <b>aˣ¹ = aˣ² ⇔ x₁ = x₂</b>. Это основа решения показательных уравнений: 2ˣ = 32 = 2⁵ ⇒ x = 5. А в неравенствах нужно смотреть на основание: при a &gt; 1 aˣ¹ &lt; aˣ² ⇔ x₁ &lt; x₂ (знак сохраняется), при 0 &lt; a &lt; 1 aˣ¹ &lt; aˣ² ⇔ x₁ &gt; x₂ (знак меняется).', 'The exponential function is strictly monotonic, so <b>aˣ¹ = aˣ² ⇔ x₁ = x₂</b>. This is the basis for exponential equations: 2ˣ = 32 = 2⁵ ⇒ x = 5. In inequalities look at the base: for a &gt; 1, aˣ¹ &lt; aˣ² ⇔ x₁ &lt; x₂ (sign kept); for 0 &lt; a &lt; 1, aˣ¹ &lt; aˣ² ⇔ x₁ &gt; x₂ (sign flips).'),
      L('Shu xossa yordamida sonlarni solishtirish mumkin: 3^√2 va 3^1,5 dan qaysi biri katta? √2 ≈ 1,414 &lt; 1,5 va 3 &gt; 1, demak 3^√2 &lt; 3^1,5. 0,7^2 va 0,7^3 dan esa 0,7² &gt; 0,7³, chunki asos 1 dan kichik.', 'С помощью этого свойства можно сравнивать числа: что больше, 3^√2 или 3^1,5? √2 ≈ 1,414 &lt; 1,5 и 3 &gt; 1, значит, 3^√2 &lt; 3^1,5. А из 0,7² и 0,7³ больше 0,7², так как основание меньше 1.', 'This property lets us compare numbers: which is bigger, 3^√2 or 3^1.5? √2 ≈ 1.414 &lt; 1.5 and 3 &gt; 1, so 3^√2 &lt; 3^1.5. Of 0.7² and 0.7³ the larger is 0.7², because the base is less than 1.')
    ] },
    { kind: 'history', h: L('Tarixdan', 'Из истории', 'From history'), p: [
      L('Shaxmat va bug‘doy donlari haqidagi hind afsonasi ko‘rsatkichli o‘sishning eng qadimiy tasviri: taxtaning 64-katagiga 2⁶³ don to‘g‘ri keladi — bu butun dunyo bir necha ming yilda yetishtiradigan bug‘doydan ko‘p. Abu Rayhon Beruniy «Hindiston» asarida aynan shu masalani ko‘rib chiqib, donlar yig‘indisi 2⁶⁴ − 1 = 18 446 744 073 709 551 615 ekanini hisoblagan.', 'Индийская легенда о шахматах и пшеничных зёрнах — древнейшая иллюстрация показательного роста: на 64-ю клетку доски приходится 2⁶³ зёрен — больше, чем весь мир вырастит за несколько тысяч лет. Абу Райхан Беруни в труде «Индия» рассмотрел именно эту задачу и вычислил, что сумма зёрен равна 2⁶⁴ − 1 = 18 446 744 073 709 551 615.', 'The Indian legend of chess and grains of wheat is the oldest picture of exponential growth: the 64th square gets 2⁶³ grains — more than the whole world grows in several thousand years. Abu Rayhan al-Biruni examined exactly this problem in his book “India” and computed the total as 2⁶⁴ − 1 = 18 446 744 073 709 551 615.'),
      L('Kasr va manfiy ko‘rsatkichlarni XVII asrda Jon Uollis va Isaak Nyuton tizimli qo‘llay boshladilar. e sonini 1683-yilda Yakob Bernulli murakkab foizlarni o‘rganayotganda kashf etdi, «e» harfi bilan esa 1727–1731-yillarda Leonard Eyler belgiladi. Eyler y = aˣ funksiyasini birinchi bo‘lib mustaqil funksiya sifatida o‘rgandi va uni logarifm bilan bog‘ladi.', 'Дробные и отрицательные показатели систематически стали применять в XVII веке Джон Валлис и Исаак Ньютон. Число e открыл в 1683 году Якоб Бернулли, изучая сложные проценты, а буквой «e» его обозначил Леонард Эйлер в 1727–1731 годах. Эйлер первым изучил y = aˣ как самостоятельную функцию и связал её с логарифмом.', 'John Wallis and Isaac Newton began using fractional and negative exponents systematically in the 17th century. The number e was discovered in 1683 by Jacob Bernoulli while studying compound interest, and Leonhard Euler named it “e” in 1727–1731. Euler was the first to study y = aˣ as a function in its own right and connected it with the logarithm.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('y = 2ˣ va y = (1/2)ˣ grafiklarini x = −2, −1, 0, 1, 2 nuqtalar bo‘yicha taqqoslang.', 'Сравните графики y = 2ˣ и y = (1/2)ˣ по точкам x = −2, −1, 0, 1, 2.', 'Compare y = 2ˣ and y = (1/2)ˣ at x = −2, −1, 0, 1, 2.'),
        s: L('2ˣ: 1/4, 1/2, 1, 2, 4 — o‘suvchi. (1/2)ˣ: 4, 2, 1, 1/2, 1/4 — kamayuvchi. Ikkalasi (0; 1) dan o‘tadi va Oy ga nisbatan bir-birining aksi.', '2ˣ: 1/4, 1/2, 1, 2, 4 — возрастает. (1/2)ˣ: 4, 2, 1, 1/2, 1/4 — убывает. Обе проходят через (0; 1) и симметричны друг другу относительно Oy.', '2ˣ: 1/4, 1/2, 1, 2, 4 — increasing. (1/2)ˣ: 4, 2, 1, 1/2, 1/4 — decreasing. Both pass through (0; 1) and mirror each other in Oy.') },
      { q: L('Solishtiring: (0,3)^(−2) va (0,3)^(−3); 5^(2/3) va 5^(3/4).', 'Сравните: (0,3)^(−2) и (0,3)^(−3); 5^(2/3) и 5^(3/4).', 'Compare: (0.3)^(−2) and (0.3)^(−3); 5^(2/3) and 5^(3/4).'),
        s: L('0,3 &lt; 1 — funksiya kamayuvchi; −2 &gt; −3, demak (0,3)^(−2) &lt; (0,3)^(−3). 5 &gt; 1 — o‘suvchi; 2/3 ≈ 0,667 &lt; 3/4 = 0,75, demak 5^(2/3) &lt; 5^(3/4).', '0,3 &lt; 1 — функция убывает; −2 &gt; −3, значит, (0,3)^(−2) &lt; (0,3)^(−3). 5 &gt; 1 — возрастает; 2/3 ≈ 0,667 &lt; 3/4 = 0,75, значит, 5^(2/3) &lt; 5^(3/4).', '0.3 &lt; 1 so the function decreases; −2 &gt; −3, hence (0.3)^(−2) &lt; (0.3)^(−3). 5 &gt; 1 so it increases; 2/3 ≈ 0.667 &lt; 3/4 = 0.75, hence 5^(2/3) &lt; 5^(3/4).') },
      { q: L('y = 3ˣ⁻¹ + 2 funksiyaning qiymatlar to‘plami va asimptotasini toping.', 'Найдите множество значений и асимптоту y = 3ˣ⁻¹ + 2.', 'Find the range and asymptote of y = 3ˣ⁻¹ + 2.'),
        s: L('y = 3ˣ grafigi 1 birlik o‘ngga va 2 birlik yuqoriga siljigan. 3ˣ⁻¹ &gt; 0, demak y &gt; 2. E = (2; +∞), gorizontal asimptota y = 2.', 'График y = 3ˣ сдвинут на 1 вправо и на 2 вверх. 3ˣ⁻¹ &gt; 0, значит, y &gt; 2. E = (2; +∞), горизонтальная асимптота y = 2.', 'The graph of y = 3ˣ is shifted 1 right and 2 up. 3ˣ⁻¹ &gt; 0, so y &gt; 2. E = (2; +∞), horizontal asymptote y = 2.') },
      { q: L('Omonatga 10 000 000 so‘m yillik 20 % murakkab foiz bilan qo‘yildi. 3 yildan keyin qancha bo‘ladi?', 'На вклад положили 10 000 000 сумов под 20 % годовых (сложные проценты). Сколько будет через 3 года?', '10 000 000 soums are deposited at 20 % a year compound interest. How much after 3 years?'),
        s: L('S = S₀ · 1,2ᵗ. S(3) = 10 000 000 · 1,728 = 17 280 000 so‘m. Oddiy foizda esa 16 000 000 bo‘lardi — farq «foizga foiz» hisobiga.', 'S = S₀ · 1,2ᵗ. S(3) = 10 000 000 · 1,728 = 17 280 000 сумов. При простых процентах было бы 16 000 000 — разница за счёт «процентов на проценты».', 'S = S₀ · 1.2ᵗ. S(3) = 10 000 000 · 1.728 = 17 280 000 soums. Simple interest would give 16 000 000 — the difference is “interest on interest”.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Common mistakes'), list: [
      L('<b>2ˣ ni x² bilan chalkashtirish.</b> Darajali funksiyada o‘zgaruvchi asosda, ko‘rsatkichlida — ko‘rsatkichda. x = 10 da x² = 100, 2ˣ = 1 024.', '<b>Путать 2ˣ и x².</b> В степенной функции переменная в основании, в показательной — в показателе. При x = 10: x² = 100, 2ˣ = 1 024.', '<b>Confusing 2ˣ with x².</b> In a power function the variable is the base; in an exponential it is the exponent. At x = 10: x² = 100 but 2ˣ = 1 024.'),
      L('<b>Manfiy ko‘rsatkich manfiy son beradi deb o‘ylash.</b> 2⁻³ = 1/8 &gt; 0. aˣ hech qachon manfiy yoki nol bo‘lmaydi.', '<b>Думать, что отрицательный показатель даёт отрицательное число.</b> 2⁻³ = 1/8 &gt; 0. aˣ никогда не бывает отрицательной или нулём.', '<b>Thinking a negative exponent gives a negative number.</b> 2⁻³ = 1/8 &gt; 0. aˣ is never negative or zero.'),
      L('<b>0 &lt; a &lt; 1 da tengsizlik ishorasini almashtirmaslik.</b> (1/2)ˣ &gt; (1/2)³ ⇒ x &lt; 3.', '<b>Не менять знак неравенства при 0 &lt; a &lt; 1.</b> (1/2)ˣ &gt; (1/2)³ ⇒ x &lt; 3.', '<b>Not flipping the inequality when 0 &lt; a &lt; 1.</b> (1/2)ˣ &gt; (1/2)³ ⇒ x &lt; 3.'),
      L('<b>aˣ + aʸ = aˣ⁺ʸ deb yozish.</b> Ko‘paytirishda ko‘rsatkichlar qo‘shiladi, qo‘shishda emas: 2³ + 2² = 12 ≠ 2⁵ = 32.', '<b>Писать aˣ + aʸ = aˣ⁺ʸ.</b> Показатели складываются при умножении, а не при сложении: 2³ + 2² = 12 ≠ 2⁵ = 32.', '<b>Writing aˣ + aʸ = aˣ⁺ʸ.</b> Exponents add when multiplying, not when adding: 2³ + 2² = 12 ≠ 2⁵ = 32.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Radioaktiv parchalanish.</b> m(t) = m₀ · (1/2)^(t/T), bu yerda T — yarim yemirilish davri. Uglerod-14 uchun T ≈ 5 730 yil; arxeologlar qadimiy suyak yoki yog‘ochdagi C-14 miqdoriga qarab uning yoshini aniqlaydi. Agar namunada C-14 ning chorak qismi qolgan bo‘lsa, unga taxminan 2 · 5 730 = 11 460 yil.', '<b>Радиоактивный распад.</b> m(t) = m₀ · (1/2)^(t/T), где T — период полураспада. Для углерода-14 T ≈ 5 730 лет; археологи по количеству C-14 в древней кости или дереве определяют её возраст. Если в образце осталась четверть C-14, ему примерно 2 · 5 730 = 11 460 лет.', '<b>Radioactive decay.</b> m(t) = m₀ · (1/2)^(t/T), where T is the half-life. For carbon-14, T ≈ 5 730 years; archaeologists date ancient bone or wood by how much C-14 remains. If a quarter is left, the sample is about 2 · 5 730 = 11 460 years old.'),
      L('<b>Texnologiya va biologiya.</b> Mur qonuniga ko‘ra, mikrosxemadagi tranzistorlar soni o‘nlab yillar davomida taxminan har ikki yilda ikki baravar oshib keldi. Epidemiyalarning boshlang‘ich bosqichida kasallanganlar soni ham ko‘rsatkichli o‘sadi — shuning uchun erta choralar juda muhim. Issiq choy esa ko‘rsatkichli qonun bo‘yicha soviydi: xona harorati bilan farq har teng vaqtda bir xil marta kamayadi.', '<b>Технологии и биология.</b> По закону Мура число транзисторов в микросхеме десятилетиями удваивалось примерно каждые два года. На начальной стадии эпидемии число заболевших тоже растёт показательно — поэтому ранние меры так важны. А горячий чай остывает по показательному закону: разница с комнатной температурой за равные промежутки уменьшается в одно и то же число раз.', '<b>Technology and biology.</b> By Moore’s law the number of transistors on a chip roughly doubled every two years for decades. In the early stage of an epidemic the number of cases also grows exponentially — which is why early measures matter so much. Hot tea cools exponentially too: its difference from room temperature shrinks by the same factor in equal time intervals.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('Hisoblang: 27^(2/3) · 4^(−1/2).', 'Вычислите: 27^(2/3) · 4^(−1/2).', 'Compute: 27^(2/3) · 4^(−1/2).'),
        s: L('27^(2/3) = (∛27)² = 9; 4^(−1/2) = 1/2. Natija: 4,5.', '27^(2/3) = (∛27)² = 9; 4^(−1/2) = 1/2. Результат: 4,5.', '27^(2/3) = (∛27)² = 9; 4^(−1/2) = 1/2. Result: 4.5.') },
      { q: L('a ning qanday qiymatlarida y = (a − 2)ˣ kamayuvchi ko‘rsatkichli funksiya bo‘ladi?', 'При каких a функция y = (a − 2)ˣ — убывающая показательная?', 'For which a is y = (a − 2)ˣ a decreasing exponential function?'),
        s: L('0 &lt; a − 2 &lt; 1 ⇒ 2 &lt; a &lt; 3.', '0 &lt; a − 2 &lt; 1 ⇒ 2 &lt; a &lt; 3.', '0 &lt; a − 2 &lt; 1 ⇒ 2 &lt; a &lt; 3.') }
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Qog‘oz varag‘ini (qalinligi 0,1 mm) har safar ikkiga buklasak, 42 marta buklangandan keyin qalinligi 0,1 · 2⁴² mm ≈ 440 000 km bo‘lardi — Yerdan Oygacha (≈ 384 000 km) masofadan ham ko‘p.', 'Если лист бумаги толщиной 0,1 мм каждый раз складывать пополам, после 42 сгибов его толщина была бы 0,1 · 2⁴² мм ≈ 440 000 км — больше расстояния от Земли до Луны (≈ 384 000 км).', 'If a sheet of paper 0.1 mm thick were folded in half each time, after 42 folds it would be 0.1 · 2⁴² mm ≈ 440 000 km thick — more than the Earth–Moon distance (≈ 384 000 km).'),
      L('«72 qoidasi»: yillik r % murakkab foizda pul taxminan 72/r yilda ikki baravar ko‘payadi. 8 % da — 9 yilda, 12 % da — 6 yilda.', '«Правило 72»: при r % годовых сложных процентов деньги удваиваются примерно за 72/r лет. При 8 % — за 9 лет, при 12 % — за 6 лет.', 'The “rule of 72”: at r % compound interest money doubles in about 72/r years. At 8 % that is 9 years, at 12 % 6 years.'),
      L('Har qanday ko‘rsatkichli funksiya oxir-oqibat istalgan darajali funksiyadan tezroq o‘sadi: masalan, 1,01ˣ ham yetarlicha katta x da x¹⁰⁰ dan o‘zib ketadi.', 'Любая показательная функция в конце концов растёт быстрее любой степенной: например, даже 1,01ˣ при достаточно больших x обгоняет x¹⁰⁰.', 'Any exponential eventually outgrows any power function: even 1.01ˣ overtakes x¹⁰⁰ for large enough x.')
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('y = aˣ, a &gt; 0, a ≠ 1 — ko‘rsatkichli funksiya.', 'y = aˣ, a &gt; 0, a ≠ 1 — показательная функция.', 'y = aˣ with a &gt; 0, a ≠ 1 is the exponential function.'),
      L('D = ℝ, E = (0; +∞); grafik (0; 1) dan o‘tadi, y = 0 — asimptota.', 'D = ℝ, E = (0; +∞); график проходит через (0; 1), y = 0 — асимптота.', 'D = ℝ, E = (0; +∞); the graph passes through (0; 1), with asymptote y = 0.'),
      L('a &gt; 1 da o‘suvchi, 0 &lt; a &lt; 1 da kamayuvchi.', 'При a &gt; 1 возрастает, при 0 &lt; a &lt; 1 убывает.', 'Increasing for a &gt; 1, decreasing for 0 &lt; a &lt; 1.'),
      L('aˣ¹ = aˣ² ⇔ x₁ = x₂; tengsizlikda 0 &lt; a &lt; 1 bo‘lsa ishora almashadi.', 'aˣ¹ = aˣ² ⇔ x₁ = x₂; в неравенстве при 0 &lt; a &lt; 1 знак меняется.', 'aˣ¹ = aˣ² ⇔ x₁ = x₂; in inequalities the sign flips when 0 &lt; a &lt; 1.'),
      L('Daraja xossalari barcha haqiqiy ko‘rsatkichlar uchun o‘rinli.', 'Свойства степеней верны для всех действительных показателей.', 'Power rules hold for all real exponents.'),
      L('e ≈ 2,718 — tabiiy asos; murakkab foiz, parchalanish, o‘sish — ko‘rsatkichli qonunlar.', 'e ≈ 2,718 — естественное основание; сложные проценты, распад, рост — показательные законы.', 'e ≈ 2.718 is the natural base; compound interest, decay and growth are exponential laws.')
    ] }
  ] });
})(this);
// --END--

// Nuvemath — 10-sinf, I qism (Algebra 10) nazariyasi, t11–t20. Format: js/theory/GUIDE.md
(function (root) {
  'use strict';
  var L = root.NMCurriculum.H.L, T = root.NMTheory, P = '10-1';

  // ---------- t11. Ko‘rsatkichli tenglama va tengsizliklar ----------
  T.add(P, 't11', { sections: [
    { kind: 'intro', h: L('Noma’lum daraja ko‘rsatkichida', 'Неизвестное в показателе', 'The unknown in the exponent'), p: [
      L('Shu paytgacha biz noma’lum asosda turgan tenglamalarni yechdik: x² = 9, x³ = 8. Endi vaziyat teskari: asos ma’lum, noma’lum esa daraja ko‘rsatkichida turibdi, masalan 2<sup>x</sup> = 32. Bunday tenglamalar <b>ko‘rsatkichli</b> tenglamalar deyiladi. Ular tabiatda juda ko‘p uchraydi: bakteriyalar soni har soatda ikki baravar oshsa, qachon million bo‘ladi? Bankdagi omonat necha yilda ikki baravar ko‘payadi? Dori organizmdan qachon chiqib ketadi?', 'До сих пор мы решали уравнения с неизвестным в основании: x² = 9, x³ = 8. Теперь наоборот: основание известно, а неизвестное стоит в показателе, например 2<sup>x</sup> = 32. Такие уравнения называются <b>показательными</b>. Они очень часто встречаются в природе: если число бактерий удваивается каждый час, когда их станет миллион? За сколько лет вклад в банке удвоится? Когда лекарство выведется из организма?', 'Until now we solved equations with the unknown in the base: x² = 9, x³ = 8. Now it is the other way round: the base is known and the unknown sits in the exponent, for example 2<sup>x</sup> = 32. Such equations are called <b>exponential</b>. They appear everywhere in nature: if bacteria double every hour, when will there be a million? In how many years does a bank deposit double? When does a medicine leave the body?'),
      L('Bu mavzuda biz ko‘rsatkichli tenglamalarni yechishning asosiy usullarini — bir asosga keltirish, umumiy ko‘paytuvchini qavsdan chiqarish, yangi o‘zgaruvchi kiritish — va ko‘rsatkichli tengsizliklarni yechishni o‘rganamiz. Hamma usullarning asosida bitta oddiy fakt yotadi: ko‘rsatkichli funksiya <b>monoton</b>, ya’ni har bir qiymatni faqat bir marta qabul qiladi.', 'В этой теме мы изучим основные методы решения показательных уравнений — приведение к одному основанию, вынесение общего множителя, введение новой переменной — и решение показательных неравенств. В основе всех методов лежит один простой факт: показательная функция <b>монотонна</b>, то есть принимает каждое значение только один раз.', 'In this topic we learn the main methods for exponential equations — reducing to one base, taking out a common factor, introducing a new variable — and how to solve exponential inequalities. All methods rest on one simple fact: the exponential function is <b>monotonic</b>, so it takes each value only once.')
    ] },
    { kind: 'def', h: L('Ta’rif va asosiy teorema', 'Определение и основная теорема', 'Definition and key theorem'), p: [
      L('Noma’lum faqat daraja ko‘rsatkichida qatnashgan tenglama <b>ko‘rsatkichli tenglama</b> deyiladi. Eng sodda ko‘rinishi: a<sup>x</sup> = b, bu yerda a &gt; 0, a ≠ 1. Agar b ≤ 0 bo‘lsa, yechim yo‘q, chunki a<sup>x</sup> har doim musbat. Agar b &gt; 0 bo‘lsa, yagona yechim bor.', 'Уравнение, в котором неизвестное входит только в показатель степени, называется <b>показательным</b>. Простейший вид: a<sup>x</sup> = b, где a &gt; 0, a ≠ 1. Если b ≤ 0, решений нет, так как a<sup>x</sup> всегда положительно. Если b &gt; 0, решение единственно.', 'An equation in which the unknown appears only in an exponent is called an <b>exponential equation</b>. The simplest form is a<sup>x</sup> = b with a &gt; 0, a ≠ 1. If b ≤ 0 there is no solution, because a<sup>x</sup> is always positive. If b &gt; 0 there is exactly one solution.'),
      L('<b>Asosiy teorema.</b> a &gt; 0, a ≠ 1 bo‘lsa, a<sup>f(x)</sup> = a<sup>g(x)</sup> tenglama f(x) = g(x) tenglamaga teng kuchli. <i>Isbot g‘oyasi:</i> y = a<sup>t</sup> funksiya a &gt; 1 da qat’iy o‘suvchi, 0 &lt; a &lt; 1 da qat’iy kamayuvchi. Qat’iy monoton funksiya ikki xil nuqtada bir xil qiymat qabul qila olmaydi, shuning uchun darajalar teng bo‘lsa, ko‘rsatkichlar ham teng.', '<b>Основная теорема.</b> При a &gt; 0, a ≠ 1 уравнение a<sup>f(x)</sup> = a<sup>g(x)</sup> равносильно уравнению f(x) = g(x). <i>Идея доказательства:</i> функция y = a<sup>t</sup> строго возрастает при a &gt; 1 и строго убывает при 0 &lt; a &lt; 1. Строго монотонная функция не может принимать одно значение в двух разных точках, поэтому из равенства степеней следует равенство показателей.', '<b>Key theorem.</b> If a &gt; 0, a ≠ 1, the equation a<sup>f(x)</sup> = a<sup>g(x)</sup> is equivalent to f(x) = g(x). <i>Proof idea:</i> y = a<sup>t</sup> is strictly increasing for a &gt; 1 and strictly decreasing for 0 &lt; a &lt; 1. A strictly monotonic function cannot take the same value at two different points, so equal powers mean equal exponents.')
    ] },
    { kind: 'history', h: L('Tarixdan: shaxmat taxtasi va bug‘doy', 'Из истории: шахматная доска и пшеница', 'History: the chessboard and the wheat'), p: [
      L('Hind afsonasiga ko‘ra, shaxmatni ixtiro qilgan donishmand podshodan mukofot sifatida birinchi katakka 1 ta, ikkinchisiga 2 ta, uchinchisiga 4 ta bug‘doy donini va hokazo har gal ikki baravar ko‘p so‘ragan. Oxirgi, 64-katakka 2<sup>63</sup> ta don to‘g‘ri keladi, jami esa 2<sup>64</sup> − 1 ≈ 1,8 · 10<sup>19</sup> ta don — bu butun dunyoning ming yillik hosilidan ham ko‘p. Bu hikoyani Beruniy ham o‘z asarlarida keltirib, yig‘indini hisoblab bergan.', 'По индийской легенде, изобретатель шахмат попросил у царя в награду 1 зерно пшеницы на первую клетку, 2 — на вторую, 4 — на третью и так далее, каждый раз вдвое больше. На последнюю, 64-ю клетку приходится 2<sup>63</sup> зёрен, а всего 2<sup>64</sup> − 1 ≈ 1,8 · 10<sup>19</sup> — больше, чем урожай всего мира за тысячу лет. Эту историю приводил и Беруни, вычислив сумму.', 'According to an Indian legend, the inventor of chess asked the king for 1 grain of wheat on the first square, 2 on the second, 4 on the third and so on, doubling each time. The last, 64th square gets 2<sup>63</sup> grains, and the total is 2<sup>64</sup> − 1 ≈ 1.8 · 10<sup>19</sup> — more than the world’s harvest over a thousand years. Al-Biruni also told this story and computed the sum.'),
      L('Daraja ko‘rsatkichini o‘zgaruvchi deb qarash g‘oyasi XVII asrda paydo bo‘ldi. Isaak Nyuton va Gotfrid Leybnits kasr va manfiy ko‘rsatkichlarni erkin ishlatdi, Leonard Eyler esa 1748-yilda ko‘rsatkichli funksiyani alohida funksiya sifatida o‘rgandi va e sonini kiritdi.', 'Идея рассматривать показатель как переменную появилась в XVII веке. Исаак Ньютон и Готфрид Лейбниц свободно использовали дробные и отрицательные показатели, а Леонард Эйлер в 1748 году изучил показательную функцию как самостоятельную и ввёл число e.', 'The idea of treating the exponent as a variable appeared in the 17th century. Isaac Newton and Gottfried Leibniz freely used fractional and negative exponents, and in 1748 Leonhard Euler studied the exponential function in its own right and introduced the number e.')
    ] },
    { kind: 'rule', h: L('Asosiy usullar', 'Основные методы', 'Main methods'), list: [
      L('<b>Bir asosga keltirish:</b> 8<sup>x</sup> = 4 → 2<sup>3x</sup> = 2<sup>2</sup> → 3x = 2 → x = 2/3.', '<b>Приведение к одному основанию:</b> 8<sup>x</sup> = 4 → 2<sup>3x</sup> = 2<sup>2</sup> → 3x = 2 → x = 2/3.', '<b>Same base:</b> 8<sup>x</sup> = 4 → 2<sup>3x</sup> = 2<sup>2</sup> → 3x = 2 → x = 2/3.'),
      L('<b>Umumiy ko‘paytuvchini chiqarish:</b> 3<sup>x+1</sup> + 3<sup>x</sup> = 36 → 3<sup>x</sup>(3 + 1) = 36 → 3<sup>x</sup> = 9 → x = 2.', '<b>Вынесение общего множителя:</b> 3<sup>x+1</sup> + 3<sup>x</sup> = 36 → 3<sup>x</sup>(3 + 1) = 36 → 3<sup>x</sup> = 9 → x = 2.', '<b>Common factor:</b> 3<sup>x+1</sup> + 3<sup>x</sup> = 36 → 3<sup>x</sup>(3 + 1) = 36 → 3<sup>x</sup> = 9 → x = 2.'),
      L('<b>Yangi o‘zgaruvchi:</b> 4<sup>x</sup> − 3 · 2<sup>x</sup> − 4 = 0 da t = 2<sup>x</sup> &gt; 0 deb olsak, t² − 3t − 4 = 0 kvadrat tenglama hosil bo‘ladi.', '<b>Новая переменная:</b> в 4<sup>x</sup> − 3 · 2<sup>x</sup> − 4 = 0 положим t = 2<sup>x</sup> &gt; 0 и получим квадратное уравнение t² − 3t − 4 = 0.', '<b>New variable:</b> in 4<sup>x</sup> − 3 · 2<sup>x</sup> − 4 = 0 put t = 2<sup>x</sup> &gt; 0 to get the quadratic t² − 3t − 4 = 0.'),
      L('<b>Bir jinsli tenglama:</b> 9<sup>x</sup> − 6<sup>x</sup> − 2 · 4<sup>x</sup> = 0 ni 4<sup>x</sup> ga bo‘lamiz va t = (3/2)<sup>x</sup> deb olamiz.', '<b>Однородное уравнение:</b> 9<sup>x</sup> − 6<sup>x</sup> − 2 · 4<sup>x</sup> = 0 делим на 4<sup>x</sup> и полагаем t = (3/2)<sup>x</sup>.', '<b>Homogeneous equation:</b> divide 9<sup>x</sup> − 6<sup>x</sup> − 2 · 4<sup>x</sup> = 0 by 4<sup>x</sup> and set t = (3/2)<sup>x</sup>.'),
      L('<b>Tengsizlik:</b> a &gt; 1 bo‘lsa a<sup>f</sup> &gt; a<sup>g</sup> ⇔ f &gt; g; 0 &lt; a &lt; 1 bo‘lsa a<sup>f</sup> &gt; a<sup>g</sup> ⇔ f &lt; g (belgi almashadi).', '<b>Неравенство:</b> при a &gt; 1 a<sup>f</sup> &gt; a<sup>g</sup> ⇔ f &gt; g; при 0 &lt; a &lt; 1 a<sup>f</sup> &gt; a<sup>g</sup> ⇔ f &lt; g (знак меняется).', '<b>Inequality:</b> if a &gt; 1 then a<sup>f</sup> &gt; a<sup>g</sup> ⇔ f &gt; g; if 0 &lt; a &lt; 1 then a<sup>f</sup> &gt; a<sup>g</sup> ⇔ f &lt; g (the sign flips).')
    ] },
    { kind: 'steps', h: L('Yechish algoritmi', 'Алгоритм решения', 'Solving algorithm'), list: [
      L('1. Barcha asoslarni ko‘rib chiqing: ular bitta sonning darajasimi (4 = 2², 8 = 2³, 1/9 = 3<sup>−2</sup>, √3 = 3<sup>1/2</sup>)?', '1. Посмотрите на все основания: являются ли они степенями одного числа (4 = 2², 8 = 2³, 1/9 = 3<sup>−2</sup>, √3 = 3<sup>1/2</sup>)?', '1. Look at all the bases: are they powers of one number (4 = 2², 8 = 2³, 1/9 = 3<sup>−2</sup>, √3 = 3<sup>1/2</sup>)?'),
      L('2. Agar ko‘rsatkichlar x + 1, x − 2 kabi farq qilsa, eng kichik darajani qavsdan chiqaring.', '2. Если показатели отличаются на число (x + 1, x − 2), вынесите за скобки наименьшую степень.', '2. If the exponents differ by a constant (x + 1, x − 2), factor out the smallest power.'),
      L('3. Agar a<sup>2x</sup> va a<sup>x</sup> birga uchrasa, t = a<sup>x</sup> almashtirishni bajaring va t &gt; 0 shartni yozib qo‘ying.', '3. Если встречаются a<sup>2x</sup> и a<sup>x</sup>, сделайте замену t = a<sup>x</sup> и запишите условие t &gt; 0.', '3. If a<sup>2x</sup> and a<sup>x</sup> appear together, substitute t = a<sup>x</sup> and write down t &gt; 0.'),
      L('4. Hosil bo‘lgan algebraik tenglamani yeching, manfiy va nol ildizlarni tashlab yuboring.', '4. Решите полученное алгебраическое уравнение, отбросьте отрицательные и нулевые корни.', '4. Solve the resulting algebraic equation and discard negative and zero roots.'),
      L('5. Eski o‘zgaruvchiga qayting va javobni tenglamaga qo‘yib tekshiring.', '5. Вернитесь к старой переменной и проверьте ответ подстановкой.', '5. Return to the original variable and check the answer by substitution.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: tenglamalar', 'Решённые примеры: уравнения', 'Worked examples: equations'), ex: [
      { q: L('27<sup>x</sup> = 1/9 tenglamani yeching.', 'Решите уравнение 27<sup>x</sup> = 1/9.', 'Solve 27<sup>x</sup> = 1/9.'), s: L('27 = 3³, 1/9 = 3<sup>−2</sup>. Demak 3<sup>3x</sup> = 3<sup>−2</sup>, ko‘rsatkichlarni tenglaymiz: 3x = −2, x = −2/3. Tekshirish: 27<sup>−2/3</sup> = (∛27)<sup>−2</sup> = 3<sup>−2</sup> = 1/9. Javob: x = −2/3.', '27 = 3³, 1/9 = 3<sup>−2</sup>. Значит 3<sup>3x</sup> = 3<sup>−2</sup>, приравниваем показатели: 3x = −2, x = −2/3. Проверка: 27<sup>−2/3</sup> = (∛27)<sup>−2</sup> = 3<sup>−2</sup> = 1/9. Ответ: x = −2/3.', '27 = 3³ and 1/9 = 3<sup>−2</sup>, so 3<sup>3x</sup> = 3<sup>−2</sup>; equating exponents gives 3x = −2, x = −2/3. Check: 27<sup>−2/3</sup> = (∛27)<sup>−2</sup> = 3<sup>−2</sup> = 1/9. Answer: x = −2/3.') },
      { q: L('2<sup>x+2</sup> − 2<sup>x</sup> = 48 tenglamani yeching.', 'Решите уравнение 2<sup>x+2</sup> − 2<sup>x</sup> = 48.', 'Solve 2<sup>x+2</sup> − 2<sup>x</sup> = 48.'), s: L('Eng kichik daraja 2<sup>x</sup>: 2<sup>x</sup>(2² − 1) = 48, ya’ni 3 · 2<sup>x</sup> = 48, 2<sup>x</sup> = 16 = 2⁴. Javob: x = 4. Tekshirish: 64 − 16 = 48.', 'Наименьшая степень 2<sup>x</sup>: 2<sup>x</sup>(2² − 1) = 48, то есть 3 · 2<sup>x</sup> = 48, 2<sup>x</sup> = 16 = 2⁴. Ответ: x = 4. Проверка: 64 − 16 = 48.', 'The smallest power is 2<sup>x</sup>: 2<sup>x</sup>(2² − 1) = 48, so 3 · 2<sup>x</sup> = 48 and 2<sup>x</sup> = 16 = 2⁴. Answer: x = 4. Check: 64 − 16 = 48.') },
      { q: L('9<sup>x</sup> − 4 · 3<sup>x</sup> + 3 = 0 tenglamani yeching.', 'Решите уравнение 9<sup>x</sup> − 4 · 3<sup>x</sup> + 3 = 0.', 'Solve 9<sup>x</sup> − 4 · 3<sup>x</sup> + 3 = 0.'), s: L('9<sup>x</sup> = (3<sup>x</sup>)². t = 3<sup>x</sup> &gt; 0 deb olamiz: t² − 4t + 3 = 0, t₁ = 1, t₂ = 3. Ikkalasi ham musbat. 3<sup>x</sup> = 1 ⇒ x = 0; 3<sup>x</sup> = 3 ⇒ x = 1. Javob: 0; 1.', '9<sup>x</sup> = (3<sup>x</sup>)². Положим t = 3<sup>x</sup> &gt; 0: t² − 4t + 3 = 0, t₁ = 1, t₂ = 3. Оба положительны. 3<sup>x</sup> = 1 ⇒ x = 0; 3<sup>x</sup> = 3 ⇒ x = 1. Ответ: 0; 1.', '9<sup>x</sup> = (3<sup>x</sup>)². Let t = 3<sup>x</sup> &gt; 0: t² − 4t + 3 = 0, so t = 1 or t = 3, both positive. 3<sup>x</sup> = 1 gives x = 0; 3<sup>x</sup> = 3 gives x = 1. Answer: 0; 1.') },
      { q: L('4<sup>x</sup> + 2<sup>x</sup> − 6 = 0 tenglamani yeching.', 'Решите уравнение 4<sup>x</sup> + 2<sup>x</sup> − 6 = 0.', 'Solve 4<sup>x</sup> + 2<sup>x</sup> − 6 = 0.'), s: L('t = 2<sup>x</sup> &gt; 0: t² + t − 6 = 0, t₁ = 2, t₂ = −3. t = −3 mos emas, chunki 2<sup>x</sup> manfiy bo‘lmaydi. 2<sup>x</sup> = 2 ⇒ x = 1. Javob: x = 1.', 't = 2<sup>x</sup> &gt; 0: t² + t − 6 = 0, t₁ = 2, t₂ = −3. t = −3 не подходит, так как 2<sup>x</sup> не бывает отрицательным. 2<sup>x</sup> = 2 ⇒ x = 1. Ответ: x = 1.', 't = 2<sup>x</sup> &gt; 0: t² + t − 6 = 0, so t = 2 or t = −3. t = −3 is rejected because 2<sup>x</sup> is never negative. 2<sup>x</sup> = 2 gives x = 1. Answer: x = 1.') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: tengsizliklar', 'Решённые примеры: неравенства', 'Worked examples: inequalities'), ex: [
      { q: L('3<sup>2x−1</sup> &gt; 27 tengsizlikni yeching.', 'Решите неравенство 3<sup>2x−1</sup> &gt; 27.', 'Solve 3<sup>2x−1</sup> &gt; 27.'), s: L('27 = 3³. Asos 3 &gt; 1, belgi saqlanadi: 2x − 1 &gt; 3, 2x &gt; 4, x &gt; 2. Javob: (2; +∞).', '27 = 3³. Основание 3 &gt; 1, знак сохраняется: 2x − 1 &gt; 3, 2x &gt; 4, x &gt; 2. Ответ: (2; +∞).', '27 = 3³. The base 3 &gt; 1, so the sign is kept: 2x − 1 &gt; 3, 2x &gt; 4, x &gt; 2. Answer: (2; +∞).') },
      { q: L('(1/2)<sup>x²−3x</sup> ≥ 1/16 tengsizlikni yeching.', 'Решите неравенство (1/2)<sup>x²−3x</sup> ≥ 1/16.', 'Solve (1/2)<sup>x²−3x</sup> ≥ 1/16.'), s: L('1/16 = (1/2)⁴. Asos 1/2 &lt; 1, belgi almashadi: x² − 3x ≤ 4, x² − 3x − 4 ≤ 0, (x − 4)(x + 1) ≤ 0. Javob: [−1; 4].', '1/16 = (1/2)⁴. Основание 1/2 &lt; 1, знак меняется: x² − 3x ≤ 4, x² − 3x − 4 ≤ 0, (x − 4)(x + 1) ≤ 0. Ответ: [−1; 4].', '1/16 = (1/2)⁴. The base 1/2 &lt; 1, so the sign flips: x² − 3x ≤ 4, x² − 3x − 4 ≤ 0, (x − 4)(x + 1) ≤ 0. Answer: [−1; 4].') },
      { q: L('4<sup>x</sup> − 5 · 2<sup>x</sup> + 4 &lt; 0 tengsizlikni yeching.', 'Решите неравенство 4<sup>x</sup> − 5 · 2<sup>x</sup> + 4 &lt; 0.', 'Solve 4<sup>x</sup> − 5 · 2<sup>x</sup> + 4 &lt; 0.'), s: L('t = 2<sup>x</sup> &gt; 0: t² − 5t + 4 &lt; 0, (t − 1)(t − 4) &lt; 0, 1 &lt; t &lt; 4. Demak 2⁰ &lt; 2<sup>x</sup> &lt; 2², asos 2 &gt; 1, shuning uchun 0 &lt; x &lt; 2. Javob: (0; 2).', 't = 2<sup>x</sup> &gt; 0: t² − 5t + 4 &lt; 0, (t − 1)(t − 4) &lt; 0, 1 &lt; t &lt; 4. Значит 2⁰ &lt; 2<sup>x</sup> &lt; 2², основание 2 &gt; 1, поэтому 0 &lt; x &lt; 2. Ответ: (0; 2).', 't = 2<sup>x</sup> &gt; 0: t² − 5t + 4 &lt; 0, (t − 1)(t − 4) &lt; 0, 1 &lt; t &lt; 4. So 2⁰ &lt; 2<sup>x</sup> &lt; 2²; since 2 &gt; 1, 0 &lt; x &lt; 2. Answer: (0; 2).') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Asosi 1 dan kichik bo‘lganda belgini almashtirmaslik.</b> (0,5)<sup>x</sup> &gt; 0,25 ⇒ x &lt; 2, x &gt; 2 emas. Har doim avval asosni 1 bilan solishtiring.', '<b>Не менять знак при основании меньше 1.</b> (0,5)<sup>x</sup> &gt; 0,25 ⇒ x &lt; 2, а не x &gt; 2. Всегда сначала сравнивайте основание с 1.', '<b>Not flipping the sign when the base is below 1.</b> (0.5)<sup>x</sup> &gt; 0.25 ⇒ x &lt; 2, not x &gt; 2. Always compare the base with 1 first.'),
      L('<b>t &gt; 0 shartini unutish.</b> t² + t − 6 = 0 dan t = −3 chiqsa, 2<sup>x</sup> = −3 ning yechimi yo‘q — uni javobga yozmang.', '<b>Забыть условие t &gt; 0.</b> Если из t² + t − 6 = 0 получилось t = −3, уравнение 2<sup>x</sup> = −3 решений не имеет — не пишите его в ответ.', '<b>Forgetting t &gt; 0.</b> If t² + t − 6 = 0 gives t = −3, the equation 2<sup>x</sup> = −3 has no solution — leave it out of the answer.'),
      L('<b>Darajalarni noto‘g‘ri qo‘shish.</b> 2<sup>x</sup> + 2<sup>x</sup> = 2<sup>x+1</sup>, lekin 2<sup>2x</sup> emas! Shuningdek 2<sup>x</sup> + 3<sup>x</sup> ≠ 5<sup>x</sup>.', '<b>Неверное сложение степеней.</b> 2<sup>x</sup> + 2<sup>x</sup> = 2<sup>x+1</sup>, а не 2<sup>2x</sup>! И 2<sup>x</sup> + 3<sup>x</sup> ≠ 5<sup>x</sup>.', '<b>Adding powers wrongly.</b> 2<sup>x</sup> + 2<sup>x</sup> = 2<sup>x+1</sup>, not 2<sup>2x</sup>! Also 2<sup>x</sup> + 3<sup>x</sup> ≠ 5<sup>x</sup>.'),
      L('<b>a<sup>x</sup> = 0 yoki a<sup>x</sup> = −4 ga yechim izlash.</b> Ko‘rsatkichli funksiya faqat musbat qiymatlar oladi, bunday tenglamalarning yechimi yo‘q.', '<b>Искать решение a<sup>x</sup> = 0 или a<sup>x</sup> = −4.</b> Показательная функция принимает только положительные значения, у таких уравнений решений нет.', '<b>Looking for solutions of a<sup>x</sup> = 0 or a<sup>x</sup> = −4.</b> The exponential function takes only positive values, so such equations have no solution.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Biologiya.</b> E. coli bakteriyasi qulay sharoitda taxminan har 20 daqiqada ikkiga bo‘linadi. Bitta hujayradan N = 2<sup>t/20</sup> hujayra hosil bo‘ladi. «Qachon million bo‘ladi?» degan savol 2<sup>t/20</sup> = 10⁶ tenglamaga olib keladi: 2²⁰ ≈ 10⁶ bo‘lgani uchun t ≈ 400 daqiqa, ya’ni 7 soatga yaqin.', '<b>Биология.</b> Бактерия E. coli в хороших условиях делится примерно каждые 20 минут. Из одной клетки получается N = 2<sup>t/20</sup> клеток. Вопрос «когда будет миллион?» приводит к уравнению 2<sup>t/20</sup> = 10⁶: так как 2²⁰ ≈ 10⁶, t ≈ 400 минут, почти 7 часов.', '<b>Biology.</b> Under good conditions E. coli divides about every 20 minutes, so one cell becomes N = 2<sup>t/20</sup> cells. The question “when will there be a million?” leads to 2<sup>t/20</sup> = 10⁶: since 2²⁰ ≈ 10⁶, t ≈ 400 minutes, almost 7 hours.'),
      L('<b>Moliya.</b> Omonat yiliga 20% o‘ssa, n yildan keyin S₀ · 1,2<sup>n</sup> bo‘ladi. «Qachon ikki baravar?» — 1,2<sup>n</sup> ≥ 2 tengsizlik; 1,2⁴ ≈ 2,07, demak 4 yil yetadi. <b>Tibbiyot.</b> Dori miqdori har 6 soatda yarmiga kamaysa, uning qoldig‘i (1/2)<sup>t/6</sup> ga ko‘paytiriladi; shifokorlar shundan dori ichish oralig‘ini hisoblaydi.', '<b>Финансы.</b> Если вклад растёт на 20% в год, через n лет он составит S₀ · 1,2<sup>n</sup>. «Когда удвоится?» — неравенство 1,2<sup>n</sup> ≥ 2; 1,2⁴ ≈ 2,07, значит, хватит 4 лет. <b>Медицина.</b> Если количество лекарства уменьшается вдвое каждые 6 часов, остаток умножается на (1/2)<sup>t/6</sup>; по этому врачи рассчитывают интервал приёма.', '<b>Finance.</b> If a deposit grows 20% a year, after n years it is S₀ · 1.2<sup>n</sup>. “When does it double?” is the inequality 1.2<sup>n</sup> ≥ 2; 1.2⁴ ≈ 2.07, so 4 years are enough. <b>Medicine.</b> If a drug halves every 6 hours, the amount left is multiplied by (1/2)<sup>t/6</sup>; doctors use this to set dosing intervals.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Qog‘oz varag‘ini 42 marta ikkiga buklash mumkin bo‘lsa, uning qalinligi 0,1 mm · 2⁴² ≈ 440 000 km bo‘lib, Oygacha yetardi.', 'Если бы лист бумаги можно было сложить пополам 42 раза, его толщина составила бы 0,1 мм · 2⁴² ≈ 440 000 км — до Луны.', 'If a sheet of paper could be folded in half 42 times, it would be 0.1 mm · 2⁴² ≈ 440 000 km thick — enough to reach the Moon.'),
      L('2<sup>x</sup> = x² tenglamaning uchta ildizi bor: x = 2, x = 4 va bitta manfiy ildiz x ≈ −0,77. Uni faqat grafik yoki taqribiy usul bilan topish mumkin.', 'Уравнение 2<sup>x</sup> = x² имеет три корня: x = 2, x = 4 и отрицательный x ≈ −0,77. Его можно найти только графически или приближённо.', 'The equation 2<sup>x</sup> = x² has three roots: x = 2, x = 4 and a negative one x ≈ −0.77, which can only be found graphically or numerically.'),
      L('Kompyuter xotirasi 2 ning darajalarida o‘lchanadi: 1 KB = 2¹⁰ = 1024 bayt, 1 GB = 2³⁰ bayt.', 'Память компьютера измеряется степенями двойки: 1 КБ = 2¹⁰ = 1024 байта, 1 ГБ = 2³⁰ байт.', 'Computer memory comes in powers of two: 1 KB = 2¹⁰ = 1024 bytes, 1 GB = 2³⁰ bytes.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('5<sup>x−3</sup> = 25', '5<sup>x−3</sup> = 25', '5<sup>x−3</sup> = 25'), s: L('5<sup>x−3</sup> = 5² ⇒ x − 3 = 2 ⇒ x = 5.', '5<sup>x−3</sup> = 5² ⇒ x − 3 = 2 ⇒ x = 5.', '5<sup>x−3</sup> = 5² ⇒ x − 3 = 2 ⇒ x = 5.') },
      { q: L('(1/3)<sup>x</sup> &lt; 9 tengsizlikni yeching.', 'Решите неравенство (1/3)<sup>x</sup> &lt; 9.', 'Solve (1/3)<sup>x</sup> &lt; 9.'), s: L('9 = (1/3)<sup>−2</sup>, asos 1/3 &lt; 1, belgi almashadi: x &gt; −2.', '9 = (1/3)<sup>−2</sup>, основание 1/3 &lt; 1, знак меняется: x &gt; −2.', '9 = (1/3)<sup>−2</sup>, base 1/3 &lt; 1, the sign flips: x &gt; −2.') },
      { q: L('2<sup>x</sup> = −8 tenglamaning nechta ildizi bor?', 'Сколько корней у уравнения 2<sup>x</sup> = −8?', 'How many roots does 2<sup>x</sup> = −8 have?'), s: L('Birorta ham yo‘q: 2<sup>x</sup> &gt; 0.', 'Ни одного: 2<sup>x</sup> &gt; 0.', 'None: 2<sup>x</sup> &gt; 0.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Ko‘rsatkichli tenglamada noma’lum daraja ko‘rsatkichida turadi.', 'В показательном уравнении неизвестное стоит в показателе степени.', 'In an exponential equation the unknown is in the exponent.'),
      L('a<sup>f(x)</sup> = a<sup>g(x)</sup> ⇔ f(x) = g(x) (a &gt; 0, a ≠ 1) — monotonlik natijasi.', 'a<sup>f(x)</sup> = a<sup>g(x)</sup> ⇔ f(x) = g(x) (a &gt; 0, a ≠ 1) — следствие монотонности.', 'a<sup>f(x)</sup> = a<sup>g(x)</sup> ⇔ f(x) = g(x) (a &gt; 0, a ≠ 1) — a consequence of monotonicity.'),
      L('Usullar: bir asosga keltirish, qavsdan chiqarish, yangi o‘zgaruvchi, bir jinsli tenglamaga bo‘lish.', 'Методы: одно основание, вынесение за скобки, новая переменная, деление однородного уравнения.', 'Methods: same base, factoring out, new variable, dividing a homogeneous equation.'),
      L('t = a<sup>x</sup> almashtirishda doim t &gt; 0.', 'При замене t = a<sup>x</sup> всегда t &gt; 0.', 'With t = a<sup>x</sup> always t &gt; 0.'),
      L('Tengsizlikda: a &gt; 1 — belgi saqlanadi, 0 &lt; a &lt; 1 — belgi almashadi.', 'В неравенстве: a &gt; 1 — знак сохраняется, 0 &lt; a &lt; 1 — меняется.', 'In inequalities: a &gt; 1 keeps the sign, 0 &lt; a &lt; 1 flips it.'),
      L('a<sup>x</sup> = b (b ≤ 0) ning yechimi yo‘q.', 'a<sup>x</sup> = b (b ≤ 0) не имеет решений.', 'a<sup>x</sup> = b (b ≤ 0) has no solution.')
    ] }
  ] });

  // ---------- t12. Logarifm tushunchasi. Logarifmik funksiya ----------
  T.add(P, 't12', { sections: [
    { kind: 'intro', h: L('Qaysi darajaga ko‘tarish kerak?', 'В какую степень возвести?', 'Which power do we need?'), p: [
      L('2<sup>x</sup> = 8 tenglamani og‘zaki yechamiz: x = 3. Lekin 2<sup>x</sup> = 5 ni qanday yechamiz? 2² = 4, 2³ = 8, demak x ikki bilan uch orasida, lekin aniq qiymatini butun yoki oddiy kasr bilan yozib bo‘lmaydi. Matematiklar bunday son uchun maxsus belgi o‘ylab topishgan: x = log<sub>2</sub>5, o‘qilishi «5 ning 2 asosga ko‘ra logarifmi». Logarifm — bu «qaysi darajaga?» degan savolga javob beradigan amal.', 'Уравнение 2<sup>x</sup> = 8 решаем устно: x = 3. А как решить 2<sup>x</sup> = 5? 2² = 4, 2³ = 8, значит x между двумя и тремя, но точно записать его целым числом или простой дробью нельзя. Для такого числа математики придумали специальное обозначение: x = log<sub>2</sub>5, читается «логарифм 5 по основанию 2». Логарифм — это действие, отвечающее на вопрос «в какую степень?».', 'We solve 2<sup>x</sup> = 8 in our heads: x = 3. But how do we solve 2<sup>x</sup> = 5? 2² = 4 and 2³ = 8, so x lies between two and three, but it cannot be written as a whole number or a simple fraction. Mathematicians invented a special symbol for it: x = log<sub>2</sub>5, read “the logarithm of 5 to base 2”. The logarithm is the operation that answers the question “which power?”.'),
      L('Qo‘shishga ayirish, ko‘paytirishga bo‘lish, kvadratga ko‘tarishga kvadrat ildiz teskari bo‘lgani kabi, darajaga ko‘tarishga ham ikki teskari amal bor: asosni topish (ildiz chiqarish) va ko‘rsatkichni topish (logarifmlash). Bu mavzuda logarifm ta’rifi, asosiy logarifmik ayniyat, o‘nli va natural logarifmlar hamda y = log<sub>a</sub>x funksiyaning grafigi va xossalarini o‘rganamiz.', 'Как вычитание обратно сложению, деление — умножению, корень — возведению в квадрат, так и у возведения в степень есть два обратных действия: нахождение основания (извлечение корня) и нахождение показателя (логарифмирование). В этой теме мы изучим определение логарифма, основное логарифмическое тождество, десятичные и натуральные логарифмы, а также график и свойства функции y = log<sub>a</sub>x.', 'Just as subtraction undoes addition, division undoes multiplication and the square root undoes squaring, raising to a power has two inverse operations: finding the base (taking a root) and finding the exponent (taking a logarithm). In this topic we study the definition of the logarithm, the basic logarithmic identity, common and natural logarithms, and the graph and properties of y = log<sub>a</sub>x.')
    ] },
    { kind: 'def', h: L('Logarifm ta’rifi', 'Определение логарифма', 'Definition of the logarithm'), p: [
      L('Musbat b sonining a asosga ko‘ra <b>logarifmi</b> deb, b ni hosil qilish uchun a ni ko‘tarish kerak bo‘lgan daraja ko‘rsatkichiga aytiladi: <b>log<sub>a</sub>b = c ⇔ a<sup>c</sup> = b</b>. Bu yerda a &gt; 0, a ≠ 1, b &gt; 0. Masalan, log<sub>3</sub>81 = 4, chunki 3⁴ = 81; log<sub>5</sub>(1/25) = −2, chunki 5<sup>−2</sup> = 1/25; log<sub>4</sub>2 = 1/2, chunki 4<sup>1/2</sup> = 2.', '<b>Логарифмом</b> положительного числа b по основанию a называется показатель степени, в которую нужно возвести a, чтобы получить b: <b>log<sub>a</sub>b = c ⇔ a<sup>c</sup> = b</b>. Здесь a &gt; 0, a ≠ 1, b &gt; 0. Например, log<sub>3</sub>81 = 4, так как 3⁴ = 81; log<sub>5</sub>(1/25) = −2, так как 5<sup>−2</sup> = 1/25; log<sub>4</sub>2 = 1/2, так как 4<sup>1/2</sup> = 2.', 'The <b>logarithm</b> of a positive number b to base a is the exponent to which a must be raised to give b: <b>log<sub>a</sub>b = c ⇔ a<sup>c</sup> = b</b>, where a &gt; 0, a ≠ 1, b &gt; 0. For example, log<sub>3</sub>81 = 4 because 3⁴ = 81; log<sub>5</sub>(1/25) = −2 because 5<sup>−2</sup> = 1/25; log<sub>4</sub>2 = 1/2 because 4<sup>1/2</sup> = 2.'),
      L('Nega shunday shartlar? Asos manfiy bo‘lsa, kasr darajalar aniqlanmaydi; a = 1 bo‘lsa, 1<sup>c</sup> doim 1 ga teng va boshqa sonni hosil qilib bo‘lmaydi. b esa musbat bo‘lishi shart, chunki musbat asosning har qanday darajasi musbat. Shuning uchun log<sub>2</sub>(−4) va log<sub>3</sub>0 mavjud emas.', 'Почему такие условия? При отрицательном основании дробные степени не определены; при a = 1 степень 1<sup>c</sup> всегда равна 1 и другого числа не получить. А b должно быть положительным, потому что любая степень положительного основания положительна. Поэтому log<sub>2</sub>(−4) и log<sub>3</sub>0 не существуют.', 'Why these conditions? With a negative base, fractional powers are undefined; with a = 1 the power 1<sup>c</sup> is always 1, so no other number can be obtained. And b must be positive, since every power of a positive base is positive. That is why log<sub>2</sub>(−4) and log<sub>3</sub>0 do not exist.')
    ], list: [
      L('<b>Asosiy logarifmik ayniyat:</b> a<sup>log<sub>a</sub>b</sup> = b. Masalan, 7<sup>log<sub>7</sub>3</sup> = 3.', '<b>Основное логарифмическое тождество:</b> a<sup>log<sub>a</sub>b</sup> = b. Например, 7<sup>log<sub>7</sub>3</sup> = 3.', '<b>Basic logarithmic identity:</b> a<sup>log<sub>a</sub>b</sup> = b. For example, 7<sup>log<sub>7</sub>3</sup> = 3.'),
      L('log<sub>a</sub>1 = 0, log<sub>a</sub>a = 1, log<sub>a</sub>a<sup>c</sup> = c.', 'log<sub>a</sub>1 = 0, log<sub>a</sub>a = 1, log<sub>a</sub>a<sup>c</sup> = c.', 'log<sub>a</sub>1 = 0, log<sub>a</sub>a = 1, log<sub>a</sub>a<sup>c</sup> = c.'),
      L('<b>O‘nli logarifm:</b> lg b = log<sub>10</sub>b. <b>Natural logarifm:</b> ln b = log<sub>e</sub>b, e ≈ 2,71828.', '<b>Десятичный логарифм:</b> lg b = log<sub>10</sub>b. <b>Натуральный:</b> ln b = log<sub>e</sub>b, e ≈ 2,71828.', '<b>Common logarithm:</b> lg b = log<sub>10</sub>b. <b>Natural logarithm:</b> ln b = log<sub>e</sub>b, e ≈ 2.71828.')
    ] },
    { kind: 'history', h: L('Tarixdan: Neper, Byurgi va Brigs', 'Из истории: Непер, Бюрги и Бриггс', 'History: Napier, Bürgi and Briggs'), p: [
      L('XVI asr oxirida astronomlar va dengizchilar ulkan sonlarni ko‘paytirishdan qiynalardi: bitta hisob bir necha kun olishi mumkin edi. Shotlandiyalik baron <b>Jon Neper</b> 20 yil ishlab, 1614-yilda «Logarifmlarning ajoyib jadvalining tavsifi» kitobini nashr etdi. «Logarifm» so‘zi yunoncha <i>logos</i> (nisbat) va <i>arithmos</i> (son) so‘zlaridan olingan. Shveytsariyalik soatsoz <b>Iost Byurgi</b> ham mustaqil ravishda shunday jadval tuzgan, lekin uni 1620-yilda kechroq nashr qilgan.', 'В конце XVI века астрономы и мореплаватели мучились с умножением огромных чисел: один расчёт мог занять несколько дней. Шотландский барон <b>Джон Непер</b> работал 20 лет и в 1614 году издал книгу «Описание удивительной таблицы логарифмов». Слово «логарифм» происходит от греческих <i>logos</i> (отношение) и <i>arithmos</i> (число). Швейцарский часовщик <b>Йост Бюрги</b> независимо составил похожую таблицу, но опубликовал её позже, в 1620 году.', 'At the end of the 16th century astronomers and navigators struggled to multiply huge numbers: one calculation could take days. The Scottish baron <b>John Napier</b> worked for 20 years and in 1614 published “A Description of the Wonderful Table of Logarithms”. The word “logarithm” comes from Greek <i>logos</i> (ratio) and <i>arithmos</i> (number). The Swiss clockmaker <b>Jost Bürgi</b> independently built a similar table but published it later, in 1620.'),
      L('Neperning jadvallari noqulay asosga ega edi. Oksfordlik professor <b>Genri Brigs</b> Neper bilan uchrashib, asosni 10 qilib olishni taklif qildi va 1624-yilda 14 xonali o‘nli logarifmlar jadvalini chiqardi. Pyer-Simon Laplas logarifmlar haqida ular «astronomlar umrini ikki baravar uzaytirdi» degan. Natural logarifm va e sonini esa XVIII asrda Leonard Eyler tizimlashtirdi.', 'У таблиц Непера было неудобное основание. Оксфордский профессор <b>Генри Бриггс</b> встретился с Непером, предложил взять основание 10 и в 1624 году выпустил таблицу десятичных логарифмов с 14 знаками. Пьер-Симон Лаплас говорил, что логарифмы «удвоили жизнь астрономов». Натуральный логарифм и число e систематизировал в XVIII веке Леонард Эйлер.', 'Napier’s tables used an awkward base. The Oxford professor <b>Henry Briggs</b> met Napier, proposed base 10, and in 1624 published a table of common logarithms to 14 digits. Pierre-Simon Laplace said logarithms had “doubled the life of astronomers”. The natural logarithm and the number e were systematised by Leonhard Euler in the 18th century.')
    ] },
    { kind: 'rule', h: L('Logarifmik funksiya va uning xossalari', 'Логарифмическая функция и её свойства', 'The logarithmic function and its properties'), p: [
      L('y = log<sub>a</sub>x funksiya y = a<sup>x</sup> ga <b>teskari</b> funksiya. Shuning uchun ularning grafiklari y = x to‘g‘ri chiziqqa nisbatan simmetrik. Ko‘rsatkichli funksiyaning aniqlanish sohasi ℝ, qiymatlari (0; +∞) edi — logarifmda esa aksincha.', 'Функция y = log<sub>a</sub>x — <b>обратная</b> к y = a<sup>x</sup>. Поэтому их графики симметричны относительно прямой y = x. У показательной функции область определения ℝ, а значения (0; +∞) — у логарифмической наоборот.', 'The function y = log<sub>a</sub>x is the <b>inverse</b> of y = a<sup>x</sup>, so their graphs are symmetric in the line y = x. The exponential function has domain ℝ and range (0; +∞) — for the logarithm it is the other way round.')
    ], list: [
      L('Aniqlanish sohasi: D = (0; +∞); qiymatlar to‘plami: E = ℝ.', 'Область определения: D = (0; +∞); множество значений: E = ℝ.', 'Domain: D = (0; +∞); range: E = ℝ.'),
      L('Grafik har doim (1; 0) nuqtadan o‘tadi va (a; 1) nuqtadan o‘tadi.', 'График всегда проходит через (1; 0) и через (a; 1).', 'The graph always passes through (1; 0) and through (a; 1).'),
      L('a &gt; 1 da funksiya o‘suvchi: x &gt; 1 da log &gt; 0, 0 &lt; x &lt; 1 da log &lt; 0.', 'При a &gt; 1 функция возрастает: при x &gt; 1 log &gt; 0, при 0 &lt; x &lt; 1 log &lt; 0.', 'For a &gt; 1 the function increases: log &gt; 0 for x &gt; 1 and log &lt; 0 for 0 &lt; x &lt; 1.'),
      L('0 &lt; a &lt; 1 da funksiya kamayuvchi, ishoralar teskari.', 'При 0 &lt; a &lt; 1 функция убывает, знаки противоположные.', 'For 0 &lt; a &lt; 1 the function decreases and the signs are reversed.'),
      L('Oy o‘qi (x = 0) — vertikal asimptota; funksiya juft ham, toq ham emas, davriy emas.', 'Ось Oy (x = 0) — вертикальная асимптота; функция ни чётная, ни нечётная, непериодическая.', 'The y-axis (x = 0) is a vertical asymptote; the function is neither even nor odd and not periodic.')
    ] },
    { kind: 'table', h: L('Ko‘rsatkichli va logarifmik funksiyalar taqqoslash', 'Сравнение показательной и логарифмической функций', 'Exponential vs logarithmic function'), table: {
      head: [L('Xossa', 'Свойство', 'Property'), L('y = a<sup>x</sup>', 'y = a<sup>x</sup>', 'y = a<sup>x</sup>'), L('y = log<sub>a</sub>x', 'y = log<sub>a</sub>x', 'y = log<sub>a</sub>x')],
      rows: [
        [L('Aniqlanish sohasi', 'Область определения', 'Domain'), L('ℝ', 'ℝ', 'ℝ'), L('(0; +∞)', '(0; +∞)', '(0; +∞)')],
        [L('Qiymatlar to‘plami', 'Множество значений', 'Range'), L('(0; +∞)', '(0; +∞)', '(0; +∞)'), L('ℝ', 'ℝ', 'ℝ')],
        [L('Maxsus nuqta', 'Особая точка', 'Key point'), L('(0; 1)', '(0; 1)', '(0; 1)'), L('(1; 0)', '(1; 0)', '(1; 0)')],
        [L('Asimptota', 'Асимптота', 'Asymptote'), L('y = 0', 'y = 0', 'y = 0'), L('x = 0', 'x = 0', 'x = 0')],
        [L('a &gt; 1 da', 'При a &gt; 1', 'For a &gt; 1'), L('o‘sadi', 'возрастает', 'increasing'), L('o‘sadi', 'возрастает', 'increasing')],
        [L('0 &lt; a &lt; 1 da', 'При 0 &lt; a &lt; 1', 'For 0 &lt; a &lt; 1'), L('kamayadi', 'убывает', 'decreasing'), L('kamayadi', 'убывает', 'decreasing')]
      ] }, after: [
      L('Logarifm juda sekin o‘sadi: lg 10 = 1, lg 1000 = 3, lg 1 000 000 = 6. Million marta kattalashgan son logarifmda atigi 6 birlik oshadi — shuning uchun logarifmik shkalalar juda katta diapazonlarni ixcham ko‘rsatadi.', 'Логарифм растёт очень медленно: lg 10 = 1, lg 1000 = 3, lg 1 000 000 = 6. Число, выросшее в миллион раз, увеличивает логарифм всего на 6 — поэтому логарифмические шкалы компактно показывают огромные диапазоны.', 'The logarithm grows very slowly: lg 10 = 1, lg 1000 = 3, lg 1 000 000 = 6. A number that grows a million times raises its logarithm by only 6 — which is why logarithmic scales show huge ranges compactly.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: log<sub>2</sub>32, log<sub>1/3</sub>27, lg 0,001.', 'Вычислите: log<sub>2</sub>32, log<sub>1/3</sub>27, lg 0,001.', 'Compute log<sub>2</sub>32, log<sub>1/3</sub>27, lg 0.001.'), s: L('2⁵ = 32 ⇒ log<sub>2</sub>32 = 5. (1/3)<sup>−3</sup> = 27 ⇒ log<sub>1/3</sub>27 = −3. 10<sup>−3</sup> = 0,001 ⇒ lg 0,001 = −3.', '2⁵ = 32 ⇒ log<sub>2</sub>32 = 5. (1/3)<sup>−3</sup> = 27 ⇒ log<sub>1/3</sub>27 = −3. 10<sup>−3</sup> = 0,001 ⇒ lg 0,001 = −3.', '2⁵ = 32 ⇒ log<sub>2</sub>32 = 5. (1/3)<sup>−3</sup> = 27 ⇒ log<sub>1/3</sub>27 = −3. 10<sup>−3</sup> = 0.001 ⇒ lg 0.001 = −3.') },
      { q: L('Hisoblang: 3<sup>2 + log<sub>3</sub>5</sup>.', 'Вычислите: 3<sup>2 + log<sub>3</sub>5</sup>.', 'Compute 3<sup>2 + log<sub>3</sub>5</sup>.'), s: L('Daraja xossasi bo‘yicha 3<sup>2 + log<sub>3</sub>5</sup> = 3² · 3<sup>log<sub>3</sub>5</sup> = 9 · 5 = 45 (asosiy logarifmik ayniyat).', 'По свойству степени 3<sup>2 + log<sub>3</sub>5</sup> = 3² · 3<sup>log<sub>3</sub>5</sup> = 9 · 5 = 45 (основное логарифмическое тождество).', 'By the power rule 3<sup>2 + log<sub>3</sub>5</sup> = 3² · 3<sup>log<sub>3</sub>5</sup> = 9 · 5 = 45 (basic logarithmic identity).') },
      { q: L('y = log<sub>3</sub>(4 − x²) funksiyaning aniqlanish sohasini toping.', 'Найдите область определения y = log<sub>3</sub>(4 − x²).', 'Find the domain of y = log<sub>3</sub>(4 − x²).'), s: L('Logarifm ostidagi ifoda musbat: 4 − x² &gt; 0 ⇔ x² &lt; 4 ⇔ −2 &lt; x &lt; 2. Javob: (−2; 2).', 'Выражение под логарифмом положительно: 4 − x² &gt; 0 ⇔ x² &lt; 4 ⇔ −2 &lt; x &lt; 2. Ответ: (−2; 2).', 'The argument must be positive: 4 − x² &gt; 0 ⇔ x² &lt; 4 ⇔ −2 &lt; x &lt; 2. Answer: (−2; 2).') },
      { q: L('Solishtiring: log<sub>0,5</sub>3 va log<sub>0,5</sub>5.', 'Сравните log<sub>0,5</sub>3 и log<sub>0,5</sub>5.', 'Compare log<sub>0.5</sub>3 and log<sub>0.5</sub>5.'), s: L('Asos 0,5 &lt; 1, funksiya kamayuvchi. 3 &lt; 5 bo‘lgani uchun log<sub>0,5</sub>3 &gt; log<sub>0,5</sub>5.', 'Основание 0,5 &lt; 1, функция убывает. Так как 3 &lt; 5, log<sub>0,5</sub>3 &gt; log<sub>0,5</sub>5.', 'The base 0.5 &lt; 1, so the function decreases. Since 3 &lt; 5, log<sub>0.5</sub>3 &gt; log<sub>0.5</sub>5.') },
      { q: L('log<sub>2</sub>10 qaysi ikki butun son orasida?', 'Между какими целыми числами лежит log<sub>2</sub>10?', 'Between which integers does log<sub>2</sub>10 lie?'), s: L('2³ = 8 &lt; 10 &lt; 16 = 2⁴, funksiya o‘suvchi, demak 3 &lt; log<sub>2</sub>10 &lt; 4 (aniqrog‘i ≈ 3,32).', '2³ = 8 &lt; 10 &lt; 16 = 2⁴, функция возрастает, значит 3 &lt; log<sub>2</sub>10 &lt; 4 (точнее ≈ 3,32).', '2³ = 8 &lt; 10 &lt; 16 = 2⁴ and the function increases, so 3 &lt; log<sub>2</sub>10 &lt; 4 (more precisely ≈ 3.32).') }
    ] },
    { kind: 'steps', h: L('Logarifmni qanday hisoblash kerak', 'Как вычислить логарифм', 'How to evaluate a logarithm'), p: [
      L('log<sub>a</sub>b ni hisoblash uchun quyidagi savolni bering: «a ning qaysi darajasi b ga teng?» Buning uchun a va b ni bitta sonning darajasi sifatida yozish qulay. Masalan, log<sub>8</sub>16: 8 = 2³, 16 = 2⁴. (2³)<sup>c</sup> = 2⁴ ⇒ 3c = 4 ⇒ c = 4/3. log<sub>√5</sub>25: √5 = 5<sup>1/2</sup>, 25 = 5², (5<sup>1/2</sup>)<sup>c</sup> = 5² ⇒ c = 4.', 'Чтобы вычислить log<sub>a</sub>b, задайте вопрос: «какая степень a равна b?» Для этого удобно записать a и b как степени одного числа. Например, log<sub>8</sub>16: 8 = 2³, 16 = 2⁴. (2³)<sup>c</sup> = 2⁴ ⇒ 3c = 4 ⇒ c = 4/3. log<sub>√5</sub>25: √5 = 5<sup>1/2</sup>, 25 = 5², (5<sup>1/2</sup>)<sup>c</sup> = 5² ⇒ c = 4.', 'To evaluate log<sub>a</sub>b, ask: “which power of a equals b?” It helps to write a and b as powers of one number. For example, log<sub>8</sub>16: 8 = 2³, 16 = 2⁴, (2³)<sup>c</sup> = 2⁴ ⇒ 3c = 4 ⇒ c = 4/3. log<sub>√5</sub>25: √5 = 5<sup>1/2</sup>, 25 = 5², (5<sup>1/2</sup>)<sup>c</sup> = 5² ⇒ c = 4.'),
      L('Agar bunday yozib bo‘lmasa (log<sub>3</sub>7), qiymat irratsional bo‘ladi va kalkulyator yoki jadval kerak. Kalkulyatorda odatda faqat lg va ln tugmalari bor; boshqa asos uchun keyingi mavzudagi «yangi asosga o‘tish» formulasidan foydalaniladi: log<sub>3</sub>7 = lg 7 / lg 3 ≈ 1,77.', 'Если так записать нельзя (log<sub>3</sub>7), значение иррационально и нужен калькулятор или таблица. На калькуляторе обычно есть только кнопки lg и ln; для другого основания используют формулу перехода к новому основанию из следующей темы: log<sub>3</sub>7 = lg 7 / lg 3 ≈ 1,77.', 'If this is impossible (log<sub>3</sub>7), the value is irrational and you need a calculator or a table. Calculators usually have only lg and ln keys; for other bases use the change-of-base formula from the next topic: log<sub>3</sub>7 = lg 7 / lg 3 ≈ 1.77.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Asos va argumentni almashtirish.</b> log<sub>2</sub>8 = 3, lekin log<sub>8</sub>2 = 1/3. Asos — pastdagi kichik son.', '<b>Путать основание и аргумент.</b> log<sub>2</sub>8 = 3, а log<sub>8</sub>2 = 1/3. Основание — маленькое число внизу.', '<b>Swapping base and argument.</b> log<sub>2</sub>8 = 3 but log<sub>8</sub>2 = 1/3. The base is the small number at the bottom.'),
      L('<b>Manfiy son yoki nolning logarifmini hisoblash.</b> log<sub>2</sub>(−8) mavjud emas. Lekin logarifmning <i>o‘zi</i> manfiy bo‘lishi mumkin: log<sub>2</sub>(1/8) = −3.', '<b>Брать логарифм отрицательного числа или нуля.</b> log<sub>2</sub>(−8) не существует. Но <i>сам</i> логарифм может быть отрицательным: log<sub>2</sub>(1/8) = −3.', '<b>Taking the logarithm of a negative number or zero.</b> log<sub>2</sub>(−8) does not exist. But the logarithm <i>itself</i> may be negative: log<sub>2</sub>(1/8) = −3.'),
      L('<b>log<sub>a</sub>1 = 1 deb yozish.</b> To‘g‘risi: log<sub>a</sub>1 = 0, chunki a⁰ = 1; log<sub>a</sub>a = 1.', '<b>Писать log<sub>a</sub>1 = 1.</b> Правильно: log<sub>a</sub>1 = 0, так как a⁰ = 1; log<sub>a</sub>a = 1.', '<b>Writing log<sub>a</sub>1 = 1.</b> Correct: log<sub>a</sub>1 = 0 since a⁰ = 1; log<sub>a</sub>a = 1.'),
      L('<b>Aniqlanish sohasini unutish.</b> y = lg(x − 3) da x &gt; 3, x ≥ 3 emas.', '<b>Забывать область определения.</b> У y = lg(x − 3) x &gt; 3, а не x ≥ 3.', '<b>Forgetting the domain.</b> For y = lg(x − 3) we need x &gt; 3, not x ≥ 3.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('Logarifm qayerda yashiringanini sezmaymiz, lekin u hamma joyda. <b>Zilzila</b> magnitudasi amplitudaning o‘nli logarifmiga bog‘liq: magnitudasi 7 bo‘lgan zilzilada yer tebranishi 6 bo‘lgandagidan 10 marta katta. <b>Tovush</b> balandligi desibelda: L = 10 lg(I/I₀). <b>Kimyoda</b> pH = −lg[H⁺]: suv uchun pH = 7, limon sharbati uchun taxminan 2. <b>Informatikada</b> ikkilik qidiruv 1 000 000 ta yozuvdan kerakligini log<sub>2</sub>10⁶ ≈ 20 qadamda topadi.', 'Мы не замечаем, где прячется логарифм, но он повсюду. Магнитуда <b>землетрясения</b> зависит от десятичного логарифма амплитуды: при магнитуде 7 колебания почвы в 10 раз сильнее, чем при 6. <b>Громкость звука</b> в децибелах: L = 10 lg(I/I₀). В <b>химии</b> pH = −lg[H⁺]: у воды pH = 7, у лимонного сока около 2. В <b>информатике</b> двоичный поиск находит запись среди 1 000 000 за log<sub>2</sub>10⁶ ≈ 20 шагов.', 'We rarely notice logarithms, but they are everywhere. The <b>earthquake</b> magnitude depends on the common logarithm of amplitude: a magnitude 7 quake shakes the ground 10 times more than a 6. <b>Loudness</b> in decibels is L = 10 lg(I/I₀). In <b>chemistry</b> pH = −lg[H⁺]: water has pH 7, lemon juice about 2. In <b>computer science</b> binary search finds one record among 1 000 000 in log<sub>2</sub>10⁶ ≈ 20 steps.'),
      L('Inson sezgilari ham «logarifmik»: Veber–Fexner qonuniga ko‘ra, biz yorug‘lik yoki tovushning mutlaq emas, nisbiy o‘zgarishini sezamiz. Yulduzlarning ko‘rinma kattaligi ham shu sababli logarifmik shkalada o‘lchanadi.', 'Наши ощущения тоже «логарифмические»: по закону Вебера–Фехнера мы чувствуем не абсолютное, а относительное изменение света или звука. Поэтому и видимая звёздная величина измеряется по логарифмической шкале.', 'Our senses are “logarithmic” too: by the Weber–Fechner law we perceive relative, not absolute, changes in light or sound. That is why the apparent magnitude of stars is measured on a logarithmic scale.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('log<sub>7</sub>49 + log<sub>2</sub>(1/4)', 'log<sub>7</sub>49 + log<sub>2</sub>(1/4)', 'log<sub>7</sub>49 + log<sub>2</sub>(1/4)'), s: L('2 + (−2) = 0.', '2 + (−2) = 0.', '2 + (−2) = 0.') },
      { q: L('10<sup>lg 7</sup> nimaga teng?', 'Чему равно 10<sup>lg 7</sup>?', 'What is 10<sup>lg 7</sup>?'), s: L('Asosiy ayniyat bo‘yicha 7.', 'По основному тождеству 7.', 'By the basic identity, 7.') },
      { q: L('y = ln(x + 5) ning aniqlanish sohasi?', 'Область определения y = ln(x + 5)?', 'Domain of y = ln(x + 5)?'), s: L('x + 5 &gt; 0 ⇒ (−5; +∞).', 'x + 5 &gt; 0 ⇒ (−5; +∞).', 'x + 5 &gt; 0 ⇒ (−5; +∞).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('log<sub>a</sub>b = c ⇔ a<sup>c</sup> = b; a &gt; 0, a ≠ 1, b &gt; 0.', 'log<sub>a</sub>b = c ⇔ a<sup>c</sup> = b; a &gt; 0, a ≠ 1, b &gt; 0.', 'log<sub>a</sub>b = c ⇔ a<sup>c</sup> = b; a &gt; 0, a ≠ 1, b &gt; 0.'),
      L('a<sup>log<sub>a</sub>b</sup> = b; log<sub>a</sub>1 = 0; log<sub>a</sub>a = 1.', 'a<sup>log<sub>a</sub>b</sup> = b; log<sub>a</sub>1 = 0; log<sub>a</sub>a = 1.', 'a<sup>log<sub>a</sub>b</sup> = b; log<sub>a</sub>1 = 0; log<sub>a</sub>a = 1.'),
      L('lg — 10 asosli, ln — e asosli logarifm.', 'lg — логарифм по основанию 10, ln — по основанию e.', 'lg is base 10, ln is base e.'),
      L('y = log<sub>a</sub>x — y = a<sup>x</sup> ga teskari; D = (0; +∞), E = ℝ, grafik (1; 0) dan o‘tadi.', 'y = log<sub>a</sub>x — обратная к y = a<sup>x</sup>; D = (0; +∞), E = ℝ, график проходит через (1; 0).', 'y = log<sub>a</sub>x is the inverse of y = a<sup>x</sup>; D = (0; +∞), E = ℝ, the graph passes through (1; 0).'),
      L('a &gt; 1 da o‘sadi, 0 &lt; a &lt; 1 da kamayadi.', 'При a &gt; 1 возрастает, при 0 &lt; a &lt; 1 убывает.', 'Increasing for a &gt; 1, decreasing for 0 &lt; a &lt; 1.'),
      L('Logarifmni Neper (1614) ixtiro qildi, Brigs o‘nli logarifmlarni kiritdi.', 'Логарифмы изобрёл Непер (1614), Бриггс ввёл десятичные.', 'Napier invented logarithms (1614); Briggs introduced common logarithms.')
    ] }
  ] });

  // ---------- t13. Logarifmik ifodalarni ayniy almashtirish ----------
  T.add(P, 't13', { sections: [
    { kind: 'intro', h: L('Ko‘paytirishni qo‘shishga aylantiruvchi sehr', 'Магия: умножение превращается в сложение', 'The magic that turns multiplication into addition'), p: [
      L('Tasavvur qiling, kalkulyator yo‘q va sizga 3 456 · 7 891 ni ko‘paytirish kerak. Ustun usulida bu bir necha daqiqa oladi va xato qilish oson. Qo‘shish esa ancha oson. XVII asr olimlari aynan shu g‘oyadan foydalanishgan: logarifm ko‘paytmani yig‘indiga, bo‘linmani ayirmaga, darajani esa oddiy ko‘paytirishga aylantiradi. Sonlarning logarifmlarini jadvaldan topib qo‘shasiz, so‘ng yig‘indiga mos sonni yana jadvaldan topasiz — ko‘paytma tayyor!', 'Представьте, что калькулятора нет, а нужно умножить 3 456 · 7 891. Столбиком это займёт несколько минут, и легко ошибиться. Складывать гораздо проще. Учёные XVII века использовали именно эту идею: логарифм превращает произведение в сумму, частное — в разность, а степень — в обычное умножение. Находите логарифмы чисел в таблице, складываете, затем по сумме снова находите число в таблице — произведение готово!', 'Imagine there is no calculator and you need 3 456 · 7 891. Long multiplication takes minutes and errors are easy. Adding is much easier. 17th-century scientists used exactly this idea: the logarithm turns a product into a sum, a quotient into a difference and a power into simple multiplication. Look up the logarithms in a table, add them, then look up the number for the sum — the product is ready!'),
      L('Bu mavzuda logarifmlarning asosiy xossalarini isbotlaymiz, yangi asosga o‘tish formulasini chiqaramiz va ulardan murakkab ifodalarni soddalashtirishda foydalanamiz. Bu qoidalar keyingi mavzudagi logarifmik tenglamalarni yechishning asosiy quroli bo‘ladi.', 'В этой теме мы докажем основные свойства логарифмов, выведем формулу перехода к новому основанию и применим их для упрощения сложных выражений. Эти правила станут главным инструментом при решении логарифмических уравнений в следующей теме.', 'In this topic we prove the main laws of logarithms, derive the change-of-base formula and use them to simplify complicated expressions. These rules will be the main tool for solving logarithmic equations in the next topic.')
    ] },
    { kind: 'def', h: L('Asosiy xossalar', 'Основные свойства', 'The main laws'), p: [
      L('Quyidagi formulalarda a &gt; 0, a ≠ 1, b &gt; 0, c &gt; 0 deb hisoblanadi. Ular ko‘rsatkichli funksiyaning xossalaridan bevosita kelib chiqadi.', 'В формулах ниже a &gt; 0, a ≠ 1, b &gt; 0, c &gt; 0. Они непосредственно следуют из свойств показательной функции.', 'In the formulas below a &gt; 0, a ≠ 1, b &gt; 0, c &gt; 0. They follow directly from the properties of powers.')
    ], list: [
      L('<b>Ko‘paytmaning logarifmi:</b> log<sub>a</sub>(bc) = log<sub>a</sub>b + log<sub>a</sub>c.', '<b>Логарифм произведения:</b> log<sub>a</sub>(bc) = log<sub>a</sub>b + log<sub>a</sub>c.', '<b>Log of a product:</b> log<sub>a</sub>(bc) = log<sub>a</sub>b + log<sub>a</sub>c.'),
      L('<b>Bo‘linmaning logarifmi:</b> log<sub>a</sub>(b/c) = log<sub>a</sub>b − log<sub>a</sub>c.', '<b>Логарифм частного:</b> log<sub>a</sub>(b/c) = log<sub>a</sub>b − log<sub>a</sub>c.', '<b>Log of a quotient:</b> log<sub>a</sub>(b/c) = log<sub>a</sub>b − log<sub>a</sub>c.'),
      L('<b>Darajaning logarifmi:</b> log<sub>a</sub>b<sup>n</sup> = n · log<sub>a</sub>b (n — istalgan haqiqiy son).', '<b>Логарифм степени:</b> log<sub>a</sub>b<sup>n</sup> = n · log<sub>a</sub>b (n — любое действительное число).', '<b>Log of a power:</b> log<sub>a</sub>b<sup>n</sup> = n · log<sub>a</sub>b (n any real number).'),
      L('<b>Asos darajasi:</b> log<sub>a<sup>k</sup></sub>b = (1/k) · log<sub>a</sub>b (k ≠ 0).', '<b>Степень основания:</b> log<sub>a<sup>k</sup></sub>b = (1/k) · log<sub>a</sub>b (k ≠ 0).', '<b>Power of the base:</b> log<sub>a<sup>k</sup></sub>b = (1/k) · log<sub>a</sub>b (k ≠ 0).'),
      L('<b>Yangi asosga o‘tish:</b> log<sub>a</sub>b = log<sub>c</sub>b / log<sub>c</sub>a (c &gt; 0, c ≠ 1). Xususan, log<sub>a</sub>b = 1 / log<sub>b</sub>a.', '<b>Переход к новому основанию:</b> log<sub>a</sub>b = log<sub>c</sub>b / log<sub>c</sub>a (c &gt; 0, c ≠ 1). В частности, log<sub>a</sub>b = 1 / log<sub>b</sub>a.', '<b>Change of base:</b> log<sub>a</sub>b = log<sub>c</sub>b / log<sub>c</sub>a (c &gt; 0, c ≠ 1). In particular log<sub>a</sub>b = 1 / log<sub>b</sub>a.')
    ] },
    { kind: 'rule', h: L('Isbotlar', 'Доказательства', 'Proofs'), p: [
      L('<b>Ko‘paytma.</b> log<sub>a</sub>b = x, log<sub>a</sub>c = y bo‘lsin. Ta’rif bo‘yicha a<sup>x</sup> = b, a<sup>y</sup> = c. Ko‘paytiramiz: bc = a<sup>x</sup> · a<sup>y</sup> = a<sup>x+y</sup>. Yana ta’rif bo‘yicha log<sub>a</sub>(bc) = x + y. Bo‘linma uchun xuddi shunday: b/c = a<sup>x−y</sup>.', '<b>Произведение.</b> Пусть log<sub>a</sub>b = x, log<sub>a</sub>c = y. По определению a<sup>x</sup> = b, a<sup>y</sup> = c. Перемножаем: bc = a<sup>x</sup> · a<sup>y</sup> = a<sup>x+y</sup>. Снова по определению log<sub>a</sub>(bc) = x + y. Для частного аналогично: b/c = a<sup>x−y</sup>.', '<b>Product.</b> Let log<sub>a</sub>b = x and log<sub>a</sub>c = y. By definition a<sup>x</sup> = b and a<sup>y</sup> = c. Multiplying, bc = a<sup>x</sup> · a<sup>y</sup> = a<sup>x+y</sup>, so by definition log<sub>a</sub>(bc) = x + y. For the quotient, similarly b/c = a<sup>x−y</sup>.'),
      L('<b>Daraja.</b> b = a<sup>x</sup> bo‘lsa, b<sup>n</sup> = a<sup>nx</sup>, demak log<sub>a</sub>b<sup>n</sup> = nx = n log<sub>a</sub>b. <b>Yangi asos.</b> b = a<sup>log<sub>a</sub>b</sup> ayniyatning ikki tomonini c asosda logarifmlaymiz: log<sub>c</sub>b = log<sub>a</sub>b · log<sub>c</sub>a. log<sub>c</sub>a ≠ 0 (chunki a ≠ 1) bo‘lgani uchun unga bo‘lamiz — formula isbotlandi.', '<b>Степень.</b> Если b = a<sup>x</sup>, то b<sup>n</sup> = a<sup>nx</sup>, значит log<sub>a</sub>b<sup>n</sup> = nx = n log<sub>a</sub>b. <b>Новое основание.</b> Логарифмируем обе части тождества b = a<sup>log<sub>a</sub>b</sup> по основанию c: log<sub>c</sub>b = log<sub>a</sub>b · log<sub>c</sub>a. Так как log<sub>c</sub>a ≠ 0 (a ≠ 1), делим на него — формула доказана.', '<b>Power.</b> If b = a<sup>x</sup> then b<sup>n</sup> = a<sup>nx</sup>, so log<sub>a</sub>b<sup>n</sup> = nx = n log<sub>a</sub>b. <b>Change of base.</b> Take logarithms to base c of both sides of b = a<sup>log<sub>a</sub>b</sup>: log<sub>c</sub>b = log<sub>a</sub>b · log<sub>c</sub>a. Since log<sub>c</sub>a ≠ 0 (a ≠ 1), divide by it — the formula is proved.')
    ] },
    { kind: 'history', h: L('Tarixdan: logarifmik chizg‘ich', 'Из истории: логарифмическая линейка', 'History: the slide rule'), p: [
      L('Logarifm xossasi log(bc) = log b + log c ning eng chiroyli ixtirosi — <b>logarifmik chizg‘ich</b>. 1620-yilda ingliz Edmund Gunter sonlar logarifmlari uzunligiga mos bo‘laklarga bo‘lingan shkala yasadi, 1622-yilda esa Uilyam Otred ikki shunday shkalani bir-biri bo‘ylab suriladigan qilib qo‘ydi. Kesmalarni qo‘shish — logarifmlarni qo‘shish, ya’ni sonlarni ko‘paytirish demakdir.', 'Самое красивое изобретение на основе свойства log(bc) = log b + log c — <b>логарифмическая линейка</b>. В 1620 году англичанин Эдмунд Гунтер сделал шкалу, деления которой соответствуют логарифмам чисел, а в 1622 году Уильям Отред поставил две такие шкалы так, чтобы одна скользила вдоль другой. Сложить отрезки — значит сложить логарифмы, то есть перемножить числа.', 'The most elegant invention based on log(bc) = log b + log c is the <b>slide rule</b>. In 1620 the Englishman Edmund Gunter made a scale whose markings matched the logarithms of numbers, and in 1622 William Oughtred placed two such scales so that one slides along the other. Adding lengths means adding logarithms, which means multiplying numbers.'),
      L('Logarifmik chizg‘ich 350 yil davomida muhandislarning asosiy quroli bo‘ldi: u bilan Eyfel minorasi, birinchi samolyotlar va hatto 1969-yilda Oyga qo‘ngan «Apollon» kemasining hisob-kitoblari qilingan. Faqat 1970-yillarda arzon elektron kalkulyatorlar uni siqib chiqardi.', 'Логарифмическая линейка 350 лет была главным инструментом инженеров: с её помощью рассчитывали Эйфелеву башню, первые самолёты и даже корабль «Аполлон», севший на Луну в 1969 году. Лишь в 1970-х годах её вытеснили дешёвые электронные калькуляторы.', 'For 350 years the slide rule was the engineer’s main tool: it was used for the Eiffel Tower, the first aeroplanes and even the Apollo spacecraft that landed on the Moon in 1969. Only in the 1970s did cheap electronic calculators replace it.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: log<sub>6</sub>4 + log<sub>6</sub>9.', 'Вычислите: log<sub>6</sub>4 + log<sub>6</sub>9.', 'Compute log<sub>6</sub>4 + log<sub>6</sub>9.'), s: L('Ko‘paytma xossasi: log<sub>6</sub>(4 · 9) = log<sub>6</sub>36 = 2.', 'Свойство произведения: log<sub>6</sub>(4 · 9) = log<sub>6</sub>36 = 2.', 'Product law: log<sub>6</sub>(4 · 9) = log<sub>6</sub>36 = 2.') },
      { q: L('Hisoblang: log<sub>3</sub>54 − log<sub>3</sub>2.', 'Вычислите: log<sub>3</sub>54 − log<sub>3</sub>2.', 'Compute log<sub>3</sub>54 − log<sub>3</sub>2.'), s: L('Bo‘linma xossasi: log<sub>3</sub>(54/2) = log<sub>3</sub>27 = 3.', 'Свойство частного: log<sub>3</sub>(54/2) = log<sub>3</sub>27 = 3.', 'Quotient law: log<sub>3</sub>(54/2) = log<sub>3</sub>27 = 3.') },
      { q: L('Hisoblang: 2 lg 5 + lg 4.', 'Вычислите: 2 lg 5 + lg 4.', 'Compute 2 lg 5 + lg 4.'), s: L('2 lg 5 = lg 25. lg 25 + lg 4 = lg 100 = 2.', '2 lg 5 = lg 25. lg 25 + lg 4 = lg 100 = 2.', '2 lg 5 = lg 25, and lg 25 + lg 4 = lg 100 = 2.') },
      { q: L('Hisoblang: log<sub>2</sub>3 · log<sub>3</sub>4 · log<sub>4</sub>8.', 'Вычислите: log<sub>2</sub>3 · log<sub>3</sub>4 · log<sub>4</sub>8.', 'Compute log<sub>2</sub>3 · log<sub>3</sub>4 · log<sub>4</sub>8.'), s: L('Har birini o‘nli logarifmga o‘tkazamiz: (lg 3/lg 2) · (lg 4/lg 3) · (lg 8/lg 4) = lg 8 / lg 2 = log<sub>2</sub>8 = 3. «Zanjir» qisqaradi.', 'Переводим к десятичным: (lg 3/lg 2) · (lg 4/lg 3) · (lg 8/lg 4) = lg 8 / lg 2 = log<sub>2</sub>8 = 3. «Цепочка» сокращается.', 'Convert to common logs: (lg 3/lg 2) · (lg 4/lg 3) · (lg 8/lg 4) = lg 8 / lg 2 = log<sub>2</sub>8 = 3. The “chain” cancels.') },
      { q: L('log<sub>2</sub>3 = a bo‘lsa, log<sub>2</sub>72 ni a orqali ifodalang.', 'Если log<sub>2</sub>3 = a, выразите log<sub>2</sub>72 через a.', 'If log<sub>2</sub>3 = a, express log<sub>2</sub>72 in terms of a.'), s: L('72 = 8 · 9 = 2³ · 3². log<sub>2</sub>72 = 3 log<sub>2</sub>2 + 2 log<sub>2</sub>3 = 3 + 2a.', '72 = 8 · 9 = 2³ · 3². log<sub>2</sub>72 = 3 log<sub>2</sub>2 + 2 log<sub>2</sub>3 = 3 + 2a.', '72 = 8 · 9 = 2³ · 3², so log<sub>2</sub>72 = 3 log<sub>2</sub>2 + 2 log<sub>2</sub>3 = 3 + 2a.') }
    ] },
    { kind: 'example', h: L('Murakkabroq namunalar', 'Примеры посложнее', 'Harder examples'), ex: [
      { q: L('Hisoblang: 25<sup>log<sub>5</sub>3</sup>.', 'Вычислите: 25<sup>log<sub>5</sub>3</sup>.', 'Compute 25<sup>log<sub>5</sub>3</sup>.'), s: L('25 = 5², shuning uchun 25<sup>log<sub>5</sub>3</sup> = 5<sup>2 log<sub>5</sub>3</sup> = 5<sup>log<sub>5</sub>9</sup> = 9.', '25 = 5², поэтому 25<sup>log<sub>5</sub>3</sup> = 5<sup>2 log<sub>5</sub>3</sup> = 5<sup>log<sub>5</sub>9</sup> = 9.', '25 = 5², so 25<sup>log<sub>5</sub>3</sup> = 5<sup>2 log<sub>5</sub>3</sup> = 5<sup>log<sub>5</sub>9</sup> = 9.') },
      { q: L('Hisoblang: log<sub>√2</sub>8 + log<sub>1/9</sub>3.', 'Вычислите: log<sub>√2</sub>8 + log<sub>1/9</sub>3.', 'Compute log<sub>√2</sub>8 + log<sub>1/9</sub>3.'), s: L('log<sub>√2</sub>8 = log<sub>2<sup>1/2</sup></sub>2³ = 3 : (1/2) = 6. log<sub>1/9</sub>3 = log<sub>3<sup>−2</sup></sub>3 = −1/2. Yig‘indi: 6 − 0,5 = 5,5.', 'log<sub>√2</sub>8 = log<sub>2<sup>1/2</sup></sub>2³ = 3 : (1/2) = 6. log<sub>1/9</sub>3 = log<sub>3<sup>−2</sup></sub>3 = −1/2. Сумма: 6 − 0,5 = 5,5.', 'log<sub>√2</sub>8 = log<sub>2<sup>1/2</sup></sub>2³ = 3 ÷ (1/2) = 6. log<sub>1/9</sub>3 = log<sub>3<sup>−2</sup></sub>3 = −1/2. Sum: 6 − 0.5 = 5.5.') },
      { q: L('lg 2 ≈ 0,301 bo‘lsa, lg 5 va lg 0,08 ni toping.', 'Если lg 2 ≈ 0,301, найдите lg 5 и lg 0,08.', 'If lg 2 ≈ 0.301, find lg 5 and lg 0.08.'), s: L('lg 5 = lg(10/2) = 1 − 0,301 = 0,699. lg 0,08 = lg(8/100) = 3 lg 2 − 2 ≈ 0,903 − 2 = −1,097.', 'lg 5 = lg(10/2) = 1 − 0,301 = 0,699. lg 0,08 = lg(8/100) = 3 lg 2 − 2 ≈ 0,903 − 2 = −1,097.', 'lg 5 = lg(10/2) = 1 − 0.301 = 0.699. lg 0.08 = lg(8/100) = 3 lg 2 − 2 ≈ 0.903 − 2 = −1.097.') }
    ] },
    { kind: 'steps', h: L('Ifodani soddalashtirish strategiyasi', 'Стратегия упрощения', 'Simplification strategy'), list: [
      L('1. Barcha logarifmlarni bitta asosga keltiring (yangi asosga o‘tish formulasi yordamida).', '1. Приведите все логарифмы к одному основанию (формулой перехода).', '1. Bring all logarithms to one base (using the change-of-base formula).'),
      L('2. Logarifm oldidagi koeffitsientlarni daraja ko‘rsatkichiga kiriting: 3 log<sub>a</sub>b = log<sub>a</sub>b³.', '2. Внесите коэффициенты перед логарифмами в показатель: 3 log<sub>a</sub>b = log<sub>a</sub>b³.', '2. Move coefficients into the exponent: 3 log<sub>a</sub>b = log<sub>a</sub>b³.'),
      L('3. Yig‘indini ko‘paytmaga, ayirmani bo‘linmaga birlashtiring.', '3. Сумму объедините в произведение, разность — в частное.', '3. Combine sums into products and differences into quotients.'),
      L('4. Logarifm ostidagi sonni asosning darajasi sifatida yozing va javobni hisoblang.', '4. Запишите число под логарифмом как степень основания и вычислите ответ.', '4. Write the argument as a power of the base and evaluate.'),
      L('5. Agar asos darajaga ko‘tarilgan bo‘lsa (a<sup>log...</sup>), asosiy ayniyatdan foydalaning.', '5. Если основание стоит в степени с логарифмом (a<sup>log...</sup>), используйте основное тождество.', '5. If a base is raised to a logarithm (a<sup>log...</sup>), use the basic identity.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>log(b + c) = log b + log c deb yozish.</b> Bunday formula yo‘q! lg(2 + 8) = lg 10 = 1, lekin lg 2 + lg 8 = lg 16 ≈ 1,2.', '<b>Писать log(b + c) = log b + log c.</b> Такой формулы нет! lg(2 + 8) = lg 10 = 1, а lg 2 + lg 8 = lg 16 ≈ 1,2.', '<b>Writing log(b + c) = log b + log c.</b> No such rule! lg(2 + 8) = lg 10 = 1, but lg 2 + lg 8 = lg 16 ≈ 1.2.'),
      L('<b>log b / log c = log(b/c) deb yozish.</b> Logarifmlar nisbati yangi asosga o‘tish formulasidir: lg 8 / lg 2 = log<sub>2</sub>8 = 3, lg 4 = 0,6 emas.', '<b>Писать log b / log c = log(b/c).</b> Частное логарифмов — это формула перехода: lg 8 / lg 2 = log<sub>2</sub>8 = 3, а не lg 4 ≈ 0,6.', '<b>Writing log b / log c = log(b/c).</b> A ratio of logs is the change-of-base formula: lg 8 / lg 2 = log<sub>2</sub>8 = 3, not lg 4 ≈ 0.6.'),
      L('<b>(log<sub>a</sub>b)<sup>n</sup> va log<sub>a</sub>b<sup>n</sup> ni chalkashtirish.</b> (lg 100)² = 4, lekin lg 100² = 2 · 2 = 4 — bu yerda tasodifan teng, lekin (lg 1000)² = 9 va lg 1000² = 6.', '<b>Путать (log<sub>a</sub>b)<sup>n</sup> и log<sub>a</sub>b<sup>n</sup>.</b> (lg 1000)² = 9, а lg 1000² = 6.', '<b>Confusing (log<sub>a</sub>b)<sup>n</sup> with log<sub>a</sub>b<sup>n</sup>.</b> (lg 1000)² = 9 but lg 1000² = 6.'),
      L('<b>Juft darajada modulni unutish.</b> log<sub>a</sub>x² = 2 log<sub>a</sub>|x|, chunki x manfiy bo‘lishi mumkin.', '<b>Забывать модуль при чётной степени.</b> log<sub>a</sub>x² = 2 log<sub>a</sub>|x|, так как x может быть отрицательным.', '<b>Forgetting the absolute value for even powers.</b> log<sub>a</sub>x² = 2 log<sub>a</sub>|x|, since x may be negative.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Raqamlar sonini aniqlash.</b> 2<sup>100</sup> sonida nechta raqam bor? lg 2<sup>100</sup> = 100 lg 2 ≈ 30,1, demak son 10<sup>30</sup> va 10<sup>31</sup> orasida va 31 ta raqamdan iborat. Daraja xossasisiz buni hisoblash juda qiyin bo‘lardi.', '<b>Число цифр.</b> Сколько цифр в числе 2<sup>100</sup>? lg 2<sup>100</sup> = 100 lg 2 ≈ 30,1, значит, число между 10<sup>30</sup> и 10<sup>31</sup> и содержит 31 цифру. Без свойства степени это было бы очень трудно.', '<b>Counting digits.</b> How many digits does 2<sup>100</sup> have? lg 2<sup>100</sup> = 100 lg 2 ≈ 30.1, so the number lies between 10<sup>30</sup> and 10<sup>31</sup> and has 31 digits. Without the power law this would be very hard.'),
      L('<b>Musiqa.</b> Pianinoda har oktava chastotani 2 marta oshiradi va 12 ta yarim tonga bo‘linadi; har yarim ton chastotani 2<sup>1/12</sup> ≈ 1,0595 marta oshiradi. Ikki nota orasidagi yarim tonlar soni 12 log<sub>2</sub>(f₂/f₁). <b>Muhandislik.</b> Kuchaytirgichlar zanjirida desibellar qo‘shiladi, chunki kuchaytirish koeffitsientlari ko‘paytiriladi — bu ham log(bc) = log b + log c.', '<b>Музыка.</b> На фортепиано каждая октава удваивает частоту и делится на 12 полутонов; каждый полутон умножает частоту на 2<sup>1/12</sup> ≈ 1,0595. Число полутонов между нотами 12 log<sub>2</sub>(f₂/f₁). <b>Инженерия.</b> В цепочке усилителей децибелы складываются, потому что коэффициенты усиления перемножаются, — это тоже log(bc) = log b + log c.', '<b>Music.</b> On a piano each octave doubles the frequency and is split into 12 semitones; each semitone multiplies the frequency by 2<sup>1/12</sup> ≈ 1.0595. The number of semitones between notes is 12 log<sub>2</sub>(f₂/f₁). <b>Engineering.</b> In a chain of amplifiers decibels add, because gains multiply — again log(bc) = log b + log c.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Neper o‘z jadvallarini tuzish uchun taxminan 10 million arifmetik amal bajargan va bu ishga 20 yil sarflagan.', 'Для составления своих таблиц Непер выполнил около 10 миллионов арифметических действий и потратил на это 20 лет.', 'Napier performed roughly 10 million arithmetic operations and spent 20 years building his tables.'),
      L('lg 2 ≈ 0,30103 ni bilsangiz, 2<sup>10</sup> = 1024 ≈ 10³ ekanini tushuntirasiz: 10 · 0,30103 ≈ 3,01.', 'Зная lg 2 ≈ 0,30103, можно объяснить, почему 2<sup>10</sup> = 1024 ≈ 10³: 10 · 0,30103 ≈ 3,01.', 'Knowing lg 2 ≈ 0.30103 explains why 2<sup>10</sup> = 1024 ≈ 10³: 10 · 0.30103 ≈ 3.01.'),
      L('Benford qonuni: real ma’lumotlarda (aholi soni, narxlar) 1 raqami bilan boshlanadigan sonlar ulushi lg 2 ≈ 30%, 9 bilan boshlanadiganlar esa lg(10/9) ≈ 4,6%. Soliq inspektorlari bu qonun bilan soxta hisobotlarni aniqlaydi.', 'Закон Бенфорда: в реальных данных (население, цены) доля чисел, начинающихся с 1, равна lg 2 ≈ 30%, а с 9 — лишь lg(10/9) ≈ 4,6%. Налоговые инспекторы по этому закону выявляют поддельные отчёты.', 'Benford’s law: in real data (populations, prices) the share of numbers starting with 1 is lg 2 ≈ 30%, while those starting with 9 make up only lg(10/9) ≈ 4.6%. Tax inspectors use it to spot fake reports.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('log<sub>12</sub>3 + log<sub>12</sub>4', 'log<sub>12</sub>3 + log<sub>12</sub>4', 'log<sub>12</sub>3 + log<sub>12</sub>4'), s: L('log<sub>12</sub>12 = 1.', 'log<sub>12</sub>12 = 1.', 'log<sub>12</sub>12 = 1.') },
      { q: L('log<sub>5</sub>2 · log<sub>2</sub>125', 'log<sub>5</sub>2 · log<sub>2</sub>125', 'log<sub>5</sub>2 · log<sub>2</sub>125'), s: L('log<sub>5</sub>125 = 3 (zanjir qisqaradi).', 'log<sub>5</sub>125 = 3 (цепочка сокращается).', 'log<sub>5</sub>125 = 3 (the chain cancels).') },
      { q: L('3 lg 2 + lg 12,5', '3 lg 2 + lg 12,5', '3 lg 2 + lg 12.5'), s: L('lg(8 · 12,5) = lg 100 = 2.', 'lg(8 · 12,5) = lg 100 = 2.', 'lg(8 · 12.5) = lg 100 = 2.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('log<sub>a</sub>(bc) = log<sub>a</sub>b + log<sub>a</sub>c; log<sub>a</sub>(b/c) = log<sub>a</sub>b − log<sub>a</sub>c.', 'log<sub>a</sub>(bc) = log<sub>a</sub>b + log<sub>a</sub>c; log<sub>a</sub>(b/c) = log<sub>a</sub>b − log<sub>a</sub>c.', 'log<sub>a</sub>(bc) = log<sub>a</sub>b + log<sub>a</sub>c; log<sub>a</sub>(b/c) = log<sub>a</sub>b − log<sub>a</sub>c.'),
      L('log<sub>a</sub>b<sup>n</sup> = n log<sub>a</sub>b; log<sub>a<sup>k</sup></sub>b = (1/k) log<sub>a</sub>b.', 'log<sub>a</sub>b<sup>n</sup> = n log<sub>a</sub>b; log<sub>a<sup>k</sup></sub>b = (1/k) log<sub>a</sub>b.', 'log<sub>a</sub>b<sup>n</sup> = n log<sub>a</sub>b; log<sub>a<sup>k</sup></sub>b = (1/k) log<sub>a</sub>b.'),
      L('log<sub>a</sub>b = log<sub>c</sub>b / log<sub>c</sub>a; log<sub>a</sub>b · log<sub>b</sub>a = 1.', 'log<sub>a</sub>b = log<sub>c</sub>b / log<sub>c</sub>a; log<sub>a</sub>b · log<sub>b</sub>a = 1.', 'log<sub>a</sub>b = log<sub>c</sub>b / log<sub>c</sub>a; log<sub>a</sub>b · log<sub>b</sub>a = 1.'),
      L('Barcha xossalar daraja xossalaridan va logarifm ta’rifidan kelib chiqadi.', 'Все свойства следуют из свойств степеней и определения логарифма.', 'All laws follow from the laws of powers and the definition of the logarithm.'),
      L('Yig‘indining logarifmi uchun formula yo‘q!', 'Формулы для логарифма суммы нет!', 'There is no formula for the log of a sum!'),
      L('Logarifmik chizg‘ich ko‘paytirishni kesmalarni qo‘shishga aylantirgan.', 'Логарифмическая линейка превращала умножение в сложение отрезков.', 'The slide rule turned multiplication into adding lengths.')
    ] }
  ] });

  // ---------- t14. Logarifmik tenglama va tengsizliklar ----------
  T.add(P, 't14', { sections: [
    { kind: 'intro', h: L('Noma’lum logarifm ostida', 'Неизвестное под логарифмом', 'The unknown under the logarithm'), p: [
      L('Agar noma’lum logarifm belgisi ostida yoki uning asosida tursa, tenglama <b>logarifmik</b> deyiladi: log<sub>2</sub>(x − 1) = 3, lg x + lg(x − 9) = 1, log<sub>x</sub>16 = 2. Bunday tenglamalar ko‘rsatkichli tenglamalarning «egizagi»: biri ikkinchisiga logarifm ta’rifi orqali o‘tadi. Lekin logarifmik tenglamalarda bitta xavfli tuzoq bor — <b>aniqlanish sohasi</b>. Logarifm faqat musbat sonlar uchun mavjud, shuning uchun algebraik yo‘l bilan topilgan ildizlarning bir qismi «begona» bo‘lib chiqishi mumkin.', 'Если неизвестное стоит под знаком логарифма или в его основании, уравнение называется <b>логарифмическим</b>: log<sub>2</sub>(x − 1) = 3, lg x + lg(x − 9) = 1, log<sub>x</sub>16 = 2. Такие уравнения — «близнецы» показательных: одни переходят в другие через определение логарифма. Но в логарифмических уравнениях есть опасная ловушка — <b>область определения</b>. Логарифм существует только для положительных чисел, поэтому часть корней, найденных алгебраически, может оказаться «посторонней».', 'An equation is <b>logarithmic</b> if the unknown appears under a logarithm or in its base: log<sub>2</sub>(x − 1) = 3, lg x + lg(x − 9) = 1, log<sub>x</sub>16 = 2. Such equations are “twins” of exponential ones: one turns into the other through the definition of the logarithm. But logarithmic equations hide a dangerous trap — the <b>domain</b>. Logarithms exist only for positive numbers, so some roots found algebraically may turn out to be “extraneous”.'),
      L('Bu mavzuda logarifmik tenglama va tengsizliklarni yechishning asosiy usullarini o‘rganamiz va har doim aniqlanish sohasini (ADS) tekshirishni odat qilamiz.', 'В этой теме мы изучим основные методы решения логарифмических уравнений и неравенств и выработаем привычку всегда проверять область допустимых значений (ОДЗ).', 'In this topic we learn the main methods for logarithmic equations and inequalities and build the habit of always checking the domain.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), p: [
      L('Eng sodda logarifmik tenglama: log<sub>a</sub>x = c. Uning har qanday c uchun yagona yechimi bor: x = a<sup>c</sup>. Bu logarifm ta’rifining o‘zi. Umumiyroq: log<sub>a</sub>f(x) = c ⇔ f(x) = a<sup>c</sup> (bu holda f(x) = a<sup>c</sup> &gt; 0 avtomatik bajariladi).', 'Простейшее логарифмическое уравнение: log<sub>a</sub>x = c. При любом c оно имеет единственное решение x = a<sup>c</sup> — это и есть определение логарифма. В общем виде: log<sub>a</sub>f(x) = c ⇔ f(x) = a<sup>c</sup> (условие f(x) = a<sup>c</sup> &gt; 0 выполняется автоматически).', 'The simplest logarithmic equation is log<sub>a</sub>x = c. For every c it has the unique solution x = a<sup>c</sup> — this is just the definition of the logarithm. More generally, log<sub>a</sub>f(x) = c ⇔ f(x) = a<sup>c</sup> (and f(x) = a<sup>c</sup> &gt; 0 holds automatically).'),
      L('<b>Teorema.</b> log<sub>a</sub>f(x) = log<sub>a</sub>g(x) tenglama quyidagi sistemaga teng kuchli: f(x) = g(x), f(x) &gt; 0 (g(x) &gt; 0 ham bo‘lishi kerak, lekin f = g bo‘lgani uchun bittasini tekshirish yetarli). <i>Sababi:</i> logarifmik funksiya monoton, shuning uchun teng logarifmlar teng argumentlardan kelib chiqadi.', '<b>Теорема.</b> Уравнение log<sub>a</sub>f(x) = log<sub>a</sub>g(x) равносильно системе: f(x) = g(x), f(x) &gt; 0 (g(x) &gt; 0 тоже нужно, но при f = g достаточно проверить одно). <i>Причина:</i> логарифмическая функция монотонна, поэтому равные логарифмы бывают только у равных аргументов.', '<b>Theorem.</b> The equation log<sub>a</sub>f(x) = log<sub>a</sub>g(x) is equivalent to the system f(x) = g(x), f(x) &gt; 0 (g(x) &gt; 0 is also needed, but since f = g, checking one suffices). <i>Reason:</i> the logarithmic function is monotonic, so equal logarithms come only from equal arguments.')
    ], list: [
      L('<b>ADS (aniqlanish sohasi):</b> barcha logarifm ostidagi ifodalar &gt; 0; asos &gt; 0 va ≠ 1.', '<b>ОДЗ:</b> все выражения под логарифмами &gt; 0; основание &gt; 0 и ≠ 1.', '<b>Domain:</b> every argument of a logarithm &gt; 0; every base &gt; 0 and ≠ 1.'),
      L('<b>Begona ildiz</b> — almashtirishlar natijasida paydo bo‘lgan, lekin dastlabki tenglamani qanoatlantirmaydigan son.', '<b>Посторонний корень</b> — число, появившееся при преобразованиях, но не удовлетворяющее исходному уравнению.', 'An <b>extraneous root</b> is a number produced by the transformations that does not satisfy the original equation.')
    ] },
    { kind: 'history', h: L('Tarixdan: logarifm va tenglamalar', 'Из истории: логарифмы и уравнения', 'History: logarithms and equations'), p: [
      L('Neper va Brigs davrida logarifmlar asosan hisoblash vositasi edi. Logarifmni funksiya sifatida qarash va tenglamalarda ishlatish XVII asr o‘rtasida boshlandi. 1647-yilda belgiyalik Grigoriy Sen-Vensan giperbola ostidagi yuz logarifm kabi o‘sishini ko‘rsatdi, 1668-yilda Nikolaus Merkator «natural logarifm» atamasini kiritdi. Eyler 1748-yilgi «Cheksiz kichiklar analiziga kirish» kitobida logarifmni ko‘rsatkichli funksiyaga teskari funksiya sifatida ta’rifladi — biz bugun ham aynan shu ta’rifdan foydalanamiz.', 'Во времена Непера и Бриггса логарифмы были прежде всего средством вычислений. Рассматривать логарифм как функцию и применять его в уравнениях начали в середине XVII века. В 1647 году бельгиец Грегуар де Сен-Венсан показал, что площадь под гиперболой растёт как логарифм, в 1668 году Николаус Меркатор ввёл термин «натуральный логарифм». Эйлер в книге «Введение в анализ бесконечно малых» (1748) определил логарифм как функцию, обратную показательной, — этим определением мы пользуемся и сегодня.', 'In Napier’s and Briggs’ time logarithms were mainly a computing tool. Treating the logarithm as a function and using it in equations began in the mid-17th century. In 1647 the Belgian Grégoire de Saint-Vincent showed that the area under a hyperbola grows like a logarithm, and in 1668 Nicholas Mercator coined the term “natural logarithm”. In his 1748 “Introduction to the Analysis of the Infinite” Euler defined the logarithm as the inverse of the exponential function — the definition we still use today.')
    ] },
    { kind: 'rule', h: L('Yechish usullari', 'Методы решения', 'Solving methods'), list: [
      L('<b>Ta’rif bo‘yicha:</b> log<sub>3</sub>(2x + 1) = 2 ⇒ 2x + 1 = 9 ⇒ x = 4.', '<b>По определению:</b> log<sub>3</sub>(2x + 1) = 2 ⇒ 2x + 1 = 9 ⇒ x = 4.', '<b>By definition:</b> log<sub>3</sub>(2x + 1) = 2 ⇒ 2x + 1 = 9 ⇒ x = 4.'),
      L('<b>Potensirlash</b> (logarifmlarni tashlab yuborish): log<sub>a</sub>f = log<sub>a</sub>g ⇒ f = g, so‘ng ADS ni tekshirish.', '<b>Потенцирование</b> (снятие логарифмов): log<sub>a</sub>f = log<sub>a</sub>g ⇒ f = g, затем проверка ОДЗ.', '<b>Removing logarithms:</b> log<sub>a</sub>f = log<sub>a</sub>g ⇒ f = g, then check the domain.'),
      L('<b>Xossalar yordamida birlashtirish:</b> log<sub>a</sub>f + log<sub>a</sub>g = log<sub>a</sub>(fg) — lekin buni faqat f &gt; 0, g &gt; 0 da qilish mumkin.', '<b>Объединение по свойствам:</b> log<sub>a</sub>f + log<sub>a</sub>g = log<sub>a</sub>(fg) — но только при f &gt; 0, g &gt; 0.', '<b>Combining with the laws:</b> log<sub>a</sub>f + log<sub>a</sub>g = log<sub>a</sub>(fg) — but only when f &gt; 0 and g &gt; 0.'),
      L('<b>Yangi o‘zgaruvchi:</b> lg²x − 3 lg x + 2 = 0 da t = lg x (t istalgan son bo‘lishi mumkin).', '<b>Новая переменная:</b> в lg²x − 3 lg x + 2 = 0 положить t = lg x (t может быть любым).', '<b>New variable:</b> in lg²x − 3 lg x + 2 = 0 put t = lg x (t can be any number).'),
      L('<b>Tengsizliklar:</b> a &gt; 1 da log<sub>a</sub>f &gt; log<sub>a</sub>g ⇔ f &gt; g &gt; 0; 0 &lt; a &lt; 1 da ⇔ 0 &lt; f &lt; g.', '<b>Неравенства:</b> при a &gt; 1 log<sub>a</sub>f &gt; log<sub>a</sub>g ⇔ f &gt; g &gt; 0; при 0 &lt; a &lt; 1 ⇔ 0 &lt; f &lt; g.', '<b>Inequalities:</b> for a &gt; 1, log<sub>a</sub>f &gt; log<sub>a</sub>g ⇔ f &gt; g &gt; 0; for 0 &lt; a &lt; 1, ⇔ 0 &lt; f &lt; g.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: tenglamalar', 'Решённые примеры: уравнения', 'Worked examples: equations'), ex: [
      { q: L('lg x + lg(x − 9) = 1 tenglamani yeching.', 'Решите уравнение lg x + lg(x − 9) = 1.', 'Solve lg x + lg(x − 9) = 1.'), s: L('ADS: x &gt; 0 va x &gt; 9, ya’ni x &gt; 9. Birlashtiramiz: lg(x(x − 9)) = 1 ⇒ x² − 9x = 10 ⇒ x² − 9x − 10 = 0 ⇒ x = 10 yoki x = −1. x = −1 ADS ga kirmaydi. Javob: x = 10.', 'ОДЗ: x &gt; 0 и x &gt; 9, то есть x &gt; 9. Объединяем: lg(x(x − 9)) = 1 ⇒ x² − 9x = 10 ⇒ x² − 9x − 10 = 0 ⇒ x = 10 или x = −1. x = −1 не входит в ОДЗ. Ответ: x = 10.', 'Domain: x &gt; 0 and x &gt; 9, so x &gt; 9. Combine: lg(x(x − 9)) = 1 ⇒ x² − 9x = 10 ⇒ x² − 9x − 10 = 0 ⇒ x = 10 or x = −1. x = −1 is outside the domain. Answer: x = 10.') },
      { q: L('log<sub>2</sub>(x² − 3x) = log<sub>2</sub>(x + 5) tenglamani yeching.', 'Решите уравнение log<sub>2</sub>(x² − 3x) = log<sub>2</sub>(x + 5).', 'Solve log<sub>2</sub>(x² − 3x) = log<sub>2</sub>(x + 5).'), s: L('x² − 3x = x + 5 ⇒ x² − 4x − 5 = 0 ⇒ x = 5 yoki x = −1. Tekshirish: x = 5 da x + 5 = 10 &gt; 0 ✓; x = −1 da x + 5 = 4 &gt; 0 ✓ va x² − 3x = 4 &gt; 0 ✓. Javob: −1; 5.', 'x² − 3x = x + 5 ⇒ x² − 4x − 5 = 0 ⇒ x = 5 или x = −1. Проверка: при x = 5 x + 5 = 10 &gt; 0 ✓; при x = −1 x + 5 = 4 &gt; 0 ✓ и x² − 3x = 4 &gt; 0 ✓. Ответ: −1; 5.', 'x² − 3x = x + 5 ⇒ x² − 4x − 5 = 0 ⇒ x = 5 or x = −1. Check: for x = 5, x + 5 = 10 &gt; 0 ✓; for x = −1, x + 5 = 4 &gt; 0 ✓ and x² − 3x = 4 &gt; 0 ✓. Answer: −1; 5.') },
      { q: L('log<sub>3</sub>²x − log<sub>3</sub>x − 2 = 0 tenglamani yeching.', 'Решите уравнение log<sub>3</sub>²x − log<sub>3</sub>x − 2 = 0.', 'Solve log<sub>3</sub>²x − log<sub>3</sub>x − 2 = 0.'), s: L('ADS: x &gt; 0. t = log<sub>3</sub>x: t² − t − 2 = 0 ⇒ t = 2 yoki t = −1. log<sub>3</sub>x = 2 ⇒ x = 9; log<sub>3</sub>x = −1 ⇒ x = 1/3. Javob: 1/3; 9.', 'ОДЗ: x &gt; 0. t = log<sub>3</sub>x: t² − t − 2 = 0 ⇒ t = 2 или t = −1. log<sub>3</sub>x = 2 ⇒ x = 9; log<sub>3</sub>x = −1 ⇒ x = 1/3. Ответ: 1/3; 9.', 'Domain: x &gt; 0. Let t = log<sub>3</sub>x: t² − t − 2 = 0 ⇒ t = 2 or t = −1. log<sub>3</sub>x = 2 ⇒ x = 9; log<sub>3</sub>x = −1 ⇒ x = 1/3. Answer: 1/3; 9.') },
      { q: L('log<sub>x</sub>(2x + 3) = 2 tenglamani yeching.', 'Решите уравнение log<sub>x</sub>(2x + 3) = 2.', 'Solve log<sub>x</sub>(2x + 3) = 2.'), s: L('ADS: x &gt; 0, x ≠ 1, 2x + 3 &gt; 0. Ta’rif: x² = 2x + 3 ⇒ x² − 2x − 3 = 0 ⇒ x = 3 yoki x = −1. Asos manfiy bo‘lmaydi, x = −1 tashlanadi. Javob: x = 3.', 'ОДЗ: x &gt; 0, x ≠ 1, 2x + 3 &gt; 0. По определению: x² = 2x + 3 ⇒ x² − 2x − 3 = 0 ⇒ x = 3 или x = −1. Основание не может быть отрицательным, x = −1 отбрасываем. Ответ: x = 3.', 'Domain: x &gt; 0, x ≠ 1, 2x + 3 &gt; 0. By definition x² = 2x + 3 ⇒ x² − 2x − 3 = 0 ⇒ x = 3 or x = −1. A base cannot be negative, so x = −1 is rejected. Answer: x = 3.') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: tengsizliklar', 'Решённые примеры: неравенства', 'Worked examples: inequalities'), ex: [
      { q: L('log<sub>2</sub>(x − 3) &lt; 2 tengsizlikni yeching.', 'Решите неравенство log<sub>2</sub>(x − 3) &lt; 2.', 'Solve log<sub>2</sub>(x − 3) &lt; 2.'), s: L('2 = log<sub>2</sub>4. Asos 2 &gt; 1: 0 &lt; x − 3 &lt; 4 ⇒ 3 &lt; x &lt; 7. Javob: (3; 7).', '2 = log<sub>2</sub>4. Основание 2 &gt; 1: 0 &lt; x − 3 &lt; 4 ⇒ 3 &lt; x &lt; 7. Ответ: (3; 7).', '2 = log<sub>2</sub>4. Base 2 &gt; 1: 0 &lt; x − 3 &lt; 4 ⇒ 3 &lt; x &lt; 7. Answer: (3; 7).') },
      { q: L('log<sub>1/3</sub>(2x − 1) ≥ −2 tengsizlikni yeching.', 'Решите неравенство log<sub>1/3</sub>(2x − 1) ≥ −2.', 'Solve log<sub>1/3</sub>(2x − 1) ≥ −2.'), s: L('−2 = log<sub>1/3</sub>9. Asos 1/3 &lt; 1, belgi almashadi: 0 &lt; 2x − 1 ≤ 9 ⇒ 1/2 &lt; x ≤ 5. Javob: (1/2; 5].', '−2 = log<sub>1/3</sub>9. Основание 1/3 &lt; 1, знак меняется: 0 &lt; 2x − 1 ≤ 9 ⇒ 1/2 &lt; x ≤ 5. Ответ: (1/2; 5].', '−2 = log<sub>1/3</sub>9. Base 1/3 &lt; 1, the sign flips: 0 &lt; 2x − 1 ≤ 9 ⇒ 1/2 &lt; x ≤ 5. Answer: (1/2; 5].') },
      { q: L('lg(x + 2) &gt; lg(8 − x) tengsizlikni yeching.', 'Решите неравенство lg(x + 2) &gt; lg(8 − x).', 'Solve lg(x + 2) &gt; lg(8 − x).'), s: L('Asos 10 &gt; 1: x + 2 &gt; 8 − x &gt; 0. Birinchisidan x &gt; 3, ikkinchisidan x &lt; 8. Javob: (3; 8).', 'Основание 10 &gt; 1: x + 2 &gt; 8 − x &gt; 0. Отсюда x &gt; 3 и x &lt; 8. Ответ: (3; 8).', 'Base 10 &gt; 1: x + 2 &gt; 8 − x &gt; 0, giving x &gt; 3 and x &lt; 8. Answer: (3; 8).') }
    ] },
    { kind: 'steps', h: L('Algoritm', 'Алгоритм', 'Algorithm'), list: [
      L('1. ADS ni yozing: logarifm ostidagi barcha ifodalar musbat, asoslar musbat va 1 dan farqli.', '1. Запишите ОДЗ: все выражения под логарифмами положительны, основания положительны и не равны 1.', '1. Write the domain: all arguments positive, all bases positive and different from 1.'),
      L('2. Xossalar yordamida tenglamani log<sub>a</sub>f = c yoki log<sub>a</sub>f = log<sub>a</sub>g ko‘rinishiga keltiring.', '2. С помощью свойств приведите уравнение к виду log<sub>a</sub>f = c или log<sub>a</sub>f = log<sub>a</sub>g.', '2. Use the laws to reach log<sub>a</sub>f = c or log<sub>a</sub>f = log<sub>a</sub>g.'),
      L('3. Logarifmlardan qutuling va algebraik tenglamani (tengsizlikni) yeching; tengsizlikda asosga qarab belgini tanlang.', '3. Избавьтесь от логарифмов и решите алгебраическое уравнение (неравенство); в неравенстве выберите знак по основанию.', '3. Remove the logarithms and solve the algebraic equation (inequality); for inequalities choose the sign by the base.'),
      L('4. Javobni ADS bilan kesishtiring yoki har bir ildizni tekshiring.', '4. Пересеките ответ с ОДЗ или проверьте каждый корень.', '4. Intersect the answer with the domain or check each root.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>ADS ni tekshirmaslik.</b> Eng ko‘p uchraydigan xato: lg x + lg(x − 9) = 1 ga x = −1 ni ham javob deb yozish.', '<b>Не проверять ОДЗ.</b> Самая частая ошибка: в lg x + lg(x − 9) = 1 записать в ответ и x = −1.', '<b>Not checking the domain.</b> The most common error: also giving x = −1 as an answer to lg x + lg(x − 9) = 1.'),
      L('<b>Tengsizlikda faqat bitta shartni yozish.</b> log<sub>2</sub>(x − 3) &lt; 2 ⇒ x &lt; 7 yetarli emas, x &gt; 3 ham kerak.', '<b>Записать в неравенстве только одно условие.</b> log<sub>2</sub>(x − 3) &lt; 2 ⇒ x &lt; 7 недостаточно, нужно ещё x &gt; 3.', '<b>Writing only one condition in an inequality.</b> log<sub>2</sub>(x − 3) &lt; 2 ⇒ x &lt; 7 is not enough; x &gt; 3 is also required.'),
      L('<b>Asos 1 dan kichik bo‘lganda belgini almashtirmaslik.</b> log<sub>0,5</sub>x &gt; 1 ⇒ 0 &lt; x &lt; 0,5, x &gt; 0,5 emas.', '<b>Не менять знак при основании меньше 1.</b> log<sub>0,5</sub>x &gt; 1 ⇒ 0 &lt; x &lt; 0,5, а не x &gt; 0,5.', '<b>Not flipping the sign for a base below 1.</b> log<sub>0.5</sub>x &gt; 1 ⇒ 0 &lt; x &lt; 0.5, not x &gt; 0.5.'),
      L('<b>2 lg x = lg x² almashtirishida ildiz yo‘qotish yoki qo‘shish.</b> lg x² = 2 lg |x|; ADS o‘zgaradi.', '<b>Терять или приобретать корни при замене 2 lg x = lg x².</b> lg x² = 2 lg |x|; ОДЗ меняется.', '<b>Losing or gaining roots when replacing 2 lg x by lg x².</b> lg x² = 2 lg |x|; the domain changes.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Kimyo.</b> Eritmaning pH = 3,5 ekanligi ma’lum bo‘lsa, vodorod ionlari konsentratsiyasi −lg[H⁺] = 3,5 tenglamadan topiladi: [H⁺] = 10<sup>−3,5</sup> ≈ 3,2 · 10<sup>−4</sup> mol/l. <b>Ekologiya.</b> Shovqin 85 dB dan oshmasligi kerak: 10 lg(I/I₀) ≤ 85 tengsizlik ruxsat etilgan intensivlikni beradi: I ≤ 10<sup>8,5</sup> I₀.', '<b>Химия.</b> Если pH раствора равен 3,5, концентрацию ионов водорода находят из уравнения −lg[H⁺] = 3,5: [H⁺] = 10<sup>−3,5</sup> ≈ 3,2 · 10<sup>−4</sup> моль/л. <b>Экология.</b> Шум не должен превышать 85 дБ: неравенство 10 lg(I/I₀) ≤ 85 даёт допустимую интенсивность I ≤ 10<sup>8,5</sup> I₀.', '<b>Chemistry.</b> If a solution has pH 3.5, the hydrogen-ion concentration comes from −lg[H⁺] = 3.5: [H⁺] = 10<sup>−3.5</sup> ≈ 3.2 · 10<sup>−4</sup> mol/l. <b>Ecology.</b> Noise must not exceed 85 dB: the inequality 10 lg(I/I₀) ≤ 85 gives the allowed intensity I ≤ 10<sup>8.5</sup> I₀.'),
      L('<b>Seysmologiya.</b> Ikki zilzila magnitudalari farqi M₁ − M₂ = lg(A₁/A₂). Agar biri 6,0, ikkinchisi 7,5 bo‘lsa, amplitudalar nisbati 10<sup>1,5</sup> ≈ 32, ya’ni kuchliroq zilzilada tebranish taxminan 32 marta katta. 1966-yilgi Toshkent zilzilasining magnitudasi taxminan 5,1 bo‘lgan, lekin markazi shahar ostida juda sayoz bo‘lgani uchun katta vayronagarchilik keltirgan.', '<b>Сейсмология.</b> Разность магнитуд двух землетрясений M₁ − M₂ = lg(A₁/A₂). Если одна 6,0, другая 7,5, отношение амплитуд 10<sup>1,5</sup> ≈ 32, то есть колебания при более сильном примерно в 32 раза больше. Ташкентское землетрясение 1966 года имело магнитуду около 5,1, но очаг был очень неглубоко под городом, поэтому разрушения были большими.', '<b>Seismology.</b> The difference of two magnitudes is M₁ − M₂ = lg(A₁/A₂). If one is 6.0 and the other 7.5, the amplitude ratio is 10<sup>1.5</sup> ≈ 32, so the stronger quake shakes about 32 times more. The 1966 Tashkent earthquake had a magnitude of about 5.1, but its focus was very shallow under the city, so the damage was great.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('log<sub>5</sub>(x + 3) = 2', 'log<sub>5</sub>(x + 3) = 2', 'log<sub>5</sub>(x + 3) = 2'), s: L('x + 3 = 25 ⇒ x = 22.', 'x + 3 = 25 ⇒ x = 22.', 'x + 3 = 25 ⇒ x = 22.') },
      { q: L('log<sub>3</sub>x &gt; 2', 'log<sub>3</sub>x &gt; 2', 'log<sub>3</sub>x &gt; 2'), s: L('x &gt; 9.', 'x &gt; 9.', 'x &gt; 9.') },
      { q: L('log<sub>2</sub>x + log<sub>2</sub>(x + 2) = 3', 'log<sub>2</sub>x + log<sub>2</sub>(x + 2) = 3', 'log<sub>2</sub>x + log<sub>2</sub>(x + 2) = 3'), s: L('x(x + 2) = 8 ⇒ x = 2 yoki −4; ADS bo‘yicha x = 2.', 'x(x + 2) = 8 ⇒ x = 2 или −4; по ОДЗ x = 2.', 'x(x + 2) = 8 ⇒ x = 2 or −4; by the domain x = 2.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('log<sub>a</sub>f(x) = c ⇔ f(x) = a<sup>c</sup>.', 'log<sub>a</sub>f(x) = c ⇔ f(x) = a<sup>c</sup>.', 'log<sub>a</sub>f(x) = c ⇔ f(x) = a<sup>c</sup>.'),
      L('log<sub>a</sub>f = log<sub>a</sub>g ⇔ f = g &gt; 0.', 'log<sub>a</sub>f = log<sub>a</sub>g ⇔ f = g &gt; 0.', 'log<sub>a</sub>f = log<sub>a</sub>g ⇔ f = g &gt; 0.'),
      L('Har doim ADS: argumentlar &gt; 0, asos &gt; 0 va ≠ 1.', 'Всегда ОДЗ: аргументы &gt; 0, основание &gt; 0 и ≠ 1.', 'Always the domain: arguments &gt; 0, base &gt; 0 and ≠ 1.'),
      L('Usullar: ta’rif, potensirlash, xossalar bilan birlashtirish, yangi o‘zgaruvchi.', 'Методы: определение, потенцирование, объединение по свойствам, новая переменная.', 'Methods: definition, removing logs, combining with the laws, new variable.'),
      L('Tengsizlik: a &gt; 1 — belgi saqlanadi, 0 &lt; a &lt; 1 — almashadi, ADS bilan birga.', 'Неравенство: a &gt; 1 — знак сохраняется, 0 &lt; a &lt; 1 — меняется, вместе с ОДЗ.', 'Inequality: a &gt; 1 keeps the sign, 0 &lt; a &lt; 1 flips it — together with the domain.'),
      L('Topilgan ildizlarni tekshirish — begona ildizlardan himoya.', 'Проверка найденных корней — защита от посторонних корней.', 'Checking the roots protects against extraneous ones.')
    ] }
  ] });

  // ---------- t15. Ko‘rsatkichli va logarifmik funksiyalarning tatbiqi ----------
  T.add(P, 't15', { sections: [
    { kind: 'intro', h: L('O‘sish va kamayish qonunlari', 'Законы роста и убывания', 'Laws of growth and decay'), p: [
      L('Ko‘p jarayonlarda o‘zgarish tezligi kattalikning o‘ziga proporsional bo‘ladi: pul qancha ko‘p bo‘lsa, foiz shuncha ko‘p qo‘shiladi; bakteriya qancha ko‘p bo‘lsa, shuncha tez ko‘payadi; radioaktiv modda qancha ko‘p bo‘lsa, shuncha ko‘p atom parchalanadi. Bunday jarayonlarning barchasi bitta formula bilan tasvirlanadi: <b>N(t) = N₀ · a<sup>t</sup></b> yoki <b>N(t) = N₀ · e<sup>kt</sup></b>. a &gt; 1 bo‘lsa — eksponensial o‘sish, 0 &lt; a &lt; 1 bo‘lsa — eksponensial kamayish.', 'Во многих процессах скорость изменения пропорциональна самой величине: чем больше денег, тем больше начисляется процентов; чем больше бактерий, тем быстрее они размножаются; чем больше радиоактивного вещества, тем больше атомов распадается. Все такие процессы описываются одной формулой: <b>N(t) = N₀ · a<sup>t</sup></b> или <b>N(t) = N₀ · e<sup>kt</sup></b>. При a &gt; 1 — экспоненциальный рост, при 0 &lt; a &lt; 1 — экспоненциальное убывание.', 'In many processes the rate of change is proportional to the quantity itself: the more money, the more interest is added; the more bacteria, the faster they multiply; the more radioactive material, the more atoms decay. All such processes are described by one formula: <b>N(t) = N₀ · a<sup>t</sup></b> or <b>N(t) = N₀ · e<sup>kt</sup></b>. For a &gt; 1 it is exponential growth, for 0 &lt; a &lt; 1 exponential decay.'),
      L('Ko‘rsatkichli funksiya «qancha bo‘ladi?» savoliga javob beradi, logarifm esa «qachon bo‘ladi?» savoliga. Bu mavzuda murakkab foiz, aholi o‘sishi, radioaktiv parchalanish, sovish qonuni va logarifmik shkalalar (pH, desibel, Rixter) bilan bog‘liq masalalarni yechamiz.', 'Показательная функция отвечает на вопрос «сколько будет?», а логарифм — на вопрос «когда будет?». В этой теме мы решим задачи о сложных процентах, росте населения, радиоактивном распаде, законе остывания и логарифмических шкалах (pH, децибелы, Рихтер).', 'The exponential function answers “how much will there be?” and the logarithm answers “when?”. In this topic we solve problems on compound interest, population growth, radioactive decay, the cooling law and logarithmic scales (pH, decibels, Richter).')
    ] },
    { kind: 'def', h: L('Asosiy modellar', 'Основные модели', 'Main models'), list: [
      L('<b>Murakkab foiz:</b> S = S₀(1 + p/100)<sup>n</sup>, S₀ — boshlang‘ich summa, p — yillik foiz, n — yillar soni.', '<b>Сложные проценты:</b> S = S₀(1 + p/100)<sup>n</sup>, S₀ — начальная сумма, p — годовой процент, n — число лет.', '<b>Compound interest:</b> S = S₀(1 + p/100)<sup>n</sup>, S₀ the initial sum, p the annual rate, n the number of years.'),
      L('<b>Radioaktiv parchalanish:</b> m(t) = m₀ · (1/2)<sup>t/T</sup>, T — yarim yemirilish davri (moddaning yarmi parchalanadigan vaqt).', '<b>Радиоактивный распад:</b> m(t) = m₀ · (1/2)<sup>t/T</sup>, T — период полураспада (время, за которое распадается половина вещества).', '<b>Radioactive decay:</b> m(t) = m₀ · (1/2)<sup>t/T</sup>, T the half-life (time for half of the substance to decay).'),
      L('<b>Aholi o‘sishi:</b> N(t) = N₀ · (1 + r)<sup>t</sup>, r — yillik o‘sish ulushi.', '<b>Рост населения:</b> N(t) = N₀ · (1 + r)<sup>t</sup>, r — годовая доля прироста.', '<b>Population growth:</b> N(t) = N₀ · (1 + r)<sup>t</sup>, r the annual growth fraction.'),
      L('<b>Nyutonning sovish qonuni:</b> T(t) = T<sub>m</sub> + (T₀ − T<sub>m</sub>) · e<sup>−kt</sup>, T<sub>m</sub> — muhit harorati.', '<b>Закон остывания Ньютона:</b> T(t) = T<sub>m</sub> + (T₀ − T<sub>m</sub>) · e<sup>−kt</sup>, T<sub>m</sub> — температура среды.', '<b>Newton’s law of cooling:</b> T(t) = T<sub>m</sub> + (T₀ − T<sub>m</sub>) · e<sup>−kt</sup>, T<sub>m</sub> the surrounding temperature.'),
      L('<b>Logarifmik shkalalar:</b> pH = −lg[H⁺]; L = 10 lg(I/I₀) dB; M = lg(A/A₀) (Rixter).', '<b>Логарифмические шкалы:</b> pH = −lg[H⁺]; L = 10 lg(I/I₀) дБ; M = lg(A/A₀) (Рихтер).', '<b>Logarithmic scales:</b> pH = −lg[H⁺]; L = 10 lg(I/I₀) dB; M = lg(A/A₀) (Richter).')
    ] },
    { kind: 'history', h: L('Tarixdan: Bernulli, Rezerford va Libbi', 'Из истории: Бернулли, Резерфорд и Либби', 'History: Bernoulli, Rutherford and Libby'), p: [
      L('1683-yilda <b>Yakob Bernulli</b> murakkab foiz haqidagi masalani o‘rgandi: agar 100% yillik foiz yiliga n marta qo‘shilsa, summa (1 + 1/n)<sup>n</sup> marta oshadi. n cheksiz o‘sganda bu son taxminan 2,71828 ga yaqinlashadi — keyinchalik Eyler uni <b>e</b> deb belgiladi. Shunday qilib, natural logarifm asosi bank masalasidan tug‘ilgan.', 'В 1683 году <b>Якоб Бернулли</b> исследовал задачу о сложных процентах: если 100% годовых начислять n раз в год, сумма вырастет в (1 + 1/n)<sup>n</sup> раз. При неограниченном росте n это число приближается к 2,71828 — позже Эйлер обозначил его <b>e</b>. Так основание натурального логарифма родилось из банковской задачи.', 'In 1683 <b>Jacob Bernoulli</b> studied compound interest: if 100% annual interest is added n times a year, the sum grows by a factor (1 + 1/n)<sup>n</sup>. As n grows without bound this approaches 2.71828 — Euler later called it <b>e</b>. So the base of the natural logarithm was born from a banking problem.'),
      L('1902-yilda <b>Ernest Rezerford</b> va Frederik Soddi radioaktiv parchalanish eksponensial qonunga bo‘ysunishini aniqladi va «yarim yemirilish davri» tushunchasini kiritdi. 1949-yilda amerikalik kimyogar <b>Uillard Libbi</b> shu qonun asosida radiouglerod usulini yaratdi: uglerod-14 ning yarim yemirilish davri taxminan 5730 yil. Bu kashfiyot uchun u 1960-yilda Nobel mukofotini oldi.', 'В 1902 году <b>Эрнест Резерфорд</b> и Фредерик Содди установили, что радиоактивный распад подчиняется экспоненциальному закону, и ввели понятие «период полураспада». В 1949 году американский химик <b>Уиллард Либби</b> создал на основе этого закона радиоуглеродный метод: период полураспада углерода-14 около 5730 лет. За это открытие он получил Нобелевскую премию в 1960 году.', 'In 1902 <b>Ernest Rutherford</b> and Frederick Soddy found that radioactive decay follows an exponential law and introduced the idea of “half-life”. In 1949 the American chemist <b>Willard Libby</b> used this law to create radiocarbon dating: carbon-14 has a half-life of about 5730 years. He received the Nobel Prize for it in 1960.')
    ] },
    { kind: 'rule', h: L('«Qachon?» savoliga javob: logarifm', 'Ответ на «когда?»: логарифм', 'Answering “when?”: the logarithm'), p: [
      L('Agar N₀ · a<sup>t</sup> = N bo‘lsa, noma’lum t ko‘rsatkichda turadi. Ikki tomonni logarifmlaymiz: t · lg a = lg(N/N₀), ya’ni <b>t = lg(N/N₀) / lg a</b>. Bu formula hamma «qachon?» masalalarining kaliti.', 'Если N₀ · a<sup>t</sup> = N, неизвестное t стоит в показателе. Логарифмируем обе части: t · lg a = lg(N/N₀), то есть <b>t = lg(N/N₀) / lg a</b>. Эта формула — ключ ко всем задачам «когда?».', 'If N₀ · a<sup>t</sup> = N, the unknown t is in the exponent. Taking logarithms of both sides gives t · lg a = lg(N/N₀), i.e. <b>t = lg(N/N₀) / lg a</b>. This formula is the key to all “when?” problems.'),
      L('<b>Ikki baravar oshish vaqti.</b> Har yili p% o‘sishda kattalik t = lg 2 / lg(1 + p/100) yilda ikki baravar oshadi. Kichik p uchun taqribiy <b>«72 qoidasi»</b> bor: t ≈ 72 / p. Masalan, yiliga 8% da taxminan 9 yil, 12% da taxminan 6 yil. Aniq hisob: lg 2 / lg 1,08 ≈ 0,301 / 0,0334 ≈ 9,0.', '<b>Время удвоения.</b> При росте на p% в год величина удваивается за t = lg 2 / lg(1 + p/100) лет. Для малых p есть приближённое <b>«правило 72»</b>: t ≈ 72 / p. Например, при 8% годовых — примерно 9 лет, при 12% — около 6 лет. Точный расчёт: lg 2 / lg 1,08 ≈ 0,301 / 0,0334 ≈ 9,0.', '<b>Doubling time.</b> With p% growth per year a quantity doubles in t = lg 2 / lg(1 + p/100) years. For small p there is the approximate <b>“rule of 72”</b>: t ≈ 72 / p. For example 8% a year gives about 9 years and 12% about 6. Exact: lg 2 / lg 1.08 ≈ 0.301 / 0.0334 ≈ 9.0.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: o‘sish', 'Решённые примеры: рост', 'Worked examples: growth'), ex: [
      { q: L('Bankka 5 000 000 so‘m yillik 20% murakkab foiz bilan qo‘yildi. 3 yildan keyin qancha bo‘ladi?', 'В банк положили 5 000 000 сумов под 20% годовых (сложные проценты). Сколько будет через 3 года?', '5 000 000 sum is deposited at 20% compound interest a year. How much after 3 years?'), s: L('S = 5 000 000 · 1,2³ = 5 000 000 · 1,728 = 8 640 000 so‘m. Oddiy foizda esa 5 000 000 · (1 + 3 · 0,2) = 8 000 000 bo‘lardi — farq 640 000 so‘m «foizning foizi».', 'S = 5 000 000 · 1,2³ = 5 000 000 · 1,728 = 8 640 000 сумов. При простых процентах было бы 5 000 000 · (1 + 3 · 0,2) = 8 000 000 — разница 640 000 сумов — это «проценты на проценты».', 'S = 5 000 000 · 1.2³ = 5 000 000 · 1.728 = 8 640 000 sum. With simple interest it would be 5 000 000 · (1 + 3 · 0.2) = 8 000 000 — the 640 000 difference is “interest on interest”.') },
      { q: L('Shahar aholisi har yili 2% o‘sadi. Necha yilda ikki baravar oshadi?', 'Население города растёт на 2% в год. За сколько лет оно удвоится?', 'A city’s population grows 2% a year. When will it double?'), s: L('1,02<sup>t</sup> = 2 ⇒ t = lg 2 / lg 1,02 ≈ 0,3010 / 0,0086 ≈ 35 yil. «72 qoidasi»: 72 / 2 = 36 — juda yaqin.', '1,02<sup>t</sup> = 2 ⇒ t = lg 2 / lg 1,02 ≈ 0,3010 / 0,0086 ≈ 35 лет. «Правило 72»: 72 / 2 = 36 — очень близко.', '1.02<sup>t</sup> = 2 ⇒ t = lg 2 / lg 1.02 ≈ 0.3010 / 0.0086 ≈ 35 years. The rule of 72 gives 72 / 2 = 36 — very close.') },
      { q: L('Bakteriyalar soni har 30 daqiqada ikki baravar oshadi. 500 ta bakteriyadan necha soatda 64 000 ta bo‘ladi?', 'Число бактерий удваивается каждые 30 минут. За сколько часов из 500 станет 64 000?', 'Bacteria double every 30 minutes. How many hours until 500 become 64 000?'), s: L('500 · 2<sup>n</sup> = 64 000 ⇒ 2<sup>n</sup> = 128 = 2⁷ ⇒ n = 7 ta ikki baravarlanish = 7 · 30 = 210 daqiqa = 3,5 soat.', '500 · 2<sup>n</sup> = 64 000 ⇒ 2<sup>n</sup> = 128 = 2⁷ ⇒ n = 7 удвоений = 7 · 30 = 210 минут = 3,5 часа.', '500 · 2<sup>n</sup> = 64 000 ⇒ 2<sup>n</sup> = 128 = 2⁷ ⇒ n = 7 doublings = 7 · 30 = 210 minutes = 3.5 hours.') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: kamayish va shkalalar', 'Решённые примеры: убывание и шкалы', 'Worked examples: decay and scales'), ex: [
      { q: L('Yod-131 ning yarim yemirilish davri 8 kun. 200 mg dan 24 kundan keyin qancha qoladi?', 'Период полураспада йода-131 — 8 дней. Сколько останется из 200 мг через 24 дня?', 'Iodine-131 has a half-life of 8 days. How much of 200 mg remains after 24 days?'), s: L('24 / 8 = 3 ta davr. m = 200 · (1/2)³ = 200 / 8 = 25 mg.', '24 / 8 = 3 периода. m = 200 · (1/2)³ = 200 / 8 = 25 мг.', '24 / 8 = 3 half-lives. m = 200 · (1/2)³ = 200 / 8 = 25 mg.') },
      { q: L('Qadimgi yog‘och buyumda uglerod-14 ning tirik daraxtdagiga nisbatan 25% i qolgan. Buyum necha yoshda? (T = 5730 yil)', 'В древнем деревянном предмете осталось 25% углерода-14 по сравнению с живым деревом. Сколько лет предмету? (T = 5730 лет)', 'An ancient wooden object retains 25% of the carbon-14 of living wood. How old is it? (T = 5730 years)'), s: L('(1/2)<sup>t/5730</sup> = 1/4 = (1/2)² ⇒ t/5730 = 2 ⇒ t = 11 460 yil.', '(1/2)<sup>t/5730</sup> = 1/4 = (1/2)² ⇒ t/5730 = 2 ⇒ t = 11 460 лет.', '(1/2)<sup>t/5730</sup> = 1/4 = (1/2)² ⇒ t/5730 = 2 ⇒ t = 11 460 years.') },
      { q: L('Avtomobil yiliga 15% arzonlashadi. 200 mln so‘mlik mashina necha yilda 100 mln so‘mdan arzon bo‘ladi?', 'Автомобиль дешевеет на 15% в год. Через сколько лет машина за 200 млн сумов станет дешевле 100 млн?', 'A car loses 15% of its value each year. After how many years does a 200 million sum car fall below 100 million?'), s: L('200 · 0,85<sup>n</sup> &lt; 100 ⇒ 0,85<sup>n</sup> &lt; 0,5. lg 0,85 &lt; 0 bo‘lgani uchun belgi almashadi: n &gt; lg 0,5 / lg 0,85 ≈ (−0,301)/(−0,0706) ≈ 4,27. Javob: 5 yildan keyin.', '200 · 0,85<sup>n</sup> &lt; 100 ⇒ 0,85<sup>n</sup> &lt; 0,5. Так как lg 0,85 &lt; 0, знак меняется: n &gt; lg 0,5 / lg 0,85 ≈ (−0,301)/(−0,0706) ≈ 4,27. Ответ: через 5 лет.', '200 · 0.85<sup>n</sup> &lt; 100 ⇒ 0.85<sup>n</sup> &lt; 0.5. Since lg 0.85 &lt; 0 the sign flips: n &gt; lg 0.5 / lg 0.85 ≈ (−0.301)/(−0.0706) ≈ 4.27. Answer: after 5 years.') },
      { q: L('Qahva pH = 5, sovun eritmasi pH = 9. Qahvada vodorod ionlari necha marta ko‘p?', 'pH кофе = 5, мыльного раствора = 9. Во сколько раз в кофе больше ионов водорода?', 'Coffee has pH 5 and soapy water pH 9. How many times more hydrogen ions are in coffee?'), s: L('[H⁺] = 10<sup>−pH</sup>. 10<sup>−5</sup> / 10<sup>−9</sup> = 10⁴ = 10 000 marta.', '[H⁺] = 10<sup>−pH</sup>. 10<sup>−5</sup> / 10<sup>−9</sup> = 10⁴ = 10 000 раз.', '[H⁺] = 10<sup>−pH</sup>. 10<sup>−5</sup> / 10<sup>−9</sup> = 10⁴ = 10 000 times.') }
    ] },
    { kind: 'table', h: L('Logarifmik shkalalar', 'Логарифмические шкалы', 'Logarithmic scales'), table: {
      head: [L('Shkala', 'Шкала', 'Scale'), L('Formula', 'Формула', 'Formula'), L('+1 birlik nimani bildiradi', 'Что значит +1 единица', 'What +1 unit means')],
      rows: [
        [L('pH (kislotalik)', 'pH (кислотность)', 'pH (acidity)'), L('pH = −lg[H⁺]', 'pH = −lg[H⁺]', 'pH = −lg[H⁺]'), L('ionlar 10 marta kam', 'ионов в 10 раз меньше', '10 times fewer ions')],
        [L('Desibel (tovush)', 'Децибел (звук)', 'Decibel (sound)'), L('L = 10 lg(I/I₀)', 'L = 10 lg(I/I₀)', 'L = 10 lg(I/I₀)'), L('+10 dB = intensivlik 10 marta', '+10 дБ = интенсивность в 10 раз', '+10 dB = 10 times the intensity')],
        [L('Rixter (zilzila)', 'Рихтер (землетрясение)', 'Richter (earthquake)'), L('M = lg(A/A₀)', 'M = lg(A/A₀)', 'M = lg(A/A₀)'), L('amplituda 10 marta', 'амплитуда в 10 раз', '10 times the amplitude')],
        [L('Yulduz kattaligi', 'Звёздная величина', 'Stellar magnitude'), L('m₁ − m₂ = −2,5 lg(E₁/E₂)', 'm₁ − m₂ = −2,5 lg(E₁/E₂)', 'm₁ − m₂ = −2.5 lg(E₁/E₂)'), L('yorug‘lik ≈ 2,5 marta kam', 'блеск ≈ в 2,5 раза слабее', 'about 2.5 times dimmer')]
      ] }, after: [
      L('Barcha shkalalarning g‘oyasi bir xil: juda katta diapazondagi kattalikni (milliard marta farq qiluvchi) qulay 0–14 yoki 0–10 oraliqqa siqish.', 'Идея всех шкал одна: сжать величину огромного диапазона (различающуюся в миллиарды раз) в удобный промежуток 0–14 или 0–10.', 'All these scales share one idea: squeeze a quantity with a huge range (differing by billions of times) into a convenient interval such as 0–14 or 0–10.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Murakkab foizni oddiy foiz kabi hisoblash.</b> 3 yilda 20% dan jami 60% emas, 72,8% o‘sish bo‘ladi.', '<b>Считать сложные проценты как простые.</b> За 3 года по 20% рост не 60%, а 72,8%.', '<b>Treating compound interest as simple interest.</b> 20% for 3 years gives 72.8% growth, not 60%.'),
      L('<b>Kamayishni noto‘g‘ri yozish.</b> 15% arzonlashish — 0,85 ga ko‘paytirish, 0,15 ga emas.', '<b>Неверно записывать убывание.</b> Подешевение на 15% — умножение на 0,85, а не на 0,15.', '<b>Writing decay wrongly.</b> A 15% drop means multiplying by 0.85, not by 0.15.'),
      L('<b>Manfiy logarifmga bo‘lganda tengsizlik belgisini almashtirmaslik.</b> lg 0,85 &lt; 0!', '<b>Не менять знак неравенства при делении на отрицательный логарифм.</b> lg 0,85 &lt; 0!', '<b>Not flipping the inequality when dividing by a negative logarithm.</b> lg 0.85 &lt; 0!'),
      L('<b>Logarifmik shkalani chiziqli deb o‘ylash.</b> 80 dB tovush 40 dB dan 2 marta emas, 10 000 marta intensivroq.', '<b>Считать логарифмическую шкалу линейной.</b> Звук 80 дБ интенсивнее 40 дБ не в 2, а в 10 000 раз.', '<b>Thinking a log scale is linear.</b> An 80 dB sound is not twice but 10 000 times as intense as 40 dB.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Kredit olishdan oldin</b> murakkab foiz formulasini bilish juda muhim: oyiga 3% ko‘rinishda kichik tuyuladi, lekin yiliga 1,03¹² ≈ 1,43, ya’ni 43% ga teng. <b>Kriminalistikada</b> sovish qonuni yordamida jasad harorati bo‘yicha o‘lim vaqti aniqlanadi. <b>Tibbiyotda</b> radioaktiv izotoplar (yod-131, texnetsiy-99m) yarim yemirilish davri bo‘yicha tanlanadi: diagnostika uchun tez parchalanadiganlari kerak.', '<b>Перед взятием кредита</b> очень важно знать формулу сложных процентов: 3% в месяц кажутся небольшими, но за год это 1,03¹² ≈ 1,43, то есть 43%. В <b>криминалистике</b> закон остывания позволяет определить время смерти по температуре тела. В <b>медицине</b> радиоактивные изотопы (йод-131, технеций-99m) выбирают по периоду полураспада: для диагностики нужны быстро распадающиеся.', '<b>Before taking a loan</b> it is vital to know the compound interest formula: 3% a month sounds small, but over a year it is 1.03¹² ≈ 1.43, i.e. 43%. In <b>forensics</b> the cooling law gives the time of death from body temperature. In <b>medicine</b> radioactive isotopes (iodine-131, technetium-99m) are chosen by half-life: diagnostics needs fast-decaying ones.'),
      L('<b>Epidemiologiyada</b> kasallik tarqalishining boshlang‘ich bosqichi eksponensial: har bir bemor o‘rtacha R kishini yuqtirsa, n bosqichdan keyin bemorlar soni R<sup>n</sup> ga ko‘payadi. Shuning uchun R ni 1 dan pastga tushirish (niqob, emlash) shunchalik muhim.', 'В <b>эпидемиологии</b> начальная стадия распространения болезни экспоненциальна: если каждый больной в среднем заражает R человек, через n этапов число больных умножается на R<sup>n</sup>. Поэтому так важно снизить R ниже 1 (маски, вакцинация).', 'In <b>epidemiology</b> the early spread of a disease is exponential: if each patient infects R people on average, after n stages the number of cases is multiplied by R<sup>n</sup>. That is why pushing R below 1 (masks, vaccination) matters so much.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Agar 1 so‘m yiliga 100% murakkab foiz bilan uzluksiz (har lahzada) o‘sib borsa, yil oxirida e ≈ 2,718 so‘m bo‘ladi — bundan ortiq emas.', 'Если 1 сум растёт под 100% годовых непрерывно (каждое мгновение), к концу года будет e ≈ 2,718 сума — и не больше.', 'If 1 sum grows at 100% a year compounded continuously (every instant), at the end of the year it becomes e ≈ 2.718 sum — and no more.'),
      L('Uran-238 ning yarim yemirilish davri taxminan 4,5 milliard yil — deyarli Yerning yoshiga teng. Shuning uchun u tog‘ jinslarining yoshini aniqlashda ishlatiladi.', 'Период полураспада урана-238 около 4,5 миллиарда лет — почти возраст Земли. Поэтому им определяют возраст горных пород.', 'Uranium-238 has a half-life of about 4.5 billion years — almost the age of the Earth — so it is used to date rocks.'),
      L('Inson qulog‘i eshitadigan eng past va eng baland (og‘riq chegarasi) tovush intensivliklari 10¹² marta farq qiladi, lekin desibel shkalasida bu atigi 0 dan 120 dB gacha.', 'Интенсивности самого тихого и самого громкого (порог боли) звука, которые слышит человек, различаются в 10¹² раз, но по шкале децибел это всего от 0 до 120 дБ.', 'The quietest and loudest (pain threshold) sounds we hear differ in intensity by a factor of 10¹², yet on the decibel scale this is only 0 to 120 dB.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('1 000 000 so‘m yiliga 10% dan 2 yilda qancha bo‘ladi?', 'Сколько станет 1 000 000 сумов под 10% за 2 года?', 'What does 1 000 000 sum become at 10% in 2 years?'), s: L('1 000 000 · 1,21 = 1 210 000 so‘m.', '1 000 000 · 1,21 = 1 210 000 сумов.', '1 000 000 · 1.21 = 1 210 000 sum.') },
      { q: L('T = 10 yil, m₀ = 80 g. 30 yildan keyin?', 'T = 10 лет, m₀ = 80 г. Через 30 лет?', 'T = 10 years, m₀ = 80 g. After 30 years?'), s: L('80 / 2³ = 10 g.', '80 / 2³ = 10 г.', '80 / 2³ = 10 g.') },
      { q: L('«72 qoidasi» bo‘yicha 6% da ikki baravar oshish vaqti?', 'Время удвоения при 6% по «правилу 72»?', 'Doubling time at 6% by the rule of 72?'), s: L('72 / 6 = 12 yil.', '72 / 6 = 12 лет.', '72 / 6 = 12 years.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Eksponensial model: N = N₀ · a<sup>t</sup>; a &gt; 1 — o‘sish, 0 &lt; a &lt; 1 — kamayish.', 'Экспоненциальная модель: N = N₀ · a<sup>t</sup>; a &gt; 1 — рост, 0 &lt; a &lt; 1 — убывание.', 'Exponential model: N = N₀ · a<sup>t</sup>; a &gt; 1 growth, 0 &lt; a &lt; 1 decay.'),
      L('Murakkab foiz: S = S₀(1 + p/100)<sup>n</sup>.', 'Сложные проценты: S = S₀(1 + p/100)<sup>n</sup>.', 'Compound interest: S = S₀(1 + p/100)<sup>n</sup>.'),
      L('Parchalanish: m = m₀ · (1/2)<sup>t/T</sup>.', 'Распад: m = m₀ · (1/2)<sup>t/T</sup>.', 'Decay: m = m₀ · (1/2)<sup>t/T</sup>.'),
      L('«Qachon?» — logarifm: t = lg(N/N₀) / lg a.', '«Когда?» — логарифм: t = lg(N/N₀) / lg a.', '“When?” — logarithm: t = lg(N/N₀) / lg a.'),
      L('«72 qoidasi»: ikki baravar oshish vaqti ≈ 72 / p.', '«Правило 72»: время удвоения ≈ 72 / p.', 'Rule of 72: doubling time ≈ 72 / p.'),
      L('pH, desibel, Rixter — logarifmik shkalalar.', 'pH, децибелы, Рихтер — логарифмические шкалы.', 'pH, decibels, Richter are logarithmic scales.')
    ] }
  ] });

  // ---------- t16. Trigonometrik funksiyalar va davriy jarayonlar ----------
  T.add(P, 't16', { sections: [
    { kind: 'intro', h: L('Takrorlanadigan dunyo', 'Повторяющийся мир', 'A world that repeats'), p: [
      L('Kun va tun almashinadi, fasllar qaytib keladi, yurak bir maromda uradi, soat mayatnigi u yoqdan-bu yoqqa tebranadi, rozetkadagi tok sekundiga 50 marta yo‘nalishini o‘zgartiradi. Bularning barchasi <b>davriy jarayonlar</b> — ma’lum vaqtdan keyin aynan takrorlanadigan hodisalar. Ularni tasvirlash uchun matematikada maxsus funksiyalar bor: <b>sinus</b> va <b>kosinus</b>. Ularning grafigi — to‘lqin, ya’ni <b>sinusoida</b>.', 'День сменяет ночь, возвращаются времена года, сердце бьётся в одном ритме, маятник часов качается туда-сюда, ток в розетке 50 раз в секунду меняет направление. Всё это <b>периодические процессы</b> — явления, которые точно повторяются через определённое время. Для их описания в математике есть особые функции: <b>синус</b> и <b>косинус</b>. Их график — волна, то есть <b>синусоида</b>.', 'Day follows night, seasons return, the heart beats steadily, a clock pendulum swings back and forth, and mains current changes direction 50 times a second. These are all <b>periodic processes</b> — events that repeat exactly after a fixed time. Mathematics has special functions to describe them: <b>sine</b> and <b>cosine</b>. Their graph is a wave, the <b>sinusoid</b>.'),
      L('9-sinfda sinus va kosinusni burchak uchun o‘rgangan edik. Endi ularni istalgan haqiqiy son (radianda o‘lchangan burchak) uchun aniqlaymiz, grafiklarini chizamiz, xossalarini — davriylik, juft-toqlik, monotonlik oraliqlari, eng katta va eng kichik qiymatlarni — o‘rganamiz va y = A sin(ωx + φ) garmonik tebranish formulasi bilan tanishamiz.', 'В 9 классе мы изучали синус и косинус угла. Теперь определим их для любого действительного числа (угла в радианах), построим графики, изучим свойства — периодичность, чётность, промежутки монотонности, наибольшие и наименьшие значения — и познакомимся с формулой гармонического колебания y = A sin(ωx + φ).', 'In grade 9 we studied sine and cosine of an angle. Now we define them for any real number (an angle in radians), draw their graphs, study their properties — periodicity, parity, intervals of monotonicity, maximum and minimum — and meet the harmonic oscillation formula y = A sin(ωx + φ).')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), p: [
      L('Birlik aylanada (markazi koordinata boshida, radiusi 1) (1; 0) nuqtani x radian burchakka burib, P<sub>x</sub> nuqtani olamiz. Uning abssissasi <b>cos x</b>, ordinatasi <b>sin x</b> deyiladi. Shunday qilib, har bir haqiqiy x ga yagona sin x va cos x mos keladi — bular <b>trigonometrik funksiyalar</b>. Shuningdek tg x = sin x / cos x (cos x ≠ 0) va ctg x = cos x / sin x (sin x ≠ 0).', 'На единичной окружности (центр в начале координат, радиус 1) повернём точку (1; 0) на угол x радиан и получим точку P<sub>x</sub>. Её абсцисса называется <b>cos x</b>, ордината — <b>sin x</b>. Так каждому действительному x соответствуют единственные sin x и cos x — это <b>тригонометрические функции</b>. Также tg x = sin x / cos x (cos x ≠ 0) и ctg x = cos x / sin x (sin x ≠ 0).', 'On the unit circle (centre at the origin, radius 1) rotate the point (1; 0) through x radians to get P<sub>x</sub>. Its x-coordinate is <b>cos x</b> and its y-coordinate is <b>sin x</b>. So every real x has a unique sin x and cos x — these are the <b>trigonometric functions</b>. Also tan x = sin x / cos x (cos x ≠ 0) and cot x = cos x / sin x (sin x ≠ 0).')
    ], list: [
      L('<b>Davriy funksiya:</b> shunday T ≠ 0 bor bo‘lsaki, barcha x uchun f(x + T) = f(x). Eng kichik musbat T — <b>asosiy davr</b>.', '<b>Периодическая функция:</b> существует T ≠ 0 такое, что f(x + T) = f(x) при всех x. Наименьшее положительное T — <b>основной период</b>.', '<b>Periodic function:</b> there is T ≠ 0 with f(x + T) = f(x) for all x. The smallest positive T is the <b>fundamental period</b>.'),
      L('sin va cos ning asosiy davri 2π, tg va ctg niki π.', 'Основной период sin и cos равен 2π, tg и ctg — π.', 'The period of sin and cos is 2π; of tan and cot, π.'),
      L('<b>Radian</b> — uzunligi radiusga teng yoyga tiralgan markaziy burchak: π rad = 180°, 1 rad ≈ 57,3°.', '<b>Радиан</b> — центральный угол, опирающийся на дугу длиной в радиус: π рад = 180°, 1 рад ≈ 57,3°.', 'A <b>radian</b> is the central angle subtending an arc equal to the radius: π rad = 180°, 1 rad ≈ 57.3°.')
    ] },
    { kind: 'history', h: L('Tarixdan: jayb, Beruniy va Eyler', 'Из истории: джайб, Беруни и Эйлер', 'History: jayb, al-Biruni and Euler'), p: [
      L('«Sinus» so‘zining tarixi qiziq. Hind matematiklari yarim vatarni «jiva» (kamon ipi) deb atashgan. Arab tarjimonlari uni «jiba» deb yozishgan, keyinchalik u «jayb» (qo‘yin, burma) deb o‘qilgan. XII asrda lotinchaga tarjima qilinganda «jayb» so‘zma-so‘z <i>sinus</i> (burma) bo‘lib qolgan. O‘rta Osiyo olimlari trigonometriyani mustaqil fan darajasiga ko‘tarishgan: <b>Abu Rayhon Beruniy</b> «Qonuni Mas’udiy» asarida sinuslar jadvalini tuzgan, <b>Mirzo Ulug‘bek</b> rasadxonasida 1° ning sinusi 16 xonali aniqlikda hisoblangan.', 'История слова «синус» любопытна. Индийские математики называли полухорду «джива» (тетива лука). Арабские переводчики записали его как «джиба», позже оно читалось как «джайб» (пазуха, складка). При переводе на латынь в XII веке «джайб» буквально стал <i>sinus</i> (складка). Учёные Средней Азии подняли тригонометрию до уровня самостоятельной науки: <b>Абу Рейхан Беруни</b> в «Каноне Масуда» составил таблицу синусов, а в обсерватории <b>Мирзо Улугбека</b> синус 1° вычислили с точностью до 16 знаков.', 'The word “sine” has a curious history. Indian mathematicians called the half-chord “jiva” (bowstring). Arabic translators wrote it as “jiba”, later read as “jayb” (fold, pocket). When translated into Latin in the 12th century, “jayb” literally became <i>sinus</i> (fold). Central Asian scholars made trigonometry a science of its own: <b>al-Biruni</b> compiled a table of sines in his “Mas’udi Canon”, and at <b>Ulugh Beg’s</b> observatory the sine of 1° was computed to 16 digits.'),
      L('Trigonometrik funksiyalarni burchak emas, balki son funksiyasi sifatida qarashni XVIII asrda <b>Leonard Eyler</b> boshlagan; u sin, cos belgilarini va birlik aylanadagi ta’rifni hozirgi ko‘rinishga keltirgan. «Radian» atamasi esa 1873-yilda Jeyms Tomson tomonidan kiritilgan.', 'Рассматривать тригонометрические функции как функции числа, а не угла, начал в XVIII веке <b>Леонард Эйлер</b>; он привёл обозначения sin, cos и определение через единичную окружность к современному виду. Термин «радиан» ввёл в 1873 году Джеймс Томсон.', 'Treating trigonometric functions as functions of a number rather than an angle began with <b>Leonhard Euler</b> in the 18th century; he gave the symbols sin, cos and the unit-circle definition their modern form. The term “radian” was introduced by James Thomson in 1873.')
    ] },
    { kind: 'table', h: L('Asosiy xossalar jadvali', 'Таблица основных свойств', 'Table of key properties'), table: {
      head: [L('Xossa', 'Свойство', 'Property'), L('y = sin x', 'y = sin x', 'y = sin x'), L('y = cos x', 'y = cos x', 'y = cos x'), L('y = tg x', 'y = tg x', 'y = tan x')],
      rows: [
        [L('Aniqlanish sohasi', 'Область определения', 'Domain'), L('ℝ', 'ℝ', 'ℝ'), L('ℝ', 'ℝ', 'ℝ'), L('x ≠ π/2 + πn', 'x ≠ π/2 + πn', 'x ≠ π/2 + πn')],
        [L('Qiymatlar to‘plami', 'Множество значений', 'Range'), L('[−1; 1]', '[−1; 1]', '[−1; 1]'), L('[−1; 1]', '[−1; 1]', '[−1; 1]'), L('ℝ', 'ℝ', 'ℝ')],
        [L('Davr', 'Период', 'Period'), L('2π', '2π', '2π'), L('2π', '2π', '2π'), L('π', 'π', 'π')],
        [L('Juft-toqlik', 'Чётность', 'Parity'), L('toq', 'нечётная', 'odd'), L('juft', 'чётная', 'even'), L('toq', 'нечётная', 'odd')],
        [L('Nollari', 'Нули', 'Zeros'), L('x = πn', 'x = πn', 'x = πn'), L('x = π/2 + πn', 'x = π/2 + πn', 'x = π/2 + πn'), L('x = πn', 'x = πn', 'x = πn')],
        [L('Maksimum', 'Максимум', 'Maximum'), L('1, x = π/2 + 2πn', '1, x = π/2 + 2πn', '1, x = π/2 + 2πn'), L('1, x = 2πn', '1, x = 2πn', '1, x = 2πn'), L('yo‘q', 'нет', 'none')]
      ] }, after: [
      L('sin x funksiya [−π/2; π/2] da o‘sadi va [π/2; 3π/2] da kamayadi; cos x esa [−π; 0] da o‘sadi, [0; π] da kamayadi. Kosinus grafigi sinus grafigini π/2 chapga surishdan hosil bo‘ladi: cos x = sin(x + π/2).', 'sin x возрастает на [−π/2; π/2] и убывает на [π/2; 3π/2]; cos x возрастает на [−π; 0] и убывает на [0; π]. График косинуса получается сдвигом синусоиды на π/2 влево: cos x = sin(x + π/2).', 'sin x increases on [−π/2; π/2] and decreases on [π/2; 3π/2]; cos x increases on [−π; 0] and decreases on [0; π]. The cosine graph is the sine graph shifted π/2 to the left: cos x = sin(x + π/2).')
    ] },
    { kind: 'rule', h: L('Garmonik tebranish: y = A sin(ωx + φ)', 'Гармоническое колебание: y = A sin(ωx + φ)', 'Harmonic oscillation: y = A sin(ωx + φ)'), p: [
      L('Fizikadagi ko‘p tebranishlar y = A sin(ωx + φ) + B ko‘rinishdagi funksiya bilan tasvirlanadi. Har bir parametr grafikni o‘ziga xos tarzda o‘zgartiradi:', 'Многие колебания в физике описываются функцией вида y = A sin(ωx + φ) + B. Каждый параметр по-своему меняет график:', 'Many oscillations in physics are described by y = A sin(ωx + φ) + B. Each parameter changes the graph in its own way:')
    ], list: [
      L('<b>A — amplituda:</b> grafik Oy bo‘ylab |A| marta cho‘ziladi; qiymatlar [−|A|; |A|] da.', '<b>A — амплитуда:</b> график растягивается вдоль Oy в |A| раз; значения в [−|A|; |A|].', '<b>A — amplitude:</b> the graph is stretched vertically by |A|; values lie in [−|A|; |A|].'),
      L('<b>ω — siklik chastota:</b> davr T = 2π/|ω|; ω qancha katta bo‘lsa, to‘lqinlar shuncha zich.', '<b>ω — циклическая частота:</b> период T = 2π/|ω|; чем больше ω, тем чаще волны.', '<b>ω — angular frequency:</b> period T = 2π/|ω|; the larger ω, the denser the waves.'),
      L('<b>φ — boshlang‘ich faza:</b> grafik Ox bo‘ylab φ/ω ga chapga suriladi.', '<b>φ — начальная фаза:</b> график сдвигается вдоль Ox на φ/ω влево.', '<b>φ — initial phase:</b> the graph shifts left along Ox by φ/ω.'),
      L('<b>B — vertikal siljish:</b> qiymatlar [B − |A|; B + |A|] oraliqda bo‘ladi.', '<b>B — вертикальный сдвиг:</b> значения лежат в [B − |A|; B + |A|].', '<b>B — vertical shift:</b> values lie in [B − |A|; B + |A|].')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('y = 3 sin 2x funksiyaning davri, eng katta va eng kichik qiymatini toping.', 'Найдите период, наибольшее и наименьшее значения y = 3 sin 2x.', 'Find the period, maximum and minimum of y = 3 sin 2x.'), s: L('T = 2π/2 = π. −1 ≤ sin 2x ≤ 1 ⇒ −3 ≤ y ≤ 3. Eng katta qiymat 3 (masalan x = π/4 da), eng kichik −3 (x = 3π/4 da).', 'T = 2π/2 = π. −1 ≤ sin 2x ≤ 1 ⇒ −3 ≤ y ≤ 3. Наибольшее значение 3 (например, при x = π/4), наименьшее −3 (при x = 3π/4).', 'T = 2π/2 = π. −1 ≤ sin 2x ≤ 1 ⇒ −3 ≤ y ≤ 3. The maximum is 3 (e.g. at x = π/4), the minimum −3 (at x = 3π/4).') },
      { q: L('y = 2 cos x − 1 funksiyaning qiymatlar to‘plamini toping.', 'Найдите множество значений y = 2 cos x − 1.', 'Find the range of y = 2 cos x − 1.'), s: L('−1 ≤ cos x ≤ 1 ⇒ −2 ≤ 2 cos x ≤ 2 ⇒ −3 ≤ 2 cos x − 1 ≤ 1. Javob: E = [−3; 1].', '−1 ≤ cos x ≤ 1 ⇒ −2 ≤ 2 cos x ≤ 2 ⇒ −3 ≤ 2 cos x − 1 ≤ 1. Ответ: E = [−3; 1].', '−1 ≤ cos x ≤ 1 ⇒ −2 ≤ 2 cos x ≤ 2 ⇒ −3 ≤ 2 cos x − 1 ≤ 1. Answer: E = [−3; 1].') },
      { q: L('f(x) = x² sin x funksiyaning juft yoki toqligini aniqlang.', 'Определите чётность f(x) = x² sin x.', 'Determine the parity of f(x) = x² sin x.'), s: L('f(−x) = (−x)² sin(−x) = x² · (−sin x) = −f(x). Aniqlanish sohasi ℝ simmetrik. Demak f — toq funksiya.', 'f(−x) = (−x)² sin(−x) = x² · (−sin x) = −f(x). Область определения ℝ симметрична. Значит, f — нечётная функция.', 'f(−x) = (−x)² sin(−x) = x² · (−sin x) = −f(x), and the domain ℝ is symmetric. So f is odd.') },
      { q: L('y = sin(x/3) + cos(x/2) funksiyaning davrini toping.', 'Найдите период y = sin(x/3) + cos(x/2).', 'Find the period of y = sin(x/3) + cos(x/2).'), s: L('Birinchi qo‘shiluvchi davri 2π : (1/3) = 6π, ikkinchisiniki 2π : (1/2) = 4π. Umumiy davr — ularning eng kichik umumiy karralisi: EKUK(6π; 4π) = 12π.', 'Период первого слагаемого 2π : (1/3) = 6π, второго 2π : (1/2) = 4π. Общий период — их наименьшее общее кратное: НОК(6π; 4π) = 12π.', 'The first term has period 2π ÷ (1/3) = 6π, the second 2π ÷ (1/2) = 4π. The common period is their least common multiple: LCM(6π, 4π) = 12π.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Davrni noto‘g‘ri hisoblash.</b> y = sin 4x ning davri 2π/4 = π/2, 8π emas: ω ga ko‘paytirmasdan, bo‘lish kerak.', '<b>Неверно считать период.</b> Период y = sin 4x равен 2π/4 = π/2, а не 8π: на ω надо делить, а не умножать.', '<b>Miscalculating the period.</b> The period of y = sin 4x is 2π/4 = π/2, not 8π: divide by ω, don’t multiply.'),
      L('<b>Gradus va radianni aralashtirish.</b> sin 30 ≠ 1/2! sin 30° = 1/2, sin(π/6) = 1/2, lekin sin 30 (radian) ≈ −0,99. Kalkulyator rejimini tekshiring.', '<b>Путать градусы и радианы.</b> sin 30 ≠ 1/2! sin 30° = 1/2, sin(π/6) = 1/2, но sin 30 (радиан) ≈ −0,99. Проверяйте режим калькулятора.', '<b>Mixing degrees and radians.</b> sin 30 ≠ 1/2! sin 30° = 1/2 and sin(π/6) = 1/2, but sin 30 (radians) ≈ −0.99. Check your calculator mode.'),
      L('<b>sin x ning qiymatlari [−1; 1] ekanini unutish.</b> sin x = 1,5 tenglamaning yechimi yo‘q.', '<b>Забывать, что значения sin x лежат в [−1; 1].</b> Уравнение sin x = 1,5 не имеет решений.', '<b>Forgetting that sin x lies in [−1; 1].</b> The equation sin x = 1.5 has no solution.'),
      L('<b>Amplituda manfiy bo‘lganda qiymatlarni noto‘g‘ri yozish.</b> y = −4 sin x ning qiymatlari ham [−4; 4], amplituda |A| = 4.', '<b>Ошибаться при отрицательной амплитуде.</b> У y = −4 sin x значения тоже [−4; 4], амплитуда |A| = 4.', '<b>Getting the range wrong for a negative A.</b> y = −4 sin x also has range [−4; 4]; the amplitude is |A| = 4.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Elektr energiyasi.</b> O‘zbekistonda rozetkadagi kuchlanish u(t) = 311 sin(100πt) volt: chastota 50 Gs, amplituda 311 V (ta’sir etuvchi qiymat 220 V = 311/√2). <b>Tovush.</b> «Lya» notasi — sekundiga 440 marta tebranish, y = A sin(880πt). <b>Kun uzunligi.</b> Toshkentda kun uzunligi yil davomida taxminan 9,5 soatdan 15 soatgacha o‘zgaradi va 365 kunlik davrli sinusoidaga yaqin.', '<b>Электроэнергия.</b> В Узбекистане напряжение в розетке u(t) = 311 sin(100πt) вольт: частота 50 Гц, амплитуда 311 В (действующее значение 220 В = 311/√2). <b>Звук.</b> Нота «ля» — 440 колебаний в секунду, y = A sin(880πt). <b>Длина дня.</b> В Ташкенте длина дня за год меняется примерно от 9,5 до 15 часов и близка к синусоиде с периодом 365 дней.', '<b>Electricity.</b> In Uzbekistan mains voltage is u(t) = 311 sin(100πt) volts: frequency 50 Hz, amplitude 311 V (the effective value 220 V = 311/√2). <b>Sound.</b> The note A is 440 vibrations a second, y = A sin(880πt). <b>Day length.</b> In Tashkent day length varies over the year from about 9.5 to 15 hours, close to a sinusoid with a 365-day period.'),
      L('<b>Tibbiyot:</b> EKG yurak ritmini davriy egri chiziq sifatida yozadi. <b>Okean:</b> suv ko‘tarilishi va qaytishi taxminan 12 soat 25 daqiqa davrli. <b>Muhandislik:</b> ko‘priklar quriladi, shunday qilib ularning xususiy tebranish chastotasi shamol yoki qadam chastotasi bilan mos kelmasin — aks holda rezonans halokatga olib keladi (1940-yil, Takoma ko‘prigi).', '<b>Медицина:</b> ЭКГ записывает ритм сердца как периодическую кривую. <b>Океан:</b> приливы и отливы повторяются примерно каждые 12 часов 25 минут. <b>Инженерия:</b> мосты строят так, чтобы их собственная частота не совпадала с частотой ветра или шагов — иначе резонанс приводит к катастрофе (мост Такома, 1940).', '<b>Medicine:</b> an ECG records the heartbeat as a periodic curve. <b>Ocean:</b> tides repeat about every 12 hours 25 minutes. <b>Engineering:</b> bridges are designed so that their natural frequency does not match wind or footstep frequencies — otherwise resonance causes disaster (Tacoma Narrows Bridge, 1940).')
    ] },
    { kind: 'steps', h: L('Sinusoidani qanday chizish kerak', 'Как построить синусоиду', 'How to draw a sine curve'), p: [
      L('y = A sin(ωx + φ) + B grafigini chizish uchun «besh nuqta» usulidan foydalaniladi. Avval davrni toping: T = 2π/ω. So‘ng ωx + φ = 0 tenglamadan boshlang‘ich nuqtani toping va davrni to‘rtta teng bo‘lakka bo‘ling. Shu besh nuqtada funksiya navbat bilan B, B + A, B, B − A, B qiymatlarni oladi. Nuqtalarni silliq to‘lqin bilan tutashtiring va grafikni chapga va o‘ngga davr bo‘yicha takrorlang.', 'Для построения графика y = A sin(ωx + φ) + B используют метод «пяти точек». Сначала найдите период: T = 2π/ω. Затем из уравнения ωx + φ = 0 найдите начальную точку и разделите период на четыре равные части. В этих пяти точках функция по очереди принимает значения B, B + A, B, B − A, B. Соедините точки плавной волной и повторите график влево и вправо через период.', 'To draw y = A sin(ωx + φ) + B use the “five-point” method. First find the period T = 2π/ω. Then find the starting point from ωx + φ = 0 and split the period into four equal parts. At these five points the function takes the values B, B + A, B, B − A, B in turn. Join them with a smooth wave and repeat the graph left and right by the period.'),
      L('Masalan, y = 2 sin(2x − π/2) + 1: T = π, boshlang‘ich nuqta 2x − π/2 = 0 ⇒ x = π/4. Nuqtalar: (π/4; 1), (π/2; 3), (3π/4; 1), (π; −1), (5π/4; 1). Grafik 1 to‘g‘ri chizig‘i atrofida −1 dan 3 gacha tebranadi.', 'Например, y = 2 sin(2x − π/2) + 1: T = π, начальная точка 2x − π/2 = 0 ⇒ x = π/4. Точки: (π/4; 1), (π/2; 3), (3π/4; 1), (π; −1), (5π/4; 1). График колеблется около прямой y = 1 от −1 до 3.', 'For example y = 2 sin(2x − π/2) + 1: T = π and the start is 2x − π/2 = 0 ⇒ x = π/4. Points: (π/4; 1), (π/2; 3), (3π/4; 1), (π; −1), (5π/4; 1). The graph oscillates about the line y = 1 between −1 and 3.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('Fransuz matematigi Jozef Furye (1822) isbotladi: har qanday davriy signalni — musiqa, nutq, yurak urishi — sinusoidalar yig‘indisi sifatida yozish mumkin. MP3 va JPEG formatlari shu g‘oyaga asoslangan.', 'Французский математик Жозеф Фурье (1822) доказал: любой периодический сигнал — музыку, речь, сердцебиение — можно записать как сумму синусоид. На этой идее основаны форматы MP3 и JPEG.', 'The French mathematician Joseph Fourier (1822) showed that any periodic signal — music, speech, a heartbeat — can be written as a sum of sine waves. The MP3 and JPEG formats rest on this idea.'),
      L('sin x ≈ x kichik burchaklar uchun juda aniq: x = 0,1 rad da xato 0,2% dan kam. Mayatnik formulasi shu yaqinlashishga asoslangan.', 'sin x ≈ x очень точно при малых углах: при x = 0,1 рад ошибка меньше 0,2%. На этом приближении основана формула маятника.', 'sin x ≈ x is very accurate for small angles: at x = 0.1 rad the error is under 0.2%. The pendulum formula relies on this approximation.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('y = 5 cos 3x ning davri?', 'Период y = 5 cos 3x?', 'Period of y = 5 cos 3x?'), s: L('2π/3.', '2π/3.', '2π/3.') },
      { q: L('y = 4 − 3 sin x ning eng katta qiymati?', 'Наибольшее значение y = 4 − 3 sin x?', 'Maximum of y = 4 − 3 sin x?'), s: L('sin x = −1 da 4 + 3 = 7.', 'При sin x = −1: 4 + 3 = 7.', 'At sin x = −1: 4 + 3 = 7.') },
      { q: L('cos(−x) = ?', 'cos(−x) = ?', 'cos(−x) = ?'), s: L('cos x (kosinus juft).', 'cos x (косинус чётный).', 'cos x (cosine is even).') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('sin x va cos x — birlik aylanadagi nuqta koordinatalari; D = ℝ, E = [−1; 1].', 'sin x и cos x — координаты точки единичной окружности; D = ℝ, E = [−1; 1].', 'sin x and cos x are coordinates of a point on the unit circle; D = ℝ, E = [−1; 1].'),
      L('sin, cos davri 2π; tg, ctg davri π.', 'Период sin, cos — 2π; tg, ctg — π.', 'sin, cos have period 2π; tan, cot have period π.'),
      L('sin, tg — toq; cos — juft.', 'sin, tg — нечётные; cos — чётная.', 'sin and tan are odd; cos is even.'),
      L('y = A sin(ωx + φ) + B: amplituda |A|, davr 2π/|ω|, faza φ, siljish B.', 'y = A sin(ωx + φ) + B: амплитуда |A|, период 2π/|ω|, фаза φ, сдвиг B.', 'y = A sin(ωx + φ) + B: amplitude |A|, period 2π/|ω|, phase φ, shift B.'),
      L('cos x = sin(x + π/2): kosinusoida — surilgan sinusoida.', 'cos x = sin(x + π/2): косинусоида — сдвинутая синусоида.', 'cos x = sin(x + π/2): the cosine curve is a shifted sine curve.'),
      L('Tebranishlar, tok, tovush, fasllar — davriy jarayonlar.', 'Колебания, ток, звук, времена года — периодические процессы.', 'Oscillations, current, sound and seasons are periodic processes.')
    ] }
  ] });

  // ---------- t17. Teskari trigonometrik funksiyalar ----------
  T.add(P, 't17', { sections: [
    { kind: 'intro', h: L('Sinusi ma’lum — burchak qaysi?', 'Синус известен — какой угол?', 'The sine is known — which angle?'), p: [
      L('Tom qiyaligini loyihalayotgan quruvchi biladi: tomning balandligi 3 m, yarim eni 4 m. Demak qiyalik burchagining tangensi 3/4. Lekin burchakning o‘zi necha gradus? Bu savol trigonometriyaga teskari: biz funksiya qiymatini bilamiz va argumentni izlaymiz. Muammo shundaki, sin x = 1/2 tenglamani π/6, 5π/6, 13π/6 va yana cheksiz ko‘p son qanoatlantiradi. Qaysi birini «javob» deb olamiz?', 'Строитель, проектирующий крышу, знает: высота крыши 3 м, половина ширины 4 м. Значит, тангенс угла наклона 3/4. Но сколько градусов сам угол? Этот вопрос обратен тригонометрии: мы знаем значение функции и ищем аргумент. Проблема в том, что уравнению sin x = 1/2 удовлетворяют π/6, 5π/6, 13π/6 и ещё бесконечно много чисел. Какое из них считать «ответом»?', 'A builder designing a roof knows the height is 3 m and the half-width 4 m, so the tangent of the slope angle is 3/4. But how many degrees is the angle itself? This question is the reverse of trigonometry: we know the value of the function and look for the argument. The trouble is that sin x = 1/2 is satisfied by π/6, 5π/6, 13π/6 and infinitely many more numbers. Which one should be “the answer”?'),
      L('Matematiklar kelishib olishdi: har bir funksiya uchun u monoton bo‘lgan bitta «asosiy» oraliq tanlanadi va javob faqat shu oraliqdan olinadi. Shu yo‘l bilan <b>arksinus, arkkosinus, arktangens</b> va <b>arkkotangens</b> funksiyalari hosil bo‘ladi. Ular keyingi mavzudagi trigonometrik tenglamalarning javoblarini yozish uchun zarur.', 'Математики договорились: для каждой функции выбирается один «основной» промежуток, на котором она монотонна, и ответ берётся только из него. Так получаются функции <b>арксинус, арккосинус, арктангенс</b> и <b>арккотангенс</b>. Они нужны для записи ответов тригонометрических уравнений в следующей теме.', 'Mathematicians agreed: for each function choose one “main” interval on which it is monotonic and take the answer only from there. This gives the functions <b>arcsine, arccosine, arctangent</b> and <b>arccotangent</b>. They are needed to write the answers to the trigonometric equations of the next topic.')
    ] },
    { kind: 'def', h: L('Ta’riflar', 'Определения', 'Definitions'), list: [
      L('<b>arcsin a</b> (|a| ≤ 1) — [−π/2; π/2] oraliqdagi shunday son, uning sinusi a ga teng. Masalan, arcsin(√2/2) = π/4.', '<b>arcsin a</b> (|a| ≤ 1) — число из [−π/2; π/2], синус которого равен a. Например, arcsin(√2/2) = π/4.', '<b>arcsin a</b> (|a| ≤ 1) is the number in [−π/2; π/2] whose sine is a. For example arcsin(√2/2) = π/4.'),
      L('<b>arccos a</b> (|a| ≤ 1) — [0; π] oraliqdagi shunday son, uning kosinusi a ga teng. Masalan, arccos(−1) = π.', '<b>arccos a</b> (|a| ≤ 1) — число из [0; π], косинус которого равен a. Например, arccos(−1) = π.', '<b>arccos a</b> (|a| ≤ 1) is the number in [0; π] whose cosine is a. For example arccos(−1) = π.'),
      L('<b>arctg a</b> (istalgan a) — (−π/2; π/2) oraliqdagi shunday son, uning tangensi a ga teng. Masalan, arctg(−√3) = −π/3.', '<b>arctg a</b> (любое a) — число из (−π/2; π/2), тангенс которого равен a. Например, arctg(−√3) = −π/3.', '<b>arctan a</b> (any a) is the number in (−π/2; π/2) whose tangent is a. For example arctan(−√3) = −π/3.'),
      L('<b>arcctg a</b> (istalgan a) — (0; π) oraliqdagi shunday son, uning kotangensi a ga teng. Masalan, arcctg 0 = π/2.', '<b>arcctg a</b> (любое a) — число из (0; π), котангенс которого равен a. Например, arcctg 0 = π/2.', '<b>arccot a</b> (any a) is the number in (0; π) whose cotangent is a. For example arccot 0 = π/2.')
    ], after: [
      L('Nega aynan shu oraliqlar? [−π/2; π/2] da sinus −1 dan 1 gacha uzluksiz o‘sadi va har bir qiymatni bir marta oladi; [0; π] da kosinus 1 dan −1 gacha kamayadi. Bu oraliqlar 0 ni (yoki π/2 ni) o‘z ichiga oladi va eng «tabiiy» burchaklarni beradi.', 'Почему именно эти промежутки? На [−π/2; π/2] синус непрерывно возрастает от −1 до 1 и принимает каждое значение один раз; на [0; π] косинус убывает от 1 до −1. Эти промежутки содержат 0 (или π/2) и дают самые «естественные» углы.', 'Why these intervals? On [−π/2; π/2] sine increases continuously from −1 to 1, taking each value once; on [0; π] cosine decreases from 1 to −1. These intervals contain 0 (or π/2) and give the most “natural” angles.')
    ] },
    { kind: 'history', h: L('Tarixdan: «arc» so‘zi va Ulug‘bek jadvallari', 'Из истории: слово «arc» и таблицы Улугбека', 'History: the word “arc” and Ulugh Beg’s tables'), p: [
      L('«Arcus» lotincha «yoy» degani: arcsin a — «sinusi a bo‘lgan yoy». Bu belgini XVIII asrda avstriyalik Karl Sherfer va fransuz Jozef Lui Lagranj kiritishgan. Ingliz tilida ko‘pincha sin<sup>−1</sup> x belgisi ishlatiladi (Jon Gershel, 1813), lekin uni 1/sin x bilan adashtirish oson, shuning uchun maktabda «arc» yozuvi qulayroq.', '«Arcus» по-латыни «дуга»: arcsin a — «дуга, синус которой равен a». Это обозначение ввели в XVIII веке австриец Карл Шерфер и француз Жозеф Луи Лагранж. В английском часто пишут sin<sup>−1</sup> x (Джон Гершель, 1813), но его легко спутать с 1/sin x, поэтому в школе удобнее запись «arc».', '“Arcus” is Latin for “arc”: arcsin a is “the arc whose sine is a”. The notation was introduced in the 18th century by the Austrian Karl Scherffer and the Frenchman Joseph-Louis Lagrange. English texts often write sin<sup>−1</sup> x (John Herschel, 1813), but it is easily confused with 1/sin x, so the “arc” notation is clearer at school.'),
      L('Teskari masalani — sinus bo‘yicha burchakni topishni — astronomlar ancha oldin yechishgan. Samarqanddagi <b>Ulug‘bek rasadxonasida</b> (XV asr) tuzilgan «Ziji Ko‘ragoniy» jadvallari yordamida yulduzning balandligi bo‘yicha vaqt yoki kenglikni topish uchun aynan sinus jadvalidan teskari foydalanilgan. G‘iyosiddin Jamshid Koshiy sin 1° ni kub tenglama orqali juda yuqori aniqlikda hisoblagan.', 'Обратную задачу — нахождение угла по синусу — астрономы решали гораздо раньше. С помощью таблиц «Зидж Гурагани», составленных в <b>обсерватории Улугбека</b> в Самарканде (XV век), по высоте звезды находили время или широту, используя таблицу синусов «в обратную сторону». Гиясиддин Джамшид Каши вычислил sin 1° с очень высокой точностью через кубическое уравнение.', 'Astronomers solved the reverse problem — finding an angle from its sine — much earlier. Using the “Zij-i Gurgani” tables compiled at <b>Ulugh Beg’s observatory</b> in Samarkand (15th century), they found the time or latitude from a star’s altitude by reading the sine table “backwards”. Jamshid al-Kashi computed sin 1° to very high accuracy via a cubic equation.')
    ] },
    { kind: 'rule', h: L('Asosiy xossalar', 'Основные свойства', 'Main properties'), list: [
      L('sin(arcsin a) = a, cos(arccos a) = a (|a| ≤ 1); tg(arctg a) = a (istalgan a).', 'sin(arcsin a) = a, cos(arccos a) = a (|a| ≤ 1); tg(arctg a) = a (любое a).', 'sin(arcsin a) = a, cos(arccos a) = a (|a| ≤ 1); tan(arctan a) = a (any a).'),
      L('arcsin(sin x) = x faqat x ∈ [−π/2; π/2] bo‘lganda! Masalan, arcsin(sin π) = arcsin 0 = 0 ≠ π.', 'arcsin(sin x) = x только при x ∈ [−π/2; π/2]! Например, arcsin(sin π) = arcsin 0 = 0 ≠ π.', 'arcsin(sin x) = x only for x ∈ [−π/2; π/2]! For example arcsin(sin π) = arcsin 0 = 0 ≠ π.'),
      L('<b>Toqlik:</b> arcsin(−a) = −arcsin a, arctg(−a) = −arctg a.', '<b>Нечётность:</b> arcsin(−a) = −arcsin a, arctg(−a) = −arctg a.', '<b>Oddness:</b> arcsin(−a) = −arcsin a, arctan(−a) = −arctan a.'),
      L('<b>Kosinus uchun:</b> arccos(−a) = π − arccos a; arcctg(−a) = π − arcctg a.', '<b>Для косинуса:</b> arccos(−a) = π − arccos a; arcctg(−a) = π − arcctg a.', '<b>For cosine:</b> arccos(−a) = π − arccos a; arccot(−a) = π − arccot a.'),
      L('<b>Bog‘lanish:</b> arcsin a + arccos a = π/2; arctg a + arcctg a = π/2.', '<b>Связь:</b> arcsin a + arccos a = π/2; arctg a + arcctg a = π/2.', '<b>Link:</b> arcsin a + arccos a = π/2; arctan a + arccot a = π/2.')
    ], after: [
      L('<i>arccos(−a) = π − arccos a ning isboti g‘oyasi:</i> α = arccos a bo‘lsin, α ∈ [0; π]. U holda π − α ham [0; π] da va cos(π − α) = −cos α = −a. Ta’rif bo‘yicha arccos(−a) = π − α.', '<i>Идея доказательства arccos(−a) = π − arccos a:</i> пусть α = arccos a, α ∈ [0; π]. Тогда π − α тоже в [0; π] и cos(π − α) = −cos α = −a. По определению arccos(−a) = π − α.', '<i>Proof idea for arccos(−a) = π − arccos a:</i> let α = arccos a, α ∈ [0; π]. Then π − α is also in [0; π] and cos(π − α) = −cos α = −a. By definition arccos(−a) = π − α.')
    ] },
    { kind: 'table', h: L('Asosiy qiymatlar jadvali', 'Таблица основных значений', 'Table of key values'), table: {
      head: [L('a', 'a', 'a'), L('arcsin a', 'arcsin a', 'arcsin a'), L('arccos a', 'arccos a', 'arccos a')],
      rows: [
        [L('−1', '−1', '−1'), L('−π/2', '−π/2', '−π/2'), L('π', 'π', 'π')],
        [L('−√3/2', '−√3/2', '−√3/2'), L('−π/3', '−π/3', '−π/3'), L('5π/6', '5π/6', '5π/6')],
        [L('−1/2', '−1/2', '−1/2'), L('−π/6', '−π/6', '−π/6'), L('2π/3', '2π/3', '2π/3')],
        [L('0', '0', '0'), L('0', '0', '0'), L('π/2', 'π/2', 'π/2')],
        [L('1/2', '1/2', '1/2'), L('π/6', 'π/6', 'π/6'), L('π/3', 'π/3', 'π/3')],
        [L('√2/2', '√2/2', '√2/2'), L('π/4', 'π/4', 'π/4'), L('π/4', 'π/4', 'π/4')],
        [L('1', '1', '1'), L('π/2', 'π/2', 'π/2'), L('0', '0', '0')]
      ] }, after: [
      L('Arktangens uchun: arctg 0 = 0, arctg(√3/3) = π/6, arctg 1 = π/4, arctg √3 = π/3; manfiy argumentlar uchun ishora almashadi. Har bir satrda arcsin a + arccos a = π/2 ekanini tekshirib ko‘ring.', 'Для арктангенса: arctg 0 = 0, arctg(√3/3) = π/6, arctg 1 = π/4, arctg √3 = π/3; для отрицательных аргументов знак меняется. Проверьте, что в каждой строке arcsin a + arccos a = π/2.', 'For arctangent: arctan 0 = 0, arctan(√3/3) = π/6, arctan 1 = π/4, arctan √3 = π/3; for negative arguments the sign changes. Check that every row has arcsin a + arccos a = π/2.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('Hisoblang: arcsin(−√3/2) + arccos(−√2/2).', 'Вычислите: arcsin(−√3/2) + arccos(−√2/2).', 'Compute arcsin(−√3/2) + arccos(−√2/2).'), s: L('arcsin(−√3/2) = −π/3. arccos(−√2/2) = π − π/4 = 3π/4. Yig‘indi: −π/3 + 3π/4 = (−4π + 9π)/12 = 5π/12.', 'arcsin(−√3/2) = −π/3. arccos(−√2/2) = π − π/4 = 3π/4. Сумма: −π/3 + 3π/4 = (−4π + 9π)/12 = 5π/12.', 'arcsin(−√3/2) = −π/3 and arccos(−√2/2) = π − π/4 = 3π/4. Sum: −π/3 + 3π/4 = (−4π + 9π)/12 = 5π/12.') },
      { q: L('Hisoblang: cos(arcsin(3/5)).', 'Вычислите: cos(arcsin(3/5)).', 'Compute cos(arcsin(3/5)).'), s: L('α = arcsin(3/5) bo‘lsin, sin α = 3/5, α ∈ [−π/2; π/2], shuning uchun cos α ≥ 0. cos α = √(1 − 9/25) = √(16/25) = 4/5.', 'Пусть α = arcsin(3/5), sin α = 3/5, α ∈ [−π/2; π/2], поэтому cos α ≥ 0. cos α = √(1 − 9/25) = √(16/25) = 4/5.', 'Let α = arcsin(3/5): sin α = 3/5 and α ∈ [−π/2; π/2], so cos α ≥ 0. cos α = √(1 − 9/25) = √(16/25) = 4/5.') },
      { q: L('Hisoblang: arcsin(sin(5π/6)).', 'Вычислите: arcsin(sin(5π/6)).', 'Compute arcsin(sin(5π/6)).'), s: L('sin(5π/6) = 1/2. arcsin(1/2) = π/6. 5π/6 javob emas, chunki u [−π/2; π/2] ga kirmaydi.', 'sin(5π/6) = 1/2. arcsin(1/2) = π/6. 5π/6 не ответ, так как не лежит в [−π/2; π/2].', 'sin(5π/6) = 1/2, and arcsin(1/2) = π/6. 5π/6 is not the answer since it is not in [−π/2; π/2].') },
      { q: L('arccos(2x − 1) ifoda qaysi x larda ma’noga ega?', 'При каких x имеет смысл arccos(2x − 1)?', 'For which x is arccos(2x − 1) defined?'), s: L('−1 ≤ 2x − 1 ≤ 1 ⇒ 0 ≤ 2x ≤ 2 ⇒ 0 ≤ x ≤ 1. Javob: [0; 1].', '−1 ≤ 2x − 1 ≤ 1 ⇒ 0 ≤ 2x ≤ 2 ⇒ 0 ≤ x ≤ 1. Ответ: [0; 1].', '−1 ≤ 2x − 1 ≤ 1 ⇒ 0 ≤ 2x ≤ 2 ⇒ 0 ≤ x ≤ 1. Answer: [0; 1].') },
      { q: L('Tom balandligi 3 m, yarim eni 4 m. Qiyalik burchagini toping.', 'Высота крыши 3 м, половина ширины 4 м. Найдите угол наклона.', 'A roof is 3 m high with a half-width of 4 m. Find the slope angle.'), s: L('tg α = 3/4, α = arctg 0,75 ≈ 0,6435 rad ≈ 36,9°.', 'tg α = 3/4, α = arctg 0,75 ≈ 0,6435 рад ≈ 36,9°.', 'tan α = 3/4, α = arctan 0.75 ≈ 0.6435 rad ≈ 36.9°.') }
    ] },
    { kind: 'steps', h: L('Grafiklar', 'Графики', 'Graphs'), p: [
      L('Teskari funksiya grafigi asl funksiya grafigini y = x to‘g‘ri chiziqqa nisbatan aks ettirishdan hosil bo‘ladi. y = arcsin x grafigi — sinusoidaning [−π/2; π/2] dagi bo‘lagining aksi: u (−1; −π/2) dan (1; π/2) gacha o‘suvchi egri chiziq, koordinata boshidan o‘tadi. y = arccos x — (−1; π) dan (1; 0) gacha kamayuvchi egri, (0; π/2) dan o‘tadi.', 'График обратной функции получается отражением графика исходной относительно прямой y = x. График y = arcsin x — отражение куска синусоиды на [−π/2; π/2]: возрастающая кривая от (−1; −π/2) до (1; π/2), проходящая через начало координат. y = arccos x — убывающая кривая от (−1; π) до (1; 0), проходящая через (0; π/2).', 'The graph of an inverse function is the reflection of the original graph in the line y = x. y = arcsin x is the reflection of the piece of the sine curve on [−π/2; π/2]: an increasing curve from (−1; −π/2) to (1; π/2) through the origin. y = arccos x is a decreasing curve from (−1; π) to (1; 0) through (0; π/2).'),
      L('y = arctg x esa butun son o‘qida aniqlangan o‘suvchi funksiya; uning grafigi y = −π/2 va y = π/2 gorizontal asimptotalar orasida joylashgan. x qancha katta bo‘lmasin, arctg x hech qachon π/2 ga yetmaydi.', 'y = arctg x определена на всей числовой оси и возрастает; её график расположен между горизонтальными асимптотами y = −π/2 и y = π/2. Как бы ни было велико x, arctg x никогда не достигает π/2.', 'y = arctan x is defined on the whole number line and increasing; its graph lies between the horizontal asymptotes y = −π/2 and y = π/2. However large x is, arctan x never reaches π/2.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Qiymatlar oralig‘ini unutish.</b> arccos(−1/2) = −π/3 deb yozish xato: arccos manfiy bo‘lmaydi, to‘g‘ri javob 2π/3.', '<b>Забывать множество значений.</b> Писать arccos(−1/2) = −π/3 неверно: arccos не бывает отрицательным, правильно 2π/3.', '<b>Forgetting the range.</b> Writing arccos(−1/2) = −π/3 is wrong: arccos is never negative; the answer is 2π/3.'),
      L('<b>|a| &gt; 1 uchun arcsin a yozish.</b> arcsin 2 mavjud emas, chunki sinus 1 dan katta bo‘lmaydi.', '<b>Писать arcsin a при |a| &gt; 1.</b> arcsin 2 не существует, так как синус не больше 1.', '<b>Writing arcsin a for |a| &gt; 1.</b> arcsin 2 does not exist since sine never exceeds 1.'),
      L('<b>sin<sup>−1</sup> x ni 1/sin x deb tushunish.</b> Kalkulyatordagi sin<sup>−1</sup> tugmasi arksinusni hisoblaydi.', '<b>Понимать sin<sup>−1</sup> x как 1/sin x.</b> Кнопка sin<sup>−1</sup> на калькуляторе вычисляет арксинус.', '<b>Reading sin<sup>−1</sup> x as 1/sin x.</b> The sin<sup>−1</sup> key on a calculator computes arcsine.'),
      L('<b>arcsin(sin x) = x ni har doim to‘g‘ri deb hisoblash.</b> Bu faqat x ∈ [−π/2; π/2] da to‘g‘ri.', '<b>Считать arcsin(sin x) = x всегда верным.</b> Это верно только при x ∈ [−π/2; π/2].', '<b>Assuming arcsin(sin x) = x always.</b> It holds only for x ∈ [−π/2; π/2].')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Qurilish va yo‘llar.</b> Yo‘l belgisidagi «10% qiyalik» 100 m da 10 m ko‘tarilishni bildiradi; burchak arctg 0,1 ≈ 5,7°. Nogironlar aravachasi uchun pandus qiyaligi odatda 1:12 dan oshmasligi kerak, ya’ni arctg(1/12) ≈ 4,8°. <b>Navigatsiya.</b> Kema yoki samolyot kursini topishda sharq va shimol bo‘yicha siljishlar nisbatidan arktangens olinadi. <b>Kompyuter grafikasi va robototexnika</b>da robot qo‘li bo‘g‘imlarining burchaklari arccos va arctg yordamida hisoblanadi.', '<b>Строительство и дороги.</b> Знак «уклон 10%» означает подъём 10 м на 100 м; угол arctg 0,1 ≈ 5,7°. Уклон пандуса для инвалидных колясок обычно не больше 1:12, то есть arctg(1/12) ≈ 4,8°. <b>Навигация.</b> Курс корабля или самолёта находят арктангенсом отношения смещений на восток и на север. В <b>компьютерной графике и робототехнике</b> углы суставов манипулятора вычисляют через arccos и arctg.', '<b>Construction and roads.</b> A “10% gradient” sign means a 10 m rise over 100 m; the angle is arctan 0.1 ≈ 5.7°. A wheelchair ramp is usually no steeper than 1:12, i.e. arctan(1/12) ≈ 4.8°. <b>Navigation.</b> A ship’s or plane’s heading is the arctangent of the ratio of eastward and northward displacements. In <b>computer graphics and robotics</b> the joint angles of a robot arm are computed with arccos and arctan.'),
      L('<b>Optika.</b> Yorug‘lik suvdan havoga o‘tganda to‘liq ichki qaytish chegaraviy burchagi α = arcsin(1/n) ≈ arcsin(1/1,33) ≈ 48,8°. Optik tolalar shu hodisa asosida ishlaydi va internet signallarini okean ostidan olib o‘tadi.', '<b>Оптика.</b> При переходе света из воды в воздух предельный угол полного внутреннего отражения α = arcsin(1/n) ≈ arcsin(1/1,33) ≈ 48,8°. На этом явлении работают оптоволокна, передающие интернет-сигналы под океаном.', '<b>Optics.</b> When light passes from water to air, the critical angle for total internal reflection is α = arcsin(1/n) ≈ arcsin(1/1.33) ≈ 48.8°. Optical fibres carrying internet signals under the ocean work on this effect.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('arctg 1 + arctg 2 + arctg 3 = π. Buni katakli qog‘ozda uchta to‘g‘ri burchakli uchburchak chizib, chiroyli tarzda ko‘rsatish mumkin.', 'arctg 1 + arctg 2 + arctg 3 = π. Это красиво показывается на клетчатой бумаге с помощью трёх прямоугольных треугольников.', 'arctan 1 + arctan 2 + arctan 3 = π. This can be shown beautifully on squared paper with three right triangles.'),
      L('Jon Machin 1706-yilda π/4 = 4 arctg(1/5) − arctg(1/239) formulasini topdi va π ning 100 ta raqamini qo‘lda hisobladi. Shunga o‘xshash formulalar bilan bugun π ning trillionlab raqamlari hisoblanadi.', 'Джон Мэчин в 1706 году нашёл формулу π/4 = 4 arctg(1/5) − arctg(1/239) и вручную вычислил 100 знаков π. Подобными формулами сегодня вычисляют триллионы знаков π.', 'In 1706 John Machin found π/4 = 4 arctan(1/5) − arctan(1/239) and computed 100 digits of π by hand. Similar formulas are used today to compute trillions of digits.'),
      L('Smartfondagi kompas ilovasi magnit maydon tashkil etuvchilaridan yo‘nalishni atan2 deb ataladigan «to‘liq» arktangens funksiyasi orqali hisoblaydi.', 'Приложение-компас в смартфоне вычисляет направление по компонентам магнитного поля через «полный» арктангенс — функцию atan2.', 'A smartphone compass app computes the heading from the magnetic field components using the “full” arctangent function atan2.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('arctg(−1) + arccos 0', 'arctg(−1) + arccos 0', 'arctan(−1) + arccos 0'), s: L('−π/4 + π/2 = π/4.', '−π/4 + π/2 = π/4.', '−π/4 + π/2 = π/4.') },
      { q: L('sin(arccos(−4/5))', 'sin(arccos(−4/5))', 'sin(arccos(−4/5))'), s: L('arccos ∈ [0; π] da sinus ≥ 0: √(1 − 16/25) = 3/5.', 'На [0; π] синус ≥ 0: √(1 − 16/25) = 3/5.', 'On [0; π] sine ≥ 0: √(1 − 16/25) = 3/5.') },
      { q: L('arcsin 1,2 mavjudmi?', 'Существует ли arcsin 1,2?', 'Does arcsin 1.2 exist?'), s: L('Yo‘q: |1,2| &gt; 1.', 'Нет: |1,2| &gt; 1.', 'No: |1.2| &gt; 1.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('arcsin a ∈ [−π/2; π/2], arccos a ∈ [0; π], |a| ≤ 1.', 'arcsin a ∈ [−π/2; π/2], arccos a ∈ [0; π], |a| ≤ 1.', 'arcsin a ∈ [−π/2; π/2], arccos a ∈ [0; π], |a| ≤ 1.'),
      L('arctg a ∈ (−π/2; π/2), arcctg a ∈ (0; π), a — istalgan.', 'arctg a ∈ (−π/2; π/2), arcctg a ∈ (0; π), a — любое.', 'arctan a ∈ (−π/2; π/2), arccot a ∈ (0; π), any a.'),
      L('arcsin(−a) = −arcsin a; arccos(−a) = π − arccos a.', 'arcsin(−a) = −arcsin a; arccos(−a) = π − arccos a.', 'arcsin(−a) = −arcsin a; arccos(−a) = π − arccos a.'),
      L('arcsin a + arccos a = π/2.', 'arcsin a + arccos a = π/2.', 'arcsin a + arccos a = π/2.'),
      L('Grafiklar — asosiy oraliqdagi sin, cos, tg grafiklarining y = x ga nisbatan aksi.', 'Графики — отражения графиков sin, cos, tg на основных промежутках относительно y = x.', 'The graphs are reflections of sin, cos, tan on their main intervals in y = x.'),
      L('«arc» — yoy: arcsin a — sinusi a bo‘lgan yoy (burchak).', '«arc» — дуга: arcsin a — дуга (угол), синус которой a.', '“arc” means arc: arcsin a is the arc (angle) whose sine is a.')
    ] }
  ] });

  // ---------- t18. Sodda trigonometrik tenglamalar ----------
  T.add(P, 't18', { sections: [
    { kind: 'intro', h: L('Cheksiz ko‘p ildizli tenglamalar', 'Уравнения с бесконечным числом корней', 'Equations with infinitely many roots'), p: [
      L('Shu paytgacha biz yechgan tenglamalarning ildizlari odatda bir, ikki yoki bir nechta edi. Trigonometrik tenglamalar boshqacha: sin x = 1/2 tenglamaning ildizlari cheksiz ko‘p — π/6, 5π/6, 13π/6, 17π/6, −7π/6 va hokazo. Buning sababi trigonometrik funksiyalarning davriyligi: agar x ildiz bo‘lsa, x + 2π, x + 4π, x − 2π ham ildiz. Shuning uchun javobni ro‘yxat emas, balki <b>formula</b> ko‘rinishida yozamiz, unda n butun son parametri qatnashadi.', 'До сих пор у решаемых нами уравнений обычно было один, два или несколько корней. Тригонометрические уравнения другие: у sin x = 1/2 корней бесконечно много — π/6, 5π/6, 13π/6, 17π/6, −7π/6 и так далее. Причина — периодичность тригонометрических функций: если x — корень, то x + 2π, x + 4π, x − 2π — тоже корни. Поэтому ответ записывают не списком, а <b>формулой</b> с целым параметром n.', 'Until now the equations we solved usually had one, two or a few roots. Trigonometric equations are different: sin x = 1/2 has infinitely many roots — π/6, 5π/6, 13π/6, 17π/6, −7π/6 and so on. The reason is periodicity: if x is a root, so are x + 2π, x + 4π, x − 2π. So the answer is written not as a list but as a <b>formula</b> with an integer parameter n.'),
      L('Bu mavzuda eng sodda tenglamalar — sin x = a, cos x = a, tg x = a, ctg x = a — ning umumiy yechim formulalarini chiqaramiz. Har qanday murakkab trigonometrik tenglama oxir-oqibat shu sodda tenglamalarga keltiriladi, shuning uchun bu formulalarni puxta bilish juda muhim.', 'В этой теме мы выведем формулы общего решения простейших уравнений sin x = a, cos x = a, tg x = a, ctg x = a. Любое сложное тригонометрическое уравнение в итоге сводится к простейшим, поэтому эти формулы нужно знать твёрдо.', 'In this topic we derive general-solution formulas for the simplest equations sin x = a, cos x = a, tan x = a, cot x = a. Every complicated trigonometric equation eventually reduces to these, so the formulas must be known thoroughly.')
    ] },
    { kind: 'def', h: L('Asosiy formulalar', 'Основные формулы', 'Main formulas'), p: [
      L('Quyida n ∈ ℤ (istalgan butun son). Formulalar teskari trigonometrik funksiyalar va davriylik yordamida yoziladi.', 'Ниже n ∈ ℤ (любое целое число). Формулы записываются через обратные тригонометрические функции и периодичность.', 'Below n ∈ ℤ (any integer). The formulas are written using inverse trigonometric functions and periodicity.')
    ], list: [
      L('<b>cos x = a</b> (|a| ≤ 1): x = ±arccos a + 2πn.', '<b>cos x = a</b> (|a| ≤ 1): x = ±arccos a + 2πn.', '<b>cos x = a</b> (|a| ≤ 1): x = ±arccos a + 2πn.'),
      L('<b>sin x = a</b> (|a| ≤ 1): x = (−1)<sup>n</sup> arcsin a + πn. Bu ikki seriyaning birlashmasi: x = arcsin a + 2πn va x = π − arcsin a + 2πn.', '<b>sin x = a</b> (|a| ≤ 1): x = (−1)<sup>n</sup> arcsin a + πn. Это объединение двух серий: x = arcsin a + 2πn и x = π − arcsin a + 2πn.', '<b>sin x = a</b> (|a| ≤ 1): x = (−1)<sup>n</sup> arcsin a + πn. This combines two series: x = arcsin a + 2πn and x = π − arcsin a + 2πn.'),
      L('<b>tg x = a</b> (istalgan a): x = arctg a + πn.', '<b>tg x = a</b> (любое a): x = arctg a + πn.', '<b>tan x = a</b> (any a): x = arctan a + πn.'),
      L('<b>ctg x = a</b> (istalgan a): x = arcctg a + πn.', '<b>ctg x = a</b> (любое a): x = arcctg a + πn.', '<b>cot x = a</b> (any a): x = arccot a + πn.'),
      L('|a| &gt; 1 bo‘lsa, sin x = a va cos x = a ning <b>yechimi yo‘q</b>.', 'При |a| &gt; 1 уравнения sin x = a и cos x = a <b>не имеют решений</b>.', 'If |a| &gt; 1, sin x = a and cos x = a have <b>no solutions</b>.')
    ] },
    { kind: 'rule', h: L('Formulalar qayerdan keladi', 'Откуда берутся формулы', 'Where the formulas come from'), p: [
      L('<b>cos x = a.</b> Birlik aylanada abssissasi a bo‘lgan nuqtalar — vertikal x = a to‘g‘ri chiziqning aylana bilan kesishish nuqtalari. |a| &lt; 1 da ular ikkita: biri yuqori yarim aylanada, burchagi arccos a; ikkinchisi unga Ox o‘qiga nisbatan simmetrik, burchagi −arccos a. Har biriga to‘liq aylanishlar (2πn) qo‘shamiz: x = ±arccos a + 2πn.', '<b>cos x = a.</b> Точки единичной окружности с абсциссой a — точки пересечения вертикальной прямой x = a с окружностью. При |a| &lt; 1 их две: одна в верхней полуокружности с углом arccos a, другая симметрична ей относительно Ox, угол −arccos a. К каждой добавляем полные обороты (2πn): x = ±arccos a + 2πn.', '<b>cos x = a.</b> Points on the unit circle with x-coordinate a are where the vertical line x = a meets the circle. For |a| &lt; 1 there are two: one in the upper half with angle arccos a, and its mirror image in Ox with angle −arccos a. Adding full turns (2πn) gives x = ±arccos a + 2πn.'),
      L('<b>sin x = a.</b> Ordinatasi a bo‘lgan nuqtalar — gorizontal y = a to‘g‘ri chiziq bilan kesishish. Ular arcsin a va π − arcsin a burchaklarga mos (Oy o‘qiga nisbatan simmetrik). n juft bo‘lganda (−1)<sup>n</sup> arcsin a + πn birinchi seriyani, toq bo‘lganda ikkinchisini beradi. <b>tg x = a.</b> Tangens davri π bo‘lgani uchun (−π/2; π/2) dagi bitta yechimga πn qo‘shish yetarli.', '<b>sin x = a.</b> Точки с ординатой a — пересечения с горизонтальной прямой y = a. Им соответствуют углы arcsin a и π − arcsin a (симметричны относительно Oy). При чётном n формула (−1)<sup>n</sup> arcsin a + πn даёт первую серию, при нечётном — вторую. <b>tg x = a.</b> Так как период тангенса π, достаточно к одному решению из (−π/2; π/2) прибавить πn.', '<b>sin x = a.</b> Points with y-coordinate a are where the horizontal line y = a meets the circle, at angles arcsin a and π − arcsin a (symmetric in Oy). For even n, (−1)<sup>n</sup> arcsin a + πn gives the first series; for odd n, the second. <b>tan x = a.</b> Since tangent has period π, it is enough to add πn to the single solution in (−π/2; π/2).')
    ] },
    { kind: 'table', h: L('Xususiy holatlar', 'Частные случаи', 'Special cases'), table: {
      head: [L('Tenglama', 'Уравнение', 'Equation'), L('Yechim', 'Решение', 'Solution'), L('Tenglama', 'Уравнение', 'Equation'), L('Yechim', 'Решение', 'Solution')],
      rows: [
        [L('sin x = 0', 'sin x = 0', 'sin x = 0'), L('x = πn', 'x = πn', 'x = πn'), L('cos x = 0', 'cos x = 0', 'cos x = 0'), L('x = π/2 + πn', 'x = π/2 + πn', 'x = π/2 + πn')],
        [L('sin x = 1', 'sin x = 1', 'sin x = 1'), L('x = π/2 + 2πn', 'x = π/2 + 2πn', 'x = π/2 + 2πn'), L('cos x = 1', 'cos x = 1', 'cos x = 1'), L('x = 2πn', 'x = 2πn', 'x = 2πn')],
        [L('sin x = −1', 'sin x = −1', 'sin x = −1'), L('x = −π/2 + 2πn', 'x = −π/2 + 2πn', 'x = −π/2 + 2πn'), L('cos x = −1', 'cos x = −1', 'cos x = −1'), L('x = π + 2πn', 'x = π + 2πn', 'x = π + 2πn')],
        [L('tg x = 0', 'tg x = 0', 'tan x = 0'), L('x = πn', 'x = πn', 'x = πn'), L('ctg x = 0', 'ctg x = 0', 'cot x = 0'), L('x = π/2 + πn', 'x = π/2 + πn', 'x = π/2 + πn')]
      ] }, after: [
      L('Bu holatlarda umumiy formulani ishlatish ham mumkin, lekin u ortiqcha qismlar beradi. Masalan, sin x = 1 uchun (−1)<sup>n</sup> π/2 + πn har bir nuqtani ikki marta sanaydi. Shuning uchun xususiy formulalarni yod olish foydali — ular yozuvni qisqa va aniq qiladi.', 'В этих случаях можно использовать и общую формулу, но она даёт лишние повторения. Например, для sin x = 1 формула (−1)<sup>n</sup> π/2 + πn описывает каждую точку дважды. Поэтому частные формулы полезно запомнить — они делают запись короткой и точной.', 'The general formula also works in these cases, but it produces repetitions. For example, for sin x = 1 the formula (−1)<sup>n</sup> π/2 + πn lists each point twice. So it is worth memorising the special formulas — they make the answer short and precise.')
    ] },
    { kind: 'history', h: L('Tarixdan: astronomiyadan tenglamalargacha', 'Из истории: от астрономии к уравнениям', 'History: from astronomy to equations'), p: [
      L('Trigonometrik tenglamalar astronomiya ehtiyojlaridan kelib chiqqan. Quyosh qachon ma’lum balandlikka ko‘tariladi? Namoz vaqtlari, qibla yo‘nalishi, kun va tunning tenglashuvi — bularning barchasi sinus va kosinus qatnashgan tenglamalarni yechishni talab qilgan. <b>Beruniy</b> «Qonuni Mas’udiy» asarida qibla yo‘nalishini sferik trigonometriya orqali hisoblash usulini bergan, <b>Nasriddin Tusiy</b> esa XIII asrda trigonometriyani astronomiyadan ajratib, birinchi mustaqil darslikni yozgan.', 'Тригонометрические уравнения возникли из потребностей астрономии. Когда Солнце поднимется на заданную высоту? Время молитв, направление киблы, равноденствие — всё это требовало решения уравнений с синусами и косинусами. <b>Беруни</b> в «Каноне Масуда» дал способ вычисления направления киблы через сферическую тригонометрию, а <b>Насир ад-Дин Туси</b> в XIII веке отделил тригонометрию от астрономии и написал первый самостоятельный учебник.', 'Trigonometric equations grew out of astronomy. When will the Sun reach a given altitude? Prayer times, the direction of the qibla, the equinox — all required solving equations with sines and cosines. <b>Al-Biruni</b> in the “Mas’udi Canon” gave a method for finding the qibla direction by spherical trigonometry, and in the 13th century <b>Nasir al-Din al-Tusi</b> separated trigonometry from astronomy and wrote the first independent textbook on it.'),
      L('Javobni «barcha butun n uchun» formula ko‘rinishida yozish odati XVIII–XIX asrlarda, Eyler funksiyalarni son argumentli qilib qaraganidan keyin shakllandi.', 'Привычка записывать ответ формулой «для всех целых n» сложилась в XVIII–XIX веках, после того как Эйлер стал рассматривать функции числового аргумента.', 'The habit of writing the answer as a formula “for all integers n” formed in the 18th–19th centuries, after Euler began treating these as functions of a numerical argument.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar', 'Решённые примеры', 'Worked examples'), ex: [
      { q: L('cos x = −1/2 tenglamani yeching.', 'Решите уравнение cos x = −1/2.', 'Solve cos x = −1/2.'), s: L('arccos(−1/2) = π − π/3 = 2π/3. Javob: x = ±2π/3 + 2πn, n ∈ ℤ.', 'arccos(−1/2) = π − π/3 = 2π/3. Ответ: x = ±2π/3 + 2πn, n ∈ ℤ.', 'arccos(−1/2) = π − π/3 = 2π/3. Answer: x = ±2π/3 + 2πn, n ∈ ℤ.') },
      { q: L('sin x = √2/2 tenglamani yeching.', 'Решите уравнение sin x = √2/2.', 'Solve sin x = √2/2.'), s: L('arcsin(√2/2) = π/4. Javob: x = (−1)<sup>n</sup> π/4 + πn, yoki ikki seriya: x = π/4 + 2πn, x = 3π/4 + 2πn.', 'arcsin(√2/2) = π/4. Ответ: x = (−1)<sup>n</sup> π/4 + πn, или две серии: x = π/4 + 2πn, x = 3π/4 + 2πn.', 'arcsin(√2/2) = π/4. Answer: x = (−1)<sup>n</sup> π/4 + πn, or two series: x = π/4 + 2πn and x = 3π/4 + 2πn.') },
      { q: L('tg(2x − π/4) = 1 tenglamani yeching.', 'Решите уравнение tg(2x − π/4) = 1.', 'Solve tan(2x − π/4) = 1.'), s: L('2x − π/4 = π/4 + πn ⇒ 2x = π/2 + πn ⇒ x = π/4 + πn/2.', '2x − π/4 = π/4 + πn ⇒ 2x = π/2 + πn ⇒ x = π/4 + πn/2.', '2x − π/4 = π/4 + πn ⇒ 2x = π/2 + πn ⇒ x = π/4 + πn/2.') },
      { q: L('2 sin(x/3) + √3 = 0 tenglamani yeching.', 'Решите уравнение 2 sin(x/3) + √3 = 0.', 'Solve 2 sin(x/3) + √3 = 0.'), s: L('sin(x/3) = −√3/2. x/3 = (−1)<sup>n</sup>(−π/3) + πn = (−1)<sup>n+1</sup> π/3 + πn. Uchga ko‘paytiramiz: x = (−1)<sup>n+1</sup> π + 3πn.', 'sin(x/3) = −√3/2. x/3 = (−1)<sup>n</sup>(−π/3) + πn = (−1)<sup>n+1</sup> π/3 + πn. Умножаем на 3: x = (−1)<sup>n+1</sup> π + 3πn.', 'sin(x/3) = −√3/2, so x/3 = (−1)<sup>n</sup>(−π/3) + πn = (−1)<sup>n+1</sup> π/3 + πn. Multiplying by 3: x = (−1)<sup>n+1</sup> π + 3πn.') },
      { q: L('cos x = 0,3 tenglamani yeching va [0; 2π] dagi ildizlarni toping.', 'Решите cos x = 0,3 и найдите корни на [0; 2π].', 'Solve cos x = 0.3 and find the roots in [0; 2π].'), s: L('x = ±arccos 0,3 + 2πn. arccos 0,3 ≈ 1,266. [0; 2π] da: x₁ = arccos 0,3 ≈ 1,266 va x₂ = 2π − arccos 0,3 ≈ 5,017.', 'x = ±arccos 0,3 + 2πn. arccos 0,3 ≈ 1,266. На [0; 2π]: x₁ = arccos 0,3 ≈ 1,266 и x₂ = 2π − arccos 0,3 ≈ 5,017.', 'x = ±arccos 0.3 + 2πn, arccos 0.3 ≈ 1.266. In [0; 2π]: x₁ = arccos 0.3 ≈ 1.266 and x₂ = 2π − arccos 0.3 ≈ 5.017.') }
    ] },
    { kind: 'steps', h: L('Oraliqdagi ildizlarni tanlash', 'Отбор корней на промежутке', 'Selecting roots in an interval'), p: [
      L('Ko‘pincha masalada «[a; b] oraliqqa tegishli ildizlarni toping» deyiladi. Buning ikki usuli bor. <b>Birinchi usul — n ni sanash.</b> Masalan, x = π/4 + πn/2 seriyadan [0; π] dagilarni topish uchun 0 ≤ π/4 + πn/2 ≤ π tengsizlikni yechamiz: −1/2 ≤ n ≤ 3/2, ya’ni n = 0 va n = 1. Ildizlar: π/4 va 3π/4.', 'Часто в задаче требуется «найти корни, принадлежащие промежутку [a; b]». Есть два способа. <b>Первый — перебор n.</b> Например, чтобы найти корни серии x = π/4 + πn/2 на [0; π], решаем неравенство 0 ≤ π/4 + πn/2 ≤ π: −1/2 ≤ n ≤ 3/2, то есть n = 0 и n = 1. Корни: π/4 и 3π/4.', 'Problems often ask to “find the roots in the interval [a; b]”. There are two ways. <b>First — counting n.</b> For example, to find the roots of the series x = π/4 + πn/2 in [0; π], solve 0 ≤ π/4 + πn/2 ≤ π: −1/2 ≤ n ≤ 3/2, so n = 0 and n = 1. The roots are π/4 and 3π/4.'),
      L('<b>Ikkinchi usul — birlik aylana.</b> Oraliqni aylanada yoy sifatida belgilaymiz va tenglama nuqtalarining qaysilari shu yoyga tushishini ko‘ramiz. Bu usul tez va ko‘rgazmali, lekin uzun oraliqlarda (bir necha aylanish) birinchi usul ishonchliroq.', '<b>Второй — единичная окружность.</b> Отмечаем промежуток дугой на окружности и смотрим, какие точки решения на неё попадают. Способ быстрый и наглядный, но на длинных промежутках (несколько оборотов) первый способ надёжнее.', '<b>Second — the unit circle.</b> Mark the interval as an arc on the circle and see which solution points fall on it. This is quick and visual, but for long intervals (several turns) the first method is more reliable.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Ikkinchi seriyani yo‘qotish.</b> sin x = 1/2 ning javobi faqat π/6 + 2πn emas — 5π/6 + 2πn ham kerak.', '<b>Терять вторую серию.</b> Ответ sin x = 1/2 — не только π/6 + 2πn, нужна и 5π/6 + 2πn.', '<b>Losing the second series.</b> The answer to sin x = 1/2 is not just π/6 + 2πn — 5π/6 + 2πn is also needed.'),
      L('<b>Davrni noto‘g‘ri yozish.</b> tg x = a uchun +πn, sin va cos uchun +2πn (yoki (−1)<sup>n</sup> formulada πn). cos x = a da ±arccos a + πn deb yozish — xato.', '<b>Неверный период.</b> Для tg x = a — +πn, для sin и cos — +2πn (или πn в формуле с (−1)<sup>n</sup>). Писать ±arccos a + πn для cos x = a — ошибка.', '<b>Wrong period.</b> For tan x = a use +πn; for sin and cos +2πn (or πn in the (−1)<sup>n</sup> formula). Writing ±arccos a + πn for cos x = a is wrong.'),
      L('<b>Argumentga bo‘lishni unutish.</b> cos 3x = 1/2 ⇒ 3x = ±π/3 + 2πn ⇒ x = ±π/9 + 2πn/3. 2πn ni ham 3 ga bo‘lish kerak!', '<b>Забывать делить на коэффициент.</b> cos 3x = 1/2 ⇒ 3x = ±π/3 + 2πn ⇒ x = ±π/9 + 2πn/3. 2πn тоже надо делить на 3!', '<b>Forgetting to divide the period.</b> cos 3x = 1/2 ⇒ 3x = ±π/3 + 2πn ⇒ x = ±π/9 + 2πn/3. 2πn must be divided by 3 too!'),
      L('<b>sin x = 2 ga javob yozish.</b> |a| &gt; 1 da yechim yo‘q; arcsin 2 mavjud emas.', '<b>Писать ответ к sin x = 2.</b> При |a| &gt; 1 решений нет; arcsin 2 не существует.', '<b>Writing an answer to sin x = 2.</b> For |a| &gt; 1 there is no solution; arcsin 2 does not exist.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Astronomiya va kalendar.</b> Quyoshning ufqdan balandligi sin h = sin φ sin δ + cos φ cos δ cos t formulasi bilan topiladi (φ — kenglik, δ — og‘ish, t — soat burchagi). Quyosh chiqish va botish vaqtini topish uchun h = 0 deb cos t = −tg φ tg δ sodda trigonometrik tenglamani yechish kerak. Toshkent (φ ≈ 41,3°) uchun yozgi kun to‘xtashida (δ ≈ 23,4°) cos t ≈ −0,38, t ≈ 112°, ya’ni kun uzunligi 2 · 112° / 15° ≈ 15 soat.', '<b>Астрономия и календарь.</b> Высота Солнца над горизонтом находится по формуле sin h = sin φ sin δ + cos φ cos δ cos t (φ — широта, δ — склонение, t — часовой угол). Чтобы найти время восхода и заката, полагают h = 0 и решают простейшее уравнение cos t = −tg φ tg δ. Для Ташкента (φ ≈ 41,3°) в день летнего солнцестояния (δ ≈ 23,4°) cos t ≈ −0,38, t ≈ 112°, то есть длина дня 2 · 112° / 15° ≈ 15 часов.', '<b>Astronomy and calendars.</b> The Sun’s altitude is given by sin h = sin φ sin δ + cos φ cos δ cos t (φ latitude, δ declination, t hour angle). To find sunrise and sunset, set h = 0 and solve the basic equation cos t = −tan φ tan δ. For Tashkent (φ ≈ 41.3°) at the summer solstice (δ ≈ 23.4°), cos t ≈ −0.38, t ≈ 112°, so the day lasts 2 · 112° / 15° ≈ 15 hours.'),
      L('<b>Fizika.</b> Mayatnik x(t) = A cos(ωt) qonuni bo‘yicha tebransa, u muvozanat holatidan qachon o‘tadi? cos(ωt) = 0 ⇒ t = (π/2 + πn)/ω. <b>Elektrotexnika.</b> O‘zgaruvchan tok kuchlanishi qachon nolga teng bo‘ladi yoki 155 V ga yetadi — bu ham sodda tenglama.', '<b>Физика.</b> Если маятник колеблется по закону x(t) = A cos(ωt), когда он проходит положение равновесия? cos(ωt) = 0 ⇒ t = (π/2 + πn)/ω. <b>Электротехника.</b> Когда напряжение переменного тока равно нулю или достигает 155 В — это тоже простейшее уравнение.', '<b>Physics.</b> If a pendulum moves by x(t) = A cos(ωt), when does it pass the equilibrium point? cos(ωt) = 0 ⇒ t = (π/2 + πn)/ω. <b>Electrical engineering.</b> When AC voltage is zero or reaches 155 V is also a basic equation.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('sin x = x/100 tenglamaning ildizlari soni 63 ta: sinusoida y = x/100 to‘g‘ri chiziq bilan [−100; 100] oraliqda shuncha marta kesishadi.', 'Уравнение sin x = x/100 имеет 63 корня: синусоида столько раз пересекает прямую y = x/100 на [−100; 100].', 'The equation sin x = x/100 has 63 roots: the sine curve crosses the line y = x/100 that many times on [−100; 100].'),
      L('sin x + cos x = 2 tenglamaning yechimi yo‘q, garchi har bir qo‘shiluvchi alohida 1 ga teng bo‘la olsa ham: ular bir vaqtda 1 bo‘lmaydi, yig‘indining eng katta qiymati √2 ≈ 1,41.', 'Уравнение sin x + cos x = 2 не имеет решений, хотя каждое слагаемое по отдельности может равняться 1: одновременно они 1 не бывают, наибольшее значение суммы √2 ≈ 1,41.', 'The equation sin x + cos x = 2 has no solution, although each term on its own can equal 1: they are never 1 at the same time, and the largest value of the sum is √2 ≈ 1.41.'),
      L('Kalkulyator arcsin tugmasi faqat bitta ildizni beradi — qolgan cheksiz ko‘p ildizni sizning formulangiz beradi.', 'Кнопка arcsin на калькуляторе даёт только один корень — бесконечно много остальных даёт ваша формула.', 'The arcsin key on a calculator gives only one root — your formula supplies the infinitely many others.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('cos x = √3/2', 'cos x = √3/2', 'cos x = √3/2'), s: L('x = ±π/6 + 2πn.', 'x = ±π/6 + 2πn.', 'x = ±π/6 + 2πn.') },
      { q: L('tg x = −√3', 'tg x = −√3', 'tan x = −√3'), s: L('x = −π/3 + πn.', 'x = −π/3 + πn.', 'x = −π/3 + πn.') },
      { q: L('sin 2x = 0 ning [0; π] dagi ildizlari', 'Корни sin 2x = 0 на [0; π]', 'Roots of sin 2x = 0 in [0; π]'), s: L('x = πn/2: 0, π/2, π.', 'x = πn/2: 0, π/2, π.', 'x = πn/2: 0, π/2, π.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('cos x = a ⇒ x = ±arccos a + 2πn (|a| ≤ 1).', 'cos x = a ⇒ x = ±arccos a + 2πn (|a| ≤ 1).', 'cos x = a ⇒ x = ±arccos a + 2πn (|a| ≤ 1).'),
      L('sin x = a ⇒ x = (−1)<sup>n</sup> arcsin a + πn (|a| ≤ 1).', 'sin x = a ⇒ x = (−1)<sup>n</sup> arcsin a + πn (|a| ≤ 1).', 'sin x = a ⇒ x = (−1)<sup>n</sup> arcsin a + πn (|a| ≤ 1).'),
      L('tg x = a ⇒ x = arctg a + πn; ctg x = a ⇒ x = arcctg a + πn.', 'tg x = a ⇒ x = arctg a + πn; ctg x = a ⇒ x = arcctg a + πn.', 'tan x = a ⇒ x = arctan a + πn; cot x = a ⇒ x = arccot a + πn.'),
      L('|a| &gt; 1 da sin x = a, cos x = a ning yechimi yo‘q.', 'При |a| &gt; 1 sin x = a, cos x = a не имеют решений.', 'For |a| &gt; 1, sin x = a and cos x = a have no solution.'),
      L('Xususiy holatlar: sin x = 0 ⇒ πn; cos x = 0 ⇒ π/2 + πn; sin x = 1 ⇒ π/2 + 2πn.', 'Частные случаи: sin x = 0 ⇒ πn; cos x = 0 ⇒ π/2 + πn; sin x = 1 ⇒ π/2 + 2πn.', 'Special cases: sin x = 0 ⇒ πn; cos x = 0 ⇒ π/2 + πn; sin x = 1 ⇒ π/2 + 2πn.'),
      L('Oraliqdagi ildizlar n ni sanash yoki birlik aylana yordamida tanlanadi.', 'Корни на промежутке отбирают перебором n или по единичной окружности.', 'Roots in an interval are selected by counting n or using the unit circle.')
    ] }
  ] });

  // ---------- t19. Trigonometrik tenglamalarni yechish usullari. Tengsizliklar ----------
  T.add(P, 't19', { sections: [
    { kind: 'intro', h: L('Murakkabdan soddaga', 'От сложного к простому', 'From complicated to simple'), p: [
      L('Oldingi mavzuda biz sin x = a kabi eng sodda tenglamalarni yechishni o‘rgandik. Amalda esa tenglamalar ancha murakkab ko‘rinishda uchraydi: 2sin²x − 3sin x + 1 = 0, sin 2x = cos x, 3sin²x − 4sin x cos x + cos²x = 0. Ularni yechishning universal formulasi yo‘q, lekin bir necha <b>standart usul</b> bor. Har bir usulning maqsadi bitta — tenglamani bir yoki bir nechta sodda tenglamaga keltirish. Tajribali yechuvchi tenglamaga qarab qaysi usul mosligini darhol ko‘radi.', 'В прошлой теме мы научились решать простейшие уравнения вида sin x = a. На практике уравнения выглядят сложнее: 2sin²x − 3sin x + 1 = 0, sin 2x = cos x, 3sin²x − 4sin x cos x + cos²x = 0. Универсальной формулы для них нет, но есть несколько <b>стандартных методов</b>. Цель каждого одна — свести уравнение к одному или нескольким простейшим. Опытный решатель по виду уравнения сразу видит, какой метод подходит.', 'In the previous topic we learned to solve basic equations like sin x = a. In practice equations look more complicated: 2sin²x − 3sin x + 1 = 0, sin 2x = cos x, 3sin²x − 4sin x cos x + cos²x = 0. There is no universal formula for them, but there are several <b>standard methods</b>. Each aims at the same thing — reducing the equation to one or more basic equations. An experienced solver sees at once which method fits.'),
      L('Mavzuning ikkinchi qismi — <b>trigonometrik tengsizliklar</b>: sin x &gt; 1/2, cos x ≤ −√2/2, tg x &lt; 1. Ularni yechishning eng qulay vositasi — birlik aylana yoki funksiya grafigi.', 'Вторая часть темы — <b>тригонометрические неравенства</b>: sin x &gt; 1/2, cos x ≤ −√2/2, tg x &lt; 1. Удобнее всего их решать на единичной окружности или по графику функции.', 'The second part of the topic is <b>trigonometric inequalities</b>: sin x &gt; 1/2, cos x ≤ −√2/2, tan x &lt; 1. The most convenient tools for them are the unit circle and the graph of the function.')
    ] },
    { kind: 'def', h: L('Asosiy usullar', 'Основные методы', 'Main methods'), list: [
      L('<b>1. Yangi o‘zgaruvchi kiritish.</b> Tenglama bitta funksiyaga nisbatan algebraik bo‘lsa (masalan, sin x ga nisbatan kvadrat), t = sin x deb olinadi va |t| ≤ 1 shart yoziladi.', '<b>1. Введение новой переменной.</b> Если уравнение алгебраическое относительно одной функции (например, квадратное относительно sin x), полагают t = sin x и записывают условие |t| ≤ 1.', '<b>1. New variable.</b> If the equation is algebraic in one function (e.g. quadratic in sin x), set t = sin x and record |t| ≤ 1.'),
      L('<b>2. Bitta funksiyaga keltirish.</b> sin²x = 1 − cos²x yoki cos 2x = 1 − 2sin²x formulalari yordamida tenglama bitta funksiya orqali yoziladi.', '<b>2. Сведение к одной функции.</b> С помощью sin²x = 1 − cos²x или cos 2x = 1 − 2sin²x уравнение записывается через одну функцию.', '<b>2. Reduce to one function.</b> Use sin²x = 1 − cos²x or cos 2x = 1 − 2sin²x to write everything in terms of one function.'),
      L('<b>3. Ko‘paytuvchilarga ajratish.</b> Hamma hadlarni bir tomonga o‘tkazib, ko‘paytma = 0 ko‘rinishiga keltiriladi; har bir ko‘paytuvchi nolga tenglanadi.', '<b>3. Разложение на множители.</b> Все члены переносят в одну сторону и приводят к виду произведение = 0; каждый множитель приравнивают к нулю.', '<b>3. Factorising.</b> Move everything to one side, write it as a product = 0 and set each factor to zero.'),
      L('<b>4. Bir jinsli tenglamalar.</b> a sin x + b cos x = 0 yoki a sin²x + b sin x cos x + c cos²x = 0 — cos x (cos²x) ga bo‘lib, tg x ga nisbatan tenglama olinadi.', '<b>4. Однородные уравнения.</b> a sin x + b cos x = 0 или a sin²x + b sin x cos x + c cos²x = 0 — делят на cos x (cos²x) и получают уравнение относительно tg x.', '<b>4. Homogeneous equations.</b> a sin x + b cos x = 0 or a sin²x + b sin x cos x + c cos²x = 0 — divide by cos x (cos²x) to get an equation in tan x.'),
      L('<b>5. Yordamchi burchak.</b> a sin x + b cos x = √(a² + b²) sin(x + φ), bu yerda cos φ = a/√(a² + b²), sin φ = b/√(a² + b²).', '<b>5. Вспомогательный угол.</b> a sin x + b cos x = √(a² + b²) sin(x + φ), где cos φ = a/√(a² + b²), sin φ = b/√(a² + b²).', '<b>5. Auxiliary angle.</b> a sin x + b cos x = √(a² + b²) sin(x + φ), where cos φ = a/√(a² + b²) and sin φ = b/√(a² + b²).')
    ] },
    { kind: 'history', h: L('Tarixdan: formulalar xazinasi', 'Из истории: сокровищница формул', 'History: a treasury of formulas'), p: [
      L('Qo‘shish formulalari sin(α ± β) va cos(α ± β) ni qadimgi yunon astronomi <b>Klavdiy Ptolemey</b> (II asr) vatarlar ko‘rinishida bilgan. <b>Abul Vafo Buzjoniy</b> (X asr) ularni sinuslar tilida aniq ifodalagan va tangens funksiyasini kiritgan. Bu formulalar trigonometrik tenglamalarni yechishdagi barcha usullarning asosidir: ko‘paytuvchilarga ajratish ham, yordamchi burchak ham, ikki karrali burchak formulalari ham ulardan kelib chiqadi.', 'Формулы сложения sin(α ± β) и cos(α ± β) знал в виде хорд древнегреческий астроном <b>Клавдий Птолемей</b> (II век). <b>Абу-ль-Вафа аль-Бузджани</b> (X век) точно выразил их на языке синусов и ввёл функцию тангенс. Эти формулы — основа всех методов решения тригонометрических уравнений: и разложение на множители, и вспомогательный угол, и формулы двойного угла вытекают из них.', 'The addition formulas for sin(α ± β) and cos(α ± β) were known as chord rules to the Greek astronomer <b>Claudius Ptolemy</b> (2nd century). <b>Abu al-Wafa al-Buzjani</b> (10th century) stated them exactly in terms of sines and introduced the tangent function. These formulas underlie every method for trigonometric equations: factorising, the auxiliary angle and the double-angle formulas all follow from them.'),
      L('XVI asrda fransuz matematigi <b>Fransua Viyet</b> ko‘p karrali burchaklar formulalarini (sin nx, cos nx) chiqardi va ular yordamida 45-darajali tenglamani yechib, butun Yevropani hayratga soldi.', 'В XVI веке французский математик <b>Франсуа Виет</b> вывел формулы кратных углов (sin nx, cos nx) и с их помощью решил уравнение 45-й степени, поразив всю Европу.', 'In the 16th century the French mathematician <b>François Viète</b> derived multiple-angle formulas (sin nx, cos nx) and used them to solve an equation of degree 45, astonishing all of Europe.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: tenglamalar', 'Решённые примеры: уравнения', 'Worked examples: equations'), ex: [
      { q: L('2cos²x + 3sin x − 3 = 0 tenglamani yeching.', 'Решите уравнение 2cos²x + 3sin x − 3 = 0.', 'Solve 2cos²x + 3sin x − 3 = 0.'), s: L('cos²x = 1 − sin²x: 2 − 2sin²x + 3sin x − 3 = 0 ⇒ 2sin²x − 3sin x + 1 = 0. t = sin x: t = 1 yoki t = 1/2. sin x = 1 ⇒ x = π/2 + 2πn; sin x = 1/2 ⇒ x = (−1)<sup>n</sup> π/6 + πn.', 'cos²x = 1 − sin²x: 2 − 2sin²x + 3sin x − 3 = 0 ⇒ 2sin²x − 3sin x + 1 = 0. t = sin x: t = 1 или t = 1/2. sin x = 1 ⇒ x = π/2 + 2πn; sin x = 1/2 ⇒ x = (−1)<sup>n</sup> π/6 + πn.', 'cos²x = 1 − sin²x: 2 − 2sin²x + 3sin x − 3 = 0 ⇒ 2sin²x − 3sin x + 1 = 0. With t = sin x: t = 1 or t = 1/2. sin x = 1 ⇒ x = π/2 + 2πn; sin x = 1/2 ⇒ x = (−1)<sup>n</sup> π/6 + πn.') },
      { q: L('sin 2x = cos x tenglamani yeching.', 'Решите уравнение sin 2x = cos x.', 'Solve sin 2x = cos x.'), s: L('2sin x cos x − cos x = 0 ⇒ cos x(2sin x − 1) = 0. cos x = 0 ⇒ x = π/2 + πn; sin x = 1/2 ⇒ x = (−1)<sup>n</sup> π/6 + πn. cos x ga bo‘lib yubormaganimiz uchun hech qaysi ildiz yo‘qolmadi.', '2sin x cos x − cos x = 0 ⇒ cos x(2sin x − 1) = 0. cos x = 0 ⇒ x = π/2 + πn; sin x = 1/2 ⇒ x = (−1)<sup>n</sup> π/6 + πn. Мы не делили на cos x, поэтому корни не потеряны.', '2sin x cos x − cos x = 0 ⇒ cos x(2sin x − 1) = 0. cos x = 0 ⇒ x = π/2 + πn; sin x = 1/2 ⇒ x = (−1)<sup>n</sup> π/6 + πn. We did not divide by cos x, so no roots were lost.') },
      { q: L('sin²x − 4sin x cos x + 3cos²x = 0 tenglamani yeching.', 'Решите уравнение sin²x − 4sin x cos x + 3cos²x = 0.', 'Solve sin²x − 4sin x cos x + 3cos²x = 0.'), s: L('Bir jinsli. cos x = 0 bo‘lsa, sin²x = 0 ham bo‘lishi kerak — bu mumkin emas, shuning uchun cos²x ga bo‘lish xavfsiz: tg²x − 4tg x + 3 = 0 ⇒ tg x = 1 yoki tg x = 3. x = π/4 + πn; x = arctg 3 + πn.', 'Однородное. Если cos x = 0, то и sin²x = 0 — невозможно, поэтому делить на cos²x безопасно: tg²x − 4tg x + 3 = 0 ⇒ tg x = 1 или tg x = 3. x = π/4 + πn; x = arctg 3 + πn.', 'Homogeneous. If cos x = 0 then sin²x = 0 too — impossible, so dividing by cos²x is safe: tan²x − 4tan x + 3 = 0 ⇒ tan x = 1 or tan x = 3. x = π/4 + πn; x = arctan 3 + πn.') },
      { q: L('sin x + √3 cos x = 1 tenglamani yeching.', 'Решите уравнение sin x + √3 cos x = 1.', 'Solve sin x + √3 cos x = 1.'), s: L('√(1 + 3) = 2. Ikkiga bo‘lamiz: (1/2)sin x + (√3/2)cos x = 1/2 ⇒ sin(x + π/3) = 1/2. x + π/3 = (−1)<sup>n</sup> π/6 + πn ⇒ x = (−1)<sup>n</sup> π/6 − π/3 + πn.', '√(1 + 3) = 2. Делим на 2: (1/2)sin x + (√3/2)cos x = 1/2 ⇒ sin(x + π/3) = 1/2. x + π/3 = (−1)<sup>n</sup> π/6 + πn ⇒ x = (−1)<sup>n</sup> π/6 − π/3 + πn.', '√(1 + 3) = 2. Divide by 2: (1/2)sin x + (√3/2)cos x = 1/2 ⇒ sin(x + π/3) = 1/2. x + π/3 = (−1)<sup>n</sup> π/6 + πn ⇒ x = (−1)<sup>n</sup> π/6 − π/3 + πn.') }
    ] },
    { kind: 'rule', h: L('Trigonometrik tengsizliklar', 'Тригонометрические неравенства', 'Trigonometric inequalities'), p: [
      L('sin x &gt; a ko‘rinishidagi tengsizlikni yechish uchun birlik aylanada y = a gorizontal to‘g‘ri chiziq chiziladi. Undan yuqoridagi yoy sin x &gt; a ga mos keladi. Yoyning uchlari arcsin a va π − arcsin a; yoyni soat strelkasiga qarshi yo‘nalishda o‘qiymiz: <b>arcsin a + 2πn &lt; x &lt; π − arcsin a + 2πn</b>.', 'Чтобы решить неравенство вида sin x &gt; a, на единичной окружности проводят горизонтальную прямую y = a. Дуга выше неё соответствует sin x &gt; a. Концы дуги — arcsin a и π − arcsin a; дугу читаем против часовой стрелки: <b>arcsin a + 2πn &lt; x &lt; π − arcsin a + 2πn</b>.', 'To solve sin x &gt; a, draw the horizontal line y = a on the unit circle. The arc above it corresponds to sin x &gt; a. Its endpoints are arcsin a and π − arcsin a; reading anticlockwise gives <b>arcsin a + 2πn &lt; x &lt; π − arcsin a + 2πn</b>.'),
      L('cos x &gt; a uchun vertikal x = a to‘g‘ri chiziqdan o‘ngdagi yoy olinadi: <b>−arccos a + 2πn &lt; x &lt; arccos a + 2πn</b>. tg x &gt; a uchun tangenslar chizig‘idan foydalaniladi: <b>arctg a + πn &lt; x &lt; π/2 + πn</b>. Muhim qoida: yoyning chap uchi o‘ng uchidan kichik bo‘lishi kerak — aks holda chap uchdan 2π ayiriladi.', 'Для cos x &gt; a берут дугу правее вертикальной прямой x = a: <b>−arccos a + 2πn &lt; x &lt; arccos a + 2πn</b>. Для tg x &gt; a используют линию тангенсов: <b>arctg a + πn &lt; x &lt; π/2 + πn</b>. Важное правило: левый конец дуги должен быть меньше правого — иначе из левого конца вычитают 2π.', 'For cos x &gt; a take the arc to the right of the vertical line x = a: <b>−arccos a + 2πn &lt; x &lt; arccos a + 2πn</b>. For tan x &gt; a use the tangent line: <b>arctan a + πn &lt; x &lt; π/2 + πn</b>. Key rule: the left end of the arc must be smaller than the right end — otherwise subtract 2π from the left end.')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: tengsizliklar', 'Решённые примеры: неравенства', 'Worked examples: inequalities'), ex: [
      { q: L('sin x ≥ √2/2 tengsizlikni yeching.', 'Решите неравенство sin x ≥ √2/2.', 'Solve sin x ≥ √2/2.'), s: L('arcsin(√2/2) = π/4, π − π/4 = 3π/4. Javob: π/4 + 2πn ≤ x ≤ 3π/4 + 2πn.', 'arcsin(√2/2) = π/4, π − π/4 = 3π/4. Ответ: π/4 + 2πn ≤ x ≤ 3π/4 + 2πn.', 'arcsin(√2/2) = π/4 and π − π/4 = 3π/4. Answer: π/4 + 2πn ≤ x ≤ 3π/4 + 2πn.') },
      { q: L('cos x &lt; 1/2 tengsizlikni yeching.', 'Решите неравенство cos x &lt; 1/2.', 'Solve cos x &lt; 1/2.'), s: L('x = 1/2 chiziqdan chapdagi yoy: π/3 dan 2π − π/3 = 5π/3 gacha. Javob: π/3 + 2πn &lt; x &lt; 5π/3 + 2πn.', 'Дуга левее прямой x = 1/2: от π/3 до 2π − π/3 = 5π/3. Ответ: π/3 + 2πn &lt; x &lt; 5π/3 + 2πn.', 'The arc to the left of x = 1/2 runs from π/3 to 2π − π/3 = 5π/3. Answer: π/3 + 2πn &lt; x &lt; 5π/3 + 2πn.') },
      { q: L('tg x ≤ √3 tengsizlikni yeching.', 'Решите неравенство tg x ≤ √3.', 'Solve tan x ≤ √3.'), s: L('Bir davr (−π/2; π/2) ichida tangens o‘suvchi: −π/2 &lt; x ≤ arctg √3 = π/3. Javob: −π/2 + πn &lt; x ≤ π/3 + πn.', 'На одном периоде (−π/2; π/2) тангенс возрастает: −π/2 &lt; x ≤ arctg √3 = π/3. Ответ: −π/2 + πn &lt; x ≤ π/3 + πn.', 'On one period (−π/2; π/2) tangent increases: −π/2 &lt; x ≤ arctan √3 = π/3. Answer: −π/2 + πn &lt; x ≤ π/3 + πn.') },
      { q: L('2sin²x − sin x &lt; 0 tengsizlikni yeching.', 'Решите неравенство 2sin²x − sin x &lt; 0.', 'Solve 2sin²x − sin x &lt; 0.'), s: L('sin x(2sin x − 1) &lt; 0 ⇒ 0 &lt; sin x &lt; 1/2. Aylanada ikki yoy: 2πn &lt; x &lt; π/6 + 2πn va 5π/6 + 2πn &lt; x &lt; π + 2πn.', 'sin x(2sin x − 1) &lt; 0 ⇒ 0 &lt; sin x &lt; 1/2. На окружности две дуги: 2πn &lt; x &lt; π/6 + 2πn и 5π/6 + 2πn &lt; x &lt; π + 2πn.', 'sin x(2sin x − 1) &lt; 0 ⇒ 0 &lt; sin x &lt; 1/2. On the circle there are two arcs: 2πn &lt; x &lt; π/6 + 2πn and 5π/6 + 2πn &lt; x &lt; π + 2πn.') }
    ] },
    { kind: 'steps', h: L('Usulni qanday tanlash kerak', 'Как выбрать метод', 'How to choose a method'), list: [
      L('1. Tenglamada turli argumentlar (x, 2x, x/2) bormi? Bo‘lsa, ikki karrali yoki yarim burchak formulalari bilan bitta argumentga keltiring.', '1. Есть ли разные аргументы (x, 2x, x/2)? Если да, приведите к одному аргументу формулами двойного или половинного угла.', '1. Are there different arguments (x, 2x, x/2)? If so, bring them to one with double- or half-angle formulas.'),
      L('2. Faqat bitta funksiya (yoki sin² + cos² = 1 orqali almashtiriladigan) qoldimi? — yangi o‘zgaruvchi.', '2. Осталась одна функция (или заменяемая через sin² + cos² = 1)? — новая переменная.', '2. Is only one function left (or replaceable via sin² + cos² = 1)? — new variable.'),
      L('3. Barcha hadlarning darajasi bir xilmi (sin² , sin cos, cos²)? — bir jinsli, cos ga bo‘ling.', '3. Все члены одной степени (sin², sin cos, cos²)? — однородное, делите на cos.', '3. Are all terms of the same degree (sin², sin cos, cos²)? — homogeneous, divide by cos.'),
      L('4. Umumiy ko‘paytuvchi ko‘rinyaptimi? — qavsdan chiqaring, hech narsaga bo‘lmang.', '4. Виден общий множитель? — выносите за скобки, ни на что не делите.', '4. Is there a common factor? — factor it out, never divide by it.'),
      L('5. a sin x + b cos x = c? — yordamchi burchak.', '5. a sin x + b cos x = c? — вспомогательный угол.', '5. a sin x + b cos x = c? — auxiliary angle.')
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Umumiy ko‘paytuvchiga bo‘lish.</b> sin 2x = cos x ni cos x ga bo‘lsak, cos x = 0 dagi ildizlar (π/2 + πn) yo‘qoladi.', '<b>Деление на общий множитель.</b> Если разделить sin 2x = cos x на cos x, потеряются корни cos x = 0 (π/2 + πn).', '<b>Dividing by a common factor.</b> Dividing sin 2x = cos x by cos x loses the roots of cos x = 0 (π/2 + πn).'),
      L('<b>|t| ≤ 1 shartini unutish.</b> sin²x + sin x − 2 = 0 dan t = −2 chiqadi — u tashlanadi, faqat sin x = 1 qoladi.', '<b>Забывать условие |t| ≤ 1.</b> Из sin²x + sin x − 2 = 0 получается t = −2 — его отбрасывают, остаётся только sin x = 1.', '<b>Forgetting |t| ≤ 1.</b> sin²x + sin x − 2 = 0 gives t = −2, which is rejected; only sin x = 1 remains.'),
      L('<b>Tengsizlikda yoyni noto‘g‘ri yo‘nalishda o‘qish.</b> cos x &lt; 1/2 uchun 5π/3 &lt; x &lt; π/3 yozish xato — chap uch kichik bo‘lishi kerak.', '<b>Читать дугу не в ту сторону.</b> Для cos x &lt; 1/2 писать 5π/3 &lt; x &lt; π/3 неверно — левый конец должен быть меньше.', '<b>Reading the arc the wrong way.</b> For cos x &lt; 1/2, writing 5π/3 &lt; x &lt; π/3 is wrong — the left end must be smaller.'),
      L('<b>Kvadratga ko‘tarishda begona ildizlar.</b> sin x + cos x = 1 ni kvadratga ko‘tarsak, sin 2x = 0 hosil bo‘ladi va x = π kabi begona ildizlar paydo bo‘ladi — tekshirish shart.', '<b>Посторонние корни при возведении в квадрат.</b> Если возвести sin x + cos x = 1 в квадрат, получится sin 2x = 0, и появятся посторонние корни вроде x = π — нужна проверка.', '<b>Extraneous roots from squaring.</b> Squaring sin x + cos x = 1 gives sin 2x = 0 and introduces extraneous roots such as x = π — checking is essential.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Quyosh panellari.</b> Panel samarali ishlashi uchun Quyosh balandligi ma’lum burchakdan katta bo‘lishi kerak: sin h ≥ 0,5 tengsizlik Quyosh 30° dan baland bo‘lgan vaqt oralig‘ini beradi. O‘zbekistonda quyosh elektr stansiyalarini loyihalashda aynan shunday hisoblar qilinadi. <b>Arxitektura.</b> Derazalar va soyabonlarni shunday joylashtirish kerakki, yozda Quyosh nurlari xonaga kirmasin, qishda esa kirsin — bu trigonometrik tengsizliklar sistemasi.', '<b>Солнечные панели.</b> Чтобы панель работала эффективно, высота Солнца должна превышать некоторый угол: неравенство sin h ≥ 0,5 даёт промежуток времени, когда Солнце выше 30°. Именно такие расчёты делают при проектировании солнечных электростанций в Узбекистане. <b>Архитектура.</b> Окна и навесы располагают так, чтобы летом солнечные лучи не попадали в комнату, а зимой попадали, — это система тригонометрических неравенств.', '<b>Solar panels.</b> For a panel to work efficiently, the Sun must be above a certain angle: the inequality sin h ≥ 0.5 gives the time interval when the Sun is higher than 30°. Exactly such calculations are made when designing solar power plants in Uzbekistan. <b>Architecture.</b> Windows and awnings are placed so that summer sunlight stays out and winter sunlight comes in — a system of trigonometric inequalities.'),
      L('<b>Signal ishlovi.</b> Ikki tebranish qo‘shilganda a sin ωt + b cos ωt = R sin(ωt + φ) — yordamchi burchak usuli muhandislar uchun kundalik vosita: u natijaviy amplituda R = √(a² + b²) va faza siljishini beradi.', '<b>Обработка сигналов.</b> При сложении двух колебаний a sin ωt + b cos ωt = R sin(ωt + φ) — метод вспомогательного угла для инженеров повседневный инструмент: он даёт результирующую амплитуду R = √(a² + b²) и сдвиг фазы.', '<b>Signal processing.</b> Adding two oscillations gives a sin ωt + b cos ωt = R sin(ωt + φ) — the auxiliary angle is an everyday tool for engineers: it gives the resulting amplitude R = √(a² + b²) and the phase shift.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('sin x = cos x', 'sin x = cos x', 'sin x = cos x'), s: L('tg x = 1 ⇒ x = π/4 + πn.', 'tg x = 1 ⇒ x = π/4 + πn.', 'tan x = 1 ⇒ x = π/4 + πn.') },
      { q: L('cos²x − cos x = 0', 'cos²x − cos x = 0', 'cos²x − cos x = 0'), s: L('cos x = 0 ⇒ π/2 + πn; cos x = 1 ⇒ 2πn.', 'cos x = 0 ⇒ π/2 + πn; cos x = 1 ⇒ 2πn.', 'cos x = 0 ⇒ π/2 + πn; cos x = 1 ⇒ 2πn.') },
      { q: L('sin x &lt; 0', 'sin x &lt; 0', 'sin x &lt; 0'), s: L('π + 2πn &lt; x &lt; 2π + 2πn.', 'π + 2πn &lt; x &lt; 2π + 2πn.', 'π + 2πn &lt; x &lt; 2π + 2πn.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Har qanday usulning maqsadi — sodda tenglamalarga keltirish.', 'Цель любого метода — свести к простейшим уравнениям.', 'Every method aims to reduce to basic equations.'),
      L('Yangi o‘zgaruvchi: t = sin x yoki t = cos x, |t| ≤ 1.', 'Новая переменная: t = sin x или t = cos x, |t| ≤ 1.', 'New variable: t = sin x or t = cos x, |t| ≤ 1.'),
      L('Ko‘paytuvchilarga ajrating, lekin noma’lum qatnashgan ifodaga bo‘lmang.', 'Раскладывайте на множители, но не делите на выражение с неизвестным.', 'Factorise, but never divide by an expression containing the unknown.'),
      L('Bir jinsli tenglama: cos x yoki cos²x ga bo‘lib, tg x ga keltiring.', 'Однородное уравнение: делите на cos x или cos²x и переходите к tg x.', 'Homogeneous equation: divide by cos x or cos²x and pass to tan x.'),
      L('a sin x + b cos x = √(a² + b²) sin(x + φ).', 'a sin x + b cos x = √(a² + b²) sin(x + φ).', 'a sin x + b cos x = √(a² + b²) sin(x + φ).'),
      L('Tengsizliklar birlik aylanada: yoyni soat strelkasiga qarshi o‘qing, chap uch &lt; o‘ng uch.', 'Неравенства — на единичной окружности: дугу читаем против часовой стрелки, левый конец &lt; правого.', 'Inequalities on the unit circle: read the arc anticlockwise, left end &lt; right end.')
    ] }
  ] });

  // ---------- t20. Tasodifiy hodisalar. Ehtimollik ta’riflari ----------
  T.add(P, 't20', { sections: [
    { kind: 'intro', h: L('Tasodifning ham qonuni bor', 'У случайности тоже есть законы', 'Chance has laws too'), p: [
      L('Tangani tashlaganda gerb tushadimi yoki raqam — oldindan aytib bo‘lmaydi. Ertaga yomg‘ir yog‘adimi? Lotereya chiptasi yutadimi? Bunday hodisalar <b>tasodifiy</b> deyiladi. Bir qarashda tasodif — tartibsizlik. Lekin tangani 1000 marta tashlasak, gerb taxminan 500 marta tushadi. Ko‘p takrorlanganda tasodifiy hodisalar barqaror qonuniyatlarga bo‘ysunadi. Bu qonuniyatlarni o‘rganadigan fan <b>ehtimollar nazariyasi</b> deyiladi.', 'При броске монеты нельзя заранее сказать, выпадет герб или цифра. Будет ли завтра дождь? Выиграет ли лотерейный билет? Такие события называются <b>случайными</b>. На первый взгляд случайность — это беспорядок. Но если бросить монету 1000 раз, герб выпадет примерно 500 раз. При многократном повторении случайные события подчиняются устойчивым закономерностям. Наука, изучающая их, называется <b>теорией вероятностей</b>.', 'When you toss a coin you cannot say in advance whether it lands heads or tails. Will it rain tomorrow? Will a lottery ticket win? Such events are called <b>random</b>. At first glance chance is disorder. But toss a coin 1000 times and heads appears about 500 times. Repeated many times, random events obey stable patterns. The science that studies them is <b>probability theory</b>.'),
      L('Bu mavzuda tasodifiy hodisa, elementar natija, muqarrar va mumkin bo‘lmagan hodisa tushunchalari bilan tanishamiz, ehtimollikning uchta ta’rifini — klassik, statistik va geometrik — o‘rganamiz hamda hodisalar ustida amallar va qo‘shish, ko‘paytirish qoidalarini ko‘rib chiqamiz.', 'В этой теме мы познакомимся с понятиями случайного события, элементарного исхода, достоверного и невозможного события, изучим три определения вероятности — классическое, статистическое и геометрическое — и рассмотрим действия над событиями и правила сложения и умножения.', 'In this topic we meet random events, elementary outcomes, certain and impossible events, study three definitions of probability — classical, statistical and geometric — and look at operations on events and the addition and multiplication rules.')
    ] },
    { kind: 'def', h: L('Asosiy tushunchalar', 'Основные понятия', 'Key ideas'), list: [
      L('<b>Tajriba (sinov)</b> — natijasi oldindan ma’lum bo‘lmagan harakat: kubik tashlash, kartani tortish.', '<b>Опыт (испытание)</b> — действие с заранее неизвестным результатом: бросок кубика, вытягивание карты.', 'An <b>experiment (trial)</b> is an action whose result is not known in advance: rolling a die, drawing a card.'),
      L('<b>Elementar natijalar</b> — tajribaning bo‘linmas, bir-birini istisno qiluvchi natijalari. Kubik uchun: 1, 2, 3, 4, 5, 6. Ularning to‘plami Ω.', '<b>Элементарные исходы</b> — неделимые, взаимоисключающие результаты опыта. Для кубика: 1, 2, 3, 4, 5, 6. Их множество — Ω.', '<b>Elementary outcomes</b> are the indivisible, mutually exclusive results. For a die: 1, 2, 3, 4, 5, 6. Their set is Ω.'),
      L('<b>Hodisa</b> — elementar natijalar to‘plami. «Juft son tushdi» = {2, 4, 6}.', '<b>Событие</b> — множество элементарных исходов. «Выпало чётное» = {2, 4, 6}.', 'An <b>event</b> is a set of outcomes. “An even number” = {2, 4, 6}.'),
      L('<b>Muqarrar hodisa</b> (Ω) — albatta ro‘y beradi, P = 1. <b>Mumkin bo‘lmagan hodisa</b> (∅) — hech qachon ro‘y bermaydi, P = 0.', '<b>Достоверное событие</b> (Ω) — обязательно происходит, P = 1. <b>Невозможное</b> (∅) — никогда не происходит, P = 0.', 'A <b>certain event</b> (Ω) always happens, P = 1. An <b>impossible event</b> (∅) never happens, P = 0.'),
      L('<b>Qarama-qarshi hodisa</b> Ā — A ro‘y bermasligi. <b>Birgalikda bo‘lmagan</b> hodisalar bir vaqtda ro‘y bera olmaydi. <b>Bog‘liq bo‘lmagan</b> hodisalarda birining ro‘y berishi ikkinchisining ehtimolini o‘zgartirmaydi.', '<b>Противоположное событие</b> Ā — A не произошло. <b>Несовместные</b> события не могут произойти одновременно. У <b>независимых</b> событий наступление одного не меняет вероятности другого.', 'The <b>complement</b> Ā means A did not happen. <b>Mutually exclusive</b> events cannot happen together. For <b>independent</b> events one happening does not change the probability of the other.')
    ] },
    { kind: 'history', h: L('Tarixdan: qimor o‘yinidan fanga', 'Из истории: от азартной игры к науке', 'History: from gambling to science'), p: [
      L('Ehtimollar nazariyasi 1654-yilda tug‘ildi deyish mumkin. Fransuz zodagoni shevalye de Mere <b>Blez Paskal</b>ga savol berdi: to‘xtatilgan o‘yinda pul tikishni qanday adolatli taqsimlash kerak? Paskal bu haqda <b>Pyer Ferma</b> bilan yozishmalar olib bordi va ular birgalikda ehtimollik hisobining asoslarini yaratishdi. 1657-yilda gollandiyalik <b>Kristian Gyuygens</b> bu mavzudagi birinchi kitobni nashr etdi.', 'Можно сказать, что теория вероятностей родилась в 1654 году. Французский дворянин шевалье де Мере задал <b>Блезу Паскалю</b> вопрос: как справедливо разделить ставку в прерванной игре? Паскаль переписывался об этом с <b>Пьером Ферма</b>, и вместе они заложили основы исчисления вероятностей. В 1657 году голландец <b>Христиан Гюйгенс</b> издал первую книгу на эту тему.', 'Probability theory can be said to have been born in 1654. The French nobleman Chevalier de Méré asked <b>Blaise Pascal</b> how to divide the stakes fairly in an interrupted game. Pascal corresponded with <b>Pierre de Fermat</b>, and together they laid the foundations of probability. In 1657 the Dutchman <b>Christiaan Huygens</b> published the first book on the subject.'),
      L('1713-yilda <b>Yakob Bernulli</b>ning «Taxmin qilish san’ati» kitobida katta sonlar qonuni isbotlandi: ko‘p tajribada nisbiy chastota ehtimollikka yaqinlashadi. 1933-yilda rus matematigi <b>Andrey Kolmogorov</b> ehtimollar nazariyasini aksiomalar asosida qurdi va u to‘laqonli matematik fanga aylandi. O‘zbekistonda bu sohada akademik <b>Toshmuhammad Sarimsoqov</b> va <b>Sa’di Sirojiddinov</b> mashhur maktab yaratishgan.', 'В 1713 году в книге <b>Якоба Бернулли</b> «Искусство предположений» был доказан закон больших чисел: при многих опытах относительная частота приближается к вероятности. В 1933 году русский математик <b>Андрей Колмогоров</b> построил теорию вероятностей на аксиомах, и она стала полноценной математической наукой. В Узбекистане академики <b>Ташмухамед Сарымсаков</b> и <b>Саъди Сираждинов</b> создали в этой области известную школу.', 'In 1713 <b>Jacob Bernoulli’s</b> “The Art of Conjecturing” proved the law of large numbers: over many trials the relative frequency approaches the probability. In 1933 the Russian mathematician <b>Andrey Kolmogorov</b> built probability theory on axioms, making it a full mathematical science. In Uzbekistan the academicians <b>Tashmukhamed Sarymsakov</b> and <b>Sa’di Sirazhdinov</b> founded a well-known school in this field.')
    ] },
    { kind: 'rule', h: L('Ehtimollikning uch ta’rifi', 'Три определения вероятности', 'Three definitions of probability'), p: [
      L('<b>Klassik ta’rif.</b> Agar tajriba n ta teng imkoniyatli elementar natijaga ega bo‘lsa va ulardan m tasi A hodisaga qulay bo‘lsa, <b>P(A) = m/n</b>. Masalan, kubikda 5 dan katta son tushish ehtimoli: qulay natija bitta (6), P = 1/6.', '<b>Классическое определение.</b> Если опыт имеет n равновозможных исходов и m из них благоприятствуют событию A, то <b>P(A) = m/n</b>. Например, вероятность выпадения числа больше 5 на кубике: благоприятный исход один (6), P = 1/6.', '<b>Classical definition.</b> If an experiment has n equally likely outcomes and m of them favour event A, then <b>P(A) = m/n</b>. For example, the probability of rolling more than 5: one favourable outcome (6), P = 1/6.'),
      L('<b>Statistik ta’rif.</b> Agar n ta tajribada A hodisa m marta ro‘y bergan bo‘lsa, W = m/n — <b>nisbiy chastota</b>. Tajribalar soni ortgan sari W biror son atrofida barqarorlashadi; shu son A ning ehtimoli deb olinadi. Bu ta’rif natijalar teng imkoniyatli bo‘lmaganda ham ishlaydi (masalan, chaqaloqning o‘g‘il bo‘lish ehtimoli ≈ 0,512).', '<b>Статистическое определение.</b> Если в n опытах событие A произошло m раз, W = m/n — <b>относительная частота</b>. С ростом числа опытов W стабилизируется около некоторого числа; оно и принимается за вероятность A. Это определение работает и при неравновозможных исходах (например, вероятность рождения мальчика ≈ 0,512).', '<b>Statistical definition.</b> If A happened m times in n trials, W = m/n is the <b>relative frequency</b>. As the number of trials grows, W settles near some number, which is taken as the probability of A. This works even when outcomes are not equally likely (e.g. the probability of a newborn being a boy ≈ 0.512).'),
      L('<b>Geometrik ta’rif.</b> Agar natijalar cheksiz ko‘p bo‘lib, biror sohada (kesma, figura, jism) teng taqsimlangan bo‘lsa, <b>P(A) = qulay soha o‘lchovi / butun soha o‘lchovi</b> (uzunlik, yuz yoki hajm).', '<b>Геометрическое определение.</b> Если исходов бесконечно много и они равномерно распределены в некоторой области (отрезок, фигура, тело), то <b>P(A) = мера благоприятной области / мера всей области</b> (длина, площадь или объём).', '<b>Geometric definition.</b> If there are infinitely many outcomes spread uniformly over a region (segment, figure, solid), then <b>P(A) = measure of the favourable region / measure of the whole region</b> (length, area or volume).')
    ] },
    { kind: 'table', h: L('Hodisalar ustida amallar va qoidalar', 'Действия над событиями и правила', 'Operations on events and rules'), table: {
      head: [L('Amal', 'Действие', 'Operation'), L('Ma’nosi', 'Смысл', 'Meaning'), L('Qoida', 'Правило', 'Rule')],
      rows: [
        [L('Ā', 'Ā', 'Ā'), L('A ro‘y bermadi', 'A не произошло', 'A did not happen'), L('P(Ā) = 1 − P(A)', 'P(Ā) = 1 − P(A)', 'P(Ā) = 1 − P(A)')],
        [L('A ∪ B (yig‘indi)', 'A ∪ B (сумма)', 'A ∪ B (union)'), L('A yoki B (kamida bittasi)', 'A или B (хотя бы одно)', 'A or B (at least one)'), L('P(A) + P(B) − P(A ∩ B)', 'P(A) + P(B) − P(A ∩ B)', 'P(A) + P(B) − P(A ∩ B)')],
        [L('A ∪ B, birgalikda emas', 'A ∪ B, несовместные', 'A ∪ B, exclusive'), L('A va B bir vaqtda bo‘lmaydi', 'A и B не одновременно', 'A and B never together'), L('P(A) + P(B)', 'P(A) + P(B)', 'P(A) + P(B)')],
        [L('A ∩ B (ko‘paytma)', 'A ∩ B (произведение)', 'A ∩ B (intersection)'), L('A va B ikkalasi', 'и A, и B', 'both A and B'), L('bog‘liq emas: P(A) · P(B)', 'независимые: P(A) · P(B)', 'independent: P(A) · P(B)')]
      ] }, after: [
      L('Har qanday hodisa uchun 0 ≤ P(A) ≤ 1. Ko‘pincha «kamida bitta» so‘zli masalalarni qarama-qarshi hodisa orqali yechish oson: P(kamida bitta) = 1 − P(birorta ham emas).', 'Для любого события 0 ≤ P(A) ≤ 1. Задачи со словами «хотя бы один» часто проще решать через противоположное событие: P(хотя бы один) = 1 − P(ни одного).', 'For any event 0 ≤ P(A) ≤ 1. Problems with “at least one” are often easiest via the complement: P(at least one) = 1 − P(none).')
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: klassik ta’rif', 'Решённые примеры: классическое определение', 'Worked examples: classical definition'), ex: [
      { q: L('Ikki kubik tashlandi. Tushgan ochkolar yig‘indisi 8 ga teng bo‘lish ehtimolini toping.', 'Брошены два кубика. Найдите вероятность того, что сумма очков равна 8.', 'Two dice are rolled. Find the probability that the total is 8.'), s: L('Barcha natijalar 6 · 6 = 36. Qulaylari: (2;6), (3;5), (4;4), (5;3), (6;2) — 5 ta. P = 5/36 ≈ 0,139.', 'Всего исходов 6 · 6 = 36. Благоприятные: (2;6), (3;5), (4;4), (5;3), (6;2) — 5. P = 5/36 ≈ 0,139.', 'There are 6 · 6 = 36 outcomes. Favourable: (2;6), (3;5), (4;4), (5;3), (6;2) — 5 of them. P = 5/36 ≈ 0.139.') },
      { q: L('Qutida 7 ta oq va 3 ta qora shar bor. Tavakkaliga 2 ta shar olinadi. Ikkalasi ham oq bo‘lish ehtimoli?', 'В коробке 7 белых и 3 чёрных шара. Наугад берут 2 шара. Какова вероятность, что оба белые?', 'A box holds 7 white and 3 black balls. Two are drawn at random. What is the probability both are white?'), s: L('Barcha usullar C(10; 2) = 45, qulaylari C(7; 2) = 21. P = 21/45 = 7/15 ≈ 0,467. Boshqacha: (7/10) · (6/9) = 42/90 = 7/15.', 'Всего способов C(10; 2) = 45, благоприятных C(7; 2) = 21. P = 21/45 = 7/15 ≈ 0,467. Иначе: (7/10) · (6/9) = 42/90 = 7/15.', 'Total ways C(10, 2) = 45, favourable C(7, 2) = 21. P = 21/45 = 7/15 ≈ 0.467. Alternatively (7/10) · (6/9) = 42/90 = 7/15.') },
      { q: L('Tanga 3 marta tashlandi. Kamida bir marta gerb tushish ehtimoli?', 'Монету бросили 3 раза. Какова вероятность хотя бы одного герба?', 'A coin is tossed 3 times. What is the probability of at least one head?'), s: L('Qarama-qarshi hodisa — uch marta raqam: (1/2)³ = 1/8. P = 1 − 1/8 = 7/8.', 'Противоположное событие — три раза цифра: (1/2)³ = 1/8. P = 1 − 1/8 = 7/8.', 'The complement is three tails: (1/2)³ = 1/8. P = 1 − 1/8 = 7/8.') }
    ] },
    { kind: 'example', h: L('Yechilgan namunalar: geometrik va statistik', 'Решённые примеры: геометрическое и статистическое', 'Worked examples: geometric and statistical'), ex: [
      { q: L('Tomoni 10 sm bo‘lgan kvadrat nishonga tavakkaliga nuqta tushadi. U kvadrat ichiga chizilgan doiraga tushish ehtimoli?', 'В квадратную мишень со стороной 10 см наугад попадает точка. Какова вероятность попасть во вписанный круг?', 'A point lands at random in a square target of side 10 cm. What is the probability it lands in the inscribed circle?'), s: L('Doira radiusi 5 sm, yuzi 25π. Kvadrat yuzi 100. P = 25π/100 = π/4 ≈ 0,785.', 'Радиус круга 5 см, площадь 25π. Площадь квадрата 100. P = 25π/100 = π/4 ≈ 0,785.', 'The circle has radius 5 cm and area 25π; the square has area 100. P = 25π/100 = π/4 ≈ 0.785.') },
      { q: L('Avtobus har 15 daqiqada keladi. Bekatga tavakkaliga kelgan yo‘lovchi 5 daqiqadan ko‘p kutmaslik ehtimoli?', 'Автобус приходит каждые 15 минут. Какова вероятность, что пассажир, пришедший наугад, будет ждать не больше 5 минут?', 'A bus comes every 15 minutes. What is the probability that a passenger arriving at random waits no more than 5 minutes?'), s: L('Kelish momenti 15 daqiqalik kesmada teng taqsimlangan, qulay qism 5 daqiqa. P = 5/15 = 1/3.', 'Момент прихода равномерно распределён на отрезке длиной 15 минут, благоприятная часть 5 минут. P = 5/15 = 1/3.', 'The arrival time is uniform on a 15-minute segment and the favourable part is 5 minutes. P = 5/15 = 1/3.') },
      { q: L('Zavodda 2000 ta lampochkadan 36 tasi nosoz chiqdi. Nosoz lampochka ehtimolini baholang.', 'На заводе из 2000 лампочек 36 оказались бракованными. Оцените вероятность брака.', 'At a factory 36 of 2000 bulbs were faulty. Estimate the probability of a faulty bulb.'), s: L('Nisbiy chastota W = 36/2000 = 0,018, ya’ni taxminan 1,8%.', 'Относительная частота W = 36/2000 = 0,018, то есть примерно 1,8%.', 'Relative frequency W = 36/2000 = 0.018, i.e. about 1.8%.') },
      { q: L('Ikki mergan bir-biridan mustaqil o‘q uzadi: birinchisi 0,8, ikkinchisi 0,7 ehtimol bilan tegizadi. Nishonga kamida bitta o‘q tegish ehtimoli?', 'Два стрелка стреляют независимо: первый попадает с вероятностью 0,8, второй — 0,7. Какова вероятность хотя бы одного попадания?', 'Two shooters fire independently, hitting with probabilities 0.8 and 0.7. What is the probability of at least one hit?'), s: L('Ikkalasi ham tegizmasligi: 0,2 · 0,3 = 0,06. P = 1 − 0,06 = 0,94.', 'Оба промахнутся: 0,2 · 0,3 = 0,06. P = 1 − 0,06 = 0,94.', 'Both miss: 0.2 · 0.3 = 0.06. P = 1 − 0.06 = 0.94.') }
    ] },
    { kind: 'mistake', h: L('Tipik xatolar', 'Типичные ошибки', 'Typical mistakes'), list: [
      L('<b>Teng imkoniyatli bo‘lmagan natijalarni sanash.</b> Ikki kubik yig‘indisi 2 dan 12 gacha 11 ta qiymat oladi, lekin P(yig‘indi 7) = 1/11 emas, 6/36 = 1/6: yig‘indilar teng imkoniyatli emas.', '<b>Считать неравновозможные исходы.</b> Сумма двух кубиков принимает 11 значений от 2 до 12, но P(сумма 7) не 1/11, а 6/36 = 1/6: суммы не равновозможны.', '<b>Counting outcomes that are not equally likely.</b> The sum of two dice takes 11 values from 2 to 12, but P(sum 7) is 6/36 = 1/6, not 1/11: the sums are not equally likely.'),
      L('<b>«O‘yinchi xatosi».</b> Tanga 5 marta ketma-ket gerb tushsa, 6-sida raqam tushish ehtimoli baribir 1/2 — tanga xotiraga ega emas.', '<b>«Ошибка игрока».</b> Если монета 5 раз подряд выпала гербом, вероятность цифры на 6-м броске всё равно 1/2 — у монеты нет памяти.', '<b>The gambler’s fallacy.</b> If a coin shows heads 5 times running, the chance of tails on the 6th toss is still 1/2 — a coin has no memory.'),
      L('<b>Birgalikda bo‘lgan hodisalar ehtimollarini shunchaki qo‘shish.</b> P(A ∪ B) = P(A) + P(B) faqat birgalikda bo‘lmaganlar uchun; aks holda P(A ∩ B) ayiriladi.', '<b>Просто складывать вероятности совместных событий.</b> P(A ∪ B) = P(A) + P(B) только для несовместных; иначе вычитают P(A ∩ B).', '<b>Simply adding probabilities of overlapping events.</b> P(A ∪ B) = P(A) + P(B) holds only for exclusive events; otherwise subtract P(A ∩ B).'),
      L('<b>Ehtimollik 1 dan katta chiqishi.</b> Agar javob 1,2 yoki −0,3 bo‘lsa, hisobda xato bor: 0 ≤ P ≤ 1.', '<b>Вероятность больше 1.</b> Если получилось 1,2 или −0,3, в расчёте ошибка: 0 ≤ P ≤ 1.', '<b>A probability above 1.</b> If you get 1.2 or −0.3, there is an error: 0 ≤ P ≤ 1.')
    ] },
    { kind: 'life', h: L('Hayotda qo‘llanishi', 'Применение в жизни', 'Real-life uses'), p: [
      L('<b>Ob-havo prognozi.</b> «Ertaga yomg‘ir ehtimoli 70%» — bu shunday sharoitli kunlarning taxminan 70 foizida yomg‘ir yoqqanini bildiradi (statistik ta’rif). <b>Sug‘urta.</b> Sug‘urta kompaniyalari baxtsiz hodisalar chastotasini o‘rganib, sug‘urta badalini hisoblaydi. <b>Tibbiyot.</b> Yangi dori klinik sinovlarda minglab bemorlarda tekshiriladi va uning samaradorligi nisbiy chastota orqali baholanadi.', '<b>Прогноз погоды.</b> «Вероятность дождя завтра 70%» означает, что примерно в 70% дней с такими условиями шёл дождь (статистическое определение). <b>Страхование.</b> Страховые компании изучают частоту несчастных случаев и рассчитывают страховой взнос. <b>Медицина.</b> Новое лекарство проверяют в клинических испытаниях на тысячах пациентов и оценивают эффективность через относительную частоту.', '<b>Weather forecasts.</b> “A 70% chance of rain tomorrow” means rain fell on about 70% of days with such conditions (the statistical definition). <b>Insurance.</b> Insurers study accident frequencies to set premiums. <b>Medicine.</b> A new drug is tested on thousands of patients in clinical trials and its effectiveness is judged by relative frequency.'),
      L('<b>Sifat nazorati</b>: zavod partiyadan tasodifiy namunalar olib, nosozlik ehtimolini baholaydi. <b>Kriptografiya va internet xavfsizligi</b>: 8 belgili parolni tasodifan topish ehtimoli juda kichik bo‘lishi uchun belgilar turini ko‘paytirish kerak — 62 xil belgidan 8 ta bo‘lsa, variantlar 62⁸ ≈ 2,2 · 10<sup>14</sup>.', '<b>Контроль качества</b>: завод берёт из партии случайные образцы и оценивает вероятность брака. <b>Криптография и интернет-безопасность</b>: чтобы вероятность случайно угадать 8-символьный пароль была мала, нужно больше видов символов — из 62 символов вариантов 62⁸ ≈ 2,2 · 10<sup>14</sup>.', '<b>Quality control</b>: a factory takes random samples from a batch to estimate the defect rate. <b>Cryptography and internet security</b>: to make guessing an 8-character password unlikely you need more kinds of characters — with 62 symbols there are 62⁸ ≈ 2.2 · 10<sup>14</sup> options.')
    ] },
    { kind: 'fact', h: L('Qiziqarli faktlar', 'Интересные факты', 'Fun facts'), list: [
      L('<b>Tug‘ilgan kunlar paradoksi:</b> 23 kishilik guruhda ikki kishining tug‘ilgan kuni bir xil bo‘lish ehtimoli 50% dan oshadi (≈ 0,507). 50 kishida bu ≈ 0,97.', '<b>Парадокс дней рождения:</b> в группе из 23 человек вероятность совпадения дней рождения у двоих превышает 50% (≈ 0,507). Для 50 человек ≈ 0,97.', '<b>The birthday paradox:</b> in a group of 23 people the chance that two share a birthday exceeds 50% (≈ 0.507). For 50 people it is ≈ 0.97.'),
      L('<b>Byuffon ignasi</b> (1777): parallel chiziqlar orasiga igna tashlab, chiziqqa tegish chastotasidan π sonini taqriban topish mumkin — geometrik ehtimollikning mashhur qo‘llanishi.', '<b>Игла Бюффона</b> (1777): бросая иглу на разлинованную бумагу, по частоте пересечения линий можно приближённо найти число π — знаменитое применение геометрической вероятности.', '<b>Buffon’s needle</b> (1777): by dropping a needle on lined paper, the frequency of crossing a line lets you estimate π — a famous use of geometric probability.'),
      L('Fransuz tabiatshunosi Jorj Byuffon tangani 4040 marta tashlab, 2048 marta gerb olgan: nisbiy chastota 0,507.', 'Французский естествоиспытатель Жорж Бюффон бросил монету 4040 раз и получил 2048 гербов: относительная частота 0,507.', 'The French naturalist Georges Buffon tossed a coin 4040 times and got 2048 heads: a relative frequency of 0.507.')
    ] },
    { kind: 'practice', h: L('O‘zingizni sinang', 'Проверьте себя', 'Test yourself'), ex: [
      { q: L('Kubik tashlandi. Tub son tushish ehtimoli?', 'Брошен кубик. Вероятность простого числа?', 'A die is rolled. Probability of a prime?'), s: L('{2, 3, 5}: 3/6 = 1/2.', '{2, 3, 5}: 3/6 = 1/2.', '{2, 3, 5}: 3/6 = 1/2.') },
      { q: L('P(A) = 0,35. P(Ā) = ?', 'P(A) = 0,35. P(Ā) = ?', 'P(A) = 0.35. P(Ā) = ?'), s: L('1 − 0,35 = 0,65.', '1 − 0,35 = 0,65.', '1 − 0.35 = 0.65.') },
      { q: L('[0; 10] kesmadan tavakkaliga son tanlanadi. U 7 dan katta bo‘lish ehtimoli?', 'Из отрезка [0; 10] наугад выбрано число. Вероятность, что оно больше 7?', 'A number is picked at random from [0; 10]. Probability that it exceeds 7?'), s: L('3/10 = 0,3.', '3/10 = 0,3.', '3/10 = 0.3.') }
    ] },
    { kind: 'summary', h: L('Xulosa', 'Итоги', 'Summary'), list: [
      L('Tasodifiy hodisa — tajribada ro‘y berishi ham, bermasligi ham mumkin bo‘lgan hodisa; 0 ≤ P ≤ 1.', 'Случайное событие может произойти или не произойти в опыте; 0 ≤ P ≤ 1.', 'A random event may or may not happen in a trial; 0 ≤ P ≤ 1.'),
      L('Klassik: P = m/n (teng imkoniyatli natijalar).', 'Классическое: P = m/n (равновозможные исходы).', 'Classical: P = m/n (equally likely outcomes).'),
      L('Statistik: ko‘p tajribadagi nisbiy chastota W = m/n.', 'Статистическое: относительная частота W = m/n при многих опытах.', 'Statistical: relative frequency W = m/n over many trials.'),
      L('Geometrik: qulay soha o‘lchovi / butun soha o‘lchovi.', 'Геометрическое: мера благоприятной области / мера всей области.', 'Geometric: measure of favourable region / measure of the whole.'),
      L('P(Ā) = 1 − P(A); birgalikda bo‘lmaganlar uchun P(A ∪ B) = P(A) + P(B).', 'P(Ā) = 1 − P(A); для несовместных P(A ∪ B) = P(A) + P(B).', 'P(Ā) = 1 − P(A); for exclusive events P(A ∪ B) = P(A) + P(B).'),
      L('Bog‘liq bo‘lmaganlar uchun P(A ∩ B) = P(A) · P(B).', 'Для независимых P(A ∩ B) = P(A) · P(B).', 'For independent events P(A ∩ B) = P(A) · P(B).'),
      L('Fanning asoschilari: Paskal va Ferma (1654), Bernulli, Kolmogorov.', 'Основатели науки: Паскаль и Ферма (1654), Бернулли, Колмогоров.', 'Founders: Pascal and Fermat (1654), Bernoulli, Kolmogorov.')
    ] }
  ] });
})(this);
